do
-- Access-key checks for the launch key gate. Pure Luau: SHA-256 key hashes and optional UTC expiry days.
local createKeyGate = function(entries)
    local band, bor, bxor, bnot = bit32.band, bit32.bor, bit32.bxor, bit32.bnot
    local lshift, rshift, rrotate = bit32.lshift, bit32.rshift, bit32.rrotate
    local K = {
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
        0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
        0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
        0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
        0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
    }
    local M = 4294967296
    local function sha256(text)
        local length = #text
        local suffix = {}
        for shift = 7, 0, -1 do table.insert(suffix, string.char(math.floor(length * 8 / 2 ^ (8 * shift)) % 256)) end
        text = text .. "\128" .. string.rep("\0", (55 - length) % 64) .. table.concat(suffix)
        local h = {0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19}
        local w = {}
        for start = 1, #text, 64 do
            for i = 1, 16 do
                local a, b, c, d = string.byte(text, start + i * 4 - 4, start + i * 4 - 1)
                w[i] = bor(lshift(a, 24), lshift(b, 16), lshift(c, 8), d)
            end
            for i = 17, 64 do
                local x, y = w[i - 15], w[i - 2]
                w[i] = (w[i - 16] + bxor(rrotate(x, 7), rrotate(x, 18), rshift(x, 3)) + w[i - 7]
                    + bxor(rrotate(y, 17), rrotate(y, 19), rshift(y, 10))) % M
            end
            local a, b, c, d, e, f, g, hh = h[1], h[2], h[3], h[4], h[5], h[6], h[7], h[8]
            for i = 1, 64 do
                local t1 = (hh + bxor(rrotate(e, 6), rrotate(e, 11), rrotate(e, 25))
                    + bxor(band(e, f), band(bnot(e), g)) + K[i] + w[i]) % M
                local t2 = (bxor(rrotate(a, 2), rrotate(a, 13), rrotate(a, 22))
                    + bxor(band(a, b), band(a, c), band(b, c))) % M
                hh, g, f, e, d, c, b, a = g, f, e, (d + t1) % M, c, b, a, (t1 + t2) % M
            end
            h[1], h[2], h[3], h[4] = (h[1] + a) % M, (h[2] + b) % M, (h[3] + c) % M, (h[4] + d) % M
            h[5], h[6], h[7], h[8] = (h[5] + e) % M, (h[6] + f) % M, (h[7] + g) % M, (h[8] + hh) % M
        end
        return string.format(string.rep("%08x", 8), table.unpack(h))
    end
    -- Last second of a UTC calendar day, without os.time's local-time interpretation.
    local function dayEnd(text)
        local y, m, d = string.match(type(text) == "string" and text or "", "^(%d%d%d%d)%-(%d%d)%-(%d%d)$")
        y, m, d = tonumber(y), tonumber(m), tonumber(d)
        if not y or m < 1 or m > 12 or d < 1 then return nil end
        local leap = (y % 4 == 0 and y % 100 ~= 0) or y % 400 == 0
        if d > ({31, leap and 29 or 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31})[m] then return nil end
        local year = m <= 2 and y - 1 or y
        local era = math.floor(year / 400)
        local yoe = year - era * 400
        local doy = math.floor((153 * ((m + 9) % 12) + 2) / 5) + d - 1
        local days = era * 146097 + yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy - 719468
        return days * 86400 + 86399
    end
    local function normalize(text)
        if type(text) ~= "string" then return "" end
        return string.upper((string.gsub(text, "^%s*(.-)%s*$", "%1")))
    end
    local byHash, count = {}, 0
    for index, entry in ipairs(entries) do
        local hash = type(entry) == "table" and entry.Hash
        if type(hash) ~= "string" or #hash ~= 64 or not hash:match("^%x+$") then
            error("Key entry " .. index .. ": Hash must be 64 hexadecimal characters", 2)
        end
        local expiresAt = nil
        if entry.Expires ~= nil then
            expiresAt = dayEnd(entry.Expires)
            if not expiresAt then error("Key entry " .. index .. ": Expires must be a real date written YYYY-MM-DD", 2) end
        end
        byHash[string.lower(hash)] = {ExpiresAt = expiresAt, Note = entry.Note}
        count += 1
    end
    if count == 0 then error("The key list is empty", 2) end

    local gate = {Hash = sha256, Normalize = normalize, DayEnd = dayEnd}
    function gate.CheckHash(hash, now)
        local entry = type(hash) == "string" and byHash[hash]
        if not entry then return false, "Invalid key" end
        if entry.ExpiresAt and now > entry.ExpiresAt then return false, "Key expired" end
        return true, hash, entry
    end
    function gate.Check(text, now)
        local key = normalize(text)
        if key == "" then return false, "Enter your key" end
        if #key > 128 then return false, "Invalid key" end
        return gate.CheckHash(sha256(key), now)
    end
    return gate
end
-- Launch key gate: nothing below this block starts until a valid key is entered.
-- The prompt is WindUI's own key dialog, in the same MM2 Midnight theme as the main menu.
-- Hash = SHA-256 of the key in UPPERCASE (keys are case-insensitive).
-- Expires (optional) = last valid UTC day, written "YYYY-MM-DD".
local KeyConfig = {
    Keys = {
        {Hash = "05eda8bfdbdd67dbd26c252eea3ce750c03cebb1110d6ffd55b664faf7c560d9", Note = "Launch key"},
        {Hash = "12cb1a3bb0f5226cc77c6ed17ab7bf9441aa0ee008cd72ae74c3f0e2de93aa31", Note = "Owner mobile launch key"},
    },
    GetKeyUrl = nil, -- link copied by the dialog's Get key button; the button stays hidden while this is nil
    SaveKey = true, -- remember a valid key on this device
    SaveFile = "MM2Universal/key.txt",
}
local gate = createKeyGate(KeyConfig.Keys)
local keyEnv = (getgenv and getgenv()) or _G
local previousPrompt = keyEnv.MM2KeyPrompt
if type(previousPrompt) == "table" and type(previousPrompt.Cancel) == "function" then pcall(previousPrompt.Cancel) end
local unlocked = gate.CheckHash(keyEnv.MM2KeySession, os.time())
local savedNotice = nil
if not unlocked and KeyConfig.SaveKey then
    local readOk, saved = pcall(function() return isfile(KeyConfig.SaveFile) and readfile(KeyConfig.SaveFile) or nil end)
    if readOk and type(saved) == "string" then
        local ok, result = gate.Check(saved, os.time())
        if ok then
            unlocked, keyEnv.MM2KeySession = true, result
        else
            savedNotice = result == "Key expired" and "Your saved key expired. Enter a new one." or "Your saved key is no longer valid."
        end
    end
end
if not unlocked then
    local host = nil
    if not pcall(function() host = gethui() end) or typeof(host) ~= "Instance" then
        host = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui")
    end
    local library = createLibrary(host)
    library:AddTheme({Name="MM2 Midnight",Accent=Color3.fromRGB(19,23,32),Background=Color3.fromRGB(13,17,24),
        Dialog=Color3.fromRGB(23,28,39),Text=Color3.fromRGB(233,239,249),Placeholder=Color3.fromRGB(148,161,184),
        Icon=Color3.fromRGB(164,181,207),Toggle=Color3.fromRGB(116,153,255),Primary=Color3.fromRGB(116,153,255),
        Slider=Color3.fromRGB(116,153,255),Button=Color3.fromRGB(36,45,62),Outline=Color3.fromRGB(85,105,136),
        ElementBackground=Color3.fromRGB(24,30,42),ElementBackgroundTransparency=0})
    library:SetTheme("MM2 Midnight")
    for _, name in ipairs({"ScreenGui", "NotificationGui", "DropdownGui", "TooltipGui"}) do
        library[name].ResetOnSpawn = false
        library[name].DisplayOrder = 500 + (name == "ScreenGui" and 0 or 2)
    end
    local done = Instance.new("BindableEvent")
    local finished, failures, lockedUntil, saveFailed = false, 0, 0, false
    local prompt = {}
    local function finish(outcome)
        if finished then return end
        finished = true
        if keyEnv.MM2KeyPrompt == prompt then keyEnv.MM2KeyPrompt = nil end
        done:Fire(outcome)
    end
    prompt.Cancel = function() finish("replaced") end
    keyEnv.MM2KeyPrompt = prompt
    library:KeyPrompt({
        Title = "MM2 Universal",
        Icon = "crosshair",
        KeySystem = {
            Note = savedNotice or "Enter your access key to unlock the menu.",
            URL = KeyConfig.GetKeyUrl,
            OnExit = function() finish("closed") end,
            KeyValidator = function(text)
                if finished then return false, "This prompt was closed." end
                local clock = os.clock()
                if clock < lockedUntil then
                    return false, ("Too many attempts. Try again in %ds."):format(math.ceil(lockedUntil - clock))
                end
                local ok, result = gate.Check(text, os.time())
                if not ok then
                    failures += 1
                    if failures >= 5 then
                        failures, lockedUntil = 0, clock + 15
                        return false, "Too many attempts. Try again in 15s."
                    end
                    return false, result .. "."
                end
                keyEnv.MM2KeySession = result
                if KeyConfig.SaveKey then
                    saveFailed = not pcall(function()
                        local folder = string.match(KeyConfig.SaveFile, "^(.+)/[^/]+$")
                        if folder and not isfolder(folder) then makefolder(folder) end
                        writefile(KeyConfig.SaveFile, gate.Normalize(text))
                    end)
                end
                return true
            end,
        },
    }, function(accepted) if accepted then finish("unlocked") end end)

    local outcome = done.Event:Wait()
    done:Destroy()
    if outcome == "unlocked" and saveFailed then
        library:Notify({Title = "Access key", Icon = "info", Duration = 5,
            Content = "Key accepted. This executor can't save it, so you'll be asked again next time."})
        task.delay(5.6, library.__MM2Dispose)
    else
        task.delay(outcome == "replaced" and 0 or 0.3, library.__MM2Dispose)
    end
    if outcome ~= "unlocked" then
        if outcome == "closed" then warn("MM2: an access key is required. Nothing was loaded.") end
        return
    end
end
end
