-- Prefer Roblox's active input so a touchscreen laptop can still use PC controls.
-- Called every frame by the camera guard; a shared reader avoids allocating a closure per call.
local function readPreferredInput(service) return service.PreferredInput end
local detectInputMode = function(UIS)
    local ok, preferred = pcall(readPreferredInput, UIS)
    if ok then
        if preferred == Enum.PreferredInput.Touch then return "Mobile" end
        if preferred == Enum.PreferredInput.KeyboardAndMouse then return "PC" end
    end
    -- Older clients and gamepad input use available hardware as a fallback.
    if UIS.TouchEnabled and not (UIS.KeyboardEnabled and UIS.MouseEnabled) then return "Mobile" end
    return "PC"
end

local function touchInput() return detectInputMode(UIS) == "Mobile" end
local function mobileBlocked()
    if State.Fling and State.Fling.Active then return true end
    local ui = State.MobileUI
    return (State.FlingQueue and State.FlingQueue.Active) or (not State.MobileActionInProgress and ui
        and (ui.MenuOpen or os.clock() < (ui.InputUntil or 0)))
end
local refreshButtons = {}
local function connect(signal, callback)
    local connection = signal:Connect(callback)
    table.insert(State.Connections, connection)
    return connection
end
do
    function State.FixCamera()
        if State.SetExperimentalInvisibility then State.SetExperimentalInvisibility(false) end
        local camera = workspace.CurrentCamera
        local humanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
        if not camera or not humanoid or humanoid.Health <= 0 then
            State.CameraRepairStatus = "Camera repair: waiting for character"
            return false, State.CameraRepairStatus
        end
        local ok, message = pcall(function()
            local playerModule = player.PlayerScripts:FindFirstChild("PlayerModule")
            local cameraModule = playerModule and playerModule:FindFirstChild("CameraModule")
            if cameraModule then
                local inputModule = cameraModule:FindFirstChild("CameraInput")
                local utilsModule = cameraModule:FindFirstChild("CameraUtils")
                local input = inputModule and require(inputModule)
                local utils = utilsModule and require(utilsModule)
                if input then
                    -- Use the native reset to disconnect/reconnect once, rather than adding a camera loop.
                    local enabled = input.getInputEnabled()
                    input.setInputEnabled(false)
                    input.setTogglePan(false)
                    input.disableCameraToggleInput()
                    input.setInputEnabled(enabled)
                end
                local cameras = require(playerModule):GetCameras()
                local lockController = cameras.activeMouseLockController
                -- An explicit Fix camera request turns off the native toggle as well as its cached cursor lock.
                if lockController and type(lockController.GetIsMouseLocked) == "function"
                    and lockController:GetIsMouseLocked() and type(lockController.OnMouseLockToggled) == "function" then
                    lockController:OnMouseLockToggled()
                end
                local controller = cameras.activeCameraController
                -- Seed CameraUtils' saved behavior too, otherwise it restores the stale lock next frame.
                if controller and not controller.inFirstPerson and not controller.inMouseLockedMode
                    and not UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
                    UIS.MouseBehavior = Enum.MouseBehavior.Default
                    if utils then
                        utils.setMouseBehaviorOverride(Enum.MouseBehavior.Default)
                        utils.restoreMouseBehavior()
                    end
                end
                if controller and controller.UpdateMouseBehavior then controller:UpdateMouseBehavior() end
            end
            UIS.MouseDeltaSensitivity = 1
            camera.CameraSubject = humanoid
            camera.CameraType = Enum.CameraType.Custom
            -- Never assign UserGameSettings sensitivity, Camera.CFrame, FOV, or zoom distance.
        end)
        State.CameraRepairStatus = ok and "Camera input restored; saved sensitivity preserved"
            or ("Camera repair failed: " .. tostring(message))
        return ok, State.CameraRepairStatus
    end
end
do
    local guard = {Corrections = 0, Status = "Waiting for native camera"}
    State.CameraGuard = guard
    local settings = UserSettings():GetService("UserGameSettings")
    local vr = game:GetService("VRService")
    local bindName = "MM2AssistCameraGuard_" .. game:GetService("HttpService"):GenerateGUID(false)
    local cameras, input, utils, module
    local rightHeld = false
    connect(UIS.InputBegan, function(event)
        if event.UserInputType == Enum.UserInputType.MouseButton2 then rightHeld = true end
    end)
    connect(UIS.InputEnded, function(event)
        if event.UserInputType == Enum.UserInputType.MouseButton2 then rightHeld = false end
    end)
    connect(UIS.WindowFocusReleased, function() rightHeld = false end)
    connect(UIS.WindowFocused, function()
        rightHeld = false
        if touchInput() or not State.Running or not input then return end
        -- A mouse-up outside the game may never reach its camera input. Clear the native accumulated input on return.
        pcall(function()
            local wasEnabled = input.getInputEnabled()
            input.setInputEnabled(false)
            input.setInputEnabled(wasEnabled)
            local controller = cameras and cameras.activeCameraController
            if controller and controller.isCameraToggle then
                local selectedPan = input.getTogglePan()
                input.disableCameraToggleInput()
                input.enableCameraToggleInput()
                input.setTogglePan(selectedPan)
            end
        end)
    end)
    local function loadNativeCamera()
        local scripts = player:FindFirstChild("PlayerScripts")
        module = scripts and scripts:FindFirstChild("PlayerModule")
        local cameraModule = module and module:FindFirstChild("CameraModule")
        local inputModule = cameraModule and cameraModule:FindFirstChild("CameraInput")
        local utilsModule = cameraModule and cameraModule:FindFirstChild("CameraUtils")
        if not inputModule or not utilsModule then return false end
        cameras, input, utils = require(module):GetCameras(), require(inputModule), require(utilsModule)
        return cameras and input and utils
    end
    function State.CheckCameraLock()
        if touchInput() or not State.Running or not cameras or not module.Parent or vr.VREnabled
            or not UIS.MouseEnabled or GuiService.MenuIsOpen then return false end
        local camera = workspace.CurrentCamera
        local char = player.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local controller = cameras.activeCameraController
        if not camera or camera.CameraType ~= Enum.CameraType.Custom or camera.CameraSubject ~= hum
            or not hum or hum.Health <= 0 or not controller or not controller.enabled then return false end
        -- The native mouse-lock controller is the player's selected toggle. A cached MouseBehavior isn't.
        local selected = controller.inMouseLockedMode == true
        local lockController = cameras.activeMouseLockController
        if lockController and type(lockController.GetIsMouseLocked) == "function" then
            selected = lockController:GetIsMouseLocked()
        elseif type(controller.GetIsMouseLocked) == "function" then
            selected = controller:GetIsMouseLocked()
        end
        if lockController and type(selected) == "boolean" and controller.inMouseLockedMode ~= selected
            and type(controller.SetIsMouseLocked) == "function" then
            controller:SetIsMouseLocked(selected)
        end
        local firstPerson = controller.inFirstPerson or player.CameraMode == Enum.CameraMode.LockFirstPerson
        local togglePan = controller.isCameraToggle and input.getTogglePan and input.getTogglePan()
        local rotation = rightHeld
            or (input.getRotationActivated and input.getRotationActivated())
        if selected or firstPerson or togglePan or rotation then
            guard.Status = "Native camera selection preserved"
            return false
        end
        local behavior = UIS.MouseBehavior
        if behavior ~= Enum.MouseBehavior.LockCenter and behavior ~= Enum.MouseBehavior.LockCurrentPosition then
            guard.Status = "Normal free cursor"
            return false
        end
        -- Clear both the current value and CameraUtils' cached restore value, so the next native frame stays free.
        UIS.MouseBehavior = Enum.MouseBehavior.Default
        utils.setMouseBehaviorOverride(Enum.MouseBehavior.Default)
        utils.restoreMouseBehavior()
        if settings.RotationType == Enum.RotationType.CameraRelative then
            settings.RotationType = Enum.RotationType.MovementRelative
            utils.setRotationTypeOverride(Enum.RotationType.MovementRelative)
            utils.restoreRotationType()
        end
        guard.Corrections += 1
        guard.Status = "Unselected camera lock cleared"
        return true
    end
    function State.StopCameraGuard()
        RunService:UnbindFromRenderStep(bindName)
    end
    task.spawn(function()
        local ok, loaded = pcall(loadNativeCamera)
        if not State.Running then return end
        if not ok or not loaded then guard.Status = "Native camera unavailable"; return end
        RunService:BindToRenderStep(bindName, Enum.RenderPriority.Camera.Value + 10, function()
            local checked, message = pcall(State.CheckCameraLock)
            if not checked then guard.Status = "Camera check unavailable: " .. tostring(message) end
        end)
    end)
end

local function getModule(folderName, moduleName)
    local folder = RS:FindFirstChild(folderName)
    local module = folder and folder:FindFirstChild(moduleName)
    if not module then return nil end
    local ok, result = pcall(require, module)
    return ok and result or nil
end
local round = getModule("Modules", "CurrentRoundClient")
local weapon = getModule("ClientServices", "WeaponService")
if not round or not weapon then
    State.Running = false
    for _, connection in ipairs(State.Connections) do connection:Disconnect() end
    if State.StopCameraGuard then State.StopCameraGuard() end
    if env.MM2Assist == State then env.MM2Assist = nil end
    error("MM2: open Murder Mystery 2; game modules are unavailable or this executor cannot access them.")
end
-- Shared map/role policy. Event roles remain real roles; they are never relabelled as Murderer.
local createGameContext=function(C)
    local world,round=C.World,C.Round
    local clock=C.Clock or os.clock
    local context={}
    local scanned,areas,boxes=-math.huge,{},{}
    local margin=Vector3.new(60,60,60)
    local supported={Classic=true,Infection=true,FreezeTag=true}
    function context.Mode()
        local mode=world:GetAttribute("GameMode")
        return type(mode)=="string" and mode or "Unknown"
    end
    function context.Data(p)
        local all=type(round.PlayerData)=="table" and round.PlayerData or {}
        local row=all[p.Name] or all[tostring(p.UserId)] or all[p.UserId]
        return type(row)=="table" and row or nil
    end
    local function finite(v)
        return v and v.X==v.X and v.Y==v.Y and v.Z==v.Z
            and math.abs(v.X)<1e7 and math.abs(v.Y)<1e7 and math.abs(v.Z)<1e7
    end
    function context.Areas()
        local now=clock()
        if now-scanned<1 then return areas end
        scanned,areas=now,{}
        local found={}
        local function visit(node,depth)
            if not (node:IsA("Model") or node:IsA("Folder")) or node:FindFirstChildOfClass("Humanoid")
                or node.Name:lower():find("lobby",1,true) or node:FindFirstChild("VotePads") then return end
            local spawns=node:FindFirstChild("Spawns") or node:FindFirstChild("SpawnPoints")
            if spawns then
                local geometry=node:FindFirstChild("Base") or node:FindFirstChild("Map")
                if not geometry or not geometry:IsA("Model") then geometry=node:IsA("Model") and node or nil end
                if geometry then
                    found[node]=true
                    local box=boxes[node]
                    if not box or box.Geometry~=geometry or now-box.At>=3 then
                        local ok,frame,size=pcall(geometry.GetBoundingBox,geometry)
                        box=ok and finite(size) and size.X>0 and size.Y>0 and size.Z>0
                            and {Object=node,Geometry=geometry,Spawns=spawns,Frame=frame,Size=size,Half=size/2+margin,At=now} or nil
                        boxes[node]=box
                    end
                    if box then table.insert(areas,box) end
                end
                return
            end
            if depth<2 then for _,child in ipairs(node:GetChildren()) do visit(child,depth+1) end end
        end
        for _,child in ipairs(world:GetChildren()) do visit(child,0) end
        for map in pairs(boxes) do if not found[map] then boxes[map]=nil end end
        return areas
    end
    function context.MapAt(position)
        if not finite(position) then return nil end
        for _,box in ipairs(context.Areas()) do
            if box.Object:IsDescendantOf(world) and box.Geometry:IsDescendantOf(world) then
                local p=box.Frame:PointToObjectSpace(position)
                if math.abs(p.X)<=box.Half.X and math.abs(p.Y)<=box.Half.Y and math.abs(p.Z)<=box.Half.Z then return box end
            end
        end
    end
    function context.Contains(position) return context.MapAt(position)~=nil end
    function context.Maps()
        local list={}
        for _,box in ipairs(context.Areas()) do if box.Object:IsDescendantOf(world) then table.insert(list,box.Object) end end
        return list
    end
    function context.InRound(p)
        local char=p.Character
        local anchor=char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head")
            or char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso"))
        return anchor~=nil and char:IsDescendantOf(world) and context.Contains(anchor.Position)
    end
    function context.Visible(p)
        local char=p.Character
        local hum=char and char:FindFirstChildOfClass("Humanoid")
        -- Visuals track the living rig, including frozen/temporarily incomplete rigs.
        -- Stale combat death metadata must not suppress those visuals.
        return hum~=nil and hum.Health>0 and context.InRound(p)
    end
    function context.Alive(p)
        local char=p.Character
        local row=context.Data(p)
        return char~=nil and char:FindFirstChild("HumanoidRootPart")~=nil
            and not (row and (row.Dead or row.Killed)) and context.Visible(p)
    end
    function context.Frozen(p)
        local row=context.Data(p)
        return context.Mode()=="FreezeTag" and ((row and row.Frozen==true)
            or (p.Character and p.Character:GetAttribute("Frozen")==true)) or false
    end
    function context.Role(p)
        local mode,row=context.Mode(),context.Data(p)
        local role=row and row.Role
        if mode=="Infection" then
            if p.Character and p.Character:GetAttribute("Zombie")==true then return "Zombie" end
            if role=="Zombie" or role=="Survivor" then return role end
            if not row and C.ToolFor(p,"Gun") then return "Survivor" end
        elseif mode=="FreezeTag" then
            if role=="Freezer" or role=="Runner" then return role end
        elseif mode=="Classic" then
            if role=="Murderer" then return role end
            if C.ToolFor(p,"Knife") then return "Murderer" end
            if C.ToolFor(p,"Gun") then return "Sheriff" end
            if role=="Innocent" or role=="Sheriff" or role=="Hero" then return role end
        elseif type(role)=="string" and #role<=32 then return role end
        return "Unknown"
    end
    function context.CanUse(p,kind)
        if context.Frozen(p) then return false end
        local mode,role=context.Mode(),context.Role(p)
        if kind=="Knife" then
            return mode=="Classic" and role=="Murderer" or mode=="Infection" and role=="Zombie"
                or mode=="FreezeTag" and role=="Freezer"
        elseif kind=="Gun" then
            return mode=="Classic" and (role=="Sheriff" or role=="Hero")
                or mode=="Infection" and role=="Survivor" or mode=="FreezeTag" and role=="Freezer"
        end
        return false
    end
    function context.Target(own,target,kind)
        if own==target or not context.CanUse(own,kind) or not context.Alive(target) or context.Frozen(target) then return false end
        local mode,role=context.Mode(),context.Role(target)
        if mode=="Classic" then return kind=="Gun" and role=="Murderer" or kind=="Knife" and role~="Murderer" end
        if mode=="Infection" then return kind=="Gun" and role=="Zombie" or kind=="Knife" and role=="Survivor" end
        return mode=="FreezeTag" and role=="Runner"
    end
    function context.CanThrow(p)
        return context.CanUse(p,"Knife") and context.Mode()~="Infection"
            and not (p.Character and p.Character:GetAttribute("Zombie")==true)
    end
    function context.Threat(own,target)
        local mode,role=context.Mode(),context.Role(target)
        if mode=="Classic" then return role=="Murderer" and context.Role(own)~="Murderer" end
        if mode=="Infection" then return role=="Zombie" and context.Role(own)=="Survivor" end
        return mode=="FreezeTag" and role=="Freezer" and context.Role(own)=="Runner"
    end
    function context.Groups()
        local mode=context.Mode()
        if mode=="Infection" then return "Zombie","Survivor" end
        if mode=="FreezeTag" then return "Freezer","Runner" end
        if mode=="Classic" then return "Murderer","Sheriff" end
    end
    function context.ResolveRole(role)
        local attacker,defender=context.Groups()
        if not attacker then return nil end
        if role=="Opponent" then return context.Role(C.Player)==attacker and defender or attacker end
        if role=="Murderer" then return attacker end
        if role=="Sheriff" then return defender end
        return (role==attacker or role==defender) and role or nil
    end
    function context.Snapshot()
        local count=0; for _ in pairs(type(round.PlayerData)=="table" and round.PlayerData or {}) do count+=1 end
        local mode=context.Mode()
        return {Mode=supported[mode] and mode or "Unknown",Supported=supported[mode]==true,Maps=#context.Maps(),PlayerRows=count,
            InRound=context.InRound(C.Player),Role=supported[mode] and context.Role(C.Player) or "Unknown"}
    end
    return context
end
local createFeatureGuard=function(C)
    local records,errors={},{}
    local guard={}
    function guard.Run(name,callback)
        local ok,result=pcall(callback)
        local record=records[name] or {Errors=0,Consecutive=0}
        records[name]=record;record.OK=ok
        if ok then record.Consecutive=0;errors[name]=nil
        else
            record.Errors+=1;record.Consecutive+=1;errors[name]=tostring(result)
            local now=C.Clock()
            if not record.WarnedAt or now-record.WarnedAt>=10 then
                record.WarnedAt=now
                if C.Warn then pcall(C.Warn,"MM2 "..name.." update failed: "..tostring(result):sub(1,240)) end
            end
        end
        return ok,result
    end
    function guard.Snapshot()
        local snapshot={}
        for name,record in pairs(records) do snapshot[name]={OK=record.OK,Errors=record.Errors,Consecutive=record.Consecutive} end
        return snapshot
    end
    function guard.GetError(name) return errors[name] end
    return guard
end
local function toolFor(p, name)
    local char, backpack = p.Character, p:FindFirstChild("Backpack")
    local item = (char and char:FindFirstChild(name)) or (backpack and backpack:FindFirstChild(name))
    return item and item:IsA("Tool") and item or nil
end
State.GameContext=createGameContext({World=workspace,Round=round,Player=player,ToolFor=toolFor})
State.FeatureGuard=createFeatureGuard({Clock=os.clock,Warn=warn})
local function dataFor(p) return State.GameContext.Data(p) end
local function alive(p)
    return State.GameContext.Alive(p)
