local function shotOrigin(kind, item)
    local char = player.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    local attachment = root and root:FindFirstChild("GunRaycastAttachment")
    if kind == "Gun" and attachment then return attachment.WorldPosition end
    local handle = item and item:FindFirstChild("Handle")
    return handle and handle.Position or (root and root.Position)
end
local function segmentHitsBox(origin, position, frame, size)
    local start = frame:PointToObjectSpace(origin)
    local direction = frame:PointToObjectSpace(position) - start
    local half = size / 2
    local enter, leave = 0, 1
    for _, axis in ipairs({"X", "Y", "Z"}) do
        local delta, offset, extent = direction[axis], start[axis], half[axis]
        if math.abs(delta) < 0.000001 then
            if math.abs(offset) > extent then return false end
        else
            local first, last = (-extent - offset) / delta, (extent - offset) / delta
            if first > last then first, last = last, first end
            enter, leave = math.max(enter, first), math.min(leave, last)
            if enter > leave then return false end
        end
    end
    return true
end
local clearPath
do
-- Hot path: called hundreds of times per target scan. Mirror the passthrough tag set via signals
-- and reuse one RaycastParams instead of fetching every tagged part and allocating per call.
local passthrough = {}
for _, instance in ipairs(CollectionService:GetTagged("WeaponPassthrough")) do passthrough[instance] = true end
connect(CollectionService:GetInstanceAddedSignal("WeaponPassthrough"), function(instance) passthrough[instance] = true end)
connect(CollectionService:GetInstanceRemovedSignal("WeaponPassthrough"), function(instance) passthrough[instance] = nil end)
local params = RaycastParams.new()
params.FilterType = Enum.RaycastFilterType.Exclude
params.IgnoreWater = true
-- RaycastParams copies its filter on assignment. This non-yielding helper can
-- reuse the scratch array without sharing filters between separate queries.
local ignored = {}
clearPath = function(origin, position, char, ignoreTarget)
    for blocker in pairs(State.ServerBlockers) do
        if not blocker:IsDescendantOf(workspace) then
            State.ServerBlockers[blocker] = nil
        elseif not blocker:IsDescendantOf(char)
            and not (player.Character and blocker:IsDescendantOf(player.Character))
            and (blocker.Transparency >= 1 or not blocker.CanQuery)
            and segmentHitsBox(origin, position, blocker.CFrame, blocker.Size) then
            return false
        end
    end
    table.clear(ignored)
    if player.Character then table.insert(ignored, player.Character) end
    if ignoreTarget then table.insert(ignored, char) end
    for instance in pairs(passthrough) do
        if not State.ServerBlockers[instance] then table.insert(ignored, instance) end
    end
    for _ = 1, 12 do
        params.FilterDescendantsInstances = ignored
        local result = workspace:Raycast(origin, position - origin, params)
        if not result or result.Instance:IsDescendantOf(char) then return true end
        if result.Instance:IsA("BasePart") and result.Instance.Transparency >= 1
            and not result.Instance.CanCollide
            and not State.ServerBlockers[result.Instance] then
            table.insert(ignored, result.Instance)
        else
            return false
        end
    end
    return false
end
end
function State.TestCoverChecks()
    local ownRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not ownRoot then return {OK = false, Error = "Character unavailable"} end
    local fixture = Instance.new("Folder")
    fixture.Name = "MM2CoverCheckProbe"
    fixture.Parent = workspace
    local blocker, result = nil, {}
    local ok, message = pcall(function()
        local origin = ownRoot.Position + Vector3.new(80, 500, 0)
        local char = Instance.new("Model")
        char.Name, char.Parent = "LocalTargetProbe", fixture
        local target = Instance.new("Part")
        target.Anchored, target.CanCollide, target.CanTouch = true, false, false
        target.Size, target.Position, target.Parent = Vector3.new(3, 3, 3), origin + Vector3.new(0, 0, -20), char
        blocker = Instance.new("Part")
        blocker.Name, blocker.Anchored, blocker.CanTouch = "InvisibleDoorProbe", true, false
        blocker.Size, blocker.Position, blocker.Transparency = Vector3.new(8, 8, 1), origin + Vector3.new(0, 0, -10), 1
        blocker.Parent = fixture
        result.InvisibleSolidBlocked = not clearPath(origin, target.Position, char)
        blocker.CanCollide = false
        result.NonSolidHelperIgnored = clearPath(origin, target.Position, char)
        State.ServerBlockers[blocker] = true
        result.LearnedNonSolidBlocked = not clearPath(origin, target.Position, char)
        blocker.CanQuery = false
        result.LearnedNonQueryableBlocked = not clearPath(origin, target.Position, char)
        State.ServerBlockers[blocker] = nil
        blocker:Destroy(); blocker = nil
        result.UnobstructedAllowed = clearPath(origin, target.Position, char)
        result.OK = result.InvisibleSolidBlocked and result.NonSolidHelperIgnored and result.LearnedNonSolidBlocked
            and result.LearnedNonQueryableBlocked and result.UnobstructedAllowed
    end)
    if blocker then State.ServerBlockers[blocker] = nil end
    fixture:Destroy()
    if not ok then result.OK, result.Error = false, tostring(message) end
    return result
end
local function futurePosition(position, velocity, airborne, gravity, floorY, dt)
    local y = position.Y + velocity.Y * dt
    if airborne then
        y -= 0.5 * gravity * dt * dt
        if floorY then y = math.max(y, floorY) end
    end
    return Vector3.new(position.X + velocity.X * dt, y, position.Z + velocity.Z * dt)
end
local function solveIntercept(positionAt, origin, speed, ping, maxLead)
    local horizon = math.max(maxLead - ping, 0)
    local low = 0
    -- Find the earliest crossing, including targets that land before impact.
    for step = 1, 32 do
        local high = horizon * step / 32
        if (positionAt(ping + high) - origin).Magnitude <= speed * high then
            for _ = 1, 16 do
                local middle = (low + high) / 2
                if (positionAt(ping + middle) - origin).Magnitude > speed * middle then
                    low = middle
                else
                    high = middle
                end
            end
            return ping + high
        end
        low = high
    end
    return nil
end
local function refineKnifeIntercept(positionAt, offset, origin, speed, ping, initialLead, maxLead)
    if not initialLead then return nil end
    local lead = initialLead
    local fallback = false
    for _ = 1, 8 do
        local point = positionAt(lead) + offset
        local nextLead = ping + (point - origin).Magnitude / speed
        if nextLead > maxLead or nextLead < ping then fallback = true; break end
        local change = math.abs(nextLead - lead)
        lead = nextLead
        if change < 0.00005 then break end
    end
    local point = positionAt(lead) + offset
    if fallback or math.abs((point - origin).Magnitude - speed * (lead - ping)) > 0.03 then
        -- Steep airborne motion can defeat the fast fixed-point refinement.
        -- Reuse the bounded interception search rather than discarding a valid throw.
        lead = solveIntercept(function(t) return positionAt(t) + offset end, origin, speed, ping, maxLead)
        if not lead then return nil end
        point = positionAt(lead) + offset
    end
    return point, lead
end
local function selectMotionVelocity(reported, current, previous, cap, airborne, previousReported, verticalHistory)
    local horizontal = Vector3.new(reported.X, 0, reported.Z)
    local vertical = math.clamp(reported.Y, -120, 120)
    local source = "Reported"
    local oldReported = previousReported and Vector3.new(previousReported.X, 0, previousReported.Z)
    local freshHorizontalChange = oldReported and (horizontal - oldReported).Magnitude > math.max(3, cap * 0.2)
    local freshVerticalChange = previousReported and math.abs(reported.Y - previousReported.Y) > 6
        or (verticalHistory and verticalHistory.Transition)
    if current and previous then
        local observed = Vector3.new(current.X, 0, current.Z)
        local older = Vector3.new(previous.X, 0, previous.Z)
        -- Require two consistent observations; reject network jumps and teleports.
        local steady = (observed - older).Magnitude <= math.max(3, cap * 0.25)
            and observed.Magnitude <= cap * 1.5
        if freshHorizontalChange then source = "FreshReportedTurn" end
        if steady and not freshHorizontalChange and (observed - horizontal).Magnitude > math.max(3, cap * 0.2) then
            horizontal, source = observed, "ObservedPositions"
        end
        local verticalSteady = math.abs(current.Y) <= 120 and math.abs(previous.Y) <= 120
            and current.Y * previous.Y > 0 and math.abs(current.Y - previous.Y) <= 25
        -- Falling samples must not replace a fresh rebound, apex, or landing.
        if freshVerticalChange and math.abs(current.Y - vertical) > 6 then
            source = source == "FreshReportedTurn" and "FreshReportedTurn3D"
                or (source == "ObservedPositions" and "ObservedPositionsFreshHeight" or "FreshReportedHeight")
        end
        if not freshVerticalChange and verticalSteady and math.abs(current.Y) > 2 and math.abs(current.Y - vertical) > 6 then
            vertical = current.Y
            if airborne and verticalHistory and verticalHistory.Interval and verticalHistory.PreviousInterval then
                local interval = verticalHistory.Interval
                local spacing = (interval + verticalHistory.PreviousInterval) * 0.5
                local gravity = verticalHistory.Gravity
                local acceleration = spacing > 0 and (current.Y - previous.Y) / spacing or 0
                if gravity and acceleration < -gravity * 0.5 and acceleration > -gravity * 1.5 then
                    vertical -= gravity * interval * 0.5
                end
            end
            vertical = math.clamp(vertical, -120, 120)
            source = source == "ObservedPositions" and "ObservedPositions3D" or "ObservedVertical"
        end
    end
    if horizontal.Magnitude > cap then horizontal = horizontal.Unit * cap end
    return Vector3.new(horizontal.X, vertical, horizontal.Z), source
