    function State.FitHorizontalMotion(velocity, history, now, cap)
        local current = flat(velocity)
        local model = {Kind = "Linear", Velocity = current, Speed = current.Magnitude, Rate = 0, Acceleration = 0, Confidence = 0}
        if current.Magnitude < 0.5 or not history then return model end
        local prior, older
        for index = #history, 1, -1 do
            local sample = history[index]
            if not prior and now - sample.Time >= 0.014 then prior = sample
            elseif prior and prior.Time - sample.Time >= 0.014 then older = sample; break end
        end
        if not prior or not older then return model end
        local dt, previousDt = now - prior.Time, prior.Time - older.Time
        if dt > 0.12 or previousDt > 0.12 then return model end
        local previous, old = flat(prior.Velocity), flat(older.Velocity)
        local speed, previousSpeed, oldSpeed = current.Magnitude, previous.Magnitude, old.Magnitude
        if previousSpeed < 4 or oldSpeed < 4 or speed > cap * 1.05 or previousSpeed > cap * 1.05 or oldSpeed > cap * 1.05 then return model end
        local recentAngle, oldAngle = angle(previous, current), angle(old, previous)
        local rate, previousRate = recentAngle / dt, oldAngle / previousDt
        local steadyTurn = rate * previousRate > 0 and math.abs(recentAngle) < 0.65 and math.abs(oldAngle) < 0.65
            and math.abs(rate) <= 6 and math.abs(previousRate) <= 6
            and math.abs(rate - previousRate) <= math.max(math.abs(rate), math.abs(previousRate)) * 0.5 + 0.25
            and speed / previousSpeed > 0.8 and speed / previousSpeed < 1.25
            and previousSpeed / oldSpeed > 0.8 and previousSpeed / oldSpeed < 1.25
        if steadyTurn and math.abs(rate) > 0.35 then
            model.Kind, model.Rate = "Steering", math.clamp(rate * 0.7 + previousRate * 0.3, -6, 6)
            model.Confidence = math.clamp(1 - math.abs(rate - previousRate) / (math.abs(rate) + 0.5), 0.35, 1)
            return model
        end
        local acceleration, previousAcceleration = (speed - previousSpeed) / dt, (previousSpeed - oldSpeed) / previousDt
        if math.abs(recentAngle) < 0.12 and math.abs(oldAngle) < 0.12 and acceleration * previousAcceleration > 0
            and math.abs(acceleration) > 8 and math.abs(acceleration) <= cap * 6
            and math.abs(previousAcceleration) <= cap * 6
            and math.abs(acceleration - previousAcceleration) < math.max(math.abs(acceleration), math.abs(previousAcceleration)) * 0.5 + 5 then
            model.Kind = acceleration < 0 and "Braking" or "Accelerating"
            model.Acceleration = math.clamp(acceleration * 0.7 + previousAcceleration * 0.3, -cap * 6, cap * 6)
            model.Confidence = math.clamp(1 - math.abs(acceleration - previousAcceleration) / (math.abs(acceleration) + 5), 0.35, 1)
        end
        return model
    end
    function State.HorizontalMotionDelta(model, dt, cap)
        dt = math.max(dt, 0)
        local velocity = model.Velocity
        if model.Kind == "Steering" then
            -- Extrapolate only a short consistent arc, then continue along its final tangent.
            local turnTime = math.min(dt, 0.12)
            local theta, rate = model.Rate * turnTime, model.Rate
            local sine, cosine = math.sin(theta), math.cos(theta)
            local delta = Vector3.new((velocity.X * sine + velocity.Z * (cosine - 1)) / rate, 0,
                (velocity.X * (1 - cosine) + velocity.Z * sine) / rate)
            local tangent = Vector3.new(velocity.X * cosine - velocity.Z * sine, 0, velocity.X * sine + velocity.Z * cosine)
            return delta + tangent * (dt - turnTime)
        end
        if model.Acceleration ~= 0 and model.Speed > 0.001 then
            local time = math.min(dt, 0.12)
            if model.Acceleration < 0 then time = math.min(time, model.Speed / -model.Acceleration)
            else time = math.min(time, math.max(0, cap - model.Speed) / model.Acceleration) end
            local speedAfter = math.clamp(model.Speed + model.Acceleration * time, 0, cap)
            local distance = model.Speed * time + 0.5 * model.Acceleration * time * time + speedAfter * (dt - time)
            return velocity.Unit * math.max(distance, 0)
        end
        return velocity * dt
    end
    function State.TestAdaptiveMotion()
        local result = {}
        local now, cap = 10, 24
        local function velocity(speed, radians) return Vector3.new(math.cos(radians) * speed, 0, math.sin(radians) * speed) end
        local function history(a, b) return {{Time = now - 0.04, Velocity = a}, {Time = now - 0.02, Velocity = b}} end
        local turn = State.FitHorizontalMotion(velocity(16, 0.08), history(velocity(16, 0), velocity(16, 0.04)), now, cap)
        result.ConsistentTurnDetected = turn.Kind == "Steering"
        local delta = State.HorizontalMotionDelta(turn, 0.08, cap)
        local expected = Vector3.new((math.sin(0.24) - math.sin(0.08)) * 8, 0, (math.cos(0.08) - math.cos(0.24)) * 8)
        result.CurvedArcAccurate = (delta - expected).Magnitude < 0.0001
        local clockwise = State.FitHorizontalMotion(velocity(16, -0.08), history(velocity(16, 0), velocity(16, -0.04)), now, cap)
        result.OppositeTurnHandled = clockwise.Kind == "Steering" and State.HorizontalMotionDelta(clockwise, 0.08, cap).Z < 0
        local straight = State.FitHorizontalMotion(velocity(16, 0), history(velocity(16, 0), velocity(16, 0)), now, cap)
        result.StraightUnchanged = straight.Kind == "Linear" and (State.HorizontalMotionDelta(straight, 0.1, cap) - Vector3.new(1.6, 0, 0)).Magnitude < 0.0001
        local reversal = State.FitHorizontalMotion(velocity(16, math.pi), history(velocity(16, 0), velocity(16, 0)), now, cap)
        result.ReversalUsesFreshDirection = reversal.Kind == "Linear" and State.HorizontalMotionDelta(reversal, 0.04, cap).X < 0
        local zigzag = State.FitHorizontalMotion(velocity(16, 0), history(velocity(16, 0), velocity(16, 0.08)), now, cap)
        result.ZigzagNotExtrapolated = zigzag.Kind == "Linear"
        local brake = State.FitHorizontalMotion(velocity(12, 0), history(velocity(16, 0), velocity(14, 0)), now, cap)
        result.BrakingDetected = brake.Kind == "Braking"
        result.BrakingDoesNotReverse = State.HorizontalMotionDelta(brake, 0.4, cap).X > 0
            and math.abs(State.HorizontalMotionDelta(brake, 0.4, cap).X - 0.72) < 0.001
        local accel = State.FitHorizontalMotion(velocity(16, 0), history(velocity(12, 0), velocity(14, 0)), now, cap)
        result.AccelerationDetected = accel.Kind == "Accelerating" and State.HorizontalMotionDelta(accel, 0.1, cap).X > 1.6
        result.SpeedCapRespected = State.HorizontalMotionDelta(accel, 1, cap).Magnitude <= cap
        local stale = State.FitHorizontalMotion(velocity(16, 0.08), {{Time = 9, Velocity = velocity(16, 0)}, {Time = 9.2, Velocity = velocity(16, 0.04)}}, now, cap)
        result.StaleHistoryIgnored = stale.Kind == "Linear"
        local jump = State.FitHorizontalMotion(Vector3.new(16, 50, 0), history(velocity(16, 0), velocity(16, 0)), now, cap)
        result.VerticalMotionSeparated = State.HorizontalMotionDelta(jump, 0.1, cap).Y == 0
        result.OK = result.ConsistentTurnDetected and result.CurvedArcAccurate and result.OppositeTurnHandled and result.StraightUnchanged
            and result.ReversalUsesFreshDirection and result.ZigzagNotExtrapolated and result.BrakingDetected and result.BrakingDoesNotReverse
            and result.AccelerationDetected and result.SpeedCapRespected and result.StaleHistoryIgnored and result.VerticalMotionSeparated
        return result
    end
end

do
-- Observed movement can widen prediction limits; reported speed alone cannot.
local installAimMotionPolicy = function(State)
    local function valid(v)
        return v and v.X==v.X and v.Y==v.Y and v.Z==v.Z
            and math.abs(v.X)<1e6 and math.abs(v.Y)<1e6 and math.abs(v.Z)<1e6
    end
    function State.IsAimSamplePlausible(velocity, delta, dt)
        return valid(velocity) and valid(delta) and dt>=.01 and dt<=.15
            and velocity.Magnitude<=900 and delta.Magnitude<=900*math.min(dt,.1)+6
    end
    function State.ResolveObservedAimMotion(record, selected, cap, airborne, now, gravity)
        local result={Velocity=selected,Cap=cap,ControlledVertical=false,Fast=false}
        if not record or not record.Time or now-record.Time>.15 or now<record.Time
            or not valid(record.Current) or not valid(record.Previous) then return result end
        local current,previous=record.Current,record.Previous
        if current.Magnitude>900 or previous.Magnitude>900 then return result end
        local a,b=Vector3.new(current.X,0,current.Z),Vector3.new(previous.X,0,previous.Z)
        local speed,oldSpeed=a.Magnitude,b.Magnitude
        if speed>cap and oldSpeed>cap and speed<oldSpeed*1.6 and oldSpeed<speed*1.6
            and a:Dot(b)>speed*oldSpeed*.8 then
            result.Velocity=Vector3.new(current.X,selected.Y,current.Z)
            result.Cap=math.max(cap,math.min(900,speed*1.15)); result.Fast=true
        end
        local older=record.Older
        local dt,priorDt=record.Interval,record.PreviousInterval
        if airborne and valid(older) and dt and priorDt and dt>=.01 and dt<=.15 and priorDt>=.01 and priorDt<=.15
            and not (record.VerticalResetUntil and now<record.VerticalResetUntil) then
            local tolerance=math.max(8,gravity*.2)
            -- Finite differences describe interval midpoints, including irregular samples.
            local spacing=(dt+priorDt)*.5
            local olderDt=record.OlderInterval or priorDt
            local priorSpacing=(priorDt+olderDt)*.5
            local stable=math.abs((current.Y-previous.Y)/spacing)<tolerance
                and math.abs((previous.Y-older.Y)/priorSpacing)<tolerance
            local reported=record.Reported
            local hovering=math.abs(current.Y)<2 and valid(reported) and math.abs(reported.Y)<8
            if stable and (math.abs(current.Y)>6 or hovering) and math.abs(current.Y)<=300 then
                result.Velocity=Vector3.new(result.Velocity.X,current.Y,result.Velocity.Z)
                result.ControlledVertical=true
            end
        end
        return result
    end
end

installAimMotionPolicy(State)
end
do
-- Local evidence only: the private weapon protocol does not echo request IDs.
local installAimFeedbackSafety = function(State)
    local function vector(v)
        return typeof(v)=="Vector3" and v.X==v.X and v.Y==v.Y and v.Z==v.Z
            and math.abs(v.X)<1e8 and math.abs(v.Y)<1e8 and math.abs(v.Z)<1e8
    end
    function State.RootPointVelocity(root)
        local ok,value=pcall(function() return root:GetVelocityAtPosition(root.Position) end)
        if ok and vector(value) then return value end
        return root.AssemblyLinearVelocity
    end
    function State.IsBallisticAimState(state)
        return state==Enum.HumanoidStateType.Jumping or state==Enum.HumanoidStateType.Freefall
    end
    State.GunReplyReceipts={}
    function State.MatchGunFeedback(item,origin,endpoint,hitPart,character,now)
        if not vector(endpoint) then return nil,"Invalid reply" end
        -- MM2's beam event identifies the exact gun Handle, rather than its Tool.
        -- Normalize only the currently parented Handle, never by name or shared origin.
        if typeof(item)=="Instance" and item:IsA("BasePart") then
            local tool=item.Parent
            if tool and tool:IsA("Tool") and tool:FindFirstChild("Handle")==item then item=tool end
        end
        local receipts=State.GunReplyReceipts
        for i=#receipts,1,-1 do
            local receipt=receipts[i]
            if now-receipt.Time>3 then table.remove(receipts,i)
            elseif receipt.Item==item and receipt.Origin==origin and receipt.Endpoint==endpoint
                and receipt.HitPart==hitPart then return nil,"Duplicate or indistinguishable reply" end
        end
        local match
        for index,pending in ipairs(State.PendingGun) do
            local age=now-pending.SentAt
            local current=pending.OwnCharacter==character and character~=nil
                and pending.Record and pending.Record.Active~=false
                and State.WeaponHandlers[pending.Item]==pending.Record
                and (not pending.Target or pending.Target.Character==pending.TargetCharacter)
            if current and pending.Item==item and age>=0 and age<=3
                and vector(pending.Origin) and vector(pending.AimPoint) then
                local sameOrigin=vector(origin) and (origin-pending.Origin).Magnitude<.15
                    or (typeof(origin)=="Instance" and origin:IsDescendantOf(character))
                local wanted,actual=pending.AimPoint-pending.Origin,endpoint-pending.Origin
                if sameOrigin and wanted.Magnitude>.001 and actual.Magnitude>.001
                    and wanted.Unit:Dot(actual.Unit)>.9999 then
                    if match then return nil,"Ambiguous reply" end
                    match=index
                end
            end
        end
        if not match then return nil,"Unmatched or stale reply" end
        table.insert(receipts,{Item=item,Origin=origin,Endpoint=endpoint,HitPart=hitPart,Time=now})
        while #receipts>16 do table.remove(receipts,1) end
        return match,"Heuristic"
    end
end

installAimFeedbackSafety(State)
end
local function sampleMotion(now, force)
    -- Records already have a 20 ms minimum interval; avoid walking the entire
    -- roster on intervening frames. Attack-time calls always inspect fresh state.
    if not force and State.LastMotionSampleAt and now >= State.LastMotionSampleAt
        and now - State.LastMotionSampleAt < 0.02 then return end
    State.LastMotionSampleAt = now
    State.Performance.MotionSweeps += 1
    for _, other in ipairs(Players:GetPlayers()) do
        local char = other.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if other ~= player and root then
            local hum = char:FindFirstChildOfClass("Humanoid")
            local humanoidState = hum and hum:GetState()
            local record = State.Motion[other]
            if not record or record.Root ~= root then
                State.Motion[other] = {Root = root, Position = root.Position, Time = now,
                    Reported = State.RootPointVelocity(root), HumanoidState = humanoidState,
                    History = {{Time = now, Velocity = State.RootPointVelocity(root), Position = root.Position}}}
            else
                if humanoidState ~= record.HumanoidState then
                    record.HumanoidState = humanoidState
                    record.VerticalResetUntil = now + 0.08
                end
                local dt = now - record.Time
                if dt >= 0.02 then
                    record.Older = record.Previous
                    record.Previous = record.Current
                    record.Current = dt <= 0.15 and (root.Position - record.Position) / dt or nil
                    local networkJump = record.Current and not State.IsAimSamplePlausible(record.Current,root.Position-record.Position,dt)
                    if networkJump then record.Current, record.Previous, record.Older = nil, nil, nil end
                    record.OlderInterval = record.PreviousInterval
                    record.PreviousInterval = record.Interval
                    record.Interval = dt <= 0.15 and dt or nil
                    record.PreviousReported = record.Reported
                    record.Reported = State.RootPointVelocity(root)
                    record.Position, record.Time = root.Position, now
                    if networkJump or dt > 0.15 then record.History = {} end
                    record.History = record.History or {}
                    table.insert(record.History, {Time = now, Velocity = record.Current or record.Reported, Position = root.Position})
                    while #record.History > 8 do table.remove(record.History, 1) end
                end
            end
        else
            State.Motion[other] = nil
        end
    end
end
connect(Players.PlayerRemoving, function(other) State.Motion[other] = nil end)
local function constrainGunMotion(frame, size, desired, params)
    local current = Vector3.new(frame.Position.X, desired.Y, frame.Position.Z)
    local remaining = Vector3.new(desired.X - current.X, 0, desired.Z - current.Z)
    local collided = false
    -- This is a query shape only; no character part is resized or moved.
    local querySize = Vector3.new(size.X * 0.95, math.min(size.Y * 0.5, 1), size.Z * 0.95)
    for _ = 1, 2 do
        if remaining.Magnitude < 0.001 then break end
        local hit = workspace:Blockcast(CFrame.new(current) * frame.Rotation, querySize, remaining, params)
        if not hit or math.abs(hit.Normal.Y) >= 0.6 then current += remaining; break end
        local normal = Vector3.new(hit.Normal.X, 0, hit.Normal.Z).Unit
        local travel = remaining.Unit * math.clamp(hit.Distance - 0.035, 0, remaining.Magnitude)
        current += travel
        remaining -= travel
        remaining -= normal * math.min(remaining:Dot(normal), 0)
        collided = true
    end
    return Vector3.new(current.X, desired.Y, current.Z), collided
end
local function motionPredictor(part, root, samplePosition, wallAware, historyOverride)
    local hum = root.Parent:FindFirstChildOfClass("Humanoid")
    local cap = math.max(hum and hum.WalkSpeed or 16, 16) * 1.5
    local other = Players:GetPlayerFromCharacter(root.Parent)
    local record = historyOverride or (other and State.Motion[other])
    if record and (record.Root ~= root or os.clock() - record.Time > 0.15) then record = nil end
    local reported = State.RootPointVelocity(root)
    local state = hum and hum:GetState()
    local airborne = hum and State.IsBallisticAimState(state) or false
    local velocity, source = selectMotionVelocity(reported,
        record and record.Current, record and record.Previous, cap, airborne,
        record and (record.PreviousReported or record.Reported), record and {
            Transition = record.HumanoidState ~= state or (record.VerticalResetUntil and os.clock() < record.VerticalResetUntil),
            Interval = record.Interval, PreviousInterval = record.PreviousInterval, Gravity = workspace.Gravity})
    local gravity = workspace.Gravity
    local observed = State.ResolveObservedAimMotion(record,velocity,cap,airborne,os.clock(),gravity)
    velocity,cap = observed.Velocity,observed.Cap
    if observed.Fast then source ..= "+VerifiedFast" end
    if observed.ControlledVertical then source ..= "+ControlledVertical" end
    State.LastAimMotionPolicy = {Fast=observed.Fast,ControlledVertical=observed.ControlledVertical,Cap=cap}
    local ballistic = airborne and not observed.ControlledVertical
    local model = wallAware and State.FitHorizontalMotion(velocity, record and record.History, os.clock(), cap)
    if model then
        source ..= "+" .. model.Kind
        State.LastMotionPrediction = {Kind = model.Kind, Confidence = model.Confidence, TurnRate = model.Rate,
            Acceleration = model.Acceleration, Target = other and other.Name}
    end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = {root.Parent, player.Character}
    params.RespectCanCollide = true
    params.CollisionGroup = root.CollisionGroup
    local rootPosition, partPosition = root.Position, samplePosition or part.Position
    local rootFrame, rootSize = root.CFrame, root.Size
    local standingHeight = (hum and hum.HipHeight or 2) + root.Size.Y / 2
    if hum and hum.RigType == Enum.HumanoidRigType.R6 then
        local leg = root.Parent:FindFirstChild("Left Leg")
        standingHeight += leg and leg.Size.Y or 2
    end
    return function(dt)
        local point = futurePosition(partPosition, velocity, ballistic, gravity, nil, dt)
        if model then
            local horizontal = State.HorizontalMotionDelta(model, dt, cap)
            point = Vector3.new(partPosition.X + horizontal.X, point.Y, partPosition.Z + horizontal.Z)
        end
        if airborne or math.abs(velocity.Y) > 2 then
            local sample = Vector3.new(point.X, rootPosition.Y + 0.5, point.Z)
            local ground = workspace:Raycast(sample, Vector3.new(0, -512, 0), params)
            if ground then
                local floorY = ground.Position.Y + standingHeight + partPosition.Y - rootPosition.Y
                point = Vector3.new(point.X, math.max(point.Y, floorY), point.Z)
            end
        end
        local blocked = false
        if wallAware then
            local rootDesired = point - (partPosition - rootPosition)
            local constrained
            constrained, blocked = constrainGunMotion(rootFrame, rootSize, rootDesired, params)
            point += constrained - rootDesired
        end
        return point, blocked
    end, airborne, source
end
function State.TestMotionIntegration()
    local ownRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not ownRoot then return {OK = false, Error = "Character unavailable"} end
    local folder = Instance.new("Folder")
    folder.Name, folder.Parent = "MM2MotionPredictionProbe", workspace
    local result = {}
    local ok, message = pcall(function()
        local base = ownRoot.Position + Vector3.new(120, 500, 0)
        local floor = Instance.new("Part")
        floor.Anchored, floor.Size, floor.Position, floor.Parent = true, Vector3.new(60, 2, 60), base, folder
        local char = Instance.new("Model")
        char.Parent = folder
        local root = Instance.new("Part")
        root.Name, root.Anchored, root.Size, root.Position, root.Parent = "HumanoidRootPart", true, Vector3.new(2, 2, 1), base + Vector3.new(0, 4, 0), char
        local hum = Instance.new("Humanoid")
        hum.HipHeight, hum.WalkSpeed, hum.RigType, hum.Parent = 2, 16, Enum.HumanoidRigType.R15, char
        local now = os.clock()
        local velocity = Vector3.new(16 * math.cos(0.08), 0, 16 * math.sin(0.08))
        root.AssemblyLinearVelocity = velocity
        local record = {Root = root, Time = now, History = {
            {Time = now - 0.04, Velocity = Vector3.new(16, 0, 0)},
            {Time = now - 0.02, Velocity = Vector3.new(16 * math.cos(0.04), 0, 16 * math.sin(0.04))}}}
        local positionAt = motionPredictor(root, root, root.Position, true, record)
        local predicted = positionAt(0.08)
        result.SteeringApplied = State.LastMotionPrediction.Kind == "Steering"
            and (Vector3.new(predicted.X - root.Position.X, 0, predicted.Z - root.Position.Z) - velocity * 0.08).Magnitude > 0.05
        local wall = Instance.new("Part")
        wall.Anchored, wall.Size, wall.Position, wall.Parent = true, Vector3.new(1, 12, 30), base + Vector3.new(2.5, 6, 0), folder
        local blockedPoint, blocked = positionAt(0.2)
        result.WallClampPreserved = blocked and blockedPoint.X <= base.X + 1.1
        wall:Destroy()
        root.Position = base + Vector3.new(0, 8, 0)
        root.AssemblyLinearVelocity = Vector3.new(0, 50, 0)
        local jumping = motionPredictor(root, root, root.Position, true)
        local jumpPoint = jumping(0.1)
        result.JumpGravityPreserved = math.abs(jumpPoint.Y - (root.Position.Y + 5 - 0.5 * workspace.Gravity * 0.01)) < 0.001
        root.AssemblyLinearVelocity = Vector3.new(0, -50, 0)
        local falling = motionPredictor(root, root, root.Position, true)
        local landed = falling(0.3)
        result.LandingClampPreserved = math.abs(landed.Y - (base.Y + 4)) < 0.001
        result.OK = result.SteeringApplied and result.WallClampPreserved and result.JumpGravityPreserved and result.LandingClampPreserved
    end)
    folder:Destroy()
    if not ok then result.OK, result.Error = false, tostring(message) end
    return result
end
function State.TestObservedAimIntegration()
    local ownRoot=player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not ownRoot then return {OK=false,Error="Character unavailable"} end
    local folder=Instance.new("Folder"); folder.Name="MM2ObservedAimProbe"; folder.Parent=workspace
    local result={LocalDummiesOnly=true}
    local ok,message=pcall(function()
        local char=Instance.new("Model"); char.Parent=folder
        local root=Instance.new("Part"); root.Name="HumanoidRootPart"; root.Anchored=true
        root.Size=Vector3.new(2,2,1); root.Position=ownRoot.Position+Vector3.new(180,1200,0); root.Parent=char
        local hum=Instance.new("Humanoid"); hum.RequiresNeck=false; hum.HipHeight=2; hum.Parent=char
        local record={Root=root,Time=os.clock(),Current=Vector3.new(300,40,0),Previous=Vector3.new(300,40,0),
            Older=Vector3.new(300,40,0),Interval=.02,PreviousInterval=.02,Reported=Vector3.zero}
        local at,_,source=motionPredictor(root,root,root.Position,true,record)
        local point=at(.1)
        result.FastFlightError=(point-(root.Position+Vector3.new(30,4,0))).Magnitude
        result.VerifiedFastSource=source:find("VerifiedFast",1,true)~=nil
        result.ControlledFlight=State.LastAimMotionPolicy.ControlledVertical
        root.AssemblyLinearVelocity=Vector3.new(0,42.152,0)
        record.Current,record.Previous,record.Older=Vector3.new(0,42.152,0),Vector3.new(0,46.076,0),Vector3.new(0,50,0)
        record.Reported=root.AssemblyLinearVelocity
        local ballistic=motionPredictor(root,root,root.Position,true,record)
        local jump=ballistic(.1)
        result.JumpGravityError=math.abs(jump.Y-(root.Position.Y+4.2152-.5*workspace.Gravity*.01))
        result.JumpIsBallistic=not State.LastAimMotionPolicy.ControlledVertical
        result.OK=result.FastFlightError<.01 and result.VerifiedFastSource and result.ControlledFlight
            and result.JumpGravityError<.01 and result.JumpIsBallistic
    end)
    folder:Destroy()
    if not ok then result.OK,result.Error=false,tostring(message) end
    return result
end

local function predict(part, root, origin, kind, item, samplePosition, gunProfile)
    local positionAt, airborne, source = motionPredictor(part, root, samplePosition, kind == "Gun")
    if kind == "Gun" then
        local lead = math.clamp(State.Config.Ping, 0, 0.15) -- configured assumption, not measured one-way delay
        if gunProfile and gunProfile.Stationary then lead = 0; source ..= "+Stationary" end
        State.CurrentGunLead = lead
        local point, blocked = positionAt(lead)
        return point, lead, airborne, blocked and (source .. "+Wall") or source, positionAt
    end
    local speed = item and (item:GetAttribute("ProjectileSpeed") or item:GetAttribute("KnifeSpeed"))
    speed = type(speed) == "number" and speed > 0 and speed
        or State.ObservedKnifeSpeed or State.Config.KnifeSpeed
    local lead = solveIntercept(positionAt, origin, speed, State.Config.Ping, State.Config.MaxLead)
    return lead and positionAt(lead) or nil, lead, airborne, source, positionAt, speed
end
