local function hiddenBodyPart(part)
    return part.Transparency >= 0.95 or part.LocalTransparencyModifier >= 0.95
end
local clearanceOffsets = {Vector3.new(0.12, 0, 0), Vector3.new(-0.12, 0, 0),
    Vector3.new(0, 0.12, 0), Vector3.new(0, -0.12, 0),
    Vector3.new(0, 0, 0.12), Vector3.new(0, 0, -0.12)}
do
    State.CamperPeekOffsets = {Vector3.new(0.44, 0, 0), Vector3.new(-0.44, 0, 0),
        Vector3.new(0, 0.44, 0), Vector3.new(0, -0.44, 0), Vector3.new(0, 0, 0.44), Vector3.new(0, 0, -0.44),
        Vector3.new(0.42, 0.42, 0), Vector3.new(-0.42, 0.42, 0), Vector3.new(0.42, -0.42, 0), Vector3.new(-0.42, -0.42, 0),
        Vector3.new(0.42, 0, 0.42), Vector3.new(-0.42, 0, 0.42), Vector3.new(0.42, 0, -0.42), Vector3.new(-0.42, 0, -0.42)}
    function State.GunAimProfile(root, origin, ownVelocity, now, historyOverride)
        local velocity = root.AssemblyLinearVelocity
        local horizontal = Vector3.new(velocity.X, 0, velocity.Z)
        local toShooter = Vector3.new(origin.X - root.Position.X, 0, origin.Z - root.Position.Z)
        local distance = (root.Position - origin).Magnitude
        local toward = toShooter.Magnitude > 0.01 and horizontal:Dot(toShooter.Unit) or 0
        local relative = velocity - (ownVelocity or Vector3.zero)
        local closing = toShooter.Magnitude > 0.01 and Vector3.new(relative.X, 0, relative.Z):Dot(toShooter.Unit) or 0
        local profile = {Mode = "Moving", Stationary = false, Approaching = toward > math.max(3, horizontal.Magnitude * 0.6)
            and closing > 2, Distance = distance, Core = false}
        local other = Players:GetPlayerFromCharacter(root.Parent)
        local record = historyOverride or (other and State.Motion[other])
        local stable, samples, oldest = true, 0, now
        if record and record.Root == root and now - record.Time < 0.15 then
            for _, sample in record.History or {} do
                if now - sample.Time <= 0.15 and sample.Position then
                    samples += 1; oldest = math.min(oldest, sample.Time)
                    if (sample.Position - root.Position).Magnitude > 0.12 then stable = false end
                end
            end
        end
        local hum = root.Parent:FindFirstChildOfClass("Humanoid")
        if hum and samples >= 3 and now - oldest >= 0.06 and stable and horizontal.Magnitude < 0.8 and math.abs(velocity.Y) < 1.5 then
            local height = hum.HipHeight + root.Size.Y / 2
            if hum.RigType == Enum.HumanoidRigType.R6 then
                local leg = root.Parent:FindFirstChild("Left Leg")
                height += leg and leg.Size.Y or 2
            end
            local params = RaycastParams.new()
            params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, {root.Parent, player.Character}
            params.RespectCanCollide, params.CollisionGroup = true, root.CollisionGroup
            local floor = workspace:Raycast(root.Position + Vector3.new(0, 0.25, 0), Vector3.new(0, -height - 1.25, 0), params)
            profile.Stationary = floor ~= nil and floor.Normal.Y > 0.55 and math.abs(root.Position.Y - floor.Position.Y - height) < 0.65
        end
        profile.Mode = profile.Stationary and "Stationary" or (profile.Approaching and "Approaching" or "Moving")
        local localOrigin, half = root.CFrame:PointToObjectSpace(origin), root.Size / 2
        local inside = math.abs(localOrigin.X) <= half.X and math.abs(localOrigin.Y) <= half.Y and math.abs(localOrigin.Z) <= half.Z
        profile.Core = root.CanQuery and not inside and not CollectionService:HasTag(root, "WeaponPassthrough")
            and (profile.Stationary or (profile.Approaching and distance <= 14))
        return profile
    end
end

local function projectedArea(part, origin, frame, size)
    frame, size = frame or part.CFrame, size or part.Size
    local direction = frame.Position - origin
    if direction.Magnitude < 0.001 then return 0 end
    local localDirection = frame:VectorToObjectSpace(direction.Unit)
    return math.abs(localDirection.X) * size.Y * size.Z
        + math.abs(localDirection.Y) * size.X * size.Z
        + math.abs(localDirection.Z) * size.X * size.Y
end
local function bodyWeight(name)
    if name == "HumanoidRootPart" then return 1.15 end
    if name == "UpperTorso" or name == "Torso" then return 1.1 end
    if name == "LowerTorso" then return 0.9 end
    if name == "Head" then return 0.95 end
    if name:find("Hand") or name:find("Foot") then return 0.25 end
    return 0.45
end
function State.IsAimPointOnScreen(position,char)
    local camera=workspace.CurrentCamera
    if not camera or typeof(position)~="Vector3" then return false end
    if position.X~=position.X or position.Y~=position.Y or position.Z~=position.Z then return false end
    if math.abs(position.X)>=1e8 or math.abs(position.Y)>=1e8 or math.abs(position.Z)>=1e8 then return false end
    local point,visible=camera:WorldToViewportPoint(position)
    local size=camera.ViewportSize
    if not (visible==true and point.Z>0 and point.X>=0 and point.Y>=0 and point.X<size.X and point.Y<size.Y) then return false end
    return not char or clearPath(camera.CFrame.Position,position,char)
end
local function visibleBodySamples(char, kind, origin, camera, cursor, profileOverride, allowOffscreen, onScreenOnly)
    if not camera and kind ~= "Gun" then return nil, {} end
    local minimum, body = nil, {}
    local names = hitPartNames[kind]
    if kind == "Gun" then
        local root = char:FindFirstChild("HumanoidRootPart")
        local ownRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
        local profile = profileOverride or (root and State.GunAimProfile(root, origin, ownRoot and ownRoot.AssemblyLinearVelocity, os.clock()))
        body._GunProfile = profile
        if profile and profile.Core then names = table.clone(names); table.insert(names, 1, "HumanoidRootPart") end
    end
    for _, name in ipairs(names) do
        local part = char:FindFirstChild(name)
        if part and part:IsA("BasePart") then
            local frame, size = part.CFrame, part.Size
            local offsets = hitOffsets
            if kind == "Gun" and body._GunProfile and body._GunProfile.Stationary and not clearPath(origin, frame.Position, char) then
                offsets = table.clone(hitOffsets)
                for _, offset in State.CamperPeekOffsets do table.insert(offsets, offset) end
            end
            local info = {Part = part, Frame = frame, Size = size, Samples = {}, OffsetCount = #offsets}
            for _, offset in ipairs(offsets) do
                local worldOffset = frame:VectorToWorldSpace(size * offset)
                local sample = frame.Position + worldOffset
                local worldDistance = (sample - origin).Magnitude
                if worldDistance <= State.Config.MaxRange then
                    local screen, visible = Vector3.zero, false
                    if camera then screen, visible = camera:WorldToViewportPoint(sample) end
                    if (visible or kind == "Gun" or allowOffscreen) and (not onScreenOnly or visible) then
                        local cursorScore
                        if cursor then
                            cursorScore = visible and (Vector2.new(screen.X, screen.Y) - cursor).Magnitude
                                or (1000000 + worldDistance)
                            if not minimum or cursorScore < minimum then minimum = cursorScore end
                        end
                        table.insert(info.Samples, {Offset = offset, WorldOffset = worldOffset, Position = sample,
                            Screen = screen, Visible = visible, CursorScore = cursorScore})
                    end
                end
            end
            body[name] = info
        end
    end
    return minimum, body
end
local function sampleRayHitsBody(origin, point, params)
    local direction = point - origin
    if direction.Magnitude < 0.001 then return false end
    return workspace:Raycast(origin, direction.Unit * (direction.Magnitude + 8), params) ~= nil
end
local function gunTimingCoverage(origin, point, translations, params)
    if not translations then return 1, 0 end
    local passed = 0
    local hits = {}
    for index, shift in ipairs(translations) do
        local hit
        -- Stationary targets often produce five identical translations. Reuse
        -- exact matches only within this synchronous point evaluation.
        for previous = 1, index - 1 do
            if shift == translations[previous] then hit = hits[previous]; break end
        end
        if hit == nil then hit = sampleRayHitsBody(origin - shift, point - shift, params) end
        hits[index] = hit
        if hit then passed += 1
        elseif State.Config.ConservativeGun then return 0, passed end
    end
    -- The nominal ray was already verified. Conservative mode requires every
    -- additional sampled time to intersect; this is geometry, not a hit probability.
    return (1 + passed) / (1 + #translations), passed
end
function State.GunTimingShifts(positionAt, lead, position)
    local window = math.clamp(lead * 0.25, 0.012, 0.035)
    if State.Config.ConservativeGun then window = math.max(window, 0.04) end
    local shifts = {positionAt(math.max(0, lead - window)) - position,
        positionAt(math.min(0.2, lead + window)) - position, Vector3.zero}
    if State.Config.ConservativeGun then
        -- Include intermediate and later arrival hypotheses without claiming
        -- response round-trip time is a measurement of one-way shot latency.
        table.insert(shifts, positionAt(lead * 0.5) - position)
        table.insert(shifts, positionAt(math.min(0.2, lead * 2 + 0.02)) - position)
    end
    return shifts
end
local function exposedSolution(char, root, kind, origin, item, camera, bodySamples, onScreenOnly)
    if not camera and kind ~= "Gun" then return nil end
    if not bodySamples then local _, body = visibleBodySamples(char, kind, origin, camera,nil,nil,nil,onScreenOnly); bodySamples = body end
    local names = hitPartNames[kind]
    if kind == "Gun" and bodySamples.HumanoidRootPart then names = table.clone(names); table.insert(names, 1, "HumanoidRootPart") end
    local queryParts = {}
    for _, name in ipairs(names) do
        local info = bodySamples[name]
        if info and info.Part.Parent == char then table.insert(queryParts, info.Part) end
    end
    if #queryParts == 0 then return nil end
    local bodyQuery = RaycastParams.new()
    bodyQuery.FilterType = Enum.RaycastFilterType.Include
    bodyQuery.FilterDescendantsInstances = queryParts
    bodyQuery.IgnoreWater = true
    local best, bestQuality = nil, 0
    for _, name in ipairs(names) do
        local info = bodySamples[name]
        local part = info and info.Part
        if part and part.Parent == char then
            local maximumQuality = projectedArea(part, origin, info.Frame, info.Size) * bodyWeight(name)
            if maximumQuality > bestQuality then
                local predicted, lead, airborne, source, positionAt, knifeSpeed
                local timingShifts
                local predictionChecked = false
                local exposedSamples, partBest, partBestQuality = 0, nil, 0
                for _, candidate in ipairs(info.Samples) do
                    local offset, worldOffset, sample, screen = candidate.Offset, candidate.WorldOffset, candidate.Position, candidate.Screen
                    if clearPath(origin, sample, char) and (not onScreenOnly or State.IsAimPointOnScreen(sample,char)) then
                            -- Solve once per body part; apply its interior sample offsets.
                            if not predictionChecked then
                                predicted, lead, airborne, source, positionAt, knifeSpeed = predict(part, root, origin, kind, item, info.Frame.Position, bodySamples._GunProfile)
                                if kind == "Gun" and predicted and positionAt then
                                    timingShifts = State.GunTimingShifts(positionAt, lead, info.Frame.Position)
                                end
                                predictionChecked = true
                            end
                            local point = predicted and predicted + worldOffset
                            local sampleLead = lead
                            if point and kind == "Knife" and positionAt then
                                point, sampleLead = refineKnifeIntercept(positionAt, worldOffset, origin, knifeSpeed,
                                    State.Config.Ping, lead, State.Config.MaxLead)
                            end
                            -- Translate the ray back into the current body geometry
                            -- rather than accepting an empty corner of a mesh's box.
                            if point and (not onScreenOnly or State.IsAimPointOnScreen(point)) and clearPath(origin, point, char, true)
                                and (kind~="Gun" or not State.GunPathClear
                                    or State.GunPathClear(State.GunPathSnapshot,origin,point,char))
                                and sampleRayHitsBody(origin - (point - sample), sample, bodyQuery) then
                                exposedSamples += 1
                                local centreWeight = offset == Vector3.zero and 1 or 0.85
                                if maximumQuality * centreWeight > partBestQuality then
                                local timingCoverage, timingPassed = gunTimingCoverage(origin, point, timingShifts, bodyQuery)
                                -- Reject failed timing hypotheses before the six
                                -- neighbouring clearance rays. The bound cannot
                                -- remove a candidate capable of beating the best.
                                if maximumQuality * centreWeight * timingCoverage > partBestQuality then
                                local clearNeighbours = 0
                                for _, neighbour in ipairs(clearanceOffsets) do
                                    local delta = info.Frame:VectorToWorldSpace(info.Size * neighbour)
                                    if clearPath(origin, point + delta, char, true) then clearNeighbours += 1 end
                                end
                                    local quality = maximumQuality * ((1 + clearNeighbours) / (1 + #clearanceOffsets))
                                        * centreWeight * timingCoverage
                                    if quality > partBestQuality then
                                        partBestQuality = quality
                                        partBest = {Position = point, BodyPoint = sample, LeadTime = sampleLead,
                                            Airborne = airborne, VelocitySource = source, AimPart = name, SampleOffset = offset,
                                            TargetMode = bodySamples._GunProfile and bodySamples._GunProfile.Mode,
                                            TimingCoverage = kind == "Gun" and timingCoverage or nil,
                                            TimingPassed = kind == "Gun" and timingPassed or nil,
                                            CursorScore = candidate.CursorScore, Offscreen = not candidate.Visible,
                                            Screen = screen, ClearShot = true, ExposureQuality = quality, ClearNeighbours = clearNeighbours}
                                    end
                                end
                                end
                            end
                    end
                end
                if partBest then
                    local quality = partBestQuality * exposedSamples / (info.OffsetCount or #hitOffsets)
                    if quality > bestQuality then
                        bestQuality, best = quality, partBest
                        best.ExposureQuality = quality
                        best.ExposedSamples = exposedSamples
                    end
                end
            end
        end
    end
    return best
end
function State.TestCampChaseAim()
    local ownRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not ownRoot then return {OK = false, Error = "Character unavailable"} end
    local folder = Instance.new("Folder")
    folder.Name, folder.Parent = "MM2CampChaseAimProbe", workspace
    local result = {}
    local ok, message = pcall(function()
        local base = ownRoot.Position + Vector3.new(150, 500, 0)
        local floor = Instance.new("Part")
        floor.Anchored, floor.Size, floor.Position, floor.Parent = true, Vector3.new(60, 2, 60), base, folder
        local char = Instance.new("Model")
        char.Parent = folder
        local root = Instance.new("Part")
        root.Name, root.Anchored, root.CanCollide, root.Transparency = "HumanoidRootPart", true, false, 1
        root.Size, root.Position, root.Parent = Vector3.new(2, 2, 1), base + Vector3.new(0, 4, 0), char
        local hum = Instance.new("Humanoid")
        hum.HipHeight, hum.WalkSpeed, hum.RigType, hum.Parent = 2, 16, Enum.HumanoidRigType.R15, char
        local now = os.clock()
        local origin = root.Position + Vector3.new(0, 0, -12)
        local record = {Root = root, Time = now, History = {
            {Time = now - 0.08, Position = root.Position}, {Time = now - 0.04, Position = root.Position},
            {Time = now, Position = root.Position}}}
        local stationary = State.GunAimProfile(root, origin, Vector3.zero, now, record)
        result.StationaryDetected = stationary.Stationary and stationary.Mode == "Stationary"
        result.StableCoreEligible = stationary.Core
        local _, body = visibleBodySamples(char, "Gun", origin, nil, nil, stationary)
        local solution = exposedSolution(char, root, "Gun", origin, nil, nil, body)
        result.StationaryZeroLead = solution and solution.LeadTime == 0 and solution.AimPart == "HumanoidRootPart"
        root.AssemblyLinearVelocity = Vector3.new(0, 0, -16)
        local approaching = State.GunAimProfile(root, origin, Vector3.zero, now, record)
        result.CloseApproachEligible = approaching.Mode == "Approaching" and approaching.Core
        local _, approachingBody = visibleBodySamples(char, "Gun", origin, nil, nil, approaching)
        local approachingShot = exposedSolution(char, root, "Gun", origin, nil, nil, approachingBody)
        result.ApproachUsesPredictedCore = approachingShot and approachingShot.AimPart == "HumanoidRootPart" and approachingShot.LeadTime > 0
        root.AssemblyLinearVelocity = Vector3.new(16, 0, 0)
        local crossing = State.GunAimProfile(root, origin, Vector3.zero, now, record)
        result.CrossingNotMisclassified = crossing.Mode == "Moving" and not crossing.Core
        root.AssemblyLinearVelocity = Vector3.new(0, 50, 0)
        result.JumpNotStationary = not State.GunAimProfile(root, origin, Vector3.zero, now, record).Stationary
        root.AssemblyLinearVelocity = Vector3.zero
        record.History[1].Position = root.Position + Vector3.new(2, 0, 0)
        result.RecentStopMustSettle = not State.GunAimProfile(root, origin, Vector3.zero, now, record).Stationary
        record.History[1].Position = root.Position
        result.InsideCoreExcluded = not State.GunAimProfile(root, root.Position, Vector3.zero, now, record).Core
        root.CanQuery = false
        result.NonQueryableCoreExcluded = not State.GunAimProfile(root, origin, Vector3.zero, now, record).Core
        root.CanQuery = true
        local wall = Instance.new("Part")
        wall.Anchored, wall.Size, wall.Position, wall.Parent = true, Vector3.new(21.16, 20, 0.1), base + Vector3.new(-10, 10, -3), folder
        local _, peekBody = visibleBodySamples(char, "Gun", origin, nil, nil, stationary)
        local peekShot = exposedSolution(char, root, "Gun", origin, nil, nil, peekBody)
        result.ThinPeekFound = peekShot and math.abs(peekShot.SampleOffset.X) > 0.35
        wall.Size, wall.Position = Vector3.new(40, 20, 0.1), base + Vector3.new(0, 10, -3)
        local _, coveredBody = visibleBodySamples(char, "Gun", origin, nil, nil, stationary)
        result.FullCoverRejected = exposedSolution(char, root, "Gun", origin, nil, nil, coveredBody) == nil
        result.HitboxUnchanged = root.Size == Vector3.new(2, 2, 1)
            and player.Character:FindFirstChild("HumanoidRootPart") == ownRoot
        result.OK = result.StationaryDetected and result.StableCoreEligible and result.StationaryZeroLead
            and result.CloseApproachEligible and result.ApproachUsesPredictedCore and result.CrossingNotMisclassified
            and result.JumpNotStationary and result.RecentStopMustSettle and result.InsideCoreExcluded
            and result.NonQueryableCoreExcluded and result.ThinPeekFound and result.FullCoverRejected and result.HitboxUnchanged
    end)
    folder:Destroy()
    if not ok then result.OK, result.Error = false, tostring(message) end
    return result
end
do
-- A small score preference for a still-valid solution; no camera or part writes.
local installTargetContinuity = function(C)
    local State, player = C.State, C.Player
    State.Config = State.Config or {}
    if State.Config.TargetContinuity == nil then State.Config.TargetContinuity = true end
    local memory = {}
    function State.ClearTargetContinuity() table.clear(memory) end
    function State.SetTargetContinuity(enabled)
        State.Config.TargetContinuity = enabled == true
        State.ClearTargetContinuity()
    end
    function State.TargetContinuityBias(kind, other, char, preferred, strict, now)
        if not State.Config.TargetContinuity or preferred or strict then return 0 end
        local previous = memory[kind]
        if previous and previous.Player == other and previous.Character == char
            and previous.OwnCharacter == player.Character and now >= previous.At and now-previous.At <= .35 then return 20 end
        return 0
    end
    function State.RememberAimTarget(kind, solution, preferred, strict, now)
        if preferred or strict then return end
        if not State.Config.TargetContinuity or not solution then memory[kind]=nil; return end
        memory[kind] = {Player=solution.Player,Character=solution.Player.Character,OwnCharacter=player.Character,At=now}
    end
end

installTargetContinuity({State=State,Player=player})
end
local function chooseTarget(kind, origin, item, preferred, strict, onScreenOnly)
    if not origin then return nil end
    local started = os.clock()
    local camera = workspace.CurrentCamera
    -- GetMouseLocation and WorldToViewportPoint both ignore the GUI inset; subtracting it shifted the cursor up.
    local cursor = UIS:GetMouseLocation()
    if camera and touchInput() then cursor = camera.ViewportSize / 2 end
    local candidates = {}
    for order, other in ipairs(Players:GetPlayers()) do
        if other ~= player and not State.IsPlayerExcluded(other) and alive(other) and (not strict or other == preferred) and State.IsCombatTarget(kind,other) then
            local char = other.Character
            local root = char:FindFirstChild("HumanoidRootPart")
            local lower, body = visibleBodySamples(char, kind, origin, camera, cursor, nil,
                strict or (kind == "Knife" and State.Config.KnifeAllDirections),onScreenOnly)
            if lower then
                local bias = State.TargetContinuityBias(kind,other,char,preferred,strict,started)
                table.insert(candidates, {Player = other, Character = char, Root = root, Order = order,
                    Lower = lower - (other == preferred and 1000000 or 0) - bias, Body = body, Bias = bias})
            end
        end
    end
    table.sort(candidates, function(a, b)
        if a.Lower == b.Lower then return a.Order < b.Order end
        return a.Lower < b.Lower
    end)
    local best, bestScore, bestOrder
    State.Performance.Selections += 1
    for index, candidate in ipairs(candidates) do
        -- Every solution is one of the sampled points. Its screen distance cannot
        -- beat the closest sample, even after cover/prediction reject points.
        if bestScore and candidate.Lower > bestScore then
            State.Performance.PrunedCandidates += #candidates - index + 1
            break
        end
        local other, char, root = candidate.Player, candidate.Character, candidate.Root
        State.Performance.CandidateEvaluations += 1
            local solution = exposedSolution(char, root, kind, origin, item, camera, candidate.Body,onScreenOnly)
            if solution then
                local screen = solution.Screen
                local score = solution.CursorScore or (Vector2.new(screen.X, screen.Y) - cursor).Magnitude
                solution.CursorDistance = score
                if other == preferred then score -= 1000000 end
                score -= candidate.Bias
                if not bestScore or score < bestScore or (score == bestScore and candidate.Order < bestOrder) then
                    bestScore = score
                    bestOrder = candidate.Order
                    solution.Player = other
                    solution.Character = char
                    solution.Velocity = root.AssemblyLinearVelocity
                    solution.Screen = nil
                    best = solution
                end
            end
    end
    State.RememberAimTarget(kind,best,preferred,strict,started)
    State.Performance.LastSelectionMs = (os.clock() - started) * 1000
    return best
end

-- Visual previews may lag by half a second; attack paths never use this cache.
function State.GetCachedAimPreview(kind, item, origin)
    local now, cached = os.clock(), State.PreviewCache
    local mode=State.GameContext and State.GameContext.Mode() or "Classic"
    local target = cached and cached.Target
    local valid = cached and cached.Kind == kind and cached.Item == item
        and cached.OwnCharacter == player.Character and now >= cached.At and now < cached.Until
        and cached.ExclusionsRevision == State.ExclusionsRevision
        and cached.Mode==mode
        and cached.ConservativeGun == State.Config.ConservativeGun
        and cached.KnifeAllDirections == State.Config.KnifeAllDirections
    if target then
        valid = valid and target.Player.Character == target.Character and alive(target.Player)
            and not State.IsPlayerExcluded(target.Player)
            and State.IsCombatTarget(kind,target.Player)
    end
    if valid then
        State.Performance.PreviewCacheHits += 1
        State.RememberAimTarget(kind, target, nil, nil, now)
        return target
    end
    target = chooseTarget(kind, origin, item)
    State.PreviewCache = {Kind=kind,Mode=mode,Item=item,OwnCharacter=player.Character,Target=target,At=now,Until=now+(State.Config.PerformancePreset=="Low effects" and 1 or .5),
        ExclusionsRevision=State.ExclusionsRevision,ConservativeGun=State.Config.ConservativeGun,
        KnifeAllDirections=State.Config.KnifeAllDirections}
    return target
end

-- This executor cannot hook the live script's module cache. Replace only the local
-- tool input script, keep a clone for restoration, and send its verified payloads.
local function owned(item)
    return item.Parent == player.Character or item.Parent == player:FindFirstChild("Backpack")
end
local function restoreInvisibility()
    if State.SetInvisibility then return State.SetInvisibility(false) end
    return true
end
function State.RepairCharacter()
    if not restoreInvisibility() then return false end
    local hum=player.Character and player.Character:FindFirstChildOfClass("Humanoid")
    if not hum or hum.Health<=0 then return false end
    State.RepairRequired=true
    State.Stats.RepairRequests+=1
    hum.Health=0 -- Only the explicit Repair character (respawns) control requests this.
    return true
end
local gameplayRemotes = RS:FindFirstChild("Remotes") and RS.Remotes:FindFirstChild("Gameplay")
local coinCollected = gameplayRemotes and gameplayRemotes:FindFirstChild("CoinCollected")
if coinCollected and coinCollected:IsA("RemoteEvent") then
    connect(coinCollected.OnClientEvent, function(bag, amount)
        State.Stats.ServerCoinEvents += 1
        State.LastCoinCollection = {Bag = tostring(bag), Amount = amount}
    end)
end

local function recordConnect(record, signal, callback)
    local connection = signal:Connect(callback)
    table.insert(record.Connections, connection)
end
do
-- One listener per live projectile, released when the knife is removed (previously one was kept per knife ever thrown).
local speedListeners = {}
local function observeKnife(projectile)
    local function updateSpeed()
        local speed = projectile:GetAttribute("ThrowSpeed")
        if type(speed) == "number" and speed >= 20 and speed <= 1000 then State.ObservedKnifeSpeed = speed end
    end
    updateSpeed()
    if not speedListeners[projectile] then
        speedListeners[projectile] = projectile:GetAttributeChangedSignal("ThrowSpeed"):Connect(updateSpeed)
    end
end
for _, projectile in ipairs(CollectionService:GetTagged("ThrowingKnife")) do observeKnife(projectile) end
connect(CollectionService:GetInstanceAddedSignal("ThrowingKnife"), observeKnife)
connect(CollectionService:GetInstanceRemovedSignal("ThrowingKnife"), function(projectile)
    local listener = speedListeners[projectile]
    if listener then listener:Disconnect(); speedListeners[projectile] = nil end
end)
table.insert(State.Connections, {Disconnect = function()
    for projectile, listener in pairs(speedListeners) do listener:Disconnect(); speedListeners[projectile] = nil end
end})
end
do
local function finiteDodgeVector(v)
    return typeof(v)=="Vector3" and v.X==v.X and v.Y==v.Y and v.Z==v.Z
        and math.abs(v.X)<1e7 and math.abs(v.Y)<1e7 and math.abs(v.Z)<1e7
end
local function resolveKnifeVelocity(record,position,now,direction,speed,physical)
    if not finiteDodgeVector(position) then return nil end
    local velocity,source
    if finiteDodgeVector(direction) and direction.Magnitude>.01 and type(speed)=="number"
        and speed==speed and speed>=5 and speed<=1500 then
        velocity,source=direction.Unit*speed,"Direction"
    elseif finiteDodgeVector(physical) and physical.Magnitude>=5 and physical.Magnitude<=1500 then
        velocity,source=physical,"Physics"
    end
    local elapsed=record.SampleAt and now-record.SampleAt
    if not velocity and elapsed and elapsed>=1/300 and elapsed<=.25 then
        local sampled=(position-record.SamplePosition)/elapsed
        if finiteDodgeVector(sampled) and sampled.Magnitude>=5 and sampled.Magnitude<=1500 then velocity,source=sampled,"Sampled"
        else record.Velocity,record.VelocityAt=nil,nil end
    end
    if not record.SampleAt or elapsed and elapsed>=1/300 then record.SamplePosition,record.SampleAt=position,now end
    if velocity then record.Velocity,record.VelocityAt=velocity,now
    elseif record.VelocityAt and now>=record.VelocityAt and now-record.VelocityAt<=.15 then velocity,source=record.Velocity,"Recent sample" end
    return velocity,source
end
local function knifeTeleportClearance(ctx,point,incoming,motions,floorY)
    if not finiteDodgeVector(point) then return nil end
    local clearance=100
    local function check(motion)
        if not finiteDodgeVector(motion.Position) or not finiteDodgeVector(motion.Velocity) then return false end
        local velocity=motion.Velocity
        local control=finiteDodgeVector(ctx.ControlVelocity) and ctx.ControlVelocity or Vector3.zero
        local flat=Vector3.new(velocity.X-control.X,0,velocity.Z-control.Z)
        local offset=motion.Position-point
        local flatOffset=Vector3.new(offset.X,0,offset.Z)
        local speed2=flat:Dot(flat)
        local horizon=ctx.Horizon or .55
        local dot=flatOffset:Dot(flat)
        local time=speed2>.0001 and math.clamp(-dot/speed2,0,horizon) or 0
        local distance=(flatOffset+flat*time).Magnitude
        clearance=math.min(clearance,distance)
        local radius=ctx.Radius+.8
        if distance>radius then return true end
        local first,last=0,horizon
        if speed2>.0001 then
            local disc=dot*dot-speed2*(flatOffset:Dot(flatOffset)-radius*radius)
            if disc<0 then return true end
            first=math.max(0,(-dot-math.sqrt(disc))/speed2)
            last=math.min(horizon,(-dot+math.sqrt(disc))/speed2)
            if first>last then return true end
        end
        local shift=point.Y-ctx.Position.Y
        local function rise(t)
            local value=not ctx.Grounded and (ctx.Velocity.Y*t-.5*ctx.Gravity*t*t) or 0
            if not ctx.Grounded and floorY then value=math.max(value,floorY-(ctx.Low+shift)) end
            return value
        end
        local lowRise,highRise=math.min(rise(first),rise(last)),math.max(rise(first),rise(last))
        if not ctx.Grounded and ctx.Velocity.Y>0 then
            local peak=ctx.Velocity.Y/ctx.Gravity
            if peak>first and peak<last then highRise=math.max(highRise,rise(peak)) end
        end
        local firstY,lastY=motion.Position.Y+velocity.Y*first,motion.Position.Y+velocity.Y*last
        return math.max(firstY,lastY)<ctx.Low+shift+lowRise-.7
            or math.min(firstY,lastY)>ctx.High+shift+highRise+.7
    end
    if not check(incoming) then return nil end
    for _,motion in ipairs(motions or {}) do if not check(motion) then return nil end end
    return clearance
end
local function planKnifeTeleport(C,ctx,incoming,motions)
    if not finiteDodgeVector(ctx.Position) or not finiteDodgeVector(incoming.Velocity)
        or type(incoming.Time)~="number" or incoming.Time~=incoming.Time or incoming.Time<=.01
        or incoming.Time>(ctx.Horizon or .55) then return nil end
    local heading=Vector3.new(incoming.Velocity.X,0,incoming.Velocity.Z)
    if heading.Magnitude<.1 then return nil end
    local side=Vector3.new(-heading.Z,0,heading.X).Unit
    for _,distance in ipairs({4,6,8}) do
        local best
        for _,direction in ipairs({side,-side}) do
            local point,floorY=C.Landing(ctx,ctx.Position+direction*distance)
            if point and finiteDodgeVector(point) and (point-ctx.Position).Magnitude<=8.5 and C.Clear(ctx,point) then
                local clearance=knifeTeleportClearance(ctx,point,incoming,motions,floorY)
                if clearance and (not best or clearance>best.Clearance) then
                    best={Kind="Teleport",Position=point,Distance=(point-ctx.Position).Magnitude,
                        Clearance=clearance,Time=incoming.Time,CreatedAt=ctx.Now,Projectile=incoming.Projectile}
                end
            end
        end
        if best then return best end -- Prefer the shortest supported displacement that clears all known paths.
    end
end
local function commitKnifeTeleport(C,ctx,action)
    local State,dodge=C.State,C.Dodge
    local now=C.Clock()
    local function allowed()
        return State.Running and State.Config.AutoKnifeDodge and State.Config.KnifeDodgeMode=="Side teleport" and C.Valid(ctx)
    end
    if not action or action.Kind~="Teleport" or not finiteDodgeVector(action.Position) or not allowed()
        or dodge.TeleportBusy or now<(dodge.NextTeleport or 0) then return false end
    local age=action.CreatedAt and now-action.CreatedAt
    if not age or age<0 or age>.08 or age>action.Time then return false end
    if not C.Safe(ctx,action) or not allowed() then return false end
    dodge.TeleportBusy=true
    dodge.NextTeleport=now+.3
    local ok,message=pcall(C.Move,ctx,action.Position)
    dodge.TeleportBusy=false
    if not ok then
        dodge.FailedTeleports=(dodge.FailedTeleports or 0)+1
        dodge.Status="Side teleport failed  ·  waiting for another safe action"
        dodge.LastError=tostring(message)
        return false,"Move failed"
    end
    dodge.Teleports=(dodge.Teleports or 0)+1
    return true
end

local installKnifeDodgeLifecycle=function(C)
    local State,dodge=C.State,C.Dodge
    local bound,destroyed=false,false
    local function clear() dodge.Direction,dodge.Character=nil,nil end
    local function unbind()
        if bound then C.Unbind(); bound=false end
    end
    local function bind()
        if bound or destroyed then return end
        C.Bind(function()
            if destroyed or not State.Running or not State.Config.AutoKnifeDodge then clear(); return end
            local ok,message=pcall(C.Step)
            if not ok then
                clear(); unbind(); State.Config.AutoKnifeDodge=false
                dodge.LastError=tostring(message)
                dodge.Status="Knife dodge error  ·  toggle off/on to retry"
            end
        end)
        bound=true
    end
    function State.SetAutoKnifeDodge(enabled)
        if destroyed then return false,"Knife dodge is unloaded" end
        enabled=enabled==true
        State.Config.AutoKnifeDodge=enabled==true
        dodge.LastError=nil
        clear()
        if enabled then bind() else unbind() end
        dodge.Status=enabled and "Knife dodge ready" or "Knife dodge OFF"
        if C.Refresh then C.Refresh() end
        return true
    end
    function State.SetKnifeDodgeMode(mode)
        if mode~="Side teleport" and mode~="Jump / sidestep" then return false,"Choose Side teleport or Jump / sidestep" end
        if destroyed then return false,"Knife dodge is unloaded" end
        State.Config.KnifeDodgeMode=mode; clear()
        dodge.Status=State.Config.AutoKnifeDodge and "Knife dodge ready" or "Knife dodge OFF"
        return true
    end
    function State.StopKnifeDodge(reason)
        -- Cancel only the current movement override. Invisibility pauses the guarded loop.
        clear()
        dodge.Status=reason or "Knife dodge paused"
    end
    function State.DestroyKnifeDodge()
        destroyed=true; clear(); unbind()
        dodge.Status="Knife dodge unloaded"
    end
    function State.GetKnifeDodgeSnapshot()
        local tracked=0
        for _ in pairs(dodge.Tracked) do tracked+=1 end
        return {Enabled=State.Config.AutoKnifeDodge==true,Bound=bound,Focused=dodge.Focused,
            Status=dodge.Status,Tracked=tracked,Decisions=dodge.Decisions,Jumps=dodge.Jumps,Sidesteps=dodge.Sidesteps,
            Mode=State.Config.KnifeDodgeMode,Teleports=dodge.Teleports or 0,FailedTeleports=dodge.FailedTeleports or 0,
            ValidMotions=dodge.ValidMotions or 0}
    end
    C.Connect(C.FocusLost,function() dodge.Focused=false; clear(); dodge.Status="Paused: window not focused" end)
    C.Connect(C.FocusGained,function() dodge.Focused=true end)
    C.Connect(C.CharacterRemoving,function() clear(); dodge.Status="Waiting for your next character" end)
    if State.Config.KnifeDodgeMode~="Jump / sidestep" then State.Config.KnifeDodgeMode="Side teleport" end
    if State.Config.AutoKnifeDodge then bind() else dodge.Status="Knife dodge OFF" end
end

    local dodge = {Status = "Knife dodge ready", Focused = true, Tracked = setmetatable({}, {__mode = "k"}),
        Decisions = 0, Jumps = 0, Sidesteps = 0, Teleports=0, LastAction = nil}
    State.KnifeDodge = dodge
    local bindName = "MM2AssistKnifeDodge_" .. game:GetService("HttpService"):GenerateGUID(false)
    local function track(projectile) dodge.Tracked[projectile] = {} end
    for _, projectile in CollectionService:GetTagged("ThrowingKnife") do track(projectile) end
    connect(CollectionService:GetInstanceAddedSignal("ThrowingKnife"), track)
    connect(CollectionService:GetInstanceRemovedSignal("ThrowingKnife"), function(projectile) dodge.Tracked[projectile] = nil end)
    local function bounds(char, root)
        local low, high, radius = root.Position.Y - root.Size.Y / 2, root.Position.Y + root.Size.Y / 2, 1
        for _, part in char:GetChildren() do
            if part:IsA("BasePart") and bodyPartSet[part.Name] then
                local frame, half = part.CFrame, part.Size / 2
                local extent = math.abs(frame.RightVector.Y) * half.X + math.abs(frame.UpVector.Y) * half.Y
                    + math.abs(frame.LookVector.Y) * half.Z
                low, high = math.min(low, part.Position.Y - extent), math.max(high, part.Position.Y + extent)
                local delta = part.Position - root.Position
                radius = math.max(radius, Vector2.new(delta.X, delta.Z).Magnitude + math.min(half.X, half.Z) + 0.2)
            end
        end
        return low, high, math.clamp(radius, 1, 2.1)
    end
    local function context(char, root, hum)
        local low, high, radius = bounds(char, root)
        local params = RaycastParams.new()
        params.FilterType, params.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, {char}
        params.RespectCanCollide, params.IgnoreWater, params.CollisionGroup = true, true, root.CollisionGroup
        local overlap=OverlapParams.new()
        overlap.FilterType,overlap.FilterDescendantsInstances=Enum.RaycastFilterType.Exclude,{char}
        overlap.RespectCanCollide,overlap.CollisionGroup,overlap.MaxParts=true,root.CollisionGroup,32
        local gravity = math.max(workspace.Gravity, 1)
        local jump = hum.UseJumpPower and hum.JumpPower or math.sqrt(2 * gravity * hum.JumpHeight)
        return {Character = char, Root = root, Position = root.Position, Velocity = root.AssemblyLinearVelocity,
            ControlVelocity=Vector3.new(hum.MoveDirection.X,0,hum.MoveDirection.Z)*hum.WalkSpeed,
            Low = low, High = high, Radius = radius, Params = params, Overlap=overlap, Gravity = gravity, JumpVelocity = jump,
            WalkSpeed = hum.WalkSpeed, Grounded = hum.FloorMaterial ~= Enum.Material.Air,
            JumpEnabled = hum:GetStateEnabled(Enum.HumanoidStateType.Jumping), Reaction = math.clamp(State.Config.Ping + 0.02, 0.02, 0.12),
            Horizon=State.Config.KnifeDodgeMode=="Side teleport" and .55 or .38,Now=os.clock()}
    end
    local function threat(ctx, position, velocity)
        local relative = velocity - ctx.Velocity
        local offset = position - ctx.Position
        local flatV, flatOffset = Vector3.new(relative.X, 0, relative.Z), Vector3.new(offset.X, 0, offset.Z)
        if flatV.Magnitude < 5 then return nil end
        local arrival = -flatOffset:Dot(flatV) / flatV:Dot(flatV)
        if arrival <= 0 or arrival > (ctx.Horizon or .38) then return nil end
        local missDistance = (flatOffset + flatV * arrival).Magnitude
        if missDistance > ctx.Radius + 0.45 then return nil end
        local heightShift = ctx.Velocity.Y * arrival
        if not ctx.Grounded then
            heightShift -= 0.5 * ctx.Gravity * arrival * arrival
            local landingOrigin = ctx.Position + Vector3.new(ctx.Velocity.X * arrival, 0.5, ctx.Velocity.Z * arrival)
            local landing = workspace:Raycast(landingOrigin, Vector3.new(0, -512, 0), ctx.Params)
            if landing and landing.Normal.Y > 0.55 then heightShift = math.max(heightShift, landing.Position.Y - ctx.Low) end
        end
        local knifeY = position.Y + velocity.Y * arrival
        if knifeY < ctx.Low + heightShift - 0.45 or knifeY > ctx.High + heightShift + 0.45 then return nil end
        local impact = position + velocity * arrival
        if not clearPath(position, impact, ctx.Character, true) then return nil end
        return {Time = arrival, Position = position, Velocity = velocity, Height = knifeY,
            Low = knifeY <= ctx.Low + (ctx.High - ctx.Low) * 0.42, MissDistance = missDistance}
    end
    local function bodyCast(ctx, delta)
        local center = Vector3.new(ctx.Position.X, (ctx.Low + ctx.High) / 2 + 0.05, ctx.Position.Z)
        local size = Vector3.new(math.max(1.5, ctx.Radius * 1.5), math.max(1, ctx.High - ctx.Low - 0.15), math.max(1.5, ctx.Radius * 1.5))
        return workspace:Blockcast(CFrame.new(center), size, delta, ctx.Params)
    end
    local function choose(ctx, incoming)
        local available = math.max(0, incoming.Time - ctx.Reaction)
        local rise = ctx.JumpVelocity * available - 0.5 * ctx.Gravity * available * available
        local peak = ctx.JumpVelocity * ctx.JumpVelocity / (2 * ctx.Gravity)
        if incoming.Low and ctx.Grounded and ctx.JumpEnabled and available > 0
            and ctx.Low + rise > incoming.Height + 0.7 and not bodyCast(ctx, Vector3.new(0, peak + 0.25, 0)) then
            return {Kind = "Jump", Duration = 0, Time = incoming.Time}
        end
        local heading = Vector3.new(incoming.Velocity.X, 0, incoming.Velocity.Z)
        if heading.Magnitude < 0.1 or ctx.WalkSpeed <= 0 then return nil end
        local side = Vector3.new(-heading.Z, 0, heading.X).Unit
        local duration = math.clamp(incoming.Time + 0.05, 0.12, 0.38)
        local travel = math.min(ctx.WalkSpeed * duration, 6)
        local best, score
        for _, direction in ipairs({side, -side}) do
            if not bodyCast(ctx, direction * travel) then
                local destination = ctx.Position + direction * travel
                local floor = workspace:Raycast(destination + Vector3.new(0, 1, 0), Vector3.new(0, -18, 0), ctx.Params)
                local maxDrop = ctx.Grounded and 2.5 or math.min(12, peak + 3)
                if floor and floor.Normal.Y > 0.55 and floor.Position.Y >= ctx.Low - maxDrop
                    and floor.Position.Y <= ctx.Low + 1.5 then
                    local futureRoot = ctx.Position + ctx.Velocity * math.min(ctx.Reaction, incoming.Time)
                        + direction * ctx.WalkSpeed * available
                    local futureKnife = incoming.Position + incoming.Velocity * incoming.Time
                    local gap = Vector2.new(futureKnife.X - futureRoot.X, futureKnife.Z - futureRoot.Z).Magnitude
                    if not score or gap > score then score = gap; best = {Kind = "Side", Direction = direction, Duration = duration,
                        Time = incoming.Time, Clearance = gap, Late = gap < ctx.Radius + 0.45} end
                end
            end
        end
        return best
    end
    local function projectileMotion(projectile,record,now)
        local link = projectile:FindFirstChild("HandleLink")
        local handle = link and link:IsA("ObjectValue") and link.Value
        if handle and ((player.Character and handle:IsDescendantOf(player.Character))
            or (player:FindFirstChild("Backpack") and handle:IsDescendantOf(player.Backpack))) then return nil end
        local part = projectile:FindFirstChild("KnifeVisual") or projectile:FindFirstChild("BladePosition")
        if not part and projectile:IsA("BasePart") then part = projectile end
        if not part or not part:IsA("BasePart") then return nil end
        local direction = projectile:GetAttribute("Direction") or part:GetAttribute("Direction")
        local speed = projectile:GetAttribute("ThrowSpeed") or part:GetAttribute("ThrowSpeed") or State.ObservedKnifeSpeed or 96
        local velocity,source=resolveKnifeVelocity(record or {},part.Position,now or os.clock(),direction,speed,part.AssemblyLinearVelocity)
        if not velocity then return nil end
        return part.Position,velocity,source
    end
    local function pauseReason()
        local pause
        if mobileBlocked() or GuiService.MenuIsOpen or UIS:GetFocusedTextBox() then pause="Paused: menu, chat or character action"
        elseif not dodge.Focused then pause="Paused: window not focused"
        elseif not alive(player) then pause="Waiting for a living round character"
        elseif State.Invis.Busy or State.ExperimentalInvis and (State.ExperimentalInvis.Active or State.ExperimentalInvis.Busy) then
            pause="Paused during invisibility"
        end
        return pause
    end
    local teleportChecks={}
    function teleportChecks.Landing(ctx,point)
        local floor=workspace:Raycast(point+Vector3.new(0,2,0),Vector3.new(0,-18,0),ctx.Params)
        local maxDrop=ctx.Grounded and 2.5 or 6
        if not floor or floor.Normal.Y<.65 or floor.Position.Y<ctx.Low-maxDrop or floor.Position.Y>ctx.Low+1.5
            or floor.Position.Y<=workspace.FallenPartsDestroyHeight+32 then return nil end
        local vertical=ctx.Grounded and floor.Position.Y-ctx.Low+.08 or 0
        return point+Vector3.new(0,vertical,0),floor.Position.Y
    end
    function teleportChecks.Clear(ctx,point)
        local lift=Vector3.new(0,(ctx.Low+ctx.High)*.5-ctx.Position.Y+.05,0)
        local size=Vector3.new(ctx.Radius*2+.15,math.max(1,ctx.High-ctx.Low-.15),ctx.Radius*2+.15)
        return not workspace:Blockcast(CFrame.new(ctx.Position+lift),size,point-ctx.Position,ctx.Params)
            and #workspace:GetPartBoundsInBox(CFrame.new(point+lift),size,ctx.Overlap)==0
    end
    local teleportCommit={State=State,Dodge=dodge,Clock=os.clock}
    function teleportCommit.Valid(ctx)
        local char=player.Character
        local hum=char and char:FindFirstChildOfClass("Humanoid")
        return not pauseReason() and char==ctx.Character and ctx.Root.Parent==char and hum and hum.Health>0
            and not hum.Sit and not hum.PlatformStand and not ctx.Root.Anchored
            and finiteDodgeVector(ctx.Root.Position) and (ctx.Root.Position-ctx.Position).Magnitude<=1.5
    end
    function teleportCommit.Safe(ctx,action)
        local base=Vector3.new(action.Position.X,ctx.Position.Y,action.Position.Z)
        local supported,floorY=teleportChecks.Landing(ctx,base)
        if not supported or (supported-action.Position).Magnitude>.15 or not teleportChecks.Clear(ctx,action.Position) then return false end
        local primary=action.Projectile
        local record=primary and dodge.Tracked[primary]
        if not record or not primary.Parent then return false end
        local primaryPosition,primaryVelocity=projectileMotion(primary,record,os.clock())
        if not primaryPosition or not threat(ctx,primaryPosition,primaryVelocity) then return false end
        local motions={}
        for projectile,record in pairs(dodge.Tracked) do
            if projectile.Parent then
                local position,velocity=projectileMotion(projectile,record,os.clock())
                if position then table.insert(motions,{Position=position,Velocity=velocity}) end
            end
        end
        for _,motion in ipairs(motions) do
            if not knifeTeleportClearance(ctx,action.Position,motion,{},floorY) then return false end
        end
        return true
    end
    function teleportCommit.Move(ctx,point)
        local root,char=ctx.Root,ctx.Character
        local offset=root.CFrame:ToObjectSpace(char:GetPivot())
        local target=CFrame.new(point)*root.CFrame.Rotation*offset
        local vertical=root.AssemblyLinearVelocity.Y
        char:PivotTo(target)
        root.AssemblyLinearVelocity=Vector3.new(0,vertical,0)
        root.AssemblyAngularVelocity=Vector3.zero
    end
    local function step()
        local pause=pauseReason()
        if pause then
            dodge.Direction, dodge.Character = nil, nil
            dodge.Status=pause
            return
        end
        local char = player.Character
        local hum, root = char and char:FindFirstChildOfClass("Humanoid"), char and char:FindFirstChild("HumanoidRootPart")
        if not hum or not root or hum.Sit or hum.PlatformStand or root.Anchored then
            dodge.Direction, dodge.Character = nil, nil
            dodge.Status="Paused: character unavailable, seated or controlled"
            return
        end
        local now = os.clock()
        local ctx, soonest, projectileRecord = nil, nil, nil
        local motions={}
        dodge.ValidMotions=0
        if not dodge.Direction then dodge.Status="Watching for incoming thrown knives" end
        for projectile, record in pairs(dodge.Tracked) do
            if not projectile.Parent then dodge.Tracked[projectile] = nil
            else
                local position, velocity = projectileMotion(projectile,record,now)
                if position and (position - root.Position).Magnitude < math.clamp(velocity.Magnitude*.6+8,60,600) then
                    dodge.ValidMotions+=1
                    table.insert(motions,{Position=position,Velocity=velocity})
                    ctx = ctx or context(char, root, hum)
                    local retry=State.Config.KnifeDodgeMode=="Side teleport" and (record.Attempts or 0)<2 and now-(record.LastDodgeAt or -math.huge)>=.35
                    if not record.Handled or retry then
                        local incoming = threat(ctx, position, velocity)
                        if incoming then incoming.Projectile=projectile end
                        if incoming and (not soonest or incoming.Time < soonest.Time) then soonest, projectileRecord = incoming, record end
                    end
                end
            end
        end
        if soonest then
            local action,teleported
            if State.Config.KnifeDodgeMode=="Side teleport" and now>=(dodge.NextTeleport or 0) and (projectileRecord.TeleportFailures or 0)<2 then
                action=planKnifeTeleport(teleportChecks,ctx,soonest,motions)
                if action then
                    local failure
                    teleported,failure=commitKnifeTeleport(teleportCommit,ctx,action)
                    if failure=="Move failed" then projectileRecord.TeleportFailures=(projectileRecord.TeleportFailures or 0)+1 end
                end
            end
            if not teleported then action=choose(ctx,soonest) end
            if player.Character~=char or hum.Health<=0 or not State.Running or not State.Config.AutoKnifeDodge or pauseReason() then
                dodge.Direction,dodge.Character=nil,nil; return
            end
            if action then
                projectileRecord.Handled = true
                projectileRecord.Attempts=(projectileRecord.Attempts or 0)+1
                projectileRecord.LastDodgeAt=now
                dodge.Decisions += 1
                dodge.LastAction = {Kind = action.Kind, TimeToImpact = soonest.Time, KnifeHeight = soonest.Height,
                    Clearance = action.Clearance, Late = action.Late, At = now,Distance=action.Distance}
                if teleported then
                    dodge.Direction,dodge.Character=nil,nil
                    dodge.Status=("Side teleport sent  ·  %.1f studs"):format(action.Distance)
                elseif action.Kind == "Jump" then
                    hum.Jump = true
                    hum:ChangeState(Enum.HumanoidStateType.Jumping)
                    dodge.Jumps += 1
                    dodge.Status = "Jumped over incoming low knife"
                else
                    dodge.Direction, dodge.Character, dodge.Until = action.Direction, char, now + action.Duration
                    dodge.Sidesteps += 1
                    dodge.Status = action.Late and "Late knife: attempting sidestep" or "Sidestepping incoming knife"
                end
            else dodge.Status = "Incoming knife: no clear dodge route" end
        end
        if dodge.Direction then
            if char == dodge.Character and now < dodge.Until then hum:Move(dodge.Direction, false)
            else dodge.Direction, dodge.Character = nil, nil end
        end
    end
    installKnifeDodgeLifecycle({State=State,Dodge=dodge,Step=step,Connect=connect,
        Bind=function(callback) RunService:BindToRenderStep(bindName,Enum.RenderPriority.Input.Value+2,callback) end,
        Unbind=function() RunService:UnbindFromRenderStep(bindName) end,
        FocusLost=UIS.WindowFocusReleased,FocusGained=UIS.WindowFocused,CharacterRemoving=player.CharacterRemoving,
        Refresh=function() if refreshButtons.AutoKnifeDodge then refreshButtons.AutoKnifeDodge() end end})
    function State.TestKnifeDodge()
        local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
        if not root then return {OK = false, Error = "Character unavailable"} end
        local folder = Instance.new("Folder")
        folder.Name, folder.Parent = "MM2KnifeDodgeProbe", workspace
        local result = {}
        local ok, message = pcall(function()
            local base = root.Position + Vector3.new(100, 500, 0)
            local floor = Instance.new("Part")
            floor.Anchored, floor.Size, floor.Position, floor.Parent = true, Vector3.new(50, 2, 50), base, folder
            local char = Instance.new("Model")
            char.Parent = folder
            local params = RaycastParams.new()
            params.FilterType, params.FilterDescendantsInstances, params.RespectCanCollide = Enum.RaycastFilterType.Exclude, {char}, true
            local overlap=OverlapParams.new()
            overlap.FilterType,overlap.FilterDescendantsInstances,overlap.RespectCanCollide=Enum.RaycastFilterType.Exclude,{char},true
            local ctx = {Character = char, Position = base + Vector3.new(0, 4, 0), Velocity = Vector3.zero,
                Low = base.Y + 1.05, High = base.Y + 6.5, Radius = 1.4, Params = params, Gravity = 196.2,
                JumpVelocity = 50, WalkSpeed = 16, Grounded = true, JumpEnabled = true, Reaction = 0.04,
                Overlap=overlap,Now=os.clock(),Horizon=.55}
            local function incoming(height, x, velocity)
                return threat(ctx, Vector3.new(ctx.Position.X + (x or 0), height, ctx.Position.Z - 24), velocity or Vector3.new(0, 0, 96))
            end
            local low = incoming(ctx.Low + 0.5)
            result.LowKnifeDetected = low ~= nil
            result.LowKnifeJump = low and choose(ctx, low).Kind == "Jump"
            local high = incoming(ctx.High - 1)
            result.HighKnifeSide = high and choose(ctx, high).Kind == "Side"
            local teleport=high and planKnifeTeleport(teleportChecks,ctx,high,{})
            result.SideTeleportPlanned=teleport and teleport.Kind=="Teleport" and teleport.Distance<=8.5 or false
            result.PassingKnifeIgnored = incoming(ctx.Low + 1, 8) == nil
            result.RecedingKnifeIgnored = incoming(ctx.Low + 1, 0, Vector3.new(0, 0, -96)) == nil
            local ceiling = Instance.new("Part")
            ceiling.Anchored, ceiling.Size, ceiling.Position, ceiling.Parent = true, Vector3.new(20, 1, 20), base + Vector3.new(0, 7.5, 0), folder
            result.LowCeilingUsesSide = choose(ctx, low).Kind == "Side"
            ceiling:Destroy()
            local wall = Instance.new("Part")
            wall.Anchored, wall.Size, wall.Position, wall.Parent = true, Vector3.new(1, 12, 15), base + Vector3.new(-3, 6, 0), folder
            local side = choose(ctx, high)
            result.BlockedSideRejected = side and side.Direction.X > 0
            wall:Destroy()
            local obstruction = Instance.new("Part")
            obstruction.Anchored, obstruction.Size, obstruction.Position, obstruction.Parent = true, Vector3.new(10, 10, 1), base + Vector3.new(0, 5, -12), folder
            result.KnifeBehindWallIgnored = incoming(ctx.Low + 0.5) == nil
            obstruction:Destroy()
            local ownProjectile = Instance.new("Model")
            ownProjectile.Parent = folder
            local link = Instance.new("ObjectValue")
            link.Name, link.Value, link.Parent = "HandleLink", root, ownProjectile
            result.OwnKnifeIgnored = projectileMotion(ownProjectile) == nil
            ownProjectile:Destroy()
            ctx.Position, ctx.Low, ctx.High = ctx.Position + Vector3.new(0, 4, 0), ctx.Low + 4, ctx.High + 4
            ctx.Grounded, ctx.Velocity = false, Vector3.new(0, -35, 0)
            local landingKnife = incoming(base.Y + 1.55)
            result.LandingKnifeDetected = landingKnife ~= nil
            result.AirborneSidestep = landingKnife and choose(ctx, landingKnife).Kind == "Side"
            ctx.Position, ctx.Low, ctx.High = ctx.Position - Vector3.new(0, 4, 0), ctx.Low - 4, ctx.High - 4
            ctx.Grounded, ctx.Velocity = true, Vector3.zero
            floor:Destroy()
            result.LedgeRejected = choose(ctx, high) == nil
            result.TeleportLedgeRejected=planKnifeTeleport(teleportChecks,ctx,high,{})==nil
            result.OK = result.LowKnifeDetected and result.LowKnifeJump and result.HighKnifeSide and result.PassingKnifeIgnored
                and result.RecedingKnifeIgnored and result.LowCeilingUsesSide and result.BlockedSideRejected
                and result.KnifeBehindWallIgnored and result.LedgeRejected and result.OwnKnifeIgnored
                and result.LandingKnifeDetected and result.AirborneSidestep and result.SideTeleportPlanned and result.TeleportLedgeRejected
        end)
        folder:Destroy()
        if not ok then result.OK, result.Error = false, tostring(message) end
        return result
    end
end

local weaponServiceScript = RS.ClientServices:FindFirstChild("WeaponService")
local gunFired = weaponServiceScript and weaponServiceScript:FindFirstChild("GunFired")
if gunFired and gunFired:IsA("RemoteEvent") then
    connect(gunFired.OnClientEvent, function(item, origin, endpoint, hitPart)
        local now = os.clock()
        local match, correlation = State.MatchGunFeedback(item,origin,endpoint,hitPart,player.Character,now)
        State.LastGunReplyCorrelation = correlation
        if not match then return end
        local pending = table.remove(State.PendingGun, match)
        State.Stats.GunReplies += 1
        -- Show the firing animation only after the server reports a real shot.
        local shootTrack = pending.Record and pending.Record.Tracks.Shoot
        if shootTrack then pcall(function() shootTrack:Play(0.1) end) end
        local responseTime = os.clock() - pending.SentAt
        -- Includes processing, transport and scheduling; cannot identify one-way latency.
        State.LastGunResponseSeconds = responseTime
        State.MeasuredGunDelay = nil
        local targetChar = pending.TargetCharacter or (pending.Target and pending.Target.Character)
        local targetRoot = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
        local hitPath = typeof(hitPart) == "Instance" and hitPart:GetFullName() or nil
        local hitTarget = targetChar and typeof(hitPart) == "Instance" and hitPart:IsDescendantOf(targetChar) or false
        if not hitTarget and typeof(hitPart) == "Instance" and hitPart:IsA("BasePart") then
            State.ServerBlockers[hitPart] = true
        end
        if pending.Target then
            if hitTarget then State.Stats.GunTargetHits += 1 else State.Stats.GunMisses += 1 end
        end
        if pending.ShotId == State.GunShotSequence then
        State.LastGunFeedback = {Target = pending.Target and pending.Target.Name,
            TargetHit = hitTarget, Correlation = correlation, ShotId = pending.ShotId, Endpoint = endpoint, HitPart = typeof(hitPart) == "Instance" and hitPart.Name or nil,
            SentAt = pending.SentAt,
            Message = hitTarget and "Reported ray hit target (heuristic match)"
                or pending.Target and (hitPath and ("Reported ray hit " .. hitPart.Name .. " instead of target (heuristic match)")
                or "Reported ray missed target (heuristic match)") or "Server shot received"}
        end
        local angle
        if typeof(endpoint) == "Vector3" and pending.AimPoint then
            local wanted, actual = pending.AimPoint - pending.Origin, endpoint - pending.Origin
            if wanted.Magnitude > 0 and actual.Magnitude > 0 then
                angle = math.deg(math.acos(math.clamp(wanted.Unit:Dot(actual.Unit), -1, 1)))
            end
        end
        table.insert(State.ShotLog, {Target = pending.Target and pending.Target.Name, TargetHit = hitTarget, Confirmed = false, Correlation = correlation, ShotId = pending.ShotId,
            RequestedPoint = pending.AimPoint, BodyPoint = pending.BodyPoint, Endpoint = endpoint,
            TargetVelocity = pending.Velocity, LeadTime = pending.LeadTime, Airborne = pending.Airborne,
            AimPart = pending.AimPart, SampleOffset = pending.SampleOffset, VelocitySource = pending.VelocitySource,
            TargetMode = pending.TargetMode,
            ExposureQuality = pending.ExposureQuality, ClearNeighbours = pending.ClearNeighbours,
            TimingCoverage = pending.TimingCoverage, TimingPassed = pending.TimingPassed,
            HitPath = hitPath, TargetRootAtReply = targetRoot and targetRoot.Position,
            TargetVelocityAtReply = targetRoot and targetRoot.AssemblyLinearVelocity, Origin = pending.Origin,
            CursorDistance = pending.CursorDistance, RayAngleErrorDegrees = angle, ResponseSeconds = responseTime})
        if #State.ShotLog > 10 then table.remove(State.ShotLog, 1) end
    end)
end
local victory = gameplayRemotes and gameplayRemotes:FindFirstChild("VictoryScreen")
if victory and victory:IsA("RemoteEvent") then
    connect(victory.OnClientEvent, function(won, role, reason, winner)
        local winnerMatches = winner == player.Name or winner == player
        if won and winnerMatches and (role == "Sheriff" or role == "Hero")
            and (reason == "MurdererDied" or reason == "SheriffWin")
            and State.LastGunSentAt and os.clock() - State.LastGunSentAt < 5 then
            State.LastGunFeedback = {RoundWon = true, SentAt = State.LastGunSentAt,
                Message = "Sheriff victory after your shot"}
        end
    end)
end
local function stopTracks(record)
    for _, track in pairs(record.Tracks) do pcall(function() track:Stop(0.1) end) end
end
local function playTrack(record, name, speed)
    local track = record.Tracks[name]
    if track then pcall(function() track:Play(0.1, 1, speed or 1) end) end
end
local function loadTracks(record)
    local char = player.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    local animator = hum and hum:FindFirstChildOfClass("Animator")
    if not animator then return end
    local animationFolder = record.Kind == "Gun" and record.Item:FindFirstChild("Animations") or record.Backup
    if not animationFolder then return end
    for _, name in ipairs({"Shoot", "Reload", "Slash", "Downstab", "ThrowCharge", "ThrowHold", "ThrowKnife"}) do
        local animation = animationFolder:FindFirstChild(name)
        if animation and animation:IsA("Animation") then
            local success, track = pcall(animator.LoadAnimation, animator, animation)
            if success then record.Tracks[name] = track end
        end
    end
end
local function restoreHandler(item)
    local record = State.WeaponHandlers[item]
    if not record then return end
    record.Active = false
    record.ThrowToken += 1
    for _, connection in ipairs(record.Connections) do connection:Disconnect() end
    stopTracks(record)
    for _, track in pairs(record.Tracks) do pcall(function() track:Destroy() end) end
    State.WeaponHandlers[item] = nil
    local backup = record.Backup
    if owned(item) and backup then
        local equipped = item.Parent == player.Character
        if equipped then item.Parent = player:FindFirstChild("Backpack") end
        -- The native clients move these objects during initialization. Put them
        -- back before starting the saved script, or its WaitForChild never finishes.
        if record.Kind == "Knife" then
            local sounds, handle = item:FindFirstChild("Sounds"), item:FindFirstChild("Handle")
            local sound = handle and handle:FindFirstChild("Throw")
            if sounds and sound and not sounds:FindFirstChild("Throw") then sound.Parent = sounds end
        elseif record.Kind == "Gun" then
            local cantShoot = item:FindFirstChild("CantShoot")
            if cantShoot and not backup:FindFirstChild("CantShoot") then cantShoot.Parent = backup end
        end
        backup.Parent = item
        backup.Enabled = record.NativeEnabled
        if equipped then
            local char = player.Character
            task.delay(0.15, function()
                -- A subsequent takeover destroys this clone, cancelling re-equip.
                if backup.Parent == item and item.Parent == player:FindFirstChild("Backpack") and player.Character == char then
                    local hum = char and char:FindFirstChildOfClass("Humanoid")
                    if hum and hum.Health > 0 then hum:EquipTool(item) end
                end
            end)
        end
    elseif backup then backup:Destroy() end
end
local function ready(record)
    return State.Running and not mobileBlocked() and State.Config.Aim and record.Active
        and not (State.ExperimentalInvis and State.ExperimentalInvis.Busy)
        and not State.Invis.Busy
        and record.Item.Parent == player.Character and alive(player) and State.CanUseCombatWeapon(record.Kind)
        and record.Item:GetAttribute("Disabled") ~= true and not UIS:GetFocusedTextBox()
end
function State.ExcludedPlayerInShotPath(origin, destination)
    for _, other in ipairs(Players:GetPlayers()) do
        local char = other.Character
        if other ~= player and char and State.IsPlayerExcluded(other) then
            for _, part in ipairs(char:GetDescendants()) do
                if part:IsA("BasePart") and part.Parent == char
                    and (bodyPartSet[part.Name] or part.Name == "HumanoidRootPart")
                    and segmentHitsBox(origin, destination, part.CFrame, part.Size) then return true end
            end
        end
    end
    return false
end
local function aimPoint(record, preferred, strict, origin, onScreenOnly)
    sampleMotion(os.clock(), true)
    State.Stats.AimCalls += 1
    if record.Kind == "Knife" and not State.Config.KnifeAim then return weapon:GetMouseTargetCFrame(), nil end
    local target = chooseTarget(record.Kind, origin or shotOrigin(record.Kind, record.Item), record.Item, preferred, strict,onScreenOnly)
    if target then
        State.Stats.Redirects += 1
        if record.Kind == "Knife" then State.Stats.KnifeRedirects += 1 end
        State.Target = target.Player.Name
        return CFrame.new(target.Position), target.Player.Name, target
    end
    -- Never replace a failed target selection with an unaimed cursor shot.
    return nil, nil
end
do
-- Predict only other players' possible ray obstruction; never move or resize an avatar.
local installGunPathGuard=function(C)
    local State,player=C.State,C.Player
    local clock=C.Clock or os.clock
    local function finite(v)
        return v and v.X==v.X and v.Y==v.Y and v.Z==v.Z
            and math.abs(v.X)<1e7 and math.abs(v.Y)<1e7 and math.abs(v.Z)<1e7
    end
    -- Segment versus an OBB swept through a constant translation. In box space
    -- the Minkowski difference has five generators (three box axes, ray, motion).
    -- The ten pairwise cross-product axes give a continuous SAT test, without
    -- filling the empty corners of an expanded enclosing box.
    local function sweptIntersects(origin,point,entry,age,horizon)
        if entry.Velocity.Magnitude<.000001 then
            return C.Intersects(origin,point,entry.Frame,entry.Size)
        end
        local frame=entry.Frame
        local start=frame:PointToObjectSpace(origin)
        local finish=frame:PointToObjectSpace(point)
        local velocity=frame:VectorToObjectSpace(entry.Velocity)
        local d=(finish-start)*.5
        local v=velocity*(horizon*.5)
        local c=(start+finish)*.5-velocity*(age+horizon*.5)
        local h=entry.Size*.5
        local function separated(x,y,z)
            local norm=math.sqrt(x*x+y*y+z*z)
            if norm<1e-12 then return false end
            local distance=math.abs(c.X*x+c.Y*y+c.Z*z)
            local extent=h.X*math.abs(x)+h.Y*math.abs(y)+h.Z*math.abs(z)
                +math.abs(d.X*x+d.Y*y+d.Z*z)+math.abs(v.X*x+v.Y*y+v.Z*z)
            return distance>extent+1e-6*norm
        end
        return not (separated(1,0,0) or separated(0,1,0) or separated(0,0,1)
            or separated(0,-d.Z,d.Y) or separated(d.Z,0,-d.X) or separated(-d.Y,d.X,0)
            or separated(0,-v.Z,v.Y) or separated(v.Z,0,-v.X) or separated(-v.Y,v.X,0)
            or separated(d.Y*v.Z-d.Z*v.Y,d.Z*v.X-d.X*v.Z,d.X*v.Y-d.Y*v.X))
    end
    function State.CreateGunPathSnapshot()
        local delay=tonumber(State.Config.Ping) or 0
        if delay~=delay then delay=0 end
        delay=math.clamp(delay,0,.15)
        local margin=math.clamp(delay*.25,.012,.035)
        local times={0,math.max(0,delay-margin),delay,math.min(.185,delay+margin)}
        local snapshot={Time=clock(),Groups={},Times=times,Horizon=times[4],Parts=0}
        local ignored={}
        for _,o in ipairs(C.GetPassthrough()) do ignored[o]=true end
        local function passthrough(part)
            local node=part
            while node do
                if ignored[node] then return true end
                node=node.Parent
            end
            return false
        end
        for _,p in ipairs(C.Players:GetPlayers()) do
            local char=p.Character
            local root=char and char:FindFirstChild("HumanoidRootPart")
            if p~=player and root and finite(root.Position) then
                local group={Character=char,Name=p.Name,Centre=root.Position,Radius=0,MaxSpeed=0,Parts={}}
                for _,part in ipairs(char:GetDescendants()) do
                    if part:IsA("BasePart") and (part.CanQuery or part.CanCollide or State.ServerBlockers[part])
                        and (part.Transparency<1 or State.ServerBlockers[part]) and not passthrough(part)
                        and finite(part.Position) and finite(part.Size) then
                        if snapshot.Parts>=512 then snapshot.Truncated=true; break end
                        local ok,velocity=pcall(function() return root:GetVelocityAtPosition(part.Position) end)
                        if not ok or not finite(velocity) then velocity=root.AssemblyLinearVelocity end
                        if not finite(velocity) then velocity=Vector3.zero end
                        if velocity.Magnitude>900 then velocity=velocity.Unit*900 end
                        local radius=(part.Position-group.Centre).Magnitude+part.Size.Magnitude*.5
                            +velocity.Magnitude*times[4]+.05
                        group.Radius=math.max(group.Radius,radius)
                        group.MaxSpeed=math.max(group.MaxSpeed,velocity.Magnitude)
                        table.insert(group.Parts,{Part=part,Frame=part.CFrame,Size=part.Size,Velocity=velocity,Time=clock()})
                        snapshot.Parts+=1
                    end
                end
                if #group.Parts>0 then table.insert(snapshot.Groups,group) end
                if snapshot.Truncated then break end
            end
        end
        return snapshot
    end
    function State.GunPathClear(snapshot,origin,point,targetCharacter)
        if not snapshot then return true end
        local now=clock()
        local age=now-snapshot.Time
        if age<0 or age>.25 or snapshot.Truncated then return false end
        local delta=point-origin
        local lengthSquared=delta:Dot(delta)
        if lengthSquared<.000001 then return false end
        for _,group in ipairs(snapshot.Groups) do
            if group.Character~=targetCharacter then
                local t=math.clamp((group.Centre-origin):Dot(delta)/lengthSquared,0,1)
                local distance=group.Centre-(origin+delta*t)
                local radius=group.Radius+(group.MaxSpeed or 0)*age
                if distance:Dot(distance)<=radius*radius then
                    for _,entry in ipairs(group.Parts) do
                        if entry.Part:IsDescendantOf(group.Character) then
                            local elapsed=math.max(0,now-(entry.Time or snapshot.Time))
                            local horizon=snapshot.Horizon or snapshot.Times[4]
                            if sweptIntersects(origin,point,entry,elapsed,horizon) then
                                State.LastGunPathBlock={Player=group.Name,Part=entry.Part.Name,
                                    LookAhead=horizon,SnapshotAge=elapsed,Continuous=true}
                                return false
                            end
                        end
                    end
                end
            end
        end
        return true
    end
end

installGunPathGuard({State=State,Player=player,Players=Players,Intersects=segmentHitsBox,
    GetPassthrough=function() return CollectionService:GetTagged("WeaponPassthrough") end})
end
local function sendGun(record, preferred, strict, onScreenOnly)
    if not record or record.GunSending or not State.Config.MagicBullet then return end
    if State.ExitUndergroundForAttack and not State.ExitUndergroundForAttack("Gun") then return end
    if not State.Config.MagicBullet or not ready(record) or os.clock()-record.LastGun<0.1 then return end
    local function skip(message)
        State.Stats.SkippedGunShots+=1
        State.LastGunFeedback={Message=message}
        return false
    end
    if not record.Item.Enabled then return skip("Gun is not ready to fire") end
    local ownCharacter=player.Character
    local root=ownCharacter and ownCharacter:FindFirstChild("HumanoidRootPart")
    local attachment=root and root:FindFirstChild("GunRaycastAttachment")
    local remote=record.Item:FindFirstChild("Shoot")
    if not attachment or not remote or not remote:IsA("RemoteEvent") then
        return skip("Gun attachment or firing remote unavailable")
    end
    local function finite(v)
        return typeof(v)=="Vector3" and v.X==v.X and v.Y==v.Y and v.Z==v.Z
            and math.abs(v.X)<1e8 and math.abs(v.Y)<1e8 and math.abs(v.Z)<1e8
    end
    local originFrame=attachment.WorldCFrame
    local snapshot=State.CreateGunPathSnapshot and State.CreateGunPathSnapshot()
    local function selectAim()
        State.GunPathSnapshot=snapshot
        local ok,frame,name,found=pcall(aimPoint,record,preferred,strict,originFrame.Position,onScreenOnly)
        State.GunPathSnapshot=nil
        if not ok then return nil,nil,nil,tostring(frame) end
        return frame,name,found
    end
    local targetFrame,targetName,solution,aimError=selectAim()
    if aimError then return skip("Shot cancelled: aiming failed: "..aimError) end
    -- Recalculate once if the muzzle moved materially while selecting a body point.
    if player.Character~=ownCharacter or not ready(record) or not record.Item.Enabled then
        return skip("Shot cancelled: weapon or character changed")
    end
    if root:FindFirstChild("GunRaycastAttachment")~=attachment then
        return skip("Shot cancelled: muzzle attachment changed")
    end
    if (attachment.WorldPosition-originFrame.Position).Magnitude>.25 then
        originFrame=attachment.WorldCFrame
        targetFrame,targetName,solution,aimError=selectAim()
        if aimError then return skip("Shot cancelled: aiming failed: "..aimError) end
    end
    if not targetFrame or typeof(targetFrame)~="CFrame" or not finite(targetFrame.Position) then
        return skip(State.Config.ConservativeGun and "Shot skipped: no clear target passes timing checks; reposition and fire again"
            or "Shot skipped: no clear finite target")
    end
    if State.Config.ConservativeGun and (not solution or solution.TimingCoverage~=1
        or not solution.TimingPassed or solution.TimingPassed<5) then
        return skip("Shot skipped: uncertain target timing; reposition and fire again")
    end
    local targetPlayer=targetName and Players:FindFirstChild(targetName)
    local targetCharacter=solution and solution.Character or targetPlayer and targetPlayer.Character
    if not targetPlayer or not targetCharacter or targetPlayer.Character~=targetCharacter
        or State.IsPlayerExcluded(targetPlayer) or not alive(targetPlayer) or not State.IsCombatTarget("Gun",targetPlayer) then
        return skip("Shot cancelled: target changed or is protected")
    end
    if player.Character~=ownCharacter or not ready(record) or not record.Item.Enabled
        or root:FindFirstChild("GunRaycastAttachment")~=attachment then
        return skip("Shot cancelled: weapon or character changed")
    end
    -- Keep the selected origin in both the pending record and payload. A second
    -- large movement after the bounded recalculation invalidates this click.
    if (attachment.WorldPosition-originFrame.Position).Magnitude>.25 then
        return skip("Shot cancelled: muzzle moved during aiming; fire again")
    end
    local origin=originFrame.Position
    local head=ownCharacter:FindFirstChild("Head")
    if not finite(origin) or (targetFrame.Position-origin).Magnitude<.001 then
        return skip("Shot skipped: invalid shot geometry")
    end
    if head and not clearPath(head.Position,origin,ownCharacter) then
        return skip("Shot skipped: muzzle obstructed")
    end
    if not clearPath(origin,targetFrame.Position,targetCharacter,true) then
        return skip("Shot skipped: firing path became blocked")
    end
    if State.GunPathClear and not State.GunPathClear(snapshot,origin,targetFrame.Position,targetCharacter) then
        return skip("Shot skipped: another player may cross the firing path")
    end
    if State.ExcludedPlayerInShotPath(origin,targetFrame.Position) then
        return skip("Shot skipped: excluded player in firing path")
    end
    if onScreenOnly and (not solution or not State.IsAimPointOnScreen(solution.BodyPoint,targetCharacter)
        or not State.IsAimPointOnScreen(targetFrame.Position)) then
        return skip("Shot skipped: assisted target left the screen")
    end
    local previousLastGun,previousSentAt=record.LastGun,State.LastGunSentAt
    local now=os.clock()
    record.LastGun=now
    State.LastGunSentAt=now
    State.GunShotSequence = (State.GunShotSequence or 0) + 1
    local shotId=State.GunShotSequence
    State.LastGunFeedback={ShotId=shotId,SentAt=now,Message="Waiting for server shot feedback"}
    local pending={Item=record.Item,Record=record,Target=targetPlayer,ShotId=shotId,
        OwnCharacter = player.Character,TargetCharacter=targetCharacter,
        Origin=origin,SentAt=now,AimPoint=targetFrame.Position,
        BodyPoint=solution and solution.BodyPoint,Velocity=solution and solution.Velocity,
        LeadTime=solution and solution.LeadTime,Airborne=solution and solution.Airborne,
        AimPart=solution and solution.AimPart,SampleOffset=solution and solution.SampleOffset,
        VelocitySource=solution and solution.VelocitySource,TargetMode=solution and solution.TargetMode,
        ExposureQuality=solution and solution.ExposureQuality,ClearNeighbours=solution and solution.ClearNeighbours,
        TimingCoverage=solution and solution.TimingCoverage,TimingPassed=solution and solution.TimingPassed,
        CursorDistance=solution and solution.CursorDistance,OnScreenOnly=onScreenOnly==true}
    table.insert(State.PendingGun,pending)
    record.GunSending=true
    local sent,why=pcall(function() remote:FireServer(originFrame,targetFrame) end)
    record.GunSending=false
    if not sent then
        for i=#State.PendingGun,1,-1 do
            if State.PendingGun[i]==pending then table.remove(State.PendingGun,i); break end
        end
        if State.GunShotSequence==shotId then
            record.LastGun,State.LastGunSentAt=previousLastGun,previousSentAt
            State.LastGunFeedback={ShotId=shotId,Message="Shot request failed: "..tostring(why)}
        end
        State.Stats.GunSendErrors=(State.Stats.GunSendErrors or 0)+1
        return false
    end
    while #State.PendingGun>8 do table.remove(State.PendingGun,1) end
    State.Stats.GunRequests+=1
    State.LastRequest={Weapon="Gun",Target=targetName,Position=targetFrame.Position,
        Offscreen=solution and solution.Offscreen,Mode=onScreenOnly and "OnScreenAssist" or "MagicBullet",AimPart=solution and solution.AimPart,
        TargetMode=solution and solution.TargetMode}
    return true
end


do
-- Bounded, paired blade-touch requests. Sending either request is not proof of damage.
local installAuraTouch=function(C)
    local State,player=C.State,C.Player
    local clock=C.Clock or os.clock
    local pending={}
    local report={Available=type(C.Touch)=="function",Begins=0,Ends=0,Errors=0,Pending=0,Status="Idle"}
    State.AuraTouch=report
    local function finish(record,pair)
        if pending[record]~=pair then return true end
        local ok,why=pcall(C.Touch,pair.Handle,pair.Hit,1)
        if ok then
            pending[record]=nil; report.Pending-=1; report.Ends+=1
            report.Status="Touch ended; damage unconfirmed"
        else
            report.Errors+=1; report.Status="Touch cleanup failed: "..tostring(why)
        end
        return ok,why
    end
    function State.FlushAuraTouches(record)
        local success=true
        if record then
            local pair=pending[record]
            if pair then success=finish(record,pair) end
        else
            for owner,pair in pairs(pending) do
                if not finish(owner,pair) then success=false end
            end
        end
        return success,report.Status
    end
    function State.TryAuraTouch(record,hit)
        if not report.Available then report.Status="Touch API unavailable; contact remote only"; return false end
        if not State.Running or not record.AuraStab or not State.CanAuraContact or not State.CanAuraContact()
            or clock()>record.StabbingUntil then return false end
        local target=record.StabTarget
        local char=target and target.Character
        local own=player.Character
        local handle=record.Item and record.Item:FindFirstChild("Handle")
        if not own or record.Item.Parent~=own or not handle or not handle:IsA("BasePart")
            or not hit or not hit:IsA("BasePart") or not char or not hit:IsDescendantOf(char)
            or State.IsPlayerExcluded(target) then return false end
        -- One outstanding pair per weapon; failed cleanup cannot create an unbounded backlog.
        if pending[record] then report.Status="Waiting for previous touch cleanup"; return false end
        if record.AuraTouchWindow==record.StabbingUntil then return false end
        local pair={Handle=handle,Hit=hit}
        pending[record]=pair; report.Pending+=1
        record.AuraTouchWindow=record.StabbingUntil
        -- Reserve the pair before begin: native Touched may re-enter the contact reporter.
        local ok,why=pcall(C.Touch,handle,hit,0)
        if ok then report.Begins+=1; report.Status="Touch requested; damage unconfirmed"
        else report.Errors+=1; report.Status="Touch begin failed: "..tostring(why) end
        -- End even after a partial begin error, cancellation, respawn or a replacement character.
        local scheduled=pcall(C.Schedule,0.04,function() finish(record,pair) end)
        if not scheduled then finish(record,pair) end
        return ok
    end
    return report
end

installAuraTouch({State=State,Player=player,Touch=type(firetouchinterest)=="function" and firetouchinterest or nil,Schedule=task.delay})
end
local function reportStabContact(record, hit, source)
    if not ready(record) or os.clock() > record.StabbingUntil or not hit or not hit:IsA("BasePart") then return end
    if record.AuraStab and (not State.CanAuraContact or not State.CanAuraContact()) then return end
    local burst=source=="KillAllBurst"
    if burst and (not record.AuraStab or not State.KillAll or not State.KillAll.Active) then return end
    record.StabContacts = record.StabContacts or {}
    if record.StabContacts[hit] then return end
    local ownRoot = player.Character:FindFirstChild("HumanoidRootPart")
    if not ownRoot then return end
    local locked=record.StabTarget
    if locked and Players:FindFirstChild(locked.Name)~=locked then return end
    local contactTargets=locked and {locked} or Players:GetPlayers()
    for _, other in ipairs(contactTargets) do
        local char = other.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if other ~= player and root and not State.IsPlayerExcluded(other) and alive(other) and State.IsCombatTarget("Knife",other) and (not record.StabTarget or other == record.StabTarget) and hit:IsDescendantOf(char)
            and (hit.Transparency < 1 or (hit.Parent == char and bodyPartSet[hit.Name]))
            and (root.Position - ownRoot.Position).Magnitude <= (record.AuraStab and State.GetKillAuraRange and State.GetKillAuraRange() or 7)
            and (burst or clearPath(ownRoot.Position, hit.Position, char)) then
            local events = record.Item:FindFirstChild("Events")
            local remote = events and events:FindFirstChild("HandleTouched")
            if remote then
                record.StabContactFailures=record.StabContactFailures or {}
                if (record.StabContactFailures[hit] or 0)>=2 then return end
                record.StabContacts[hit] = true
                local touched=record.AuraStab and State.TryAuraTouch and State.TryAuraTouch(record,hit) or false
                local sent,why=pcall(function() remote:FireServer(hit) end)
                State.LastStabContact = {Target=other.Name,Part=hit.Name,Source=source,
                    TouchRequested=touched,RemoteSent=sent,DamageConfirmed=false,Error=not sent and tostring(why) or nil}
                if not sent then
                    record.StabContacts[hit]=nil
                    record.StabContactFailures[hit]=(record.StabContactFailures[hit] or 0)+1
                    return
                end
                State.Stats.StabContactReports += 1
                if State.LastKnifeInput and State.LastKnifeInput.Action == "Stab" then State.LastKnifeInput.Target = other.Name end
            end
            return
        end
    end
end
local function scanStabContacts(record)
    if (not State.Config.StabSweep and not record.AuraStab) or record.Kind ~= "Knife" or not ready(record)
        or os.clock() > record.StabbingUntil then record.BladeFrame = nil; return end
    local handle = record.Item:FindFirstChild("Handle")
    if not handle or not handle:IsA("BasePart") then return end
    local frame, now = handle.CFrame, os.clock()
    local previous, previousTime = record.BladeFrame, record.BladeTime
    record.BladeFrame, record.BladeTime = frame, now
    local ownRoot = player.Character:FindFirstChild("HumanoidRootPart")
    local visibleParts = {}
    for _, other in ipairs(Players:GetPlayers()) do
        local char = other.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if other ~= player and root and not State.IsPlayerExcluded(other) and alive(other) and (not record.StabTarget or other == record.StabTarget) and (root.Position - ownRoot.Position).Magnitude <= 7 then
            for _, part in ipairs(char:GetDescendants()) do
                if part:IsA("BasePart") and (part.Transparency < 1 or (part.Parent == char and bodyPartSet[part.Name])) then
                    table.insert(visibleParts, part)
                end
            end
        end
    end
    if #visibleParts == 0 then return end
    local overlap = OverlapParams.new()
    overlap.FilterType = Enum.RaycastFilterType.Include
    overlap.FilterDescendantsInstances = visibleParts
    overlap.MaxParts = 24
    for _, hit in ipairs(workspace:GetPartsInPart(handle, overlap)) do reportStabContact(record, hit, "BladeOverlap") end
    if previous and previousTime and now - previousTime <= 0.12 then
        local movement = frame.Position - previous.Position
        if movement.Magnitude > 0.001 and movement.Magnitude <= 10 then
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Include
            params.FilterDescendantsInstances = visibleParts
            local hit = workspace:Blockcast(previous, handle.Size, movement, params)
            if hit then reportStabContact(record, hit.Instance, "BladeSweep") end
        end
    end
end
-- Select one nearby body point for a manual click; no automatic attack loop.
function State.SelectStabAssistTarget(onScreenOnly,automated)
    if (not automated and not State.Config.StabAssist) or not State.CanUseCombatWeapon("Knife") then return nil end
    local ownRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not ownRoot then return nil end
    local best, bestPart, bestDistance
    for _, other in ipairs(Players:GetPlayers()) do
        local char = other.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if other ~= player and root and alive(other) and not State.IsPlayerExcluded(other)
            and State.IsCombatTarget("Knife",other) then
            local distance = (root.Position - ownRoot.Position).Magnitude
            if distance <= 6.5 and (not bestDistance or distance < bestDistance) then
                for _, name in ipairs({"UpperTorso", "Torso", "Head", "LowerTorso"}) do
                    local part = char:FindFirstChild(name)
                    if part and part:IsA("BasePart") and (not onScreenOnly or State.IsAimPointOnScreen(part.Position,char))
                        and clearPath(ownRoot.Position, part.Position, char) then
                        best, bestPart, bestDistance = other, part, distance
                        break
                    end
                end
            end
        end
    end
    return best, bestPart
end
local function stabKnife(record, preferred)
    if not ready(record) then return false end
    -- A click cancels an explicit throw even during the stab cooldown.
    record.ThrowToken += 1
    if record.Charging then
        record.Charging = false
        record.LastThrow = -math.huge
        stopTracks(record)
    end
    if os.clock() - record.LastStab < 0.85 then return false end
    -- The live KnifeClient gates stabs on the same 2 * ThrowSpeed interval
    -- as another throw. Avoid sending a stab while a released knife recovers.
    local throwSpeed = record.Item:GetAttribute("ThrowSpeed")
    throwSpeed = type(throwSpeed)=="number" and throwSpeed==throwSpeed and throwSpeed>0
        and throwSpeed<math.huge and throwSpeed or 1
    local remaining = 2 * throwSpeed - (os.clock() - record.LastThrow)
    if remaining > 0 then
        State.KnifeFeedback = {Message = ("Stab waiting for throw cooldown: %.1fs"):format(remaining), Until = os.clock() + 1.8}
        return false
    end
    local events = record.Item:FindFirstChild("Events")
    local remote = events and events:FindFirstChild("KnifeStabbed")
    if not remote or not remote:IsA("RemoteEvent") then return false end
    local sent, why = pcall(function() remote:FireServer() end)
    if not sent then
        State.KnifeFeedback = {Message = "Stab request failed: " .. tostring(why), Until = os.clock() + 1.8}
        return false
    end
    record.StabTarget = preferred
    record.AuraStab = false
    State.KnifeFeedback = nil
    record.LastStab = os.clock()
    record.StabbingUntil = os.clock() + 0.85
    record.StabContacts = {}
    record.StabContactFailures = {}
    local handle = record.Item:FindFirstChild("Handle")
    record.BladeFrame, record.BladeTime = handle and handle.CFrame, os.clock()
    State.Stats.StabRequests += 1
    -- Optional local animation failures must not interrupt contact assistance.
    pcall(stopTracks, record)
    pcall(playTrack, record, math.random(1, 2) == 1 and "Slash" or "Downstab")
    return true
end
local function knifeFeedback(message)
    State.KnifeFeedback = {Message = message, Until = os.clock() + 1.8}
    State.AimStatus = message
end
local function startThrow(record, preferred, strict, canRelease)
    if record.Kind ~= "Knife" then return false end
    if State.CanThrowKnife and not State.CanThrowKnife() then knifeFeedback("This role / mode cannot throw knives"); return false end
    if State.ExitUndergroundForAttack and not State.ExitUndergroundForAttack("Knife") then return false end
    if not ready(record) then knifeFeedback("Equip a ready knife to throw"); return false end
    if strict and not State.Config.KnifeAim then knifeFeedback("Turn on Knife throw prediction for auto attack"); return false end
    if record.Charging then return false end
    local throwSpeed = record.Item:GetAttribute("ThrowSpeed")
    throwSpeed = type(throwSpeed)=="number" and throwSpeed==throwSpeed and throwSpeed>0 and throwSpeed<math.huge and throwSpeed or 1
    local cooldown = math.max(.4-(os.clock()-record.LastStab),2*throwSpeed-(os.clock()-record.LastThrow))
    if cooldown>0 then knifeFeedback(("Throw cooldown: %.1fs"):format(cooldown)); return false end
    local events=record.Item:FindFirstChild("Events")
    local remote=events and events:FindFirstChild("KnifeThrown")
    local handle=record.Item:FindFirstChild("Handle")
    if not remote or not remote:IsA("RemoteEvent") or not handle or not handle:IsA("BasePart") then knifeFeedback("Knife throw objects unavailable"); return false end
    local chosen=State.Config.KnifeAim and chooseTarget("Knife",handle.Position,record.Item,preferred,strict)
    if not chosen and (strict or (State.Config.KnifeAim and State.Config.RequireClearKnifeTarget)) then
        State.Stats.SkippedKnifeThrows += 1
        knifeFeedback("No clear throw target"); return false
    end
    record.KillAllThrow=nil
    record.Charging=true
    record.ThrowToken+=1
    local token=record.ThrowToken
    local chargedTarget=chosen and chosen.Player
    local chargedCharacter=chargedTarget and chargedTarget.Character
    record.ThrowTargetUserId=chargedTarget and chargedTarget.UserId
    record.LastThrow=os.clock()
    record.StabbingUntil=0
    record.AuraStab=false
    local sent=false
    State.KnifeFeedback=nil
    State.LastKnifeInput={Action="Throw",Target=chargedTarget and chargedTarget.Name}
    local function cancel(message)
        if record.ThrowToken~=token then return end
        record.Charging=false
        if not sent then record.LastThrow=-math.huge end
        pcall(stopTracks,record)
        if message then knifeFeedback(message) end
    end
    local ok,message=pcall(function() stopTracks(record); playTrack(record,"ThrowCharge",1/throwSpeed) end)
    if not ok then cancel("Throw animation failed: "..tostring(message)); return false end
    task.spawn(function()
        local success,why=pcall(function()
            task.wait(throwSpeed)
            if record.ThrowToken~=token then return end
            if canRelease and not canRelease() then cancel("Throw cancelled: automatic action paused or stopped"); return end
            if not ready(record) then cancel("Throw cancelled: weapon is no longer ready"); return end
            if State.CanThrowKnife and not State.CanThrowKnife() then cancel("Throw cancelled: role / mode changed"); return end
            if record.Item:FindFirstChild("Handle")~=handle or record.Item:FindFirstChild("Events")~=events
                or events:FindFirstChild("KnifeThrown")~=remote then cancel("Throw cancelled: weapon objects changed"); return end
            if chargedTarget and (chargedTarget.Character~=chargedCharacter or not alive(chargedTarget)) then
                cancel("Throw cancelled: target is no longer alive in the same character"); return
            end
            if chargedTarget and State.IsPlayerExcluded(chargedTarget) then cancel("Throw cancelled: target excluded"); return end
            if (strict or (chargedTarget and State.Config.RequireClearKnifeTarget)) and not State.Config.KnifeAim then
                cancel("Throw cancelled: knife prediction disabled"); return
            end
            local originFrame=handle.CFrame
            local lockTarget=strict or (chargedTarget~=nil and State.Config.RequireClearKnifeTarget)
            local targetFrame,targetName,solution=aimPoint(record,chargedTarget,lockTarget,originFrame.Position)
            -- Cursor fallback is explicit; protected assisted throws keep their target.
            local manual=false
            if not targetFrame and not strict and (not State.Config.KnifeAim or not State.Config.RequireClearKnifeTarget) then
                targetFrame=weapon:GetMouseTargetCFrame(); targetName,solution=nil,nil; manual=true
            end
            if not targetFrame then
                State.Stats.SkippedKnifeThrows+=1; cancel("Throw cancelled: target no longer clear"); return
            end
            if solution and (not alive(solution.Player) or solution.Player.Character~=solution.Character
                or State.IsPlayerExcluded(solution.Player)
                or not clearPath(originFrame.Position,targetFrame.Position,solution.Character,true)) then
                State.Stats.SkippedKnifeThrows+=1; cancel("Throw cancelled: target or firing path changed"); return
            end
            if State.ExcludedPlayerInShotPath(originFrame.Position,targetFrame.Position) then
                State.Stats.SkippedKnifeThrows+=1; cancel("Throw cancelled: excluded player in firing path"); return
            end
            if not ready(record) or record.ThrowToken~=token then cancel(); return end
            remote:FireServer(originFrame,targetFrame)
            sent=true
            record.Charging=false
            State.Stats.KnifeRequests+=1
            State.LastRequest={Weapon="Knife",Target=targetName,Position=targetFrame.Position,
                LeadTime=solution and solution.LeadTime,AimPart=solution and solution.AimPart,
                VelocitySource=solution and solution.VelocitySource,ManualFallback=manual}
            knifeFeedback(manual and "Knife thrown toward your cursor (no clear assist target)"
                or targetName and ("Knife thrown toward "..targetName) or "Knife throw sent")
            stopTracks(record); playTrack(record,"ThrowKnife")
            local sound=handle:FindFirstChild("Throw")
            if sound and sound:IsA("Sound") then sound:Play() end
        end)
        if not success then cancel((sent and "Knife request sent; local effects failed: " or "Throw failed: ")..tostring(why)) end
    end)
    return true
end

local function clickKnife(record)
    if State.ExitUndergroundForAttack and not State.ExitUndergroundForAttack("Knife") then return end
    if not ready(record) then return end
    -- A stab cancels a pending charge before its release task can throw.
    State.LastKnifeInput = {Action = "Stab"}
    local target, part = State.SelectStabAssistTarget()
    if stabKnife(record, target) and part then
        reportStabContact(record, part, "ClickedStabAssist")
    end
end
local function takeOver(item)
    if State.WeaponHandlers[item] or not State.Config.Aim or not owned(item)
        or not item:IsA("Tool") or (item.Name ~= "Gun" and item.Name ~= "Knife") or not State.CanUseCombatWeapon(item.Name) then return end
    if item.Name == "Gun" and not State.Config.MagicBullet then return end
    local native = item:FindFirstChild(item.Name .. "Client")
    if not native or not native:IsA("LocalScript") then return end
    local success, backup = pcall(native.Clone, native)
    if not success or not backup then
        State.AimStatus = "Weapon backup unavailable"
        return
    end
    local record = {Item = item, Kind = item.Name, Backup = backup, NativeEnabled = native.Enabled,
        Connections = {}, Tracks = {}, Active = true, ThrowToken = 0, Charging = false,
        LastGun = -math.huge, LastStab = -math.huge, LastThrow = -math.huge, StabbingUntil = 0}
    backup.Enabled = false
    State.WeaponHandlers[item] = record
    -- Destroying the old local script removes its click callbacks; the saved clone
    -- restores it on toggle/unload. No server script or another player's tool changes.
    native.Enabled = false
    native:Destroy()
    if record.Kind == "Gun" then
        local cantShoot = item:FindFirstChild("CantShoot")
        if cantShoot and cantShoot:IsA("LayerCollector") then cantShoot.Enabled = false end
    end
    loadTracks(record)
    recordConnect(record, item.Activated, function()
        if record.Kind == "Gun" then
            if not touchInput() then sendGun(record) end
        else clickKnife(record) end
    end)
    recordConnect(record, item.Unequipped, function()
        record.ThrowToken += 1
        record.Charging = false
        record.StabbingUntil = 0
        stopTracks(record)
        if record.Kind == "Knife" then
            local hum = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.WalkSpeed = 16 end
        end
    end)
    if record.Kind == "Knife" then
        local function equippedSpeed()
            local hum = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.WalkSpeed = item:GetAttribute("EquippedPerk") == "Haste" and 18 or 17 end
        end
        recordConnect(record, item.Equipped, equippedSpeed)
        if item.Parent == player.Character then equippedSpeed() end
    end
    local handle = item:FindFirstChild("Handle")
    if record.Kind == "Knife" and handle then
        recordConnect(record, handle.Touched, function(hit)
            if ready(record) and os.clock() <= record.StabbingUntil then
                -- Native blade touches use the same exclusion check even with sweep OFF.
                reportStabContact(record, hit, "NativeTouch")
            end
        end)
    end
end
local function syncWeapons()
    local remove = {}
    for item, record in pairs(State.WeaponHandlers) do
        if not State.Config.Aim or not owned(item) or not State.CanUseCombatWeapon(record.Kind) or (record.Kind == "Gun" and not State.Config.MagicBullet) then
            table.insert(remove, item)
        end
    end
    for _, item in ipairs(remove) do restoreHandler(item) end
    if not State.Config.Aim then
        State.AimStatus = "Aim off"
        State.Target = nil
        State.AimPreview = nil
        return
    end
    if State.Invis.Busy then State.AimStatus = "Switching invisibility"; return end
    if State.ExperimentalInvis and State.ExperimentalInvis.Busy then
        State.AimStatus = "Going invisible  ·  Restore character cancels"
        State.Target, State.AimPreview = nil, nil
        return
    end
    local backpack = player:FindFirstChild("Backpack")
    if backpack then for _, item in ipairs(backpack:GetChildren()) do takeOver(item) end end
    local char = player.Character
    if char then for _, item in ipairs(char:GetChildren()) do takeOver(item) end end
    local item, kind = equippedWeapon()
    if not item or not alive(player) then
        State.AimStatus = "Equip a weapon"
        State.Target = nil
        State.AimPreview = nil
        return
    end
    if kind == "Gun" and not State.Config.MagicBullet then
        State.AimStatus = "Gun aim off"
        State.Target, State.AimPreview = nil, nil
        return
    end
    local target
    if kind == "Knife" and not State.Config.KnifeAim then
        target = nil -- the status only reports that knife aim is off; skip the full scan
    else
        target = State.GetCachedAimPreview(kind, item, shotOrigin(kind, item))
    end
    State.Target = target and target.Player.Name or nil
    State.AimPreview = kind == "Gun" and target and {Player = target.Player,
        Character = target.Player.Character, AimPart = target.AimPart, SampleOffset = target.SampleOffset, TargetMode = target.TargetMode} or nil
    local record = State.WeaponHandlers[item]
    if record and record.Charging then
        State.AimStatus = "Charging throw"
    elseif kind == "Knife" and State.KnifeFeedback and os.clock() < State.KnifeFeedback.Until then
        State.AimStatus = State.KnifeFeedback.Message
    elseif kind == "Knife" and not State.Config.KnifeAim then
        State.AimStatus = "Knife aim off"
    elseif kind == "Gun" then
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local targetRoot = target and target.Player.Character and target.Player.Character:FindFirstChild("HumanoidRootPart")
        local height = root and targetRoot and targetRoot.Position.Y - root.Position.Y or 0
        local elevation = height > 5 and "  ·  above" or (height < -5 and "  ·  below" or "")
        State.AimStatus = target and ((item.Enabled and "Gun ready  ·  " or "Reloading  ·  ")
            .. target.Player.DisplayName .. elevation
            .. (target.TargetMode == "Stationary" and "  ·  standing still" or (target.TargetMode == "Approaching" and "  ·  approaching" or ""))
            .. (target.Offscreen and "  ·  off screen" or "")) or "No clear shot at an eligible opponent"
    else
        State.AimStatus = target and ("Knife ready  ·  " .. target.Player.DisplayName .. (target.Offscreen and "  ·  off screen" or ""))
            or "No clear target"
    end
end
do
local installWeaponEquipRecovery=function(C)
    local State=C.State
    local clock=C.Clock or os.clock
    local report={Presses=0,Recoveries=0,Skipped=0,Failures=0,NativeSignals=0,Status="Waiting for slot 1 input"}
    State.WeaponEquipRecovery=report
    if not State.Config.WeaponEquipRecovery then report.Status="Off" end
    local focused=true
    local stable,watched,watch,action,actionWatch,revision,nativeAt,token=nil,nil,nil,nil,nil,0,-math.huge,0
    local function clear()
        token+=1; stable=nil
        if watch then watch:Disconnect(); watch=nil end
        if actionWatch then actionWatch:Disconnect(); actionWatch=nil end
        watched,action=nil,nil
    end
    function State.StopWeaponEquipRecovery() clear(); report.Status="Stopped" end
    function State.SetWeaponEquipRecovery(enabled)
        State.Config.WeaponEquipRecovery=enabled==true
        clear(); report.Status=enabled and "Waiting for slot 1 input" or "Off"
        return true
    end
    function State.GetWeaponEquipSnapshot()
        return {Enabled=State.Config.WeaponEquipRecovery==true,Presses=report.Presses,Recoveries=report.Recoveries,
            Skipped=report.Skipped,Failures=report.Failures,Status=report.Status,NativeSignals=report.NativeSignals,
            LastProcessed=report.LastProcessed,NativeObserved=report.LastNativeSignal,NativeAllowed=report.LastNativeAllowed,LastWhere=report.LastWhere}
    end
    C.Connect(C.Heartbeat,function()
        if not State.Running or not State.Config.WeaponEquipRecovery or not C.IsPC() or not focused then
            if watched or action then clear() end
            return
        end
        local state=C.Read()
        if state.Action~=action then
            if actionWatch then actionWatch:Disconnect(); actionWatch=nil end
            action=state.Action; nativeAt=-math.huge
            if action then actionWatch=C.Watch(action.Pressed,function() nativeAt=clock(); report.NativeSignals+=1 end) end
        end
        if state.Tool~=watched then
            if watch then watch:Disconnect(); watch=nil end
            watched=state.Tool; revision+=1
            if watched then watch=C.Watch(watched:GetPropertyChangedSignal("Parent"),function() revision+=1 end) end
        end
        stable={Tool=state.Tool,Character=state.Character,Backpack=state.Backpack,Parent=state.Tool and state.Tool.Parent,Revision=revision}
    end)
    C.Connect(C.Input,function(input,processed)
        if input.KeyCode~=C.One or input.UserInputType~=C.Keyboard or not State.Running or not State.Config.WeaponEquipRecovery or not C.IsPC() then return end
        token+=1; local request=token
        report.Presses+=1; report.LastProcessed=processed==true; report.LastNativeSignal=nil
        local state=C.Read()
        report.LastNativeAllowed=state.NativeAllowed==true
        report.LastWhere=state.Tool and (state.Tool.Parent==state.Character and "Character" or "Backpack") or "Unavailable"
        local function skip(message) report.Skipped+=1; report.Status=message end
        if not focused or C.Blocked() then skip("Paused for menu, chat or player action"); return end
        if not state.NativeAllowed then skip("Native slot 1 action unavailable"); return end
        if not state.Tool then skip(state.Ambiguous and "Multiple weapons: native slot selection preserved" or "No owned slot 1 weapon"); return end
        local item,char,bag=state.Tool,state.Character,state.Backpack
        if not stable or stable.Tool~=item or stable.Character~=char or stable.Backpack~=bag then skip("Waiting for a stable weapon / character"); return end
        if revision~=stable.Revision or item.Parent~=stable.Parent then skip("Native hotbar changed equip state"); return end
        if stable.Parent~=bag then skip("Native unequip toggle preserved"); return end
        local observedRevision=revision
        local at=clock()
        report.Status="Checking native slot 1 equip"
        C.Schedule(.12,function()
            if request~=token or not State.Running or not State.Config.WeaponEquipRecovery or not focused then return end
            local current=C.Read()
            report.LastNativeSignal=nativeAt>=at-.02
            if current.Character~=char or current.Backpack~=bag or current.Tool~=item then skip("Weapon or character changed"); return end
            if item.Parent==char then report.Status="Native equip succeeded"; return end
            if revision~=observedRevision then skip("Native equip state changed; no retry needed"); return end
            if processed and not report.LastNativeSignal then skip("Input consumed outside the native hotbar"); return end
            if C.Blocked() or not current.NativeAllowed then skip("Equip cancelled: input unavailable"); return end
            if item.Parent~=bag or not current.Humanoid or current.Humanoid.Health<=0 then skip("Equip cancelled: character unavailable"); return end
            if item.RequiresHandle and not item:FindFirstChild("Handle") then skip("Weapon handle is loading"); return end
            local ok,why=pcall(C.Equip,current.Humanoid,item)
            if ok and item.Parent==char then report.Recoveries+=1; report.Status="Slot 1 equip recovered locally"
            else report.Failures+=1; report.Status="Equip recovery failed"; report.LastError=not ok and tostring(why) or nil end
        end)
    end)
    if C.FocusLost then C.Connect(C.FocusLost,function() focused=false; clear(); report.Status="Paused: window unfocused" end) end
    if C.FocusGained then C.Connect(C.FocusGained,function() focused=true end) end
end
installWeaponEquipRecovery({State=State,Heartbeat=RunService.Heartbeat,Input=UIS.InputBegan,One=Enum.KeyCode.One,Keyboard=Enum.UserInputType.Keyboard,
    FocusLost=UIS.WindowFocusReleased,FocusGained=UIS.WindowFocused,
    Connect=connect,Watch=function(signal,callback) return signal:Connect(callback) end,Schedule=task.delay,
    IsPC=function() return detectInputMode(UIS)=="PC" end,
    Blocked=function() return mobileBlocked() or GuiService.MenuIsOpen or UIS:GetFocusedTextBox()~=nil or State.Invis.Busy
        or State.ExperimentalInvis and State.ExperimentalInvis.Busy end,
    Equip=function(hum,item) hum:EquipTool(item) end,
    Read=function()
        local char=player.Character
        local bag=player:FindFirstChild("Backpack")
        local pg=player:FindFirstChild("PlayerGui")
        local root=pg and pg:FindFirstChild("InputContext")
        local context=root and root:FindFirstChild("BackpackContext")
        local action=context and context:FindFirstChild("Item1")
        local selected,count=nil,0
        for _,container in ipairs({char or false,bag or false}) do
            if container then
                for _,item in ipairs(container:GetChildren()) do
                    if item:IsA("Tool") and (item.Name=="Knife" or item.Name=="Gun") and item:HasTag("Weapon") then selected=item; count+=1 end
                end
            end
        end
        return {Character=char,Backpack=bag,Humanoid=char and char:FindFirstChildOfClass("Humanoid"),Tool=count==1 and selected or nil,
            Ambiguous=count>1,Action=action,NativeAllowed=root and root.Enabled and context and context.Enabled and action and action.Enabled or false}
    end})
end
function State.SetMagicBullet(enabled)
    State.Config.MagicBullet = enabled == true
    if State.Config.MagicBullet then State.Config.Aim = true end
    if refreshButtons.MagicBullet then refreshButtons.MagicBullet() end
    if refreshButtons.Aim then refreshButtons.Aim() end
    syncWeapons()
end
connect(UIS.InputBegan, function(input, processed)
    local rightClick = input.UserInputType == Enum.UserInputType.MouseButton2
    -- Camera consumption must not swallow an explicit right-button throw.
    if mobileBlocked() or (processed and not rightClick) or UIS:GetFocusedTextBox() then return end
    local item = equippedWeapon()
    local record = item and State.WeaponHandlers[item]
    if (rightClick or input.KeyCode == Enum.KeyCode.E) and record and record.Kind == "Knife" then
        State.LastThrowInput = rightClick and "RightButtonPress" or "E"
        startThrow(record)
    end
end)
connect(UIS.TouchTapInWorld, function(_, processed)
    if processed or mobileBlocked() then return end
    local item = equippedWeapon()
    local record = item and State.WeaponHandlers[item]
    if record and record.Kind == "Gun" then sendGun(record) end
end)
local inputContext = player.PlayerGui:FindFirstChild("InputContext")
local gameplay = inputContext and inputContext:FindFirstChild("GameplayContext")
local throwAction = gameplay and gameplay:FindFirstChild("Throw")
if throwAction then
    connect(throwAction.Pressed, function()
        local item = equippedWeapon()
        local record = item and State.WeaponHandlers[item]
        if record and record.Kind == "Knife" then startThrow(record) end
    end)
end

do
-- Local-seat replication hypothesis. Local assembly checks cannot verify observer visibility.
-- Keeps the original character, joints, humanoid settings and native camera controls.
local installSeatVisibility=function(C)
    local State, player, world = C.State, C.Player, C.Workspace
    local now, new = C.Clock or os.clock, C.NewInstance or Instance.new
    local mode = {Mode="LocalSeat", Phase="Off", Active=false, Busy=false,
        OtherClientsVerified=false, Status="Off", Record=nil}
    State.Invis = mode
    -- Compatibility for the baseline's attack, pickup, dodge and unload guards.
    State.ExperimentalInvis = mode
    State.Config.Invisibility, State.Config.ExperimentalInvisibility = false, false
    if State.Config.InvisibleKnife==nil then State.Config.InvisibleKnife=true end
    local function refresh()
        if C.Refresh then pcall(C.Refresh) end
        if State.MobileUI and State.MobileUI.Refresh then pcall(State.MobileUI.Refresh) end
    end
    local function finite(v)
        return v and v.X==v.X and v.Y==v.Y and v.Z==v.Z
            and math.abs(v.X)<1e7 and math.abs(v.Y)<1e7 and math.abs(v.Z)<1e7
    end
    local function ownsCharacter(r)
        return player.Character==r.Character and r.Character.Parent and r.Humanoid.Parent==r.Character
            and r.Humanoid.Health>0 and r.Root.Parent==r.Character
            and r.Character:FindFirstChild("HumanoidRootPart")==r.Root
    end
    local function restoreCamera(r)
        if r.Camera and r.Proxy and r.Camera.CameraSubject==r.Proxy then
            r.Camera.CameraSubject = r.CameraSubject
        end
        if r.Proxy and r.Proxy.Parent then r.Proxy:Destroy() end
    end
    local function restore(reason, move)
        local r=mode.Record
        State.Config.Invisibility, State.Config.ExperimentalInvisibility=false,false
        mode.Active=false
        if not r then mode.Busy=false; mode.Phase="Off"; refresh(); return true end
        local errors={}
        local function attempt(name,fn)
            local ok,message=pcall(fn)
            if not ok then table.insert(errors,name..": "..tostring(message)) end
        end
        local destination=r.StartFrame
        if r.LocalReady and ownsCharacter(r) and finite(r.Root.Position)
            and r.Root.Position.Y>world.FallenPartsDestroyHeight+16
            and (r.Root.Position-r.ParkFrame.Position).Magnitude>64 then
            destination=r.Root.CFrame
        end
        -- Remove only instances owned by this activation, even after a character change.
        attempt("weld",function() if r.Weld and r.Weld.Parent then r.Weld:Destroy() end end)
        attempt("seat",function() if r.Seat and r.Seat.Parent then r.Seat:Destroy() end end)
        attempt("camera",function() restoreCamera(r) end)
        local detached=not (r.Weld and r.Weld.Parent) and not (r.Seat and r.Seat.Parent)
        if move~=false and ownsCharacter(r) and detached then
            attempt("position",function()
                r.Root.CFrame=destination
                r.Root.AssemblyLinearVelocity, r.Root.AssemblyAngularVelocity=Vector3.zero,Vector3.zero
            end)
        end
        if not detached then table.insert(errors,"local assembly still attached") end
        if #errors>0 then
            mode.Busy,mode.Phase=true,"RestoreFailed"
            mode.Status="Restore incomplete  ·  press Restore character again: "..table.concat(errors,"; ")
            -- Retain the record for retry; do not hide failures behind a reset.
            refresh(); return false,mode.Status
        end
        mode.Record=nil
        mode.Busy,mode.Phase=false,"Off"
        mode.Status=reason or "Invisibility OFF; local body restored / server sync unverified"
        refresh(); return true,mode.Status
    end
    local function fail(message)
        local ok=restore(message)
        if not ok then return false,mode.Status end
        return false,message
    end
    function State.SetInvisibility(enabled)
        if not enabled then return restore() end
        if mode.Phase=="RestoreFailed" then State.Config.Invisibility=false; refresh(); return false,mode.Status end
        if mode.Record then State.Config.Invisibility=true; refresh(); return true,mode.Status end
        local function reject(message) State.Config.Invisibility=false; mode.Status=message; refresh(); return false,message end
        if not State.Running or State.RepairRequired then return reject("Restore your normal character first") end
        if State.Fling and State.Fling.Active then return reject("Stop fling before enabling invisibility") end
        if State.ReleaseFly then State.ReleaseFly() end -- fly holds PlatformStand; release it before the free-to-move check
        local char=player.Character
        local hum=char and char:FindFirstChildOfClass("Humanoid")
        local root=char and char:FindFirstChild("HumanoidRootPart")
        if not char or not hum or hum.Health<=0 or not root or root.Anchored or (root.AssemblyRootPart and root.AssemblyRootPart.Anchored) or hum.Sit or hum.PlatformStand
            or hum.RootPart~=root or not finite(root.Position) then
            return reject("A living, unseated character with its original root is required")
        end
        local r={Character=char,Humanoid=hum,Root=root,Original=root,StartFrame=root.CFrame,
            ParkFrame=root.CFrame+Vector3.new(0,4096,0),Started=now(),LocalReady=false}
        mode.Record=r
        mode.Busy,mode.Phase=true,"Parking"
        State.Config.Invisibility=true
        local ok,message=pcall(function()
            if C.BeforeStart then C.BeforeStart() end
            -- Ending a dodge may return the root to its previous position.
            if not ownsCharacter(r) or not finite(root.Position) then error("Character changed during preparation") end
            r.StartFrame=root.CFrame
            r.ParkFrame=root.CFrame+Vector3.new(0,4096,0)
            local camera=world.CurrentCamera
            if camera and camera.CameraSubject==hum then
                r.Camera,r.CameraSubject=camera,camera.CameraSubject
                r.Proxy=new("Part")
                r.Proxy.Name="MM2VisibilityCamera"
                r.Proxy.Anchored=true
                r.Proxy.CanCollide,r.Proxy.CanTouch,r.Proxy.CanQuery=false,false,false
                r.Proxy.Transparency=1
                r.Proxy.Size=Vector3.new(0.2,0.2,0.2)
                local head=char:FindFirstChild("Head")
                r.Proxy.CFrame=head and head.CFrame or root.CFrame
                r.Proxy.Parent=world
                camera.CameraSubject=r.Proxy
            end
            root.AssemblyLinearVelocity,root.AssemblyAngularVelocity=Vector3.zero,Vector3.zero
            root.CFrame=r.ParkFrame
        end)
        if not ok then return fail("Preparation failed: "..tostring(message)) end
        mode.Status="Going invisible"
        refresh(); return true,mode.Status
    end
    function State.SetExperimentalInvisibility(enabled) return State.SetInvisibility(enabled) end
    function State.ExitUndergroundForAttack(kind)
        -- Weapon input never reveals the character. Wait for a transition to finish instead.
        if kind=="Gun" or kind=="Knife" then
            if mode.Busy then return false end
            if kind=="Knife" and mode.Active and not State.Config.InvisibleKnife then return false end
            return true
        end
        if mode.Record then return State.SetInvisibility(false) end
        return true
    end
    function State.GetInvisibilityReport()
        return {Mode=mode.Mode,Phase=mode.Phase,Active=mode.Active,Busy=mode.Busy,
            OtherClientsVerified=false,Status=mode.Status,
            LocalRootIsSeat=mode.Record and mode.Record.Seat~=nil and mode.Record.Root.AssemblyRootPart==mode.Record.Seat or false}
    end
    local function step()
        local r=mode.Record
        if not r or mode.Phase=="RestoreFailed" then return end
        if not State.Running then restore("Off  ·  unloaded"); return end
        if not ownsCharacter(r) then restore("Off  ·  character changed",false); return end
        if r.Root.Anchored then fail("Stopped  ·  your character is anchored"); return end
        if not finite(r.Root.Position) or r.Root.Position.Y<=world.FallenPartsDestroyHeight+16 then
            -- Avoid preserving an unsafe current position during cleanup.
            r.LocalReady=false; fail("Stopped  ·  unsafe position"); return
        end
        if mode.Phase=="Parking" then
            r.Root.CFrame=r.ParkFrame
            r.Root.AssemblyLinearVelocity,r.Root.AssemblyAngularVelocity=Vector3.zero,Vector3.zero
            if now()-r.Started<0.4 then return end
            r.Seat=new("Seat")
            r.Seat.Name="MM2VisibilitySeat"
            r.Seat.Disabled=true
            r.Seat.Size=Vector3.new(2,0.5,2)
            r.Seat.Anchored,r.Seat.Massless=false,false
            r.Seat.RootPriority=127
            r.Seat.CanCollide,r.Seat.CanTouch,r.Seat.CanQuery=false,false,false
            r.Seat.Transparency=1
            r.Seat.CFrame=r.Root.CFrame
            r.Seat.Parent=r.Character
            r.Weld=new("WeldConstraint")
            r.Weld.Part0,r.Weld.Part1=r.Seat,r.Root
            r.Weld.Parent=r.Seat
            r.Attached=now()
            mode.Phase="Attaching"
        elseif mode.Phase=="Attaching" then
            if now()-r.Attached<0.1 then return end
            if r.Root.AssemblyRootPart~=r.Seat then fail("Could not go invisible  ·  restored"); return end
            r.Seat.CFrame=r.StartFrame
            r.Root.AssemblyLinearVelocity,r.Root.AssemblyAngularVelocity=Vector3.zero,Vector3.zero
            restoreCamera(r)
            r.LocalReady=true
            mode.Phase,mode.Active,mode.Busy="Active",true,false
            mode.Status="Invisible"
            refresh()
        elseif mode.Phase=="Active" then
            if not r.Seat.Parent or not r.Weld.Parent or r.Root.AssemblyRootPart~=r.Seat then
                fail("Stopped  ·  character rig changed"); return
            end
            if (r.Root.Position-r.ParkFrame.Position).Magnitude<64 then
                r.LocalReady=false; fail("Stopped  ·  position corrected"); return
            end
        end
    end
    C.Connect(C.RunService.PreSimulation,function()
        local ok,message=pcall(step)
        if not ok then fail("Invisibility error: "..tostring(message)) end
    end)
    C.Connect(player.CharacterRemoving,function(char)
        if mode.Record and mode.Record.Character==char then restore("Off  ·  character removed",false) end
    end)
    C.Connect(player.CharacterAdded,function()
        if mode.Record then restore("Off  ·  new character",false) end
        if not mode.Record then State.RepairRequired=false; mode.Status="Off"; refresh() end
    end)
    return mode
end

installSeatVisibility({State=State,Player=player,Workspace=workspace,RunService=RunService,Connect=connect,
    Refresh=function() if refreshButtons.Invisibility then refreshButtons.Invisibility() end end,
    BeforeStart=function()
        if State.StopGunPickup then
            local ok,message=State.StopGunPickup(); if ok==false then error(message) end
        end
        if State.CancelKillAuraContacts then
            local ok,message=State.CancelKillAuraContacts("Paused while invisibility prepares")
            if not ok then error(message) end
        end
        if State.StopAutoAttack then State.StopAutoAttack("Paused for invisibility") end
        if State.StopKnifeDodge then State.StopKnifeDodge("Paused for invisibility") end
        if State.CancelFlingReturn then State.CancelFlingReturn() end
        for _,record in pairs(State.WeaponHandlers) do
            record.ThrowToken+=1
            record.Charging,record.AutoSelectedThrow,record.StabbingUntil,record.StabTarget=false,nil,0,nil
            stopTracks(record)
        end
    end})
end

local colors = {Sheriff = Color3.fromRGB(55, 145, 255),Hero=Color3.fromRGB(55,145,255),
    Innocent = Color3.fromRGB(65, 235, 105), Murderer = Color3.fromRGB(255, 55, 65),
    Zombie=Color3.fromRGB(125,210,45),Survivor=Color3.fromRGB(55,160,255),
    Freezer=Color3.fromRGB(150,220,250),Runner=Color3.fromRGB(65,235,105),Unknown=Color3.fromRGB(190,195,210)}
local visualFolder = Instance.new("Folder")
visualFolder.Name = "MM2AssistVisuals"
visualFolder.Parent = workspace
-- Recover only the container owned by this script; never delete game highlights.
local function ensureVisualFolder()
    if visualFolder and visualFolder.Parent==workspace then return end
    if visualFolder then
        local ok=pcall(function() visualFolder.Parent=workspace end)
        if ok and visualFolder.Parent==workspace then return end
    end
    local replacement=Instance.new("Folder")
    replacement.Name="MM2AssistVisuals"
    replacement.Parent=workspace
    visualFolder=replacement
end

-- A label can keep working after the model's original body geometry is replaced.
-- Refresh only when geometry changes, never because the camera turns or a rig moves.
local function refreshNativeBody(visual,char)
    local previous=visual.BodyGeometry
    local current,count=previous or {},0
    local epoch=(visual.BodyGeometryEpoch or 0)+1
    local changed=false
    for _,part in ipairs(char:GetChildren()) do
        if part:IsA("BasePart") and part.Name~="HumanoidRootPart" then
            local mesh=part:IsA("MeshPart") and part.MeshId or nil
            local before=previous and previous[part]
            count+=1
            if previous and (not before or before.Size~=part.Size or before.Transparency~=part.Transparency or before.Mesh~=mesh) then changed=true end
            local record=before or {}
            record.Size,record.Transparency,record.Mesh,record.Seen=part.Size,part.Transparency,mesh,epoch
            current[part]=record
        end
    end
    if previous and count~=visual.BodyGeometryCount then changed=true end
    for part,record in pairs(current) do if record.Seen~=epoch then current[part]=nil end end
    visual.BodyGeometry,visual.BodyGeometryCount=current,count
    visual.BodyGeometryEpoch=epoch
    if changed then
        -- Destroy first so a refresh cannot temporarily consume another native slot.
        visual.Highlight:Destroy()
        local replacement=Instance.new("Highlight")
        replacement.Name="MM2RoleBody"
        replacement.Adornee=char
        replacement.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop
        replacement.FillTransparency=.3
        replacement.OutlineTransparency=0
        replacement.Parent=visualFolder
        visual.Highlight=replacement
        visual.BodyRefreshes=(visual.BodyRefreshes or 0)+1
    end
end

local function removeVisual(p)
    local visual = State.Visuals[p]
    if visual then
        visual.Highlight:Destroy()
        visual.Label:Destroy()
        for _, box in pairs(visual.HiddenBoxes or {}) do box:Destroy() end
        State.Visuals[p] = nil
    end
end
-- Only replicated invisible geometry needs a native adornment fallback.
-- Uses existing body geometry; does not resize, move or change character parts.
local function updateHiddenBoxes(visual, char, color)
    local hidden,total=0,0
    for part,box in pairs(visual.HiddenBoxes) do
        if not box.Parent or part.Parent~=char then
            box:Destroy(); visual.HiddenBoxes[part]=nil
        end
    end
    for _,name in ipairs(hitPartNames.Gun) do
        local part=char:FindFirstChild(name)
        if part and part:IsA("BasePart") then
            total+=1
            local invisible=hiddenBodyPart(part)
            if invisible then hidden+=1 end
            local wanted=invisible
            local box=visual.HiddenBoxes[part]
            if wanted then
                if not box then
                    box=Instance.new("BoxHandleAdornment")
                    box.Name="MM2BodyFill"
                    box.Parent=visualFolder; visual.HiddenBoxes[part]=box
                end
                box.Adornee=part; box.AlwaysOnTop=true; box.ZIndex=3
                box.Transparency=invisible and .3 or .55
                box.Size=part.Size; box.Color3=color; box.Visible=true
            elseif box then box:Destroy(); visual.HiddenBoxes[part]=nil end
        end
    end
    visual.Hidden=total>0 and hidden>=math.max(1,total*.5)
end

-- The same round geometry is used by visuals, attacks, HUD and map tools.
local function espInRoundArea(position) return State.GameContext.Contains(position) end
local function espViewerAtRound()
    local camera=workspace.CurrentCamera
    local root=player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    return (camera~=nil and espInRoundArea(camera.CFrame.Position)) or (root~=nil and espInRoundArea(root.Position))
end
local function visualCharacterReady(p)
    local char=p.Character
    local hum=char and char:FindFirstChildOfClass("Humanoid")
    local anchor=char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head")
        or char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso"))
    return char and char:IsDescendantOf(workspace) and hum and hum.Health>0 and anchor~=nil and State.GameContext.Visible(p)
end
local function visualRoleFor(p)
    local role=roleFor(p)
    return colors[role] and role or "Unknown"
end

local function updateESP()
    ensureVisualFolder()
    local viewerAtRound = espViewerAtRound()
    local ownRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    for _, p in ipairs(Players:GetPlayers()) do
        local role = visualRoleFor(p)
        if p ~= player and State.Config.ESP and not State.StreamerActive and viewerAtRound and visualCharacterReady(p) and colors[role] then
            local char = p.Character
            local visual = State.Visuals[p]
            if visual and (visual.Character ~= char or visual.Highlight.Parent ~= visualFolder or visual.Label.Parent ~= visualFolder or visual.Text.Parent ~= visual.Label) then removeVisual(p); visual = nil end
            if not visual then
                local highlight = Instance.new("Highlight")
                highlight.Adornee = char
                highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                highlight.FillTransparency = 0.3
                highlight.OutlineTransparency = 0
                highlight.Parent = visualFolder
                local label = Instance.new("BillboardGui")
                label.Adornee = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
                label.Size = UDim2.fromOffset(280, 44)
                label.StudsOffset = Vector3.new(0, 2.8, 0)
                label.AlwaysOnTop = true
                label.Parent = visualFolder
                local text = Instance.new("TextLabel")
                text.Size = UDim2.fromScale(1, 1)
                text.BackgroundTransparency = 1
                text.FontFace = Font.new("rbxassetid://12187365364", Enum.FontWeight.SemiBold)
                text.TextSize = 13
                text.TextStrokeTransparency = 0.25
                text.TextWrapped = true
                text.Parent = label
                visual = {Character = char, Highlight = highlight, Label = label, Text = text, HiddenBoxes = {}}
                State.Visuals[p] = visual
            end
            refreshNativeBody(visual,char)
            local highlight = visual.Highlight
            -- Restyle only a new highlight or a role change; float properties never read back equal.
            if visual.StyledHighlight ~= highlight or visual.StyledRole ~= role then
                highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                highlight.FillTransparency = 0.3
                highlight.FillColor = colors[role]
                highlight.OutlineColor = colors[role]
                visual.Text.TextColor3 = colors[role]
                visual.StyledHighlight, visual.StyledRole = highlight, role
            end
            if highlight.Adornee ~= char then highlight.Adornee = char end
            if not highlight.Enabled then highlight.Enabled = true end
            local anchor = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart")
            if visual.Label.Adornee ~= anchor then visual.Label.Adornee = anchor end
            updateHiddenBoxes(visual, char, colors[role])
            local targetRoot = char:FindFirstChild("HumanoidRootPart")
            local distance = ownRoot and targetRoot and (targetRoot.Position - ownRoot.Position).Magnitude
            local labelText = "@" .. p.Name
                .. (visual.Hidden and "  ·  invisible" or "")
                .. (distance and ("  ·  " .. math.floor(distance + 0.5) .. " studs") or "")
            local labelSize = UDim2.fromOffset(280,44)
            if State.Config.CleanVisuals then labelText, labelSize = "@"..p.Name, UDim2.fromOffset(190,24) end
            if State.GameContext.Mode()~="Classic" then
                labelText=labelText.." · "..role..(State.GameContext.Frozen(p) and " (frozen)" or "")
            end
            -- Write only real changes: the old flip between two strings re-rendered every label twice per tick.
            if visual.Text.Text ~= labelText then visual.Text.Text = labelText end
            if visual.Label.Size ~= labelSize then visual.Label.Size = labelSize end
            if not visual.Label.Enabled then visual.Label.Enabled=true end
        else removeVisual(p) end
    end
end
connect(Players.PlayerRemoving, removeVisual)
function State.GetESPSnapshot()
    local eligible,drawn=0,0
    for _,p in ipairs(Players:GetPlayers()) do if p~=player and visualCharacterReady(p) then eligible+=1 end end
    for _,visual in pairs(State.Visuals) do
        if visual.Highlight.Parent==visualFolder and visual.Highlight.Enabled and visual.Label.Enabled then drawn+=1 end
    end
    return {Enabled=State.Config.ESP==true,Streamer=State.StreamerActive==true,ViewerInMap=espViewerAtRound()==true,
        Maps=#State.GameContext.Maps(),Eligible=eligible,Drawn=drawn}
end

local threatDirections = {"AHEAD", "FRONT-RIGHT", "RIGHT", "BACK-RIGHT", "BEHIND", "BACK-LEFT", "LEFT", "FRONT-LEFT"}
local function threatDetails(ownRoot, targetRoot, camera)
    local delta = targetRoot.Position - ownRoot.Position
    local distance = delta.Magnitude
    local frame = camera and camera.CFrame or ownRoot.CFrame
    local right = Vector3.new(frame.RightVector.X, 0, frame.RightVector.Z)
    if right.Magnitude < 0.001 then right = Vector3.xAxis else right = right.Unit end
    local forward = Vector3.new(right.Z, 0, -right.X)
    local horizontal = Vector3.new(delta.X, 0, delta.Z)
    local direction = "VERY CLOSE"
    if horizontal.Magnitude > 0.01 then
        local angle = math.atan2(horizontal:Dot(right), horizontal:Dot(forward))
        direction = threatDirections[(math.floor(angle / (math.pi / 4) + 0.5) % 8) + 1]
    end
    local relativeVelocity = targetRoot.AssemblyLinearVelocity - ownRoot.AssemblyLinearVelocity
    local closing = distance > 0.01 and relativeVelocity:Dot(delta.Unit) < -2
    return {Distance = distance, Direction = direction, Closing = closing,
        Height = delta.Y > 6 and "ABOVE" or (delta.Y < -6 and "BELOW" or nil)}
end

