        Elder={idle={845397899, 845400520, 901160519}, walk={845403856}, run={845386501}, jump={845398858}, fall={845396048}, climb={845392038}, swim={845401742}, swimidle={845403127}},
        Knight={idle={657595757, 657568135, 885499184}, walk={657552124}, run={657564596}, jump={658409194}, fall={657600338}, climb={658360781}, swim={657560551}, swimidle={657557095}},
        Levitation={idle={616006778, 616008087, 886862142}, walk={616013216}, run={616010382}, jump={616008936}, fall={616005863}, climb={616003713}, swim={616011509}, swimidle={616012453}},
        Mage={idle={707742142, 707855907, 885508740}, walk={707897309}, run={707861613}, jump={707853694}, fall={707829716}, climb={707826056}, swim={707876443}, swimidle={707894699}},
        Ninja={idle={656117400, 656118341, 886742569}, walk={656121766}, run={656118852}, jump={656117878}, fall={656115606}, climb={656114359}, swim={656119721}, swimidle={656121397}},
        Pirate={idle={750781874, 750782770, 885515365}, walk={750785693}, run={750783738}, jump={750782230}, fall={750780242}, climb={750779899}, swim={750784579}, swimidle={750785176}},
        Robot={idle={616088211, 616089559, 885531463}, walk={616095330}, run={616091570}, jump={616090535}, fall={616087089}, climb={616086039}, swim={616092998}, swimidle={616094091}},
        Rthro={idle={2510197257, 2510196951, 3711062489}, walk={2510202577}, run={2510198475}, jump={2510197830}, fall={2510195892}, climb={2510192778}, swim={2510199791}, swimidle={2510201162}},
        Stylish={idle={616136790, 616138447, 886888594}, walk={616146177}, run={616140816}, jump={616139451}, fall={616134815}, climb={616133594}, swim={616143378}, swimidle={616144772}},
        Superhero={idle={616111295, 616113536, 885535855}, walk={616122287}, run={616117076}, jump={616115533}, fall={616108001}, climb={616104706}, swim={616119360}, swimidle={616120861}},
        Toy={idle={782841498, 782845736, 980952228}, walk={782843345}, run={782842708}, jump={782847020}, fall={782846423}, climb={782843869}, swim={782844582}, swimidle={782845186}},
        Vampire={idle={1083445855, 1083450166, 1088037547}, walk={1083473930}, run={1083462077}, jump={1083455352}, fall={1083443587}, climb={1083439238}, swim={1083464683}, swimidle={1083467779}},
        Werewolf={idle={1083195517, 1083214717, 1099492820}, walk={1083178339}, run={1083216690}, jump={1083218792}, fall={1083189019}, climb={1083182000}, swim={1083222527}, swimidle={1083225406}},
        Zombie={idle={616158929, 616160636, 885545458}, walk={616168032}, run={616163682}, jump={616161997}, fall={616157476}, climb={616156119}, swim={616165109}, swimidle={616166655}},
    } -- end animationPacks
    local packNames = {}
    for name in pairs(animationPacks) do table.insert(packNames, name) end
    table.sort(packNames)
    State.AnimationPackNames = packNames
    if not animationPacks[State.Config.AnimationPack] then State.Config.AnimationPack = "Mage" end
    local mage = {Token = 0, Applied = false, Loading = false, LastAttempt = 0,
        Status = "Default animations", OtherClientsVerified = false}
    State.Mage = mage
    local refreshToken = 0
    local pendingControllerStates = setmetatable({}, {__mode = "k"})
    local function restartLocomotion(record)
        local animate = record.Animate
        if not animate.Parent or animate.Parent ~= record.Character then return end
        refreshToken += 1
        local token = refreshToken
        pendingControllerStates[animate] = {Enabled = record.Enabled}
        animate.Enabled = false
        local ok, tracks = pcall(record.Animator.GetPlayingAnimationTracks, record.Animator)
        for _, track in ok and tracks or {} do
            local animation = track.Animation
            local id = animation and animation.AnimationId:match("%d+")
            if id and record.LocomotionIds[id] then track:Stop(0.1) end
        end
        -- Cleanup must restore Enabled before a replacement script snapshots it.
        if not State.Running then
            animate.Enabled = record.Enabled
            pendingControllerStates[animate] = nil
            return
        end
        task.defer(function()
            if refreshToken == token and animate.Parent == record.Character then
                animate.Enabled = record.Enabled
                pendingControllerStates[animate] = nil
            end
        end)
    end
    function State.RestoreMage(keepEnabled)
        mage.Token += 1
        mage.Applied = false
        mage.Loading = false
        if not keepEnabled then State.Config.MageAnimations = false end
        local record = mage.Record
        mage.Record = nil
        if record then
            for animation, id in pairs(record.Originals) do
                if animation.Parent then animation.AnimationId = id end
            end
            for _, animation in record.Created do animation:Destroy() end
            restartLocomotion(record)
            -- Complete restoration synchronously, including rapid toggles/reload.
            refreshToken += 1
            if record.Animate.Parent == record.Character then record.Animate.Enabled = record.Enabled end
            pendingControllerStates[record.Animate] = nil
        end
        mage.Pack = nil
        mage.Status = "Default animations"
    end
    function State.SetAnimationPack(name)
        if name == nil or name == "Default" then State.RestoreMage(); return true end
        if not animationPacks[name] then mage.Status = "Unknown animation pack"; return false end
        State.Config.AnimationPack = name
        return State.SetMageAnimations(true)
    end
    -- Applies the chosen pack (Mage unless another was picked) to every movement slot at once.
    function State.SetMageAnimations(enabled)
        if not enabled then State.RestoreMage(); return true end
        local packName = animationPacks[State.Config.AnimationPack] and State.Config.AnimationPack or "Mage"
        local mageIds = animationPacks[packName]
        State.StopPose()
        State.RestoreMage(true)
        State.Config.MageAnimations = true
        local token = mage.Token
        mage.Loading, mage.LastAttempt = true, os.clock()
        mage.Status = "Loading " .. packName .. " pack…"
        task.spawn(function()
            local char = player.Character
            local hum = char and char:WaitForChild("Humanoid", 5)
            local animator = hum and hum:WaitForChild("Animator", 5)
            local animate = char and char:WaitForChild("Animate", 5)
            local function current()
                return State.Running and mage.Token == token and State.Config.MageAnimations and player.Character == char
            end
            local function finish(status)
                mage.Loading = false
                mage.Status = status
            end
            if not current() then return end
            if not hum or hum.Health <= 0 or not animator or not animate or not animate:IsA("LocalScript") then
                finish("Waiting for character animation controller"); return
            end
            if hum.RigType ~= Enum.HumanoidRigType.R15 then finish(packName .. " pack needs an R15 avatar"); return end
            local slots, assets, ready = {}, {}, {}
            for name, ids in pairs(mageIds) do
                local folder = animate:FindFirstChild(name)
                local animations = {}
                if folder then
                    for _, child in folder:GetChildren() do
                        if child:IsA("Animation") then table.insert(animations, child) end
                    end
                end
                if #animations == 0 then finish("Waiting for movement slot: " .. name); return end
                table.sort(animations, function(a, b) return a.Name < b.Name end)
                slots[name] = {Folder = folder, Animations = animations}
            end
            for _, ids in pairs(mageIds) do
                for _, id in ids do
                    local asset = Instance.new("Animation")
                    asset.AnimationId = "rbxassetid://" .. id
                    table.insert(assets, asset)
                end
            end
            local loaded = pcall(function()
                ContentProvider:PreloadAsync(assets, function(id, status)
                    if status == Enum.AssetFetchStatus.Success then ready[id:match("%d+")] = true end
                end)
            end)
            local available = loaded
            for _, asset in assets do
                if not ready[asset.AnimationId:match("%d+")] then available = false end
                asset:Destroy()
            end
            if not current() then return end
            if char:FindFirstChild("Animate") ~= animate or hum.Parent ~= char or animator.Parent ~= hum or hum.Health <= 0 then
                finish("Waiting for character animation controller"); return
            end
            if not available then finish(packName .. " animations are unavailable here"); return end
            local originalEnabled = animate.Enabled
            local pending = pendingControllerStates[animate]
            if pending then originalEnabled = pending.Enabled end
            local record = {Character = char, Animate = animate, Animator = animator, Enabled = originalEnabled,
                Originals = {}, Created = {}, LocomotionIds = {}, Expected = {}}
            for _, ids in pairs(mageIds) do
                for _, id in ids do record.LocomotionIds[tostring(id)] = true end
            end
            mage.Record = record
            -- Animate watches AnimationId changes and child additions. Restart once
            -- so a cached idle/run track cannot keep playing the old animation.
            animate.Enabled = false
            for name, slot in pairs(slots) do
                local ids = mageIds[name]
                for i, animation in slot.Animations do
                    record.Originals[animation] = animation.AnimationId
                    local originalId = animation.AnimationId:match("%d+")
                    if originalId then record.LocomotionIds[originalId] = true end
                    animation.AnimationId = "rbxassetid://" .. ids[(i - 1) % #ids + 1]
                    record.Expected[animation] = animation.AnimationId
                end
                if name == "idle" and #slot.Animations < #ids then
                    for i = #slot.Animations + 1, #ids do
                        local animation = Instance.new("Animation")
                        animation.Name = "MM2PackIdle" .. i
                        animation.AnimationId = "rbxassetid://" .. ids[i]
                        record.Expected[animation] = animation.AnimationId
                        local weight = Instance.new("NumberValue")
                        weight.Name, weight.Value, weight.Parent = "Weight", 1, animation
                        table.insert(record.Created, animation)
                        animation.Parent = slot.Folder
                    end
                end
            end
            restartLocomotion(record)
            mage.Applied = true
            mage.Pack = packName
            finish(packName .. " pack on")
        end)
        return true
    end
    function State.EnsureMageAnimations()
        if not State.Running or not State.Config.MageAnimations or mage.Loading then return end
        local char = player.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local animator = hum and hum:FindFirstChildOfClass("Animator")
        local animate = char and char:FindFirstChild("Animate")
        if not hum or hum.Health <= 0 or hum.RigType ~= Enum.HumanoidRigType.R15
            or not animator or not animate or not animate:IsA("LocalScript") then return end
        local record = mage.Record
        local needsApply = not mage.Applied or not record or record.Character ~= char or mage.Pack ~= State.Config.AnimationPack
            or record.Animate ~= animate or record.Animator ~= animator
        if not needsApply then
            for animation, id in pairs(record.Expected) do
                if not animation:IsDescendantOf(animate) or animation.AnimationId ~= id then needsApply = true; break end
            end
            for name in pairs(animationPacks.Mage) do
                local folder = animate:FindFirstChild(name)
                if not folder then needsApply = true; break end
                for _, animation in folder:GetChildren() do
                    if animation:IsA("Animation") and not record.Expected[animation] then needsApply = true; break end
                end
                if needsApply then break end
            end
        end
        if needsApply and os.clock() - mage.LastAttempt >= 3 then State.SetMageAnimations(true) end
    end
    function State.StopPose(keepEnabled)
        pose.Token += 1
        pose.Playing = false
        if pose.Track then pcall(function() pose.Track:Stop(0.15); pose.Track:Destroy() end); pose.Track = nil end
        if pose.Animation then pose.Animation:Destroy(); pose.Animation = nil end
        pose.Character = nil
        if not keepEnabled then State.Config.PoseEnabled = false end
        pose.Status = "Pose off"
    end
    function State.SetPose(value)
        local input = tostring(value)
        local digits = input:match("^%s*(%d+)%s*$") or input:match("rbxassetid://(%d+)")
            or input:match("/library/(%d+)") or input:match("/asset/(%d+)") or input:match("[?&]id=(%d+)")
        local assetId = digits and tonumber(digits)
        if not assetId or assetId < 1 or assetId > 9000000000000000 then
            pose.Status = "Enter a valid published animation ID"
            return false
        end
        if State.Config.MageAnimations then State.RestoreMage() end
        State.StopPose(true)
        State.Config.PoseEnabled, State.Config.PoseAssetId = true, assetId
        local char = player.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local animator = hum and hum:FindFirstChildOfClass("Animator")
        if not hum or hum.Health <= 0 or not animator then pose.Status = "Waiting for your character's Animator"; return false end
        if hum.RigType ~= Enum.HumanoidRigType.R15 then pose.Status = "These pose presets require R15"; return false end
        local token = pose.Token
        pose.Character = char
        pose.Status = "Loading pose..."
        task.spawn(function()
            local animation = Instance.new("Animation")
            animation.AnimationId = "rbxassetid://" .. assetId
            local fetched = false
            local ok, message = pcall(function()
                ContentProvider:PreloadAsync({animation}, function(_, status)
                    if status == Enum.AssetFetchStatus.Success then fetched = true end
                end)
            end)
            if not State.Running or pose.Token ~= token or player.Character ~= char then animation:Destroy(); return end
            if not ok or not fetched then
                animation:Destroy()
                pose.Status = ok and "Animation unavailable or not permitted here" or ("Animation failed to load: " .. tostring(message))
                return
            end
            local loaded, track = pcall(animator.LoadAnimation, animator, animation)
            if not State.Running or pose.Token ~= token or player.Character ~= char then
                if loaded then track:Destroy() end
                animation:Destroy()
                return
            end
            if not loaded then animation:Destroy(); pose.Status = "Animation could not load on this rig"; return end
            pose.Animation, pose.Track = animation, track
            track.Priority = Enum.AnimationPriority.Movement
            track.Looped = true
            local played = pcall(track.Play, track, 0.2, 1, 1)
            if not played then State.StopPose(true); pose.Status = "Pose playback failed"; return end
            pose.Playing = true
            local name = assetId == 616006778 and "Floating" or (assetId == 696096087 and "Bend/glitch" or "Custom")
            pose.Status = name .. " pose playing"
        end)
        return true
    end
    local window = Instance.new("Frame")
    window.Name = "AnimationPoseControls"
    window.Size = UDim2.fromOffset(286, 376)
    window.Position = UDim2.new(0, 314, 0.5, -188)
    window.BackgroundColor3 = Color3.fromRGB(22, 25, 34)
    window.Visible = false
    window.Parent = gui
    Instance.new("UICorner", window).CornerRadius = UDim.new(0, 10)
    local function label(text, y, height)
        local l = Instance.new("TextLabel")
        l.Position = UDim2.fromOffset(14, y)
        l.Size = UDim2.new(1, -28, 0, height or 25)
        l.BackgroundTransparency = 1
        l.TextColor3 = Color3.fromRGB(225, 230, 240)
        l.Font = Enum.Font.Gotham
        l.TextSize = 12
        l.TextWrapped = true
        l.Text = text
        l.Parent = window
        return l
    end
    label("Mage movement + optional poses", 7)
    label("F9 toggles the complete Mage movement set.", 31)
    local function poseButton(text, y, callback)
        local b = Instance.new("TextButton")
        b.Position = UDim2.fromOffset(14, y)
        b.Size = UDim2.new(1, -28, 0, 31)
        b.BackgroundColor3 = Color3.fromRGB(38, 43, 56)
        b.TextColor3 = Color3.new(1, 1, 1)
        b.Font = Enum.Font.GothamBold
        b.TextSize = 12
        b.Text = text
        b.Parent = window
        Instance.new("UICorner", b).CornerRadius = UDim.new(0, 6)
        connect(b.Activated, callback)
    end
    poseButton("Mage: all movement animations", 62, function() State.SetMageAnimations(true) end)
    poseButton("Restore original movement", 99, function() State.StopPose(); State.RestoreMage() end)
    poseButton("Floating pose", 136, function() State.SetPose(616006778) end)
    poseButton("Bend / glitch pose", 173, function() State.SetPose(696096087) end)
    local input = Instance.new("TextBox")
    input.Position = UDim2.fromOffset(14, 210)
    input.Size = UDim2.new(1, -28, 0, 31)
    input.BackgroundColor3 = Color3.fromRGB(38, 43, 56)
    input.TextColor3 = Color3.new(1, 1, 1)
    input.Font = Enum.Font.Gotham
    input.TextSize = 12
    input.PlaceholderText = "Published R15 animation ID"
    input.ClearTextOnFocus = false
    input.Text = tostring(State.Config.PoseAssetId)
    input.Parent = window
    poseButton("Play custom pose", 247, function() State.SetPose(input.Text) end)
    poseButton("Stop / restore all animations", 284, function() State.StopPose(); State.RestoreMage() end)
    local poseStatus = label(mage.Status, 320, 44)
    local menu = Instance.new("TextButton")
    menu.Position = UDim2.fromOffset(220, 10)
    menu.Size = UDim2.fromOffset(52, 25)
    menu.BackgroundColor3 = Color3.fromRGB(38, 43, 56)
    menu.TextColor3 = Color3.new(1, 1, 1)
    menu.Font = Enum.Font.GothamBold
    menu.TextSize = 10
    menu.Text = "ANIMS"
    menu.Parent = panel
    -- Legacy animation controls stay hidden; WindUI exposes these actions.
    connect(UIS.InputBegan, function(key, processed)
        if processed then return end
        if key.KeyCode == Enum.KeyCode.Insert then window.Visible = false end
    end)
    local persistenceElapsed = 0
    connect(RunService.Heartbeat, function(dt)
        persistenceElapsed += dt
        if persistenceElapsed >= 1 then
            persistenceElapsed = 0
            State.EnsureMageAnimations()
        end
        if pose.Track then
            local playing = pose.Track.IsPlaying
            if pose.Playing and not playing then pose.Status = "Pose stopped by the game" end
            pose.Playing = playing
        end
        local text = State.Config.MageAnimations and mage.Status or (State.Config.PoseEnabled and pose.Status or mage.Status)
        if poseStatus.Text ~= text then poseStatus.Text = text end
    end)
    connect(player.CharacterAdded, function(char)
        State.StopPose(true)
        State.RestoreMage(true)
        mage.LastAttempt = 0
        local token = pose.Token
        task.spawn(function()
            local hum = char:WaitForChild("Humanoid", 5)
            if hum then hum:WaitForChild("Animator", 5) end
            if State.Running and pose.Token == token and player.Character == char then
                if State.Config.MageAnimations then State.SetMageAnimations(true)
                elseif State.Config.PoseEnabled then State.SetPose(State.Config.PoseAssetId) end
            end
        end)
    end)
    if State.Config.MageAnimations then State.SetMageAnimations(true)
    elseif State.Config.PoseEnabled then State.SetPose(State.Config.PoseAssetId) end
end

local drops = {}
local function dropPart(object)
    if object:IsA("BasePart") then return object end
    for _,child in ipairs(object:GetDescendants()) do
        if child:IsA("TouchTransmitter") and child.Parent:IsA("BasePart") then return child.Parent end
    end
    local handle=object:FindFirstChild("Handle",true)
    return handle and handle:IsA("BasePart") and handle or object:FindFirstChildWhichIsA("BasePart",true)
end
local function removeGunVisual(object)
    local visual = State.GunVisuals[object]
    if visual then
        visual.Highlight:Destroy()
        visual.Label:Destroy()
        State.GunVisuals[object] = nil
    end
end
updateGunESP = function()
    ensureVisualFolder()
    local atRound = espViewerAtRound()
    for object in pairs(State.GunVisuals) do
        if not State.Config.GunESP or State.StreamerActive or not atRound or not drops[object] or not object:IsDescendantOf(workspace) then
            removeGunVisual(object)
        end
    end
    if not State.Config.GunESP or State.StreamerActive or not atRound then return end
    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    for object in pairs(drops) do
        local part = object:IsDescendantOf(workspace) and dropPart(object)
        if part then
            local visual = State.GunVisuals[object]
            if visual and (visual.Highlight.Parent ~= visualFolder or visual.Label.Parent ~= visualFolder or visual.Text.Parent ~= visual.Label) then
                removeGunVisual(object); visual=nil
            end
            if not visual then
                local yellow = Color3.fromRGB(255, 215, 45)
                local highlight = Instance.new("Highlight")
                highlight.Adornee = object:IsA("Model") and object or part
                highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                highlight.FillColor = yellow
                highlight.OutlineColor = yellow
                highlight.FillTransparency = 0.2
                highlight.OutlineTransparency = 0
                highlight.Parent = visualFolder
                local label = Instance.new("BillboardGui")
                label.Size = UDim2.fromOffset(180, 32)
                label.StudsOffset = Vector3.new(0, 1.8, 0)
                label.AlwaysOnTop = true
                label.Parent = visualFolder
                local text = Instance.new("TextLabel")
                text.Size = UDim2.fromScale(1, 1)
                text.BackgroundTransparency = 1
                text.FontFace = Font.new("rbxassetid://12187365364", Enum.FontWeight.SemiBold)
                text.TextSize = 14
                text.TextColor3 = yellow
                text.TextStrokeTransparency = 0.15
                text.Parent = label
                visual = {Highlight = highlight, Label = label, Text = text}
                State.GunVisuals[object] = visual
            end
            -- Depth mode and transparency are set once at creation; only adornees and text can change.
            local adornee = object:IsA("Model") and object or part
            if visual.Highlight.Adornee ~= adornee then visual.Highlight.Adornee = adornee end
            if not visual.Highlight.Enabled then visual.Highlight.Enabled = true end
            if not visual.Label.Enabled then visual.Label.Enabled = true end
            if visual.Label.Adornee ~= part then visual.Label.Adornee = part end
            local distance = root and math.round((part.Position - root.Position).Magnitude)
            local text = "Gun" .. (distance and "  ·  " .. distance .. " studs" or "")
            if visual.Text.Text ~= text then visual.Text.Text = text end
        else
            removeGunVisual(object)
        end
    end
end
for _, object in ipairs(workspace:GetDescendants()) do if object.Name == "GunDrop" then drops[object] = true end end
connect(workspace.DescendantAdded, function(object)
    if object.Name ~= "GunDrop" then return end
    drops[object] = true
    if State.OnGunDropped then task.defer(State.OnGunDropped, object) end
end)
connect(workspace.DescendantRemoving, function(object)
    drops[object] = nil
    removeGunVisual(object)
end)
do
-- Touch-only pickup, with bounded attempts and explicit tool confirmation. Never moves a character.
local installGunPickup=function(C)
    local State,player=C.State,C.Player
    local clock=C.Clock or os.clock
    local pickup={Status="Off",Attempts=0,Phase="Idle",NextAttempt=0}
    State.GunPickup=pickup
    local active
    local function finish()
        local r=active
        if not r then return true end
        if pickup.Phase=="Waiting" or not r.Root.Parent or not r.Drop.Parent then
            active=nil; pickup.Phase="Idle"; return true
        end
        local ok,err=pcall(C.Touch,r.Root,r.Drop,1)
        if not ok then pickup.Status="Pickup touch cleanup failed: "..tostring(err); return false end
        active=nil; pickup.Phase="Idle"; return true
    end
    function State.StopGunPickup()
        local ok=finish()
        if ok then pickup.Status="Off" end
        return ok,pickup.Status
    end
    function State.TickGunPickup()
        local now=clock()
        if active then
            if not State.Running or not State.Config.AutoPickup or player.Character~=active.Character
                or not active.Root.Parent or not active.Drop.Parent or C.HasGun()
                or C.Blocked() or State.Invis and State.Invis.Busy then
                local acquired=C.HasGun()
                if finish() then pickup.Status=acquired and "Gun acquired" or "Pickup cancelled" end
                return
            end
            if now-active.Started>=.05 and pickup.Phase=="Touching" then
                local ok,err=pcall(C.Touch,active.Root,active.Drop,1)
                if not ok then pickup.Status="Pickup touch cleanup failed: "..tostring(err); return end
                pickup.Phase="Waiting"
            end
            if now-active.Started>=.8 then
                active=nil; pickup.Phase="Idle"
                pickup.Status="Gun not picked up  ·  move closer"
            end
            return
        end
        if not State.Running or not State.Config.AutoPickup then pickup.Status="Off"; return end
        if not C.IsAlive() or C.HasKnife() then pickup.Status="Waiting until you can pick it up"; return end
        if C.HasGun() then pickup.Status="You already have the gun"; return end
        if C.Blocked() then pickup.Status="Paused  ·  close the menu or finish typing"; return end
        if State.Invis and State.Invis.Busy then
            pickup.Status="Paused while invisibility switches"; return
        end
        if not C.Touch then pickup.Status="Unavailable  ·  your executor lacks firetouchinterest"; return end
        local char=player.Character
        local root=char and char:FindFirstChild("HumanoidRootPart")
        if not root then pickup.Status="Waiting for your character"; return end
        local drop,distance=C.FindDrop(root)
        if not drop then pickup.Status="Waiting for a dropped gun"; pickup.LastDistance=nil; return end
        local approached=pickup.LastDrop==drop and pickup.LastDistance and pickup.LastDistance>8 and distance<=8
        if pickup.LastDrop~=drop or approached then pickup.NextAttempt=0 end
        pickup.LastDrop,pickup.LastDistance=drop,distance
        if now<pickup.NextAttempt then return end
        pickup.NextAttempt=now+2
        local ok,err=pcall(C.Touch,root,drop,0)
        if not ok then
            -- A touch API may throw after starting contact; retain it for paired cleanup.
            active={Root=root,Drop=drop,Character=char,Started=now}
            pickup.Phase="Touching"; pickup.Status="Pickup touch failed: "..tostring(err)
            finish(); return
        end
        active={Root=root,Drop=drop,Character=char,Started=now}
        pickup.Phase="Touching"; pickup.Attempts+=1
        State.Stats.PickupAttempts+=1
        pickup.InvisibleAttempt=State.Invis and State.Invis.Active==true or false
        pickup.Status=("Pickup requested at %.0f local studs%s; waiting for gun"):format(distance,
            pickup.InvisibleAttempt and " while invisible" or "")
    end
end

installGunPickup({State=State,Player=player,Touch=type(firetouchinterest)=="function" and firetouchinterest or nil,
    IsAlive=function() return alive(player) end,HasGun=function() return toolFor(player,"Gun")~=nil end,
    HasKnife=function() return toolFor(player,"Knife")~=nil end,
    Blocked=function() return mobileBlocked() or GuiService.MenuIsOpen or UIS:GetFocusedTextBox()~=nil end,
    FindDrop=function(root)
        local closest,best
        for object in pairs(drops) do
            if object:IsDescendantOf(workspace) then
                local part=dropPart(object)
                if part then
                    local distance=(part.Position-root.Position).Magnitude
                    if distance==distance and (not best or distance<best) then closest,best=part,distance end
                end
            end
        end
        return closest,best
    end})
end
do
-- Experimental: touches and respawns are requests; only the server controls votes.
local installMapVoteRepeat=function(C)
    local State=C.State
    local clock=C.Clock or os.clock
    local report={Status="Off",Phase="Idle",Respawns=0,Touches=0,ObservedIncrease=0,MaxRespawns=3,
        ActivePads=0,Pads=0,Layout="Unavailable",MetadataSource="Unavailable",Detection="None"}
    State.MapVote=report
    State.Config.MapVoteRepeat=false
    local selected,contact,nextTick,armed
    local hooks={}
    local function cleanup()
        if not contact then return true end
        local r=contact
        local ended=not r.Began or r.Ended
        if not ended then ended=pcall(C.Touch,r.Root,r.Pad,1); r.Ended=ended end
        if ended then contact=nil; return true end
        report.Status="Vote cleanup incomplete  ·  switch off again to retry"
        return false
    end
    function State.StopMapVoteRepeat(message)
        State.Config.MapVoteRepeat=false
        armed=false
        selected=nil; report.Phase="Idle"
        for pad,hook in pairs(hooks) do hook:Disconnect(); hooks[pad]=nil end
        local ok=cleanup()
        if ok then report.Status=message or "Off" end
        return ok,report.Status
    end
    function State.SetMapVoteRepeat(enabled)
        if not enabled then return State.StopMapVoteRepeat() end
        if not cleanup() then return false,report.Status end
        if not State.Running then
            State.Config.MapVoteRepeat=false
            report.Status="Script is unloaded"
            return false,report.Status
        end
        if armed then return true,report.Status end
        armed=true
        State.Config.MapVoteRepeat=true
        selected=nil
        report.Respawns,report.Touches,report.ObservedIncrease=0,0,0
        report.Detection="None"
        report.Phase,report.Status="Armed","Step on a map pad during voting  ·  up to 3 respawns"
        return true,report.Status
    end
    function State.GetMapVoteSnapshot()
        return {Enabled=State.Config.MapVoteRepeat==true,Phase=report.Phase,Status=report.Status,
            Respawns=report.Respawns,Touches=report.Touches,ObservedIncrease=report.ObservedIncrease,
            MaxRespawns=report.MaxRespawns,ActivePads=report.ActivePads,Pads=report.Pads,Layout=report.Layout,MetadataSource=report.MetadataSource,
            Detection=report.Detection}
    end
    local function findPad(pad)
        for _,entry in ipairs(C.ReadPads()) do if entry.Pad==pad then return entry end end
    end
    function State.SelectMapVote(pad,source)
        if not State.Running or not State.Config.MapVoteRepeat then return false end
        local entry=findPad(pad)
        if not entry or not entry.Voting or not entry.Map then return false end
        local blocked=C.Blocked()
        if blocked then report.Status="Vote detected  ·  "..(type(blocked)=="string" and blocked or "character/input conflict"); return false end
        if selected and selected.Pad==pad and selected.Map==entry.Map then return true end
        if not cleanup() then State.StopMapVoteRepeat(); return false end
        selected={Pad=pad,Map=entry.Map,InitialVotes=entry.Votes,BeforeTouch=entry.Votes,
            ReadyAt=clock()+1,Initial=true}
        report.Detection=source or "Manual"
        report.Phase,report.Status="Observing","Selected "..entry.Name.."  ·  waiting before respawn"
        return true
    end
    local function step()
        if not State.Running then State.StopMapVoteRepeat("Unloaded"); return end
        if not State.Config.MapVoteRepeat then
            if armed or selected or contact then State.StopMapVoteRepeat() end
            return
        end
        local now=clock()
        local entries,seen=C.ReadPads(),{}
        for _,entry in ipairs(entries) do
            seen[entry.Pad]=true
            if not hooks[entry.Pad] then
                local pad=entry.Pad
                hooks[pad]=C.Watch(pad.Touched,function(hit)
                    if C.OwnTouch(hit) then State.SelectMapVote(pad,"Touch") end
                end)
            end
        end
        for pad,hook in pairs(hooks) do if not seen[pad] then hook:Disconnect(); hooks[pad]=nil end end
        report.ActivePads=0
        report.Pads=#entries
        report.Layout=entries[1] and entries[1].Layout or "Unavailable"
        report.MetadataSource=entries[1] and entries[1].Source or "Unavailable"
        for _,entry in ipairs(entries) do if entry.Voting and entry.Map then report.ActivePads+=1 end end
        if not selected then
            local blocked=C.Blocked()
            if #entries==0 then report.Status="Voting pads unavailable  ·  waiting for lobby"
            elseif report.ActivePads==0 then report.Status="Waiting for map voting to open"
            elseif blocked then report.Status="Waiting  ·  "..(type(blocked)=="string" and blocked or "character/input conflict")
            else report.Status="Voting is open  ·  step on your chosen map pad" end
            if C.OnPad and not blocked then
                for _,entry in ipairs(entries) do
                    if entry.Voting and entry.Map and C.OnPad(entry.Pad) then
                        State.SelectMapVote(entry.Pad,"Position"); break
                    end
                end
            end
            return
        end
        local r,entry=selected,findPad(selected.Pad)
        if not entry or not entry.Voting or entry.Map~=r.Map then
            State.StopMapVoteRepeat("Voting ended or maps changed  ·  stopped"); return
        end
        report.ObservedIncrease=math.max(0,entry.Votes-r.InitialVotes)
        local blocked=C.Blocked()
        if blocked then State.StopMapVoteRepeat("Stopped  ·  "..(type(blocked)=="string" and blocked or "character/input conflict")); return end
        local char,hum,root=C.Character()
        if report.Phase=="Touching" then
            if char~=r.Character or not hum or hum.Health<=0 then State.StopMapVoteRepeat("Character changed during vote touch"); return end
            if now<r.ReadyAt then return end
            if not cleanup() then State.StopMapVoteRepeat(); return end
            report.Phase="Observing"; r.ReadyAt=now+2
            report.Status="Returned to selected voting pad  ·  waiting for server count"
        elseif report.Phase=="AwaitRespawn" then
            if now>r.Deadline then State.StopMapVoteRepeat("Respawn not observed within 12 seconds  ·  stopped"); return end
            if char==r.OldCharacter or not hum or hum.Health<=0 or not root then return end
            r.Character,r.ReadyAt=char,now+.35; report.Phase="SpawnReady"
        elseif report.Phase=="SpawnReady" then
            if char~=r.Character or not hum or hum.Health<=0 or not root then State.StopMapVoteRepeat("New character unavailable  ·  stopped"); return end
            if now<r.ReadyAt then return end
            r.BeforeTouch=entry.Votes
            local touch={Pad=r.Pad,Root=root}
            contact=touch
            local ok=pcall(function()
                C.ApproachPad(root,r.Pad)
                if type(C.Touch)=="function" then
                    touch.Began=true -- An API can throw after beginning contact; always pair it.
                    C.Touch(root,r.Pad,0)
                end
            end)
            if not ok then State.StopMapVoteRepeat("Vote touch failed  ·  stopped"); return end
            report.Touches+=1; report.Phase="Touching"; r.ReadyAt=now+.25
        elseif report.Phase=="Observing" then
            if now<r.ReadyAt then return end
            if not r.Initial and entry.Votes<=r.BeforeTouch then
                State.StopMapVoteRepeat("No additional server vote count observed  ·  stopped"); return
            end
            if report.Respawns>=report.MaxRespawns then State.StopMapVoteRepeat("3 respawn attempts complete  ·  stopped"); return end
            if not char or not hum or hum.Health<=0 or not root then State.StopMapVoteRepeat("Living lobby character required  ·  stopped"); return end
            r.Initial=false; r.OldCharacter=char; r.Deadline=now+12
            report.Respawns+=1; report.Phase="AwaitRespawn"
            report.Status="Respawn requested ("..report.Respawns.."/3)  ·  waiting for a new character"
            local ok=pcall(C.Reset,hum,char)
            if not ok then State.StopMapVoteRepeat("Respawn request failed  ·  stopped") end
        end
    end
    C.Connect(C.Heartbeat,function()
        local now=clock()
        if now<(nextTick or 0) then return end
        local ok=pcall(step)
        if not ok then State.StopMapVoteRepeat("Map vote error  ·  stopped") end
        nextTick=now+(report.Phase=="Touching" and .05 or .25)
    end)
    function State.DestroyMapVoteRepeat()
        local ok,message=State.StopMapVoteRepeat("Unloaded")
        if ok then for pad,hook in pairs(hooks) do hook:Disconnect(); hooks[pad]=nil end end
        return ok,message
    end
end

local function resetMapVoteCharacter(hum,char)
    if not char or not hum or hum.Parent~=char then error("Character changed before reset") end
    hum.Health=0
    char:BreakJoints()
end

local function readMapVotePads(world)
    local lobby=world:FindFirstChild("Lobby")
    -- A current voting container takes precedence even while its boards load/close.
    -- Do not switch back to an old lobby's stale active metadata during that transition.
    if not lobby or not (lobby:FindFirstChild("VotePads") or lobby:FindFirstChild("VotePad1")) then
        lobby=world:FindFirstChild("RegularLobby") or lobby
    end
    local folder=lobby and lobby:FindFirstChild("VoteIcons")
    local detectors=lobby and lobby:FindFirstChild("VotePads")
    local entries={}
    if not lobby then return entries end
    for i=1,3 do
        local nested=detectors and detectors:FindFirstChild("VotePad"..i)
        local model=nested or lobby:FindFirstChild("VotePad"..i)
        local pad=nested and nested:FindFirstChild("Pad") or detectors and detectors:FindFirstChild("Detector"..i)
            or model and model:FindFirstChild("Pad")
        local layout=nested and "NestedVotePads" or "DirectBoards"
        local gui=model and model:FindFirstChild("VoteInfoGui")
        local container=gui and gui:FindFirstChild("Container")
        local label=container and container:FindFirstChild("MapName")
        local count=container and container:FindFirstChild("Votes")
        local icon=folder and folder:FindFirstChild("VotePad"..i)
        local map=icon and icon:FindFirstChild("Map")
        local voting=icon and icon:FindFirstChild("Voting")
        local votes=icon and icon:FindFirstChild("Votes")
        -- Current MM2 updates these server-owned boards while legacy icon values stay false/nil/0.
        -- A present but disabled board means voting is closed; never fall back to stale legacy flags.
        if pad and pad:IsA("BasePart") and gui and gui:IsA("SurfaceGui") then
            local name=label and label:IsA("TextLabel") and label.Text:match("^%s*(.-)%s*$") or ""
            local total=count and count:IsA("TextLabel") and tonumber(count.Text:match("%d+")) or nil
            table.insert(entries,{Pad=pad,Map=name~="" and name or nil,Name=name,Slot=i,
                Voting=gui.Enabled and container~=nil and container.Visible and name~="" and total~=nil,
                Votes=total or 0,Source="VotingBoard",Layout=layout})
        elseif pad and pad:IsA("BasePart") and map and map:IsA("ObjectValue")
            and voting and voting:IsA("BoolValue") and votes and votes:IsA("IntValue") then
            table.insert(entries,{Pad=pad,Map=map.Value,Name=map.Value and map.Value.Name or "Unknown map",
                Voting=voting.Value,Votes=votes.Value,Source="LegacyValues",Slot=i,Layout="LegacyDetectors"})
        end
    end
    return entries
end

installMapVoteRepeat({State=State,Heartbeat=RunService.Heartbeat,Connect=connect,
    Watch=function(signal,callback) return signal:Connect(callback) end,
    Touch=type(firetouchinterest)=="function" and firetouchinterest or nil,
    ReadPads=function() return readMapVotePads(workspace) end,
    Character=function()
        local char=player.Character
        return char,char and char:FindFirstChildOfClass("Humanoid"),char and char:FindFirstChild("HumanoidRootPart")
    end,
    OwnTouch=function(hit) return player.Character and hit:IsDescendantOf(player.Character) end,
    OnPad=function(pad)
        local char=player.Character
        local root=char and char:FindFirstChild("HumanoidRootPart")
        local hum=char and char:FindFirstChildOfClass("Humanoid")
        if not root or not hum or hum.Health<=0 then return false end
        local point=pad.CFrame:PointToObjectSpace(root.Position)
        local half=pad.Size*.5
        return math.abs(point.X)<=half.X and math.abs(point.Y)<=half.Y and math.abs(point.Z)<=half.Z
    end,
    Blocked=function()
        local char=player.Character
        local root=char and char:FindFirstChild("HumanoidRootPart")
        if GuiService.MenuIsOpen then return "Close the Roblox menu" end
        if UIS:GetFocusedTextBox() then return "Finish typing" end
        if State.MobileUI.MenuOpen then return "Close the script menu" end
        if State.Fling and State.Fling.Active or State.FlingQueue and State.FlingQueue.Active then return "Stop fling" end
        if State.Invis and (State.Invis.Active or State.Invis.Busy) then return "Invisibility is active" end
        if State.Config.KillAura then return "Stop kill aura" end
        if State.PlayerActions and State.PlayerActions.Enabled then return "Stop automatic attacks" end
        if root and espInRoundArea(root.Position) then return "Waiting until you are in the lobby" end
        if mobileBlocked() then return "Waiting for menu input to settle" end
    end,
    ApproachPad=function(root,pad)
        if State.ReleaseFly then State.ReleaseFly() end
        root.AssemblyLinearVelocity,root.AssemblyAngularVelocity=Vector3.zero,Vector3.zero
        root.CFrame=CFrame.new(pad.Position)*root.CFrame.Rotation
    end,
    Reset=resetMapVoteCharacter})
end

local function autoPickup() State.TickGunPickup() end
function State.RefreshVisuals()
    State.FeatureGuard.Run("PlayerESP",updateESP)
    State.FeatureGuard.Run("ThreatWarning",updateThreat)
    State.FeatureGuard.Run("GunESP",updateGunESP)
end

function State.Destroy()
    -- Saved before unload switches features off. A copy replaced by a newer one never writes over newer settings.
    if State.SaveSettings and player:GetAttribute("MM2UniversalInstance") == State.InstanceToken then State.SaveSettings() end
    if State.StopFlingAll then local ok,message=State.StopFlingAll("Unloaded"); if ok==false then return false,message end end
    if State.StopGunPickup then local ok,message=State.StopGunPickup(); if ok==false then return false,message end end
    if State.DestroyMapVoteRepeat then local ok,message=State.DestroyMapVoteRepeat(); if ok==false then return false,message end end
    if State.StopGhostAppearance then local ok,message=State.StopGhostAppearance(); if ok==false then return false,message end end
    if State.FlushAuraTouches and not State.FlushAuraTouches() then
        warn("Unload stopped: blade touch cleanup incomplete; retry unload")
        return false
    end
    if State.StopKillAura then State.StopKillAura("Unloaded") end
    if State.SetInvisibility and not State.SetInvisibility(false) then
        warn("Unload stopped: character restoration is incomplete; retry Restore character")
        return false
    end
    if State.StopStreamerMode then local stopped,message=State.StopStreamerMode(); if stopped==false then return false,message end end
    -- Only now can unload no longer be refused, so a refused unload keeps movement and X-ray as they were.
    if State.StopMovement then State.StopMovement() end
    if State.StopXRay then State.StopXRay() end
    if State.StopAntiFling then State.StopAntiFling() end
    if State.StopTriggerbot then State.StopTriggerbot("Unloaded") end
    if State.StopWeaponEquipRecovery then State.StopWeaponEquipRecovery() end
    if not State.Running then return end
    State.Running = false
    if State.StopScreenESP then State.StopScreenESP() end
    if State.DestroyTacticalGuide then State.DestroyTacticalGuide() end
    if State.StopAutoAttack then State.StopAutoAttack("Unloaded") end
    if State.StopFling then State.StopFling("Unloaded; position restored") end
    if State.MobileUI and State.MobileUI.Destroy then State.MobileUI.Destroy() end
    if State.DestroyKnifeDodge then State.DestroyKnifeDodge() elseif State.StopKnifeDodge then State.StopKnifeDodge() end
    if State.SetExperimentalInvisibility then State.SetExperimentalInvisibility(false) end
    if State.StopPose then State.StopPose(true) end
    if State.RestoreMage then State.RestoreMage(true) end
    restoreInvisibility()
    for _, connection in ipairs(State.Connections) do connection:Disconnect() end
    local items = {}
    for item in pairs(State.WeaponHandlers) do table.insert(items, item) end
    for _, item in ipairs(items) do restoreHandler(item) end
    if State.StopCameraGuard then State.StopCameraGuard() end
    visualFolder:Destroy()
    gui:Destroy()
    markerGui:Destroy()
    if env.MM2Assist == State then env.MM2Assist = nil end
    if player:GetAttribute("MM2UniversalInstance") == State.InstanceToken then player:SetAttribute("MM2UniversalInstance", nil) end
end
