function State.PreviewGunShot()
    if not State.Config.Aim or not State.Config.MagicBullet then return {Enabled = false} end
    sampleMotion(os.clock(), true)
    local item = toolFor(player, "Gun")
    local origin = shotOrigin("Gun", item)
    local solution = chooseTarget("Gun", origin, item)
    if not solution then return {Enabled = true, ClearShot = false, Status = "No clear eligible opponent"} end
    local head = player.Character and player.Character:FindFirstChild("Head")
    local clearMuzzle = not head or clearPath(head.Position, origin, player.Character)
    return {Enabled = true, ClearShot = clearMuzzle, Target = solution.Player.Name,
        Role = roleFor(solution.Player), AimPart = solution.AimPart, Position = solution.Position,
        Offscreen = solution.Offscreen, LeadTime = solution.LeadTime, Airborne = solution.Airborne, TargetMode = solution.TargetMode,
        Equipped = item ~= nil and item.Parent == player.Character,
        GunReady = item ~= nil and item.Enabled, TimingCoverage = solution.TimingCoverage}
end
function State.PreviewKnifeShot()
    local item = toolFor(player, "Knife")
    local origin = shotOrigin("Knife", item)
    local target = chooseTarget("Knife", origin, item)
    if not target then return {EligibleTarget = false} end
    return {EligibleTarget = true, Target = target.Player.Name, ClearShot = target.ClearShot,
        AimPoint = target.Position, PayloadType = typeof(CFrame.new(target.Position)),
        KnifeSpeed = State.ObservedKnifeSpeed or State.Config.KnifeSpeed,
        Airborne = target.Airborne, LeadTime = target.LeadTime,
        AimPart = target.AimPart, SampleOffset = target.SampleOffset, VelocitySource = target.VelocitySource,
        ExposureQuality = target.ExposureQuality, ClearNeighbours = target.ClearNeighbours}
end
do
local installPerformancePreset=function(C)
    local State=C.State
    local keys={"CleanVisuals","CompactHUD","StableBodyESP","AimMarker","ThreatWarning","TacticalGuide","LearnedSheriffGuide"}
    local low={CleanVisuals=true,CompactHUD=true,StableBodyESP=false,AimMarker=false,ThreatWarning=false,TacticalGuide=false,LearnedSheriffGuide=false}
    if State.Config.PerformancePreset~="Low effects" then State.Config.PerformancePreset="Balanced" end
    function State.GetBackgroundInterval(base)
        return base*(State.Config.PerformancePreset=="Low effects" and 2 or 1)
    end
    function State.SetPerformancePreset(name)
        if name~="Balanced" and name~="Low effects" then return false,"Unknown performance preset" end
        State.Config.PerformancePreset=name
        for _,key in ipairs(keys) do
            local value=name=="Low effects" and low[key]
            if name=="Balanced" then value=State.DefaultConfig[key] end
            if type(value)=="boolean" then State.Config[key]=value end
        end
        if State.SetTacticalGuide then State.SetTacticalGuide(State.Config.TacticalGuide) end
        if State.SetLearnedSheriffGuide then State.SetLearnedSheriffGuide(State.Config.LearnedSheriffGuide) end
        State.PreviewCache=nil
        State.NextVisualUpdate=nil
        if C.UpdateVisuals then C.UpdateVisuals() end
        if State.MobileUI and State.MobileUI.Refresh then State.MobileUI.Refresh() end
        return true,name=="Low effects" and "Low effects: fewer visuals and background updates" or "Balanced: visual defaults restored"
    end
    if State.Config.PerformancePreset=="Low effects" then State.SetPerformancePreset("Low effects") end
end
installPerformancePreset({State=State,UpdateVisuals=function() updateESP(); updateThreat(); updateGunESP() end})
end
local elapsed, pingElapsed = 0, 0
connect(RunService.Heartbeat, function(dt)
    for _, record in pairs(State.WeaponHandlers) do scanStabContacts(record) end
    sampleMotion(os.clock())
    elapsed += dt
    pingElapsed += dt
    if pingElapsed >= 3 then
        pingElapsed = 0
        local success, ping = pcall(player.GetNetworkPing, player)
        if success and type(ping) == "number" then State.Config.Ping = math.clamp(ping, 0, 0.15) end
    end
    if elapsed < 0.2 then return end
    elapsed = 0
    if player:GetAttribute("MM2UniversalInstance") ~= State.InstanceToken then
        -- A newer copy took over: unload this one, retrying each second if unload is refused.
        if os.clock() - (State.SupersededAt or -math.huge) >= 1 then
            State.SupersededAt = os.clock()
            task.spawn(State.Destroy)
        end
        return
    end
    if State.SaveSettings and os.clock() - (State.Settings.CheckedAt or -math.huge) >= 2 then
        State.Settings.CheckedAt = os.clock()
        State.SaveSettings()
    end
    while State.PendingGun[1] and os.clock() - State.PendingGun[1].SentAt > 3 do
        local expired = table.remove(State.PendingGun, 1)
        State.Stats.GunUnconfirmed += 1
        table.insert(State.ShotLog, {Target = expired.Target and expired.Target.Name,
            Confirmed = false, Status = "NoCorrelatedResponse", RequestedPoint = expired.AimPoint,
            AimPart = expired.AimPart, VelocitySource = expired.VelocitySource})
        if #State.ShotLog > 10 then table.remove(State.ShotLog, 1) end
        if expired.ShotId == State.GunShotSequence and expired.OwnCharacter == player.Character
            and (not State.LastGunFeedback or not State.LastGunFeedback.RoundWon) then
            State.LastGunFeedback = {Target = expired.Target and expired.Target.Name,
                Message = "No unique reply matched this shot; outcome unknown"}
        end
    end
    State.FeatureGuard.Run("Weapons",syncWeapons)
    if os.clock()>=(State.NextVisualUpdate or 0) then
        State.NextVisualUpdate=os.clock()+State.GetBackgroundInterval(.2)
        State.RefreshVisuals()
    end
    State.FeatureGuard.Run("GunPickup",autoPickup)
    -- Legacy panel labels: write only real changes so unchanged text is not re-laid out.
    local aimText = State.AimStatus
    local gunText = State.LastGunFeedback and State.LastGunFeedback.Message or "Gun feedback: waiting for shot"
    local dodgeText = State.Config.AutoKnifeDodge and State.KnifeDodge.Status or "Knife dodge OFF"
    if status.Text ~= aimText then status.Text = aimText end
    if gunFeedback.Text ~= gunText then gunFeedback.Text = gunText end
    if dodgeStatus.Text ~= dodgeText then dodgeStatus.Text = dodgeText end
    if invisStatus.Text ~= State.Invis.Status then invisStatus.Text = State.Invis.Status end
end)
State.RefreshVisuals()
State.FeatureGuard.Run("Weapons",syncWeapons)
print("MM2 Universal " .. State.Version .. " loaded. Right Shift or the MM2 button opens the menu.")

State.CancelExcludedWeaponActions = function(id)
    for _, record in pairs(State.WeaponHandlers) do
        if record.Charging and record.ThrowTargetUserId == id then
            record.ThrowToken += 1
            record.Charging, record.AutoSelectedThrow = false, nil
            record.LastThrow = -math.huge
            stopTracks(record)
        end
        if record.StabTarget and record.StabTarget.UserId == id then record.StabbingUntil = 0 end
    end
end


do
-- User-triggered launch sessions, with recovery between bursts until target elimination.
local installPlayerFling = function(C)
    local State, Players, player = C.State, C.Players, C.Player
    local clock = C.Clock or os.clock
    local fling = {Active = false, Status = "Idle", BurstDuration = 0.55, RecoveryDuration = 0.18,
        Attempts = 0, Requests = 0, Bursts = 0, Phase = "Idle", LaunchSpeed = 1100, LiftSpeed = 450,
        AdaptivePursuit = not State.Config or State.Config.FlingAdaptivePursuit ~= false,
        Mode = State.Config and State.Config.FlingSpinContact and "Spin"
            or (State.Config and State.Config.FlingDownward and "Downward" or "Outward")}
    if State.Config then
        State.Config.FlingSpinContact, State.Config.FlingDownward = fling.Mode == "Spin", fling.Mode == "Downward"
        State.Config.FlingAdaptivePursuit = fling.AdaptivePursuit
    end
    State.Fling = fling
    local saved, returning
    local function put(object, property, value)
        pcall(function() object[property] = value end)
    end
    local function describe(message)
        fling.Status = message
        fling.DisplayUntil = clock() + 4
        State.AimStatus = message
    end
    function State.GetFlingReport()
        local last = fling.LastResult or {}
        local request = State.MobileUI and State.MobileUI.LastFlingAction
        return table.concat({
            "MM2 fling report", "Build: " .. tostring(State.Build),
            "Contact mode: " .. tostring(fling.Mode),
            "Active: " .. tostring(fling.Active), "Phase: " .. tostring(fling.Phase),
            "Status: " .. tostring(fling.Status), "Pause: " .. tostring(fling.BlockedReason or "none"),
            "Button: " .. tostring(request and request.Name or "none"),
            "Button accepted: " .. tostring(request and request.Accepted),
            "Requests: " .. tostring(fling.Requests), "Target ID: " .. tostring(fling.Target or last.Target),
            "Contact writes: " .. tostring(fling.ContactSteps or 0),
            "Contact path: " .. tostring(fling.ContactPath or "not checked"),
            "Tracked root: " .. tostring(fling.RootName or "none"),
            "Contact body: " .. tostring(fling.ContactPartName or "none"),
            "Fast/flying tracking: " .. tostring(fling.AdaptivePursuit),
            "Motion source: " .. tostring(fling.MotionSource or "none"),
            "Return: " .. tostring(fling.ReturnStatus or "not captured"),
            ("Measured movement speed: %.2f studs/s"):format(fling.MeasuredSpeed or 0),
            ("Current contact gap: %.2f studs"):format(fling.ContactGap or 0),
            "Session bursts: " .. tostring(saved and saved.Bursts or last.Bursts or 0),
            ("Observed displacement: %.2f studs"):format(fling.TargetDisplacement or last.Displacement or 0),
            ("Observed peak speed: %.2f studs/s"):format(fling.MaxTargetSpeed or last.MaxSpeed or 0),
            "Target death observed: " .. tostring(last.TargetDied == true),
            "Local observations do not confirm server replication."
        }, "\n")
    end
    local function rigRoot(char, hum)
        if not char then return nil end
        local function valid(part)
            return part and part:IsA("BasePart") and part:IsDescendantOf(char)
        end
        local root = char:FindFirstChild("HumanoidRootPart")
        if valid(root) then return root end
        root = hum and hum.RootPart
        if valid(root) then return root end
        for _, name in ipairs({"Torso", "UpperTorso", "LowerTorso"}) do
            root = char:FindFirstChild(name)
            if valid(root) then return root end
        end
        return valid(char.PrimaryPart) and char.PrimaryPart or nil
    end
    local function anchored(part)
        return part.Anchored or (part.AssemblyRootPart and part.AssemblyRootPart.Anchored)
    end
    local function characterParts(p)
        local char = p and p.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local root = rigRoot(char, hum)
        if not char or not hum or hum.Health <= 0 or not root then return nil end
        return char, hum, root
    end
    local function finite(vector)
        return vector.X == vector.X and vector.Y == vector.Y and vector.Z == vector.Z
            and math.abs(vector.X) < 1e6 and math.abs(vector.Y) < 1e6 and math.abs(vector.Z) < 1e6
    end
    local function mapBounds(position)
        if C.GetMapBounds then return C.GetMapBounds(position) end
        if not C.Workspace.GetChildren then return nil end
        for _, map in ipairs(C.Workspace:GetChildren()) do
            if map:IsA("Model") and map:FindFirstChild("Spawns") and map:FindFirstChild("Base") then
                local base = map:FindFirstChild("Base")
                local geometry = base:IsA("Model") and base or map
                local ok, frame, size = pcall(geometry.GetBoundingBox, geometry)
                if ok and finite(size) then
                    local point = frame:PointToObjectSpace(position)
                    if math.abs(point.X) <= size.X / 2 + 12 and math.abs(point.Z) <= size.Z / 2 + 12
                        and math.abs(point.Y) <= size.Y / 2 + 20 then
                        return {Frame = frame, Size = size, Name = map.Name}
                    end
                end
            end
        end
    end
    local function launchDirection(position, ownPosition, bounds)
        if bounds then
            local point = bounds.Frame:PointToObjectSpace(position)
            local xDistance, zDistance = bounds.Size.X / 2 - math.abs(point.X), bounds.Size.Z / 2 - math.abs(point.Z)
            local localDirection = xDistance < zDistance and Vector3.new(point.X >= 0 and 1 or -1, 0, 0)
                or Vector3.new(0, 0, point.Z >= 0 and 1 or -1)
            local worldDirection = bounds.Frame:VectorToWorldSpace(localDirection)
            local flat = Vector3.new(worldDirection.X, 0, worldDirection.Z)
            if flat.Magnitude > 0.01 then return flat.Unit end
        end
        local delta = position - ownPosition
        local flat = Vector3.new(delta.X, 0, delta.Z)
        return flat.Magnitude > 0.1 and flat.Unit or Vector3.new(1, 0, 0)
    end
    local function outsideBounds(position, bounds)
        if not bounds then return false end
        local point = bounds.Frame:PointToObjectSpace(position)
        return math.abs(point.X) > bounds.Size.X / 2 + 12
            or math.abs(point.Z) > bounds.Size.Z / 2 + 12
            or point.Y > bounds.Size.Y / 2 + 24
    end
    function State.GetFlingPlayers()
        local result = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= player then
                table.insert(result, {UserId = p.UserId, Name = p.Name, DisplayName = p.DisplayName, Role = C.RoleFor(p)})
            end
        end
        table.sort(result, function(a, b) return a.Name:lower() < b.Name:lower() end)
        return result
    end
    local function clearSpinner(record)
        if record.Spinner then pcall(function() record.Spinner:Destroy() end); record.Spinner = nil end
        if record.SpinAttachment then pcall(function() record.SpinAttachment:Destroy() end); record.SpinAttachment = nil end
    end
    local function rememberBodyPart(record, part)
        if not part:IsA("BasePart") or record.BodySeen[part] then return end
        record.BodySeen[part] = true
        table.insert(record.BodyProperties, {Part=part, Massless=part.Massless,
            CanCollide=part.CanCollide, PhysicalProperties=part.CustomPhysicalProperties})
    end
    local function returnFrame(char, hum, root, frame)
        if not C.Workspace.Raycast or not C.Workspace.GetPartBoundsInBox then return frame, nil, "Saved start (floor query unavailable)" end
        local excluded = {}
        for _, p in ipairs(Players:GetPlayers()) do if p.Character then table.insert(excluded,p.Character) end end
        local ray, overlap = RaycastParams.new(), OverlapParams.new()
        ray.FilterType, overlap.FilterType = Enum.RaycastFilterType.Exclude, Enum.RaycastFilterType.Exclude
        ray.FilterDescendantsInstances, overlap.FilterDescendantsInstances = excluded, excluded
        ray.RespectCanCollide, ray.IgnoreWater, overlap.RespectCanCollide, overlap.MaxParts = true, true, true, 30
        local height = (hum.HipHeight or 2) + root.Size.Y / 2 + 0.05
        if hum.RigType == Enum.HumanoidRigType.R6 then
            local leg = char:FindFirstChild("Left Leg"); height += leg and leg.Size.Y or 2
        end
        local size = Vector3.new(math.max(.2,root.Size.X*.9),math.max(.2,height*2-.25),math.max(.2,root.Size.Z*.9))
        for _, offset in ipairs({Vector3.zero,Vector3.new(2,0,0),Vector3.new(-2,0,0),Vector3.new(0,0,2),Vector3.new(0,0,-2),
            Vector3.new(4,0,0),Vector3.new(-4,0,0),Vector3.new(0,0,4),Vector3.new(0,0,-4)}) do
            local point = frame.Position + offset
            local hit = C.Workspace:Raycast(point+Vector3.new(0,.5,0),Vector3.new(0,-512,0),ray)
            if hit and hit.Normal.Y>.6 and hit.Position.Y>C.Workspace.FallenPartsDestroyHeight+30 then
                local y = hit.Position.Y + height
                if math.abs(point.Y-y)<.7 then y=point.Y end
                local destination = CFrame.new(Vector3.new(point.X,y,point.Z)) * frame.Rotation
                local clear = #C.Workspace:GetPartBoundsInBox(destination,size,overlap)==0
                if clear then return destination, hit.Instance, offset.Magnitude==0 and "Starting spot grounded" or "Clear landing beside starting spot" end
            end
        end
        return nil, nil, "No clear floor beneath starting spot"
    end
    local function captureReturn(char, hum, root)
        local frame, support, status = returnFrame(char,hum,root,root.CFrame)
        if not frame then return nil, status end
        local anchor = {Frame=frame,Status=status,Grounded=support~=nil}
        if support and support:IsA("BasePart") and not support:IsA("Terrain") then
            anchor.Support, anchor.LocalFrame = support, support.CFrame:ToObjectSpace(frame)
        end
        return anchor
    end
    local function moveBack(record, frame)
        if record.Character.PivotTo and record.Character.GetPivot and record.RootToPivot then
            record.Character:PivotTo(frame * record.RootToPivot)
        else
            record.Root.CFrame = frame
        end
        record.Root.AssemblyLinearVelocity, record.Root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
    end
    local function restore(record, final)
        if record then
            clearSpinner(record)
            if final and record.AddedConnection then record.AddedConnection:Disconnect(); record.AddedConnection=nil end
            for _, item in ipairs(record.BodyProperties or {}) do
                if item.Part.Parent then
                    put(item.Part, "Massless", item.Massless)
                    put(item.Part, "CanCollide", item.CanCollide)
                    put(item.Part, "CustomPhysicalProperties", item.PhysicalProperties)
                end
            end
            -- Never move a newly spawned character to an older character's return point.
            local same = player.Character == record.Character and rigRoot(record.Character,record.Humanoid)==record.Root
            if record.Root.Parent then
                put(record.Root, "AssemblyAngularVelocity", Vector3.zero)
                put(record.Root, "AssemblyLinearVelocity", Vector3.zero)
                if same and record.Humanoid.Health > 0 then
                    local anchor = record.ReturnAnchor
                    local frame = anchor and anchor.Frame or record.CFrame
                    if anchor and anchor.Support and anchor.Support.Parent then frame=anchor.Support.CFrame*anchor.LocalFrame end
                    local ok, checked, support, status = pcall(returnFrame,record.Character,record.Humanoid,record.Root,frame)
                    frame = ok and checked or (anchor and anchor.Frame or record.CFrame)
                    local moved, message = pcall(moveBack,record,frame)
                    fling.ReturnStatus = moved and (ok and checked and status or "Saved start used; landing could not be rechecked") or ("Return failed: "..tostring(message))
                    if final and moved then
                        returning={Record=record,Frame=frame,Steps=0,Until=clock()+.2}
                        -- Track the actual checked landing, including any obstacle-avoidance offset.
                        if ok and checked and support and support:IsA("BasePart") and not support:IsA("Terrain") then
                            returning.Support,returning.LocalFrame=support,support.CFrame:ToObjectSpace(frame)
                        end
                    end
                end
                put(record.Root, "CanCollide", record.CanCollide)
                put(record.Root, "CollisionGroup", record.CollisionGroup)
                put(record.Root, "CustomPhysicalProperties", record.PhysicalProperties)
                if same and record.Humanoid.Health > 0 then
                    put(record.Root, "AssemblyLinearVelocity", Vector3.zero)
                    put(record.Root, "AssemblyAngularVelocity", Vector3.zero)
                end
            end
            if record.Humanoid.Parent then
                put(record.Humanoid, "AutoRotate", record.AutoRotate)
                put(record.Humanoid, "PlatformStand", record.PlatformStand)
                if same and record.Humanoid.Health > 0 then
                    if final then put(record.Humanoid,"Jump",false) end
                    pcall(function()
                        record.Humanoid:ChangeState(final and record.ReturnAnchor and record.ReturnAnchor.Grounded
                            and Enum.HumanoidStateType.GettingUp or record.HumanoidState)
                    end)
                end
            end
        end
    end
    function State.CancelFlingReturn() returning=nil end
    function State.StopFling(message)
        local record = saved
        saved = nil
        fling.Active, fling.Target, fling.Phase = false, nil, "Idle"
        fling.BlockedReason = nil
        if record then
            local targetChar = record.Target.Character
            local targetRoot = rigRoot(targetChar, targetChar and targetChar:FindFirstChildOfClass("Humanoid"))
            local position = targetRoot and finite(targetRoot.Position) and targetRoot.Position or record.LastTargetPosition
            fling.LastResult = {Target = record.Target.UserId, Mode = record.Mode, MapBoundsAvailable = record.Bounds ~= nil,
                OutsideObservedBounds = record.ObservedExit or (position ~= nil and outsideBounds(position, record.Bounds)),
                Displacement = position and (position - record.TargetStart).Magnitude or nil,
                HeightGain = position and position.Y - record.TargetStart.Y or nil,
                MaxSpeed = record.MaxSpeed or 0, Bursts = record.Bursts or 0,
                TargetDied = record.TargetDied == true}
            restore(record, true)
        end
        if record and fling.ReturnStatus and fling.ReturnStatus:find("Return failed:",1,true) then
            describe("Fling stopped | "..fling.ReturnStatus)
        else describe(message or (record and "Fling stopped; returned to starting spot" or "Idle")) end
    end
    function State.SetFlingMode(mode)
        if mode ~= "Spin" and mode ~= "Downward" and mode ~= "Outward" then return false, "Unknown fling mode" end
        if fling.Mode == mode then return true, fling.Status end
        if fling.Active then State.StopFling("Mode changed; previous position restored") end
        State.Config = State.Config or {}
        State.Config.FlingDownward, State.Config.FlingSpinContact = mode == "Downward", mode == "Spin"
        fling.Mode = mode
        describe(mode .. " contact selected; choose a target to start")
        return true, fling.Status
    end
    function State.SetFlingDownward(enabled)
        return State.SetFlingMode(enabled and "Downward" or (fling.Mode == "Downward" and "Outward" or fling.Mode))
    end
    function State.SetFlingSpinContact(enabled)
        return State.SetFlingMode(enabled and "Spin" or (fling.Mode == "Spin" and "Outward" or fling.Mode))
    end
    function State.SetFlingAdaptivePursuit(enabled)
        enabled = enabled == true
        if fling.AdaptivePursuit == enabled then return true, fling.Status end
        if fling.Active then State.StopFling("Tracking changed; saved position and settings restored") end
        State.Config = State.Config or {}
        fling.AdaptivePursuit, State.Config.FlingAdaptivePursuit = enabled, enabled
        describe("Fast/flying tracking " .. (enabled and "ON" or "OFF") .. "; choose a target to start")
        return true, fling.Status
    end
    local function adaptive(record)
        return record.Mode == "Spin" and fling.AdaptivePursuit
    end
    local function observeMotion(record, root, now)
        local motion = record.Motion
        if not motion then
            record.Motion = {Root=root,Position=root.Position,At=now,Velocity=Vector3.zero,Samples=0}
            fling.MotionSource, fling.MeasuredSpeed = "waiting for position samples", 0
            return false
        end
        local dt, delta = now-motion.At, root.Position-motion.Position
        if dt <= 1/240 then return motion.Until ~= nil end
        motion.Position, motion.At = root.Position, now
        local changedRoot = motion.Root ~= root
        motion.Root = root
        local velocity = delta / dt
        local speed = velocity.Magnitude
        if changedRoot or dt > 0.25 or not finite(velocity)
            or delta.Magnitude > 900 * math.min(dt,0.1) + 6 or (speed > 900 and delta.Magnitude > 6) then
            motion.Velocity, motion.Samples, motion.Until = Vector3.zero, 0, now + 0.35
            motion.Reason = changedRoot and "root replaced" or (dt > 0.25 and "position samples interrupted" or "abrupt position change")
            fling.MotionSource = "holding: " .. motion.Reason
            fling.MeasuredSpeed = 0
            return true
        end
        -- Position observations take precedence over spoofed or stale velocity properties.
        if speed > 900 then velocity = velocity.Unit * 900 end
        motion.Velocity, motion.Samples = velocity, motion.Samples+1
        fling.MeasuredSpeed = velocity.Magnitude
        if motion.Until and (now < motion.Until or motion.Samples < 2) then return true end
        motion.Until, motion.Reason = nil, nil
        fling.MotionSource = "observed 3D position changes"
        return false
    end
    local function recover(record, now, message, delay, reason)
        restore(record, false)
        record.Phase = "Recover"
        fling.Phase = "Recover"
        -- A continuously held condition must not push the same retry deadline forward each frame.
        if record.RecoveryReason ~= reason or not record.RetryAt then
            record.RetryAt = now + (delay or fling.RecoveryDuration)
        end
        record.RecoveryReason = reason
        fling.BlockedReason = reason
        describe(message)
    end
    local function chooseContact(record, targetRoot, now)
        if record.Mode == "Spin" then
            -- Recorded IY profile uses local noclip, so map side-clearance is not a contact requirement.
            record.PathAvailable = true
            fling.ContactPath = "IY noclip contact / follows target in 3D"
            return true
        end
        if now < (record.NextPathCheck or 0) then return record.PathAvailable end
        record.NextPathCheck = now + 0.15
        if record.Mode == "Downward" then
            local offsets = {Vector3.new(0,1.55,0), Vector3.new(0.65,1.35,0), Vector3.new(-0.65,1.35,0),
                Vector3.new(0,1.35,0.65), Vector3.new(0,1.35,-0.65)}
            local overlap
            if C.Workspace.GetPartBoundsInBox then
                local excluded = {}
                for _, p in ipairs(Players:GetPlayers()) do if p.Character then table.insert(excluded,p.Character) end end
                overlap = OverlapParams.new()
                overlap.FilterType, overlap.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, excluded
                overlap.RespectCanCollide, overlap.CollisionGroup = true, "Default"
            end
            local first = math.floor((now - record.Started) / 0.15) % #offsets
            for i = 0, #offsets - 1 do
                local offset = offsets[(first + i) % #offsets + 1]
                local blocked = overlap and #C.Workspace:GetPartBoundsInBox(
                    CFrame.new(targetRoot.Position + offset), Vector3.new(3,4,3), overlap) > 0
                if not blocked then
                    record.ContactOffset, record.PathAvailable = offset, true
                    fling.ContactPath = overlap and "overhead contact / floor penetration unconfirmed" or "overhead contact / geometry queries unavailable"
                    return true
                end
            end
            record.PathAvailable = false
            fling.ContactPath = "overhead contact blocked by nearby geometry"
            return false
        end
        if not C.Workspace.Blockcast or not C.Workspace.GetPartBoundsInBox then
            record.PathAvailable = true
            fling.ContactPath = "geometry queries unavailable"
            return true
        end
        local excluded = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p.Character then table.insert(excluded, p.Character) end
        end
        local ray, overlap = RaycastParams.new(), OverlapParams.new()
        ray.FilterType, overlap.FilterType = Enum.RaycastFilterType.Exclude, Enum.RaycastFilterType.Exclude
        ray.FilterDescendantsInstances, overlap.FilterDescendantsInstances = excluded, excluded
        ray.RespectCanCollide, overlap.RespectCanCollide = true, true
        ray.CollisionGroup, overlap.CollisionGroup = "Default", "Default"
        local preferred = launchDirection(targetRoot.Position, record.CFrame.Position, record.Bounds)
        local side = Vector3.new(-preferred.Z, 0, preferred.X)
        local directions = {preferred, side, -side, -preferred,
            (preferred + side).Unit, (preferred - side).Unit,
            (-preferred + side).Unit, (-preferred - side).Unit}
        local chosen, bestScore, chosenClearance
        for _, direction in ipairs(directions) do
            local contact = targetRoot.Position - direction * 1.15 + Vector3.new(0, 0.1, 0)
            -- Casts omit initially overlapping parts, so check the contact volume separately.
            local blockers = C.Workspace:GetPartBoundsInBox(CFrame.new(contact), Vector3.new(3, 4, 3), overlap)
            if #blockers == 0 then
                local hit = C.Workspace:Blockcast(CFrame.new(targetRoot.Position), Vector3.new(3, 3, 3), direction * 8, ray)
                local clearance = hit and math.clamp(hit.Distance, 0, 8) or 8
                if clearance >= 2.5 then
                    local alignment = direction.X * preferred.X + direction.Z * preferred.Z
                    local score = clearance * 2 + alignment * 0.75
                    if not bestScore or score > bestScore then
                        chosen, bestScore, chosenClearance = direction, score, clearance
                    end
                end
            end
        end
        record.PathAvailable = chosen ~= nil
        if chosen then
            record.Direction = chosen
            fling.ContactPath = ("open side / %.1f studs clearance"):format(chosenClearance)
        else
            fling.ContactPath = "blocked by nearby geometry"
        end
        return record.PathAvailable
    end
    local function beginBurst(record, now)
        clearSpinner(record)
        record.Humanoid.AutoRotate = record.Mode == "Spin" and record.AutoRotate or false
        record.Humanoid.PlatformStand = record.Mode ~= "Spin"
        record.Root.CanCollide = record.Mode ~= "Spin"
        record.Root.CollisionGroup = "Default"
        record.Root.CustomPhysicalProperties = PhysicalProperties.new(record.Mode == "Spin" and 100 or 35, 0.3, 0.2)
        if record.Mode == "Spin" then
            for _, item in ipairs(record.BodyProperties or {}) do
                if item.Part.Parent then
                    item.Part.Massless = true
                    item.Part.CustomPhysicalProperties = PhysicalProperties.new(100,0.3,0.5)
                    item.Part.CanCollide = false
                end
            end
        end
        if record.Mode == "Spin" then
            -- Exact force settings observed during the user's IY demonstration.
            local spinner = Instance.new("BodyAngularVelocity")
            record.Spinner = spinner
            spinner.Name = "MM2IYContactSpin"
            spinner.AngularVelocity = Vector3.new(0,99999,0)
            spinner.MaxTorque = Vector3.new(0,math.huge,0)
            spinner.P = math.huge
            spinner.Parent = record.Root
        else
            local attachment = Instance.new("Attachment")
            record.SpinAttachment = attachment
            attachment.Name = "MM2LaunchAttachment"
            attachment.Parent = record.Root
            local spinner = Instance.new("AngularVelocity")
            record.Spinner = spinner
            spinner.Name = "MM2LaunchTorque"
            spinner.Attachment0 = attachment
            spinner.RelativeTo = Enum.ActuatorRelativeTo.World
            spinner.MaxTorque = 8000000
            spinner.AngularVelocity = record.Mode == "Downward" and Vector3.new(260,80,260) or Vector3.new(180,520,160)
            spinner.Parent = record.Root
        end
        record.Phase, record.BurstStarted = "Launch", now
        record.RecoveryReason, record.RetryAt, fling.BlockedReason = nil, nil, nil
        record.Bursts = (record.Bursts or 0) + 1
        fling.Phase = "Launch"
        fling.Bursts += 1
        describe((record.Mode == "Spin" and "Spin contact @" or (record.Mode == "Downward" and "Downward contact @" or "Launching @"))
            .. record.Target.Name .. " / burst " .. record.Bursts .. " / until eliminated or stopped")
    end
    local function applyContact(record, targetRoot, now)
        local elapsed = now - record.BurstStarted
        local direction = record.Direction
        local side = Vector3.new(-direction.Z, 0, direction.X)
        local wiggle = math.sin(elapsed * 34) * 0.22
        local position = targetRoot.Position - direction * 1.15 + side * wiggle + Vector3.new(0, 0.1, 0)
        if record.Mode == "Downward" then position = targetRoot.Position + record.ContactOffset end
        local inherited = finite(targetRoot.AssemblyLinearVelocity) and targetRoot.AssemblyLinearVelocity or Vector3.zero
        if inherited.Magnitude > 360 then inherited = inherited.Unit * 360 end
        if record.Mode == "Spin" then
            -- Follow a collidable body part rather than an invisible root offset.
            -- Direct character children exclude hats, tools and their handles.
            local contact = record.ContactPart
            if targetRoot ~= record.ContactRoot or now >= (record.NextBodyCheck or 0)
                or not contact or contact.Parent ~= record.TargetCharacter or not contact.CanCollide
                or anchored(contact) then
                record.ContactRoot, record.NextBodyCheck = targetRoot, now + 0.2
                contact = nil
                local bestScore = -math.huge
                local priorities = {Torso=40, UpperTorso=40, LowerTorso=30, HumanoidRootPart=20, Head=10}
                for _, part in ipairs(record.TargetCharacter:GetChildren()) do
                    if part:IsA("BasePart") and part.CanCollide and not anchored(part)
                        and finite(part.Position) and finite(part.Size) and (adaptive(record) or finite(part.AssemblyLinearVelocity))
                        and (part.Position - targetRoot.Position).Magnitude <= 22
                        and math.min(part.Size.X,part.Size.Y,part.Size.Z) > 0 then
                        local score = priorities[part.Name] or 0
                        if score > bestScore then contact, bestScore = part, score end
                    end
                end
                record.ContactPart = contact
            end
            if not contact then
                fling.ContactPartName = "none (no collidable body)"
                recover(record, now, "Waiting: no collidable target body; physical fling unavailable | Stop remains available", 0.2, "NoContact")
                return
            end
            if not finite(contact.Position) or (not adaptive(record) and not finite(contact.AssemblyLinearVelocity)) then
                recover(record, now, "Waiting: target body physics unavailable | Stop remains available", 0.2, "NoContact")
                return
            end
            local width = math.min(contact.Size.X, record.Root.Size.X)
            local offset = math.clamp(width * 0.4, 0.05, 1.2)
            local center = contact.CFrame:PointToWorldSpace(Vector3.new(offset,0,0))
            local dt = math.clamp(now - (record.LastContactAt or now), 0, 1/30)
            local velocity = finite(contact.AssemblyLinearVelocity) and contact.AssemblyLinearVelocity or Vector3.zero
            local matched = Vector3.zero
            if adaptive(record) and record.Motion and record.Motion.Samples > 0 then
                velocity, matched = record.Motion.Velocity, record.Motion.Velocity
            elseif velocity.Magnitude > 120 then velocity = Vector3.zero end
            local lead = velocity * dt
            local maxLead = math.clamp(width * 0.75, 0.05, 1.5)
            if lead.Magnitude > maxLead then lead = lead.Unit * maxLead end
            position = center + lead
            if not finite(position) or position.Y < C.Workspace.FallenPartsDestroyHeight + 80
                or (position - targetRoot.Position).Magnitude > 24 then
                recover(record, now, "Waiting: target body is outside safe contact reach | Stop remains available", 0.2, "NoContact")
                return
            end
            fling.ContactPartName = contact.Name
            fling.ContactPath = adaptive(record) and "IY spin / observed 3D pursuit" or "IY noclip / body-size and pose contact"
            record.LastContactAt = now
            for _, item in ipairs(record.BodyProperties or {}) do
                if item.Part.Parent then
                    if item.Part.CanCollide then item.Part.CanCollide = false end
                    if not item.Part.Massless then item.Part.Massless = true end
                end
            end
            -- Recenter without replacing the orientation produced by the physics solver.
            record.Root.CFrame = CFrame.new(position) * record.Root.CFrame.Rotation
            local spin = elapsed % 0.3 < 0.2 and Vector3.new(0,99999,0) or Vector3.zero
            record.Spinner.AngularVelocity = spin
            record.Root.AssemblyLinearVelocity = matched
        else
            record.Root.CFrame = CFrame.new(position) * CFrame.Angles(elapsed * 24, elapsed * 31, elapsed * 15)
            record.Root.AssemblyAngularVelocity = record.Mode == "Downward" and Vector3.new(260,80,260) or Vector3.new(180,520,160)
            record.Root.AssemblyLinearVelocity = (record.Mode == "Downward" and Vector3.new(0,-fling.LaunchSpeed,0)
                or direction * fling.LaunchSpeed + Vector3.new(0,fling.LiftSpeed,0)) + inherited
        end
        record.ContactSteps = (record.ContactSteps or 0) + 1
        fling.ContactSteps = record.ContactSteps
        fling.ContactGap = (record.Root.Position - targetRoot.Position).Magnitude
    end
    local function findPlayer(id)
        for _, p in ipairs(Players:GetPlayers()) do if p.UserId == tonumber(id) then return p end end
    end
    function State.FlingPlayer(id)
        if not State.Running then return false, "Script is unloaded" end
        fling.Requests += 1
        local target = findPlayer(id)
        if not target or target == player then describe("Select another player who is still in this server"); return false, fling.Status end
        if State.IsPlayerExcluded and State.IsPlayerExcluded(target) then describe("Target is excluded from fling"); return false, fling.Status end
        if fling.Active and saved then
            local targetChar = characterParts(target)
            if not targetChar then describe("Target character is unavailable; current session is unchanged"); return false, fling.Status end
            if saved.Target == target and saved.TargetCharacter == targetChar and player.Character == saved.Character then
                local now = clock()
                if saved.Phase == "Launch" then
                    describe("Contact is running for @" .. target.Name .. "; repeated clicks do not reset it")
                elseif (saved.RecoveryReason == "Damage" or saved.RecoveryReason == "Physics") and now < (saved.RetryAt or 0) then
                    describe(("Recovery active; retry in %.1fs"):format(saved.RetryAt - now))
                else
                    saved.RetryAt = now
                    describe("Retry requested for @" .. target.Name .. "; checking health and target reach")
                end
                return true, fling.Status
            end
            State.StopFling("Switching target; previous position restored")
        elseif fling.Active then
            State.StopFling("Cleared stale active state")
        end
        if State.Invis and (State.Invis.Busy or State.Invis.Active) then
            describe("Turn invisibility off before flinging"); return false, fling.Status
        end
        if State.ExperimentalInvis and (State.ExperimentalInvis.Active or State.ExperimentalInvis.Busy) then
            if not State.ExitUndergroundForAttack or not State.ExitUndergroundForAttack() then
                describe("Restore your character before flinging"); return false, fling.Status
            end
        end
        local char, hum, root = characterParts(player)
        local targetChar, targetHum, targetRoot = characterParts(target)
        if not char or not targetChar then describe("Both characters must be alive and loaded"); return false, fling.Status end
        if hum.Health <= math.max(1, (hum.MaxHealth or 100) * 0.25) then
            describe("Low health: recover before starting a new fling"); return false, fling.Status
        end
        if root.Position.Y < C.Workspace.FallenPartsDestroyHeight + 80 then
            describe("Move to a safe position before starting a fling"); return false, fling.Status
        end
        if targetRoot.Position.Y < C.Workspace.FallenPartsDestroyHeight + 80 then
            describe("Target is near the void; contact cannot start safely"); return false, fling.Status
        end
        if State.ReleaseFly then State.ReleaseFly() end -- fly holds PlatformStand; release it before the free-to-move check
        if anchored(root) or anchored(targetRoot) or hum.Sit or hum.PlatformStand then
            describe("Fling unavailable while a character is anchored, seated, or disabled"); return false, fling.Status
        end
        if fling.Mode == "Spin" then
            for _, item in ipairs(char:GetDescendants()) do
                if item:IsA("BodyAngularVelocity") or item:IsA("AngularVelocity") then
                    describe("Stop the other spin script before starting selected-player contact"); return false, fling.Status
                end
            end
        end
        if not finite(root.Position) or not finite(targetRoot.Position)
            or not finite(root.AssemblyLinearVelocity) or not finite(root.AssemblyAngularVelocity)
            or (not (fling.Mode == "Spin" and fling.AdaptivePursuit) and not finite(targetRoot.AssemblyLinearVelocity))
            or root.AssemblyLinearVelocity.Magnitude > 80 or root.AssemblyAngularVelocity.Magnitude > 40 then
            describe("Wait until your character is moving normally"); return false, fling.Status
        end
        local anchorOK, anchor, anchorError = pcall(captureReturn,char,hum,root)
        if not anchorOK or not anchor then describe("Cannot save a safe return: "..tostring(anchorOK and anchorError or anchor)); return false,fling.Status end
        returning=nil
        local bounds = mapBounds(targetRoot.Position)
        saved = {Character = char, Humanoid = hum, Root = root, CFrame = root.CFrame,
            LinearVelocity = root.AssemblyLinearVelocity, AngularVelocity = root.AssemblyAngularVelocity,
            AutoRotate = hum.AutoRotate, PlatformStand = hum.PlatformStand, HumanoidState = hum:GetState(),
            CanCollide = root.CanCollide, CollisionGroup = root.CollisionGroup,
            PhysicalProperties = root.CustomPhysicalProperties,
            Target = target, TargetCharacter = targetChar, Mode = fling.Mode, Started = clock(), TargetStart = targetRoot.Position,
            -- A healthy lobby avatar can retain an earlier round's elimination flag.
            -- Trust a flagged transition only after observing a clear flag this session.
            WatchElimination = not (C.IsEliminated and C.IsEliminated(target)),
            Bounds = bounds, Direction = launchDirection(targetRoot.Position, root.Position, bounds), MaxSpeed = 0,
            LastHealth = hum.Health, LastTargetPosition = targetRoot.Position, Bursts = 0}
        saved.ReturnAnchor = anchor
        if char.GetPivot then saved.RootToPivot=root.CFrame:ToObjectSpace(char:GetPivot()) end
        fling.ReturnStatus=anchor.Status
        if adaptive(saved) then observeMotion(saved, targetRoot, saved.Started) end
        if saved.Mode == "Spin" then
            saved.BodyProperties, saved.BodySeen = {}, {}
            for _, part in ipairs(char:GetDescendants()) do rememberBodyPart(saved,part) end
            local record = saved
            if char.DescendantAdded then
                record.AddedConnection = char.DescendantAdded:Connect(function(part)
                    if saved == record then
                        rememberBodyPart(record,part)
                        if part:IsA("BasePart") and record.Phase == "Launch" then
                            part.CanCollide, part.Massless = false, true
                            part.CustomPhysicalProperties = PhysicalProperties.new(100,0.3,0.5)
                        end
                    end
                end)
            end
        end
        fling.Active, fling.Target = true, target.UserId
        fling.ContactSteps, fling.TargetDisplacement, fling.MaxTargetSpeed = 0, 0, 0
        fling.ContactPath = "not checked"
        fling.RootName, fling.ContactPartName = targetRoot.Name, nil
        if not adaptive(saved) then fling.MotionSource, fling.MeasuredSpeed = "legacy tracking", 0 end
        fling.Attempts += 1
        if C.StopWeaponActions then C.StopWeaponActions() end
        local ok, message = pcall(function()
            local now = clock()
            if not chooseContact(saved, targetRoot, now) then
                recover(saved, now, (saved.Mode == "Downward" and "Waiting: overhead contact blocked" or "Waiting: no clear contact side near target") .. " | Stop remains available", 0.18, "Wall")
                return
            end
            beginBurst(saved, now)
            -- Start on this button press; subsequent updates run before the physics solver.
            applyContact(saved, targetRoot, now)
        end)
        if not ok then State.StopFling("Fling setup failed: " .. tostring(message)); return false, fling.Status end
        return true, fling.Status
    end
    function State.FlingRole(role)
        if C.ResolveRole then role=C.ResolveRole(role)
        elseif role == "Opponent" then role = C.RoleFor(player) == "Murderer" and "Sheriff" or "Murderer" end
        if not role or not C.ResolveRole and role ~= "Murderer" and role ~= "Sheriff" then describe("Choose a supported role"); return false, fling.Status end
        local _, _, ownRoot = characterParts(player)
        local chosen, nearest
        for _, p in ipairs(Players:GetPlayers()) do
            local _, _, root = characterParts(p)
            -- The shared MM2 alive check requires the canonical root name.
            -- A healthy alternate rig can still qualify when round death flags are clear.
            local living = root and (C.IsAlive(p) or (root ~= p.Character:FindFirstChild("HumanoidRootPart")
                and C.IsEliminated and not C.IsEliminated(p)))
            if p ~= player and root and living and not (State.IsPlayerExcluded and State.IsPlayerExcluded(p))
                and (C.RoleFor(p) == role or role=="Sheriff" and C.RoleFor(p)=="Hero") then
                local distance = ownRoot and (root.Position - ownRoot.Position).Magnitude or 0
                if not nearest or distance < nearest then chosen, nearest = p, distance end
            end
        end
        if not chosen then describe("No living " .. role:lower() .. " is available"); return false, fling.Status end
        return State.FlingPlayer(chosen.UserId)
    end
    C.Connect(C.RunService.PreSimulation or C.RunService.Heartbeat, function()
        local record = saved
        if not record then
            local pending=returning
            if pending then
                local r=pending.Record
                if player.Character~=r.Character or rigRoot(r.Character,r.Humanoid)~=r.Root or r.Humanoid.Health<=0
                    or clock()>pending.Until or pending.Steps>=3 or r.Humanoid.Jump
                    or (r.Humanoid.MoveDirection and r.Humanoid.MoveDirection.Magnitude>.05) then returning=nil
                else
                    pending.Steps+=1
                    local ok,result=pcall(function()
                        if pending.Support then
                            if not pending.Support.Parent then return false end
                            pending.Frame=pending.Support.CFrame*pending.LocalFrame
                        end
                        moveBack(r,pending.Frame)
                        return true
                    end)
                    if not ok then
                        returning=nil
                        fling.ReturnStatus="Return failed: settling movement: "..tostring(result)
                        describe("Fling stopped | "..fling.ReturnStatus)
                    elseif result==false then returning=nil end
                end
            end
            return
        end
        local ok, message = pcall(function()
            if not State.Running or player.Character ~= record.Character or not record.Root.Parent
                or record.Humanoid.Health <= 0 then State.StopFling("Fling stopped: your character changed"); return end
            if rigRoot(record.Character, record.Humanoid) ~= record.Root then
                State.StopFling("Fling stopped: your avatar root changed; saved settings restored"); return
            end
            if (State.Invis and (State.Invis.Busy or State.Invis.Active))
                or (State.ExperimentalInvis and (State.ExperimentalInvis.Busy or State.ExperimentalInvis.Active)) then
                State.StopFling("Character mode changed; fling stopped and position restored"); return
            end
            local now = clock()
            if State.IsPlayerExcluded and State.IsPlayerExcluded(record.Target) then
                State.StopFling("Target excluded; fling stopped and position restored"); return
            end
            local targetChar = record.Target.Character
            local targetHum = targetChar and targetChar:FindFirstChildOfClass("Humanoid")
            if targetChar ~= record.TargetCharacter then State.StopFling("Fling stopped: target respawned or character changed"); return end
            local eliminated = C.IsEliminated and C.IsEliminated(record.Target)
            if not eliminated then record.WatchElimination = true end
            if (targetHum and targetHum.Health <= 0) or (record.WatchElimination and eliminated) then
                record.TargetDied = true
                State.StopFling("Target eliminated; returned to saved position"); return
            end
            local targetRoot = rigRoot(targetChar, targetHum)
            if targetRoot and finite(targetRoot.Position) then
                fling.RootName = targetRoot.Name
                record.LastTargetPosition = targetRoot.Position
                fling.TargetDisplacement = (targetRoot.Position - record.TargetStart).Magnitude
                record.ObservedExit = record.ObservedExit or outsideBounds(targetRoot.Position, record.Bounds)
                if finite(targetRoot.AssemblyLinearVelocity) then
                    record.MaxSpeed = math.max(record.MaxSpeed, targetRoot.AssemblyLinearVelocity.Magnitude)
                    fling.MaxTargetSpeed = record.MaxSpeed
                end
            end
            local dangerY = C.Workspace.FallenPartsDestroyHeight + 80
            if record.Humanoid.Health < record.LastHealth then
                record.LastHealth = record.Humanoid.Health
                record.RetryAt = nil
                recover(record, now, "You took damage; returned before retrying", 1.25, "Damage"); return
            end
            record.LastHealth = record.Humanoid.Health
            local lowHealth = record.Humanoid.Health <= math.max(1, (record.Humanoid.MaxHealth or 100) * 0.25)
            local validTarget = targetHum and targetRoot and targetRoot:IsA("BasePart")
                and finite(targetRoot.Position) and (adaptive(record) or finite(targetRoot.AssemblyLinearVelocity))
            local motionBlocked = validTarget and adaptive(record) and observeMotion(record, targetRoot, now)
            local pursuitLimit = adaptive(record) and 8192 or 280
            -- Bound pursuit from the target's initial position, not the lobby return point.
            local targetDistance = validTarget and (targetRoot.Position - record.TargetStart).Magnitude or 0
            local targetUnsafe = not validTarget or targetRoot.Position.Y < dangerY or targetDistance > pursuitLimit
            if lowHealth or targetUnsafe or anchored(record.Root) or (targetRoot and anchored(targetRoot)) then
                local reason = lowHealth and "LowHealth" or (not validTarget and "Unstreamed"
                    or (targetRoot.Position.Y < dangerY and "Void" or (targetDistance > pursuitLimit and "TooFar" or "Anchored")))
                local message = lowHealth and "Paused: health at or below 25%"
                    or (reason == "Unstreamed" and "Paused: target character is not loaded"
                    or (reason == "Void" and "Waiting for target death: target is near the void"
                    or (reason == "TooFar" and ("Paused: target moved %.0f studs from its start (limit: %d)"):format(targetDistance,pursuitLimit)
                    or "Paused: a character is anchored")))
                recover(record, now, message .. " | Stop remains available", 0.18, reason)
                return
            end
            if motionBlocked then
                recover(record, now, "Waiting for stable tracking: " .. (record.Motion.Reason or "position samples") .. " | Stop remains available", 0.18, "Motion")
                return
            end
            if not finite(record.Root.Position) or not finite(record.Root.AssemblyLinearVelocity)
                or record.Root.Position.Y < dangerY or record.Root.AssemblyLinearVelocity.Magnitude > 3500 then
                recover(record, now, "Physics recovery: returned before retrying", 0.8, "Physics"); return
            end
            if not chooseContact(record, targetRoot, now) then
                recover(record, now, (record.Mode == "Downward" and "Waiting: overhead contact blocked" or "Waiting: no clear contact side near target") .. " | Stop remains available", 0.18, "Wall"); return
            end
            if record.Phase == "Recover" then
                -- Stabilize at the saved position between bursts; never chase a target into the void.
                restore(record, false)
                if now < record.RetryAt then return end
                beginBurst(record, now)
            elseif record.Mode ~= "Spin" and now - record.BurstStarted >= fling.BurstDuration then
                recover(record, now, "Returned safely; retrying until target is eliminated", nil, "BetweenBursts"); return
            end
            applyContact(record, targetRoot, now)
        end)
        if not ok then State.StopFling("Fling interrupted: " .. tostring(message)) end
    end)
    C.Connect(player.CharacterRemoving, function() if fling.Active then State.StopFling("Fling stopped: respawning") end end)
    C.Connect(Players.PlayerRemoving, function(p)
        if saved and saved.Target == p then State.StopFling("Fling stopped: player left") end
    end)
    return fling
end

installPlayerFling({State = State, Players = Players, Player = player, RunService = RunService,
    Workspace = workspace, Connect = connect, RoleFor = roleFor, IsAlive = alive,ResolveRole=State.GameContext.ResolveRole,
    GetMapBounds=function(position)
        local box=State.GameContext.MapAt(position)
        return box and {Frame=box.Frame,Size=box.Size,Name=box.Object.Name} or nil
    end,
    IsEliminated = function(p)
        local data = dataFor(p)
        return data and (data.Dead == true or data.Killed == true) or false
    end,
    StopWeaponActions = function()
        for _, record in pairs(State.WeaponHandlers) do
            record.ThrowToken += 1
            record.Charging, record.StabbingUntil = false, 0
            stopTracks(record)
        end
    end})
end


do
-- Explicit one-pass batch. Uses the existing single-player controller and return path.
local installFlingQueue=function(C)
    local State,player=C.State,C.Player
    local clock=C.Clock or os.clock
    local queue={Active=false,Status="Off",Index=0,Total=0,Attempts=0,Skipped=0}
    State.FlingQueue=queue
    local targets,character,current,ownedRequest,nextAt,startedAt,watchReturn
    local limit=C.PerTargetSeconds or 6
    local function owned()
        return current and State.Fling.Active and State.Fling.Target==current.Id
            and State.Fling.Requests==ownedRequest
    end
    local function stopOwned()
        if owned() then State.StopFling("All-player attempt ended; returning") end
    end
    function State.StopFlingAll(message)
        queue.Active=false
        local ok,why=pcall(stopOwned)
        targets,character,current=nil,nil,nil
        queue.TargetId=nil
        queue.Status=ok and (message or "Fling all stopped") or "Fling all cleanup failed: "..tostring(why)
        return ok,queue.Status
    end
    local function eligible(p,expected)
        if p==player or State.IsPlayerExcluded and State.IsPlayerExcluded(p) then return false end
        local present=false
        for _,other in ipairs(C.Players:GetPlayers()) do if other==p then present=true; break end end
        local char=present and p.Character
        local hum=char and char:FindFirstChildOfClass("Humanoid")
        return char and (not expected or char==expected) and hum and hum.Health>0
    end
    local function modeBlocked()
        return State.Invis and (State.Invis.Active or State.Invis.Busy)
            or State.ExperimentalInvis and (State.ExperimentalInvis.Active or State.ExperimentalInvis.Busy)
    end
    function State.FlingAll()
        if queue.Active then return true,queue.Status end
        if not State.Running then return false,"Script is unloaded" end
        if modeBlocked() then return false,"Restore your character before Fling all" end
        local hum=player.Character and player.Character:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health<=0 then return false,"Wait for your living character" end
        local list={}
        for _,p in ipairs(C.Players:GetPlayers()) do
            if eligible(p) then table.insert(list,{Player=p,Id=p.UserId,Character=p.Character,Name=p.Name}) end
        end
        table.sort(list,function(a,b) return a.Id<b.Id end)
        if #list==0 then return false,"No eligible players; protected players are skipped" end
        local ok,why=pcall(function()
            if State.StopAutoAttack then State.StopAutoAttack("Stopped for Fling all") end
            if State.StopKillAura then
                local accepted,message=State.StopKillAura("Stopped for Fling all")
                if accepted==false then error(message or "Aura cleanup failed") end
            end
            watchReturn=State.Fling.Active
            if State.Fling.Active then State.StopFling("Returning before Fling all") end
        end)
        if not ok then return false,"Cannot start Fling all: "..tostring(why) end
        targets,character,current=list,player.Character,nil
        queue.Active,queue.Index,queue.Total,queue.Attempts,queue.Skipped=true,0,#list,0,0
        queue.TargetId=nil
        nextAt=clock()+.35
        queue.Status="Fling all ready: "..#list.." eligible players"
        return true,queue.Status
    end
    local elapsed=0
    C.Connect(C.RunService.Heartbeat,function(dt)
        if not queue.Active then return end
        elapsed+=dt; if elapsed<.1 then return end; elapsed=0
        local ok,why=pcall(function()
            local hum=player.Character and player.Character:FindFirstChildOfClass("Humanoid")
            if not State.Running or player.Character~=character or not hum or hum.Health<=0 then
                State.StopFlingAll("Fling all stopped: your character changed"); return
            end
            if modeBlocked() then State.StopFlingAll("Fling all stopped: character mode changed"); return end
            if (watchReturn or queue.Attempts>0) and State.Fling.ReturnStatus and State.Fling.ReturnStatus:find("Return failed:",1,true) then
                State.StopFlingAll("Fling all stopped: "..State.Fling.ReturnStatus); return
            end
            local now=clock()
            if current then
                if State.Fling.Requests~=ownedRequest or State.Fling.Active and State.Fling.Target~=current.Id then
                    -- A newer manual request owns the controller now.
                    current=nil; State.StopFlingAll("Fling all stopped: manual action took over"); return
                end
                if owned() and eligible(current.Player,current.Character) and now-startedAt<limit then return end
                stopOwned(); current=nil; queue.TargetId=nil; nextAt=now+.35
                queue.Status="Returning before next player ("..queue.Index.."/"..queue.Total..")"
                return
            end
            if now<nextAt then return end
            if State.Fling.Active then State.StopFlingAll("Fling all stopped: another fling is active"); return end
            while queue.Index<#targets do
                queue.Index+=1
                local target=targets[queue.Index]
                if eligible(target.Player,target.Character) then
                    local previousReturn=State.Fling.ReturnStatus
                    local accepted,message=State.FlingPlayer(target.Id)
                    if State.Fling.ReturnStatus~=previousReturn then watchReturn=true end
                    if accepted and State.Fling.Active and State.Fling.Target==target.Id then
                        current,ownedRequest,startedAt=target,State.Fling.Requests,now
                        queue.Attempts+=1; queue.TargetId=target.Id
                        queue.Status=("Attempt %d/%d: @%s"):format(queue.Index,queue.Total,target.Name)
                    else
                        queue.Skipped+=1; nextAt=now+.35
                        queue.Status="Skipped @"..target.Name..": "..tostring(message or "controller unavailable")
                    end
                    return
                end
                queue.Skipped+=1
            end
            local message=("Fling all finished: %d attempts, %d skipped; launches unconfirmed"):format(queue.Attempts,queue.Skipped)
            State.StopFlingAll(message)
        end)
        if not ok then State.StopFlingAll("Fling all stopped: "..tostring(why)) end
    end)
    C.Connect(player.CharacterRemoving,function() State.StopFlingAll("Respawning; Fling all stopped") end)
    return queue
end

installFlingQueue({State=State,Player=player,Players=Players,RunService=RunService,Connect=connect})
end


do
-- Explicit teleport and selected-target weapon automation. No server-kill claims.
local installPlayerActions = function(C)
    local State, player, Players = C.State, C.Player, C.Players
    local actions = {Enabled = false, SelectedId = nil, TargetId = nil, Status = "Auto attack off", Checks = 0}
    State.PlayerActions = actions
    local function status(text) actions.Status = text; return text end
    local function find(id)
        for _, p in ipairs(Players:GetPlayers()) do if p.UserId == tonumber(id) then return p end end
    end
    local function parts(p)
        local char = p and p.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local root = char and char:FindFirstChild("HumanoidRootPart")
        if not char or not hum or hum.Health <= 0 or not root then return nil end
        return char, hum, root
    end
    function State.StopAutoAttack(message)
        actions.Enabled, actions.TargetId, actions.Character = false, nil, nil
        if C.CancelAttack then C.CancelAttack() end
        status(message or "Auto attack off")
    end
    function State.SetSelectedPlayer(id)
        id = tonumber(id)
        if id ~= actions.SelectedId and actions.Enabled then State.StopAutoAttack("Selection changed; enable auto attack for the new player") end
        actions.SelectedId = id
    end
    function State.SetAutoAttack(enabled, id)
        if not enabled then State.StopAutoAttack(); return true, actions.Status end
        if not State.Running then return false, status("Script is unloaded") end
        local target = find(id)
        if not target or target == player then return false, status("Select another player first") end
        if State.IsPlayerExcluded and State.IsPlayerExcluded(target) then return false, status("Target is excluded from attacks") end
        local char = parts(player)
        if not char then return false, status("Wait for your character to be alive") end
        local targetChar = parts(target)
        if not targetChar or (C.IsEliminated and C.IsEliminated(target)) then return false, status("Target is not alive or loaded") end
        if State.StopFlingAll then State.StopFlingAll("Auto attack on") end
        if State.StopKillAura then State.StopKillAura("Stopped for selected-player auto attack") end
        if C.CancelAttack then C.CancelAttack() end
        actions.Enabled, actions.TargetId, actions.SelectedId, actions.Character = true, target.UserId, target.UserId, char
        actions.TargetCharacter = targetChar
        actions.WasPaused = false
        return true, status("Auto attack enabled; close the menu to play")
    end
    local function landing(char, hum, root, targetChar, targetRoot)
        if C.FindLanding then return C.FindLanding(char, hum, root, targetChar, targetRoot) end
        local excluded = {}
        for _, p in ipairs(Players:GetPlayers()) do if p.Character then table.insert(excluded, p.Character) end end
        local ray = RaycastParams.new()
        ray.FilterType, ray.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, excluded
        ray.RespectCanCollide, ray.IgnoreWater = true, true
        local overlap = OverlapParams.new()
        overlap.FilterType, overlap.FilterDescendantsInstances = Enum.RaycastFilterType.Exclude, excluded
        overlap.RespectCanCollide, overlap.MaxParts = true, 30
        local offsets = {Vector3.new(0,0,4),Vector3.new(4,0,0),Vector3.new(-4,0,0),Vector3.new(0,0,-4),Vector3.new(4,0,4),Vector3.new(-4,0,4)}
        for _, offset in ipairs(offsets) do
            local position = targetRoot.CFrame:PointToWorldSpace(offset)
            local ground = C.Workspace:Raycast(position + Vector3.new(0,6,0), Vector3.new(0,-24,0), ray)
            if ground and ground.Normal.Y > 0.6 and ground.Position.Y > C.Workspace.FallenPartsDestroyHeight + 30 then
                local height = hum.HipHeight + root.Size.Y / 2 + 0.15
                if hum.RigType == Enum.HumanoidRigType.R6 then
                    local leg = char:FindFirstChild("Left Leg")
                    height += leg and leg.Size.Y or 2
                end
                local point = ground.Position + Vector3.new(0,height,0)
                local clear = true
                for _, part in ipairs(C.Workspace:GetPartBoundsInBox(CFrame.new(point),Vector3.new(2.7,4.5,2.7),overlap)) do
                    if part.CanCollide then clear=false; break end
                end
                if clear then return CFrame.new(point) end
            end
        end
    end
    function State.TeleportToPlayer(id)
        local target = find(id)
        if not State.Running then return false, status("Script is unloaded") end
        if not target or target == player then return false, status("Select another player first") end
        local targetChar, _, targetRoot = parts(target)
        if not targetChar then return false, status("Target character is not alive or loaded") end
        if State.StopFlingAll then State.StopFlingAll("Stopped for player teleport") end
        if State.Fling and State.Fling.Active then State.StopFling("Fling stopped for teleport") end
        if State.CancelFlingReturn then State.CancelFlingReturn() end
        if C.CancelAttack then C.CancelAttack() end
        if State.Invis and (State.Invis.Active or State.Invis.Busy) then return false, status("Turn invisibility off before teleporting") end
        if State.ExitUndergroundForAttack and not State.ExitUndergroundForAttack() then return false, status("Restore your character before teleporting") end
        local char, hum, root = parts(player)
        if State.ReleaseFly then State.ReleaseFly() end -- fly holds PlatformStand; release it before the free-to-move check
        if not char or root.Anchored or hum.Sit or hum.PlatformStand then return false, status("Your character must be alive and free to move") end
        local destination = landing(char,hum,root,targetChar,targetRoot)
        if not destination then return false, status("No clear landing space beside this player") end
        local ok, message = pcall(function()
            root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
            char:PivotTo(destination * root.CFrame:ToObjectSpace(char:GetPivot()))
        end)
        if not ok then return false, status("Teleport failed: " .. tostring(message)) end
        return true, status("Teleported near @" .. target.Name .. "; server may correct the position")
    end
    local elapsed = 0
    C.Connect(C.RunService.Heartbeat, function(dt)
        if not actions.Enabled then return end
        elapsed += dt
        if elapsed < 0.2 then return end
        elapsed = 0
        local ok, message = pcall(function()
            if not State.Running then State.StopAutoAttack("Unloaded"); return end
            local char = parts(player)
            if char ~= actions.Character then State.StopAutoAttack("Your character changed; auto attack stopped"); return end
            local target = find(actions.TargetId)
            if not target then State.StopAutoAttack("Target left the server"); return end
            if State.IsPlayerExcluded and State.IsPlayerExcluded(target) then State.StopAutoAttack("Target excluded; auto attack stopped"); return end
            if target.Character ~= actions.TargetCharacter then State.StopAutoAttack("Target character changed; auto attack stopped"); return end
            local targetHum = target.Character and target.Character:FindFirstChildOfClass("Humanoid")
            if (targetHum and targetHum.Health <= 0) or (C.IsEliminated and C.IsEliminated(target)) then
                State.StopAutoAttack("Target eliminated; auto attack stopped"); return
            end
            local invisible=State.Invis and (State.Invis.Active or State.Invis.Busy)
            local blocked = invisible or (State.Fling and State.Fling.Active) or C.InputBlocked()
            if blocked then
                if not actions.WasPaused and C.CancelAttack then C.CancelAttack() end
                actions.WasPaused = true
                status(invisible and "Auto attack paused during invisibility" or (State.Fling and State.Fling.Active and "Auto attack paused during fling" or "Auto attack paused: close menu / finish typing"))
                return
            end
            actions.WasPaused = false
            if not parts(target) then status("Waiting for selected target to load"); return end
            actions.Checks += 1
            local _, text = C.PerformAttack(target)
            if text then status(text) end
        end)
        if not ok then State.StopAutoAttack("Auto attack error: " .. tostring(message)) end
    end)
    C.Connect(player.CharacterRemoving, function() State.StopAutoAttack("Respawning; auto attack stopped") end)
    C.Connect(Players.PlayerRemoving, function(p)
        if p.UserId == actions.TargetId then State.StopAutoAttack("Target left the server") end
    end)
    return actions
end

local function cancelAutoWeapon()
    for _, record in pairs(State.WeaponHandlers) do
        if record.AutoSelectedThrow then
            record.ThrowToken += 1
            record.Charging, record.AutoSelectedThrow = false, nil
            record.LastThrow = -math.huge
            stopTracks(record)
        end
        if record.StabTarget then record.StabbingUntil, record.StabTarget = 0, nil end
    end
end
installPlayerActions({State = State, Players = Players, Player = player, RunService = RunService,
    Workspace = workspace, Connect = connect, CancelAttack = cancelAutoWeapon,
    IsEliminated = function(p)
        local data = dataFor(p)
        return data and (data.Dead == true or data.Killed == true) or false
    end,
    InputBlocked = function() return mobileBlocked() or GuiService.MenuIsOpen or UIS:GetFocusedTextBox() ~= nil end,
    PerformAttack = function(target)
        if not State.Config.Aim then return false, "Enable Aim assist to use auto attack" end
        if not alive(target) then return false, "Waiting for selected target in an active round" end
        local item = toolFor(player, "Knife") or toolFor(player, "Gun")
        if not item then return false, "Waiting for a gun or knife you own" end
        if not State.IsCombatTarget(item.Name,target) then
            return false, "Selected player is not an eligible opponent for this weapon / mode"
        end
        if item.Name == "Gun" and not State.Config.MagicBullet then return false, "Enable Magic Bullet / gun aim" end
        local char = player.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return false, "Waiting for your character" end
        if item.Parent ~= char then hum:EquipTool(item); return false, "Equipping " .. item.Name end
        local record = State.WeaponHandlers[item]
        if not record then syncWeapons(); return false, "Preparing native weapon handler" end
        if record.AutoSelectedThrow and not record.Charging then record.AutoSelectedThrow = nil end
        if record.Kind == "Gun" then
            if not item.Enabled then return false, "Gun is reloading" end
            local before = State.Stats.GunRequests
            sendGun(record, target, true)
            return State.Stats.GunRequests > before, State.LastGunFeedback and State.LastGunFeedback.Message or "Waiting for a clear gun shot"
        end
        local ownRoot, targetRoot = char:FindFirstChild("HumanoidRootPart"), target.Character:FindFirstChild("HumanoidRootPart")
        if not ownRoot or not targetRoot then return false, "Waiting for character roots" end
        if record.Charging then return true, "Knife throw charging at selected player" end
        if (targetRoot.Position - ownRoot.Position).Magnitude <= 6.5 and clearPath(ownRoot.Position,targetRoot.Position,target.Character) then
            local before = State.Stats.StabRequests
            stabKnife(record,target)
            return State.Stats.StabRequests > before, "Stab selected player / respecting cooldown"
        end
        if not State.Config.KnifeAim then return false, "Enable knife throw prediction for ranged auto attack" end
        startThrow(record,target,true)
        record.AutoSelectedThrow = record.Charging and true or nil
        return record.Charging, State.KnifeFeedback and State.KnifeFeedback.Message or "Waiting for a clear knife throw"
    end})
end


do
-- Murderer-only nearby stab automation; requests are not confirmed kills.
local installKillAura=function(C)
    local State,player=C.State,C.Player
    local clock=C.Clock or os.clock
    local function knifeUser()
        if C.CanUseWeapon then return C.CanUseWeapon("Knife") end
        return C.RoleFor(player)=="Murderer"
    end
    local function eligible(target)
        if C.IsTarget then return C.IsTarget("Knife",target) end
        return C.RoleFor(target)~="Murderer"
    end
    local focused=true
    local aura={Enabled=false,Status="Off",Attempts=0,Contacts=0,TargetId=nil,LastAttempt=-math.huge}
    State.KillAura=aura
    local batch={Active=false,Status="Kill all off",Attempts=0,Contacts=0,Bursts=0,Throws=0,Observed=0,Skipped=0,Index=1,Targets={}}
    State.KillAll=batch
    batch.History,batch.Reasons,batch.RetryTargets={},{},{}
    State.Config.KillAura=false
    if State.Config.AuraEquipKnife==nil then State.Config.AuraEquipKnife=true end
    local function range(value)
        local n=tonumber(value)
        return n and n==n and n>=1 and n<=1000 and n or nil
    end
    State.Config.KillAuraRange=range(State.Config.KillAuraRange) or 1000
    local function reach(value)
        local n=tonumber(value)
        return n and n==n and n>=1 and n<=1000 and n or nil
    end
    State.Config.AuraExtendedReach=State.Config.AuraExtendedReach~=false
    State.Config.AuraReachRange=reach(State.Config.AuraReachRange) or 1000
    function State.GetKillAuraRange()
        return State.Config.AuraExtendedReach and (reach(State.Config.AuraReachRange) or 1000)
            or (range(State.Config.KillAuraRange) or 1000)
    end
    function State.GetAuraContactPart(target,origin,forKillAll)
        local char=target and target.Character
        if not char then return nil end
        for _,name in ipairs(C.BodyPartNames or {"UpperTorso","Torso","LowerTorso","Head"}) do
            local part=char:FindFirstChild(name)
            if part and part:IsA("BasePart") and (forKillAll and batch.Active or C.ClearPath(origin,part.Position,char)) then return part end
        end
    end
    local function refresh()
        if State.MobileUI and State.MobileUI.Refresh then pcall(State.MobileUI.Refresh) end
    end
    if State.Config.KillAllMode~="Aimed throws" then State.Config.KillAllMode="Burst" end
    if State.Config.TargetPriority~="Sheriff first" and State.Config.TargetPriority~="Selected player" then State.Config.TargetPriority="Nearest" end
    function State.SetKillAllMode(value)
        if value~="Burst" and value~="Aimed throws" then return false,"Unknown Kill all mode" end
        if value~=State.Config.KillAllMode and batch.Active then State.StopKillAll("Kill all stopped: mode changed") end
        State.Config.KillAllMode=value
        refresh(); return true,value
    end
    function State.SetTargetPriority(value)
        if value~="Nearest" and value~="Sheriff first" and value~="Selected player" then return false,"Unknown target priority" end
        State.Config.TargetPriority=value
        aura.NextScanAt=nil
        refresh(); return true,value
    end
    local function priority(target)
        if State.Config.TargetPriority=="Sheriff first" then
            local role=C.RoleFor(target)
            return (role=="Sheriff" or role=="Hero") and 0 or 1
        elseif State.Config.TargetPriority=="Selected player" then
            return State.PlayerActions and State.PlayerActions.SelectedId==target.UserId and 0 or 1
        end
        return 0
    end
    local function better(target,distance,other,otherDistance)
        if not other then return true end
        local rank,otherRank=priority(target),priority(other)
        return rank<otherRank or rank==otherRank and (distance<otherDistance
            or distance==otherDistance and target.UserId<other.UserId)
    end
    local function reasons(entries)
        local counts={}
        for _,entry in ipairs(entries) do
            if not entry.Done then
                local reason=entry.Reason or "Waiting for first attempt"
                counts[reason]=(counts[reason] or 0)+1
            end
        end
        return counts
    end
    function State.GetRecentCombatRuns()
        local copies,lines={},{}
        for index,run in ipairs(batch.History) do
            local copy={}
            for key,value in pairs(run) do copy[key]=value end
            copies[index]=copy
            lines[index]=("%d. %s · %.1fs · %d contacts · %d observed · %d unresolved")
                :format(index,copy.Mode,copy.Elapsed,copy.Contacts,copy.Observed,copy.Unresolved)
        end
        return copies,#lines>0 and table.concat(lines,"\n") or "No completed Kill all runs."
    end
    function State.GetCombatResults()
        local stats=State.Stats or {}
        local result={Active=batch.Active,Mode=batch.Mode or State.Config.KillAllMode,Priority=State.Config.TargetPriority,
            Attempts=batch.Attempts,Contacts=batch.Contacts,Bursts=batch.Bursts,Throws=batch.Throws,Observed=batch.Observed,Skipped=batch.Skipped,
            Unresolved=math.max(0,(batch.Total or 0)-batch.Observed-batch.Skipped),Elapsed=batch.Elapsed or 0,
            GunRequests=stats.GunRequests or 0,GunReplies=stats.GunReplies or 0,GunRayHits=stats.GunTargetHits or 0,
            GunUnconfirmed=stats.GunUnconfirmed or 0,Stabs=stats.StabRequests or 0,KnifeThrows=stats.KnifeRequests or 0,
            KnifeContacts=stats.StabContactReports or 0,Reason=batch.Status,Reasons={}}
        for reason,count in pairs(batch.Active and reasons(batch.Targets) or batch.Reasons) do result.Reasons[reason]=count end
        local explanations={}
        for reason,count in pairs(result.Reasons) do explanations[#explanations+1]=reason..": "..count end
        table.sort(explanations)
        result.Text=("Gun: %d requests · %d matched replies · %d ray hits · %d unanswered\nKnife: %d swings · %d throws · %d contacts\nKill all (%s): %d contact reports · %d bursts · %d throws started\nObserved eliminations: %d · Unresolved: %d · Skipped: %d\n%s\nObserved eliminations are not attributed kills. Requests do not prove damage.")
            :format(result.GunRequests,result.GunReplies,result.GunRayHits,result.GunUnconfirmed,result.Stabs,result.KnifeThrows,
                result.KnifeContacts,result.Mode,result.Contacts,result.Bursts,result.Throws,result.Observed,result.Unresolved,result.Skipped,result.Reason)
        if #explanations>0 then result.Text..="\nUnresolved reasons · "..table.concat(explanations," · ") end
        return result
    end
    local function cancel()
        if C.CancelStab then
            local ok,result,message=pcall(C.CancelStab)
            if not ok then return false,tostring(result) end
            if result==false then return false,tostring(message or "Blade touch cleanup incomplete") end
        end
        return true
    end
    function State.CancelKillAuraContacts(message)
        aura.TargetId=nil
        aura.NextScanAt=nil
        local ok,why=cancel()
        if message and aura.Enabled then aura.Status=message end
        return ok,why
    end
    function State.SetAuraExtendedReach(enabled)
        State.Config.AuraExtendedReach=enabled==true
        local ok,message=State.CancelKillAuraContacts("Reach updated")
        refresh(); return ok,message
    end
    function State.SetAuraReachRange(value)
        local n=reach(value)
        if not n then return false,"Extended reach must be between 1 and 1000 studs" end
        State.Config.AuraReachRange=n
        local ok,message=State.CancelKillAuraContacts("Range updated")
        return ok,ok and n or message
    end
    function State.CanAuraContact()
        local char=player.Character
        local hum=char and char:FindFirstChildOfClass("Humanoid")
        return aura.Enabled and State.Running and State.Config.Aim and focused and char==aura.Character
            and hum and hum.Health>0 and C.IsAlive(player) and knifeUser()
            and not (State.Invis and (State.Invis.Busy or State.Invis.Active and not State.Config.InvisibleKnife))
            and not (State.Fling and State.Fling.Active) and not C.InputBlocked()
    end
    function State.StopKillAura(message)
        if batch.Active then State.StopKillAll(message or "Kill all stopped") end
        aura.Enabled,State.Config.KillAura=false,false
        aura.TargetId=nil
        local ok,why=cancel()
        aura.Status=ok and (message or "Off") or "Stopped  ·  cleanup error: "..why
        refresh(); return ok,aura.Status
    end
    function State.SetKillAura(enabled)
        if not enabled then return State.StopKillAura() end
        if not State.Running then State.StopKillAura("Script is unloaded"); return false,aura.Status end
        if aura.Enabled then State.Config.KillAura=true; return true,aura.Status end
        local ok,message=pcall(function()
            if State.StopAutoAttack then State.StopAutoAttack("Stopped for kill aura") end
            State.Config.Aim=true
            if C.Prepare then C.Prepare() end
        end)
        if not ok then State.StopKillAura("Unavailable: "..tostring(message)); return false,aura.Status end
        aura.Enabled,State.Config.KillAura=true,true
        aura.NextScanAt=nil
        aura.Character=player.Character
        aura.Status="On  ·  waiting for an eligible knife role"
        refresh(); return true,aura.Status
    end
    function State.StopKillAll(message)
        if not batch.Active then return true,batch.Status end
        batch.Reasons=reasons(batch.Targets)
        batch.RetryTargets={}
        for _,entry in ipairs(batch.Targets) do
            if not entry.Done then table.insert(batch.RetryTargets,{Player=entry.Player,Character=entry.Character}) end
        end
        batch.RetryCharacter=batch.Character
        table.insert(batch.History,1,{Mode=batch.Mode,Elapsed=batch.Elapsed,Contacts=batch.Contacts,Throws=batch.Throws,
            Observed=batch.Observed,Unresolved=math.max(0,batch.Total-batch.Observed-batch.Skipped),Skipped=batch.Skipped})
        if #batch.History>5 then table.remove(batch.History) end
        batch.Active=false
        batch.Targets,batch.Character={},nil
        aura.TargetId=nil
        if not batch.RestoreAura then aura.Enabled,State.Config.KillAura=false,false end
        batch.RestoreAura=nil
        local ok,why=cancel()
        batch.Status=ok and (message or "Kill all stopped") or "Kill all cleanup failed: "..tostring(why)
        aura.Status=batch.Status
        refresh()
        return ok,batch.Status
    end
    local function startKillAll(retryOnly)
        if batch.Active then return false,"Kill all is already running" end
        if not State.Running or not C.IsAlive(player) or not knifeUser() then
            return false,"Kill all requires a living knife role"
        end
        local allowed={}
        if retryOnly then
            if batch.RetryCharacter~=player.Character then return false,"No unresolved players from this character / round" end
            for _,entry in ipairs(batch.RetryTargets) do
                if entry.Player.Character==entry.Character then allowed[entry.Player]=true end
            end
        end
        local targets={}
        for _,p in ipairs(C.Players:GetPlayers()) do
            if p~=player and (not retryOnly or allowed[p]) and not State.IsPlayerExcluded(p) and C.IsAlive(p)
                and not (C.IsEliminated and C.IsEliminated(p)) and eligible(p) then
                table.insert(targets,{Player=p,Character=p.Character,Attempts=0,NextAttempt=-math.huge})
            end
        end
        if #targets==0 then return false,retryOnly and "No eligible unresolved players to retry" or "No eligible players for Kill all" end
        table.sort(targets,function(a,b) return a.Player.UserId<b.Player.UserId end)
        local restore=aura.Enabled
        local ok,message=State.SetKillAura(true)
        if not ok then return false,message end
        batch.Active,batch.RestoreAura,batch.Character=true,restore,player.Character
        batch.Targets,batch.Index,batch.Total,batch.Remaining=targets,1,#targets,#targets
        batch.Attempts,batch.Contacts,batch.Skipped,batch.Bursts,batch.Throws,batch.Observed,batch.Elapsed=0,0,0,0,0,0,0
        batch.Mode=State.Config.KillAllMode
        batch.FeedbackUntil=-math.huge
        batch.NextBurstAt=-math.huge
        batch.Status="Kill all started ("..batch.Mode..")."
        return true,batch.Status
    end
    function State.StartKillAll() return startKillAll(false) end
    function State.RetryKillAll() return startKillAll(true) end
    function State.ClearKillAllRetry()
        batch.RetryTargets,batch.RetryCharacter={},nil
    end
    function State.SetKillAuraRange(value)
        local n=reach(value)
        if not n then return false,"Aura range must be between 1 and 1000 studs" end
        -- The main slider always controls the active range, including extended mode.
        State.Config.KillAuraRange=n
        State.Config.AuraReachRange=n
        State.Config.AuraExtendedReach=true
        local ok,message=State.CancelKillAuraContacts("Range updated")
        return ok,ok and n or message
    end
    local function pause(message)
        aura.TargetId=nil
        local ok,why=cancel()
        if not ok then State.StopKillAura("Cleanup failed: "..why); return end
        aura.Status=message
        if batch.Active then batch.Status=message end
    end
    C.Connect(C.RunService.Heartbeat,function(dt)
        if not aura.Enabled then return end
        local ok,message=pcall(function()
            if not State.Running then State.StopKillAura("Unloaded"); return end
            local char=player.Character
            if char~=aura.Character then
                if batch.Active then
                    State.StopKillAll("Kill all cancelled: character changed")
                    if not aura.Enabled then return end
                end
                pause("Waiting for your new character")
                aura.Character=char
                aura.LastEquip=nil
                return
            end
            local hum=char and char:FindFirstChildOfClass("Humanoid")
            local root=char and char:FindFirstChild("HumanoidRootPart")
            if not hum or hum.Health<=0 then
                if batch.Active then
                    State.StopKillAll("Kill all cancelled: your character is unavailable")
                    if not aura.Enabled then return end
                end
                pause("Waiting for respawn"); return
            end
            if not knifeUser() or not C.IsAlive(player) then
                if batch.Active then
                    State.StopKillAll("Kill all cancelled: knife role ended")
                    State.ClearKillAllRetry()
                    if not aura.Enabled then return end
                end
                pause("Waiting for an eligible knife role"); return
            end
            if not root then pause("Waiting for your character"); return end
            if not State.Config.Aim then pause("Paused  ·  turn on Aim assist"); return end
            if State.Invis and (State.Invis.Busy or State.Invis.Active and not State.Config.InvisibleKnife) then pause("Paused while invisible"); return end
            if State.Fling and State.Fling.Active then pause("Paused while flinging"); return end
            if not focused or C.InputBlocked() then pause("Paused  ·  close the menu or finish typing"); return end
            if batch.Active then
                batch.Elapsed+=math.max(dt,0)
                if batch.Elapsed>=30 then
                    State.StopKillAll(("Kill all finished: %d eliminations observed, %d unresolved, %d skipped; %d attacks started")
                        :format(batch.Observed,batch.Remaining or batch.Total,batch.Skipped,batch.Attempts))
                    return
                end
            end
            local item=C.EquippedWeapon()
            if (not item or item.Name~="Knife" or item.Parent~=char) and State.Config.AuraEquipKnife and C.EquipKnife
                and (not aura.LastEquip or clock()-aura.LastEquip>.5) then
                aura.LastEquip=clock(); C.EquipKnife(); item=C.EquippedWeapon()
            end
            if not item or item.Name~="Knife" or item.Parent~=char or item.Enabled==false then
                if batch.Active then
                    for _,entry in ipairs(batch.Targets) do
                        if not entry.Done and entry.Attempts<3 then entry.Reason="Knife unavailable" end
                    end
                end
                pause("Waiting for your knife"); return
            end
            local attackReady,readinessReason=C.CanStab(item)
            local canAttack=attackReady and clock()-aura.LastAttempt>=.85
            if not batch.Active and not canAttack then aura.Status=readinessReason or "Knife cooling down"; return end
            local best,bestChar,bestPart,bestDistance
            local radius=State.GetKillAuraRange()
            if batch.Active then
                local present={}
                for _,p in ipairs(C.Players:GetPlayers()) do present[p]=true end
                local remaining=0
                local hasBudget=false
                local candidates={}
                -- Scan the whole queue so unavailable players cannot stall ready targets.
                for offset=0,#batch.Targets-1 do
                    local index=(batch.Index+offset-1)%#batch.Targets+1
                    local entry=batch.Targets[index]
                    local p=entry.Player
                    local targetChar=p.Character
                    if not entry.Done then
                        local hum=targetChar and targetChar:FindFirstChildOfClass("Humanoid")
                        if present[p] and targetChar==entry.Character and ((C.IsEliminated and C.IsEliminated(p)) or hum and hum.Health<=0) then
                            entry.Done=true; batch.Observed+=1
                        elseif not present[p] or targetChar~=entry.Character or State.IsPlayerExcluded(p) or not eligible(p) then
                            entry.Done=true; batch.Skipped+=1
                        end
                    end
                    if not entry.Done then
                        remaining+=1
                        local targetRoot=targetChar and targetChar:FindFirstChild("HumanoidRootPart")
                        if entry.Attempts>=3 then entry.Reason="Retry budget used"
                        else
                            hasBudget=true
                            if not targetRoot or not C.IsAlive(p) then entry.Reason="Character loading"
                            elseif (targetRoot.Position-root.Position).Magnitude>radius then entry.Reason="Out of range"
                            elseif batch.Mode=="Aimed throws" and (targetRoot.Position-root.Position).Magnitude>6.5
                                and State.Config.KnifeAim==false then entry.Reason="Knife prediction disabled"
                            elseif not canAttack then entry.Reason="Weapon cooling down"
                            else entry.Reason="Waiting for next attempt" end
                        end
                        if canAttack and clock()>=batch.NextBurstAt and entry.Attempts<3 and clock()>=entry.NextAttempt and targetRoot and C.IsAlive(p) then
                            local distance=(targetRoot.Position-root.Position).Magnitude
                            if distance<=radius then
                                local part=State.GetAuraContactPart(p,root.Position,batch.Mode=="Burst")
                                if part then table.insert(candidates,{Entry=entry,Player=p,Character=targetChar,Part=part,Distance=distance})
                                else entry.Reason="Clear path blocked" end
                            end
                        end
                    end
                end
                batch.Remaining=remaining
                if remaining==0 or not hasBudget and clock()>=batch.FeedbackUntil then
                    State.StopKillAll(("Kill all finished: %d eliminations observed, %d unresolved, %d skipped; %d attacks started")
                        :format(batch.Observed,remaining,batch.Skipped,batch.Attempts))
                    return
                end
                if #candidates==0 then
                    batch.Status=not canAttack and (readinessReason or "Knife cooling down")
                        or ("Kill all: %d remaining; waiting for range, loading, clear path or feedback (%.0fs left)"):format(remaining,30-batch.Elapsed)
                    aura.Status=batch.Status
                    return
                end
                table.sort(candidates,function(a,b) return better(a.Player,a.Distance,b.Player,b.Distance) end)
                local generation=batch.Targets
                local accepted,why,results
                local feedbackDelay=1.25
                if batch.Mode=="Aimed throws" then
                    local candidate=candidates[1]
                    local contact
                    if candidate.Distance<=6.5 then accepted,why,contact=C.Stab(item,candidate.Player,candidate.Part)
                    else
                        accepted,why=C.Throw(item,candidate.Player)
                        local speed=tonumber(State.ObservedKnifeSpeed or State.Config.KnifeSpeed)
                        speed=speed and speed==speed and speed>0 and speed<math.huge and speed or 96
                        local charge=item:GetAttribute("ThrowSpeed")
                        charge=type(charge)=="number" and charge==charge and charge>0 and charge<math.huge and charge or 1
                        feedbackDelay=math.min(15,math.max(1.25,charge+candidate.Distance/speed+.5))
                    end
                    if accepted then
                        results={{Entry=candidate.Entry,Contact=contact==true}}
                        if candidate.Distance>6.5 then batch.Throws+=1 end
                    else
                        candidate.Entry.Reason=State.Config.KnifeAim==false and candidate.Distance>6.5
                            and "Knife prediction disabled" or "Local attack unavailable"
                    end
                else accepted,why,results=C.Burst(item,candidates) end
                if not batch.Active or batch.Targets~=generation then return end
                batch.NextBurstAt=clock()+(accepted and .85 or .15)
                if accepted then
                    batch.FeedbackUntil=math.max(batch.FeedbackUntil,clock()+feedbackDelay)
                    aura.Attempts+=1; aura.LastAttempt=clock(); aura.TargetId=nil
                    if batch.Mode=="Burst" then batch.Bursts+=1 end
                    for _,result in ipairs(results or {}) do
                        result.Entry.Attempts+=1
                        result.Entry.NextAttempt=clock()+.85
                        result.Entry.Reason=result.Contact and "Waiting for server outcome"
                            or batch.Mode=="Aimed throws" and "Throw charging / outcome pending" or "Contact report unavailable"
                        batch.Attempts+=1
                        if result.Contact then batch.Contacts+=1; aura.Contacts+=1 end
                    end
                end
                aura.Status=why or "Waiting for a ready knife"
                batch.Status=("Kill all (%s): %d contacts, %d throws started, %d observed eliminated · %s")
                    :format(batch.Mode,batch.Contacts,batch.Throws,batch.Observed,aura.Status)
                return
            else
            if clock()<(aura.NextScanAt or 0) then return end
            for _,p in ipairs(C.Players:GetPlayers()) do
                if p~=player and not State.IsPlayerExcluded(p) and C.IsAlive(p) and eligible(p) then
                    local targetChar=p.Character
                    local targetHum=targetChar and targetChar:FindFirstChildOfClass("Humanoid")
                    local targetRoot=targetChar and targetChar:FindFirstChild("HumanoidRootPart")
                    if targetHum and targetHum.Health>0 and targetRoot then
                        local distance=(targetRoot.Position-root.Position).Magnitude
                        if distance==distance and distance<=radius and better(p,distance,best,bestDistance) then
                            local part=State.GetAuraContactPart(p,root.Position)
                            if part then best,bestChar,bestPart,bestDistance=p,targetChar,part,distance end
                        end
                    end
                end
            end
            end
            if not best then
                aura.TargetId=nil; aura.Status="No clear target in range"
                aura.NextScanAt=clock()+(State.Config.PerformancePreset=="Low effects" and .1 or .05)
                return
            end
            aura.NextScanAt=nil
            if best.Character~=bestChar or State.IsPlayerExcluded(best) or not C.IsAlive(best) then return end
            local accepted,why,contact=C.Stab(item,best,bestPart)
            aura.TargetId=accepted and best.UserId or nil
            if accepted then
                aura.Attempts+=1; aura.LastAttempt=clock()
                if contact==true then aura.Contacts+=1 end
                aura.LastDistance=bestDistance
                aura.Status=(why or "Swing sent; damage unconfirmed")..("  ·  @%s  ·  %.1f studs"):format(best.Name,bestDistance)
            else aura.Status=why or "Waiting for a ready knife" end

        end)
        if not ok then State.StopKillAura("Stopped: "..tostring(message)) end
    end)
    C.Connect(player.CharacterRemoving,function()
        if batch.Active then State.StopKillAll("Kill all cancelled: respawning") end
        State.ClearKillAllRetry()
        if aura.Enabled then pause("Waiting for respawn"); aura.Character=nil end
    end)
    if C.RoundEnd then
        C.Connect(C.RoundEnd,function()
            if batch.Active then State.StopKillAll("Kill all stopped: round ended") end
            State.ClearKillAllRetry()
        end)
    end
    if C.UIS then
        C.Connect(C.UIS.WindowFocusReleased,function() focused=false; if aura.Enabled then pause("Paused  ·  Roblox is in the background") end end)
        C.Connect(C.UIS.WindowFocused,function() focused=true end)
    end
    return aura
end

local function auraKnifeReady(item)
    local record=State.WeaponHandlers[item]
    if not record or not ready(record) then return false,"Waiting for your knife" end
    if record.Charging then return false,"Paused for your throw" end
    local throwSpeed=item:GetAttribute("ThrowSpeed")
    throwSpeed=type(throwSpeed)=="number" and throwSpeed==throwSpeed and throwSpeed>0 and throwSpeed<math.huge and throwSpeed or 1
    if os.clock()-record.LastThrow<2*throwSpeed then return false,"Throw cooling down" end
    if os.clock()-record.LastStab<0.85 then return false,"Stab cooling down" end
    return true
end
local function auraStab(item,target,part)
    if not State.CanAuraContact() then return false,"Aura paused" end
    if not State.CanUseCombatWeapon("Knife") or not alive(player) or not alive(target) or State.IsPlayerExcluded(target) or not State.IsCombatTarget("Knife",target) then return false,"Target unavailable" end
    if not auraKnifeReady(item) then return false,"Knife cooling down" end
    local ownRoot=player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    local char=target.Character
    local targetRoot=char and char:FindFirstChild("HumanoidRootPart")
    if not ownRoot or not targetRoot or (targetRoot.Position-ownRoot.Position).Magnitude>State.GetKillAuraRange() then return false,"Target out of range" end
    part=part or State.GetAuraContactPart(target,ownRoot.Position)
    if not part or not part:IsA("BasePart") or not part:IsDescendantOf(char)
        or not clearPath(ownRoot.Position,part.Position,char) then return false,"No clear body contact" end
    local record=State.WeaponHandlers[item]
    if not stabKnife(record,target) then return false,"Knife did not start a swing" end
    record.AuraStab=true
    local before=State.Stats.StabContactReports
    -- Normal and extended aura both report the selected body part immediately;
    -- a physical overlap or a native Handle.Touched event is not required.
    reportStabContact(record,part,State.Config.AuraExtendedReach and "AuraReachAttempt" or "AuraStabAssist")
    local contact=State.Stats.StabContactReports>before
    return true,contact and "Contact sent; damage unconfirmed" or "Swing sent; contact report unavailable",contact
end
local function auraBurst(item,candidates)
    local batch=State.KillAll
    if not batch or not batch.Active or not State.CanAuraContact() or not auraKnifeReady(item) then return false,"Knife unavailable" end
    local generation=batch.Targets
    local record=State.WeaponHandlers[item]
    -- A single native swing window can report several distinct body contacts.
    -- Do not sleep or start another swing between players in this burst.
    if not stabKnife(record,nil) then return false,"Knife did not start a swing" end
    record.AuraStab=true
    local results={}
    local contacts=0
    for _,candidate in ipairs(candidates) do
        local target,part=candidate.Player,candidate.Part
        local char=target.Character
        local own=player.Character and player.Character:FindFirstChild("HumanoidRootPart")
        local root=char and char:FindFirstChild("HumanoidRootPart")
        if batch.Active and batch.Targets==generation and State.CanAuraContact() and target~=player and char==candidate.Character and alive(target)
            and State.IsCombatTarget("Knife",target) and not State.IsPlayerExcluded(target) and own and root
            and (root.Position-own.Position).Magnitude<=State.GetKillAuraRange()
            and part and part:IsA("BasePart") and part:IsDescendantOf(char) then
            record.StabTarget=target
            local before=State.Stats.StabContactReports
            reportStabContact(record,part,"KillAllBurst")
            local contact=State.Stats.StabContactReports>before
            table.insert(results,{Entry=candidate.Entry,Contact=contact})
            if contact then contacts+=1 end
        end
    end
    record.StabTarget=nil
    return true,("%d/%d contact requests sent in one swing; damage unconfirmed"):format(contacts,#candidates),results
end
local function auraThrow(item,target)
    local batch=State.KillAll
    if not batch or not batch.Active or batch.Mode~="Aimed throws" or not State.CanAuraContact() then return false,"Kill all paused" end
    if not State.Config.KnifeAim then return false,"Turn on Knife throw prediction for aimed throws" end
    local record=State.WeaponHandlers[item]
    if not record or not auraKnifeReady(item) then return false,"Knife cooling down" end
    local generation=batch.Targets
    local accepted=startThrow(record,target,true,function()
        local own=player.Character and player.Character:FindFirstChild("HumanoidRootPart")
        local root=target.Character and target.Character:FindFirstChild("HumanoidRootPart")
        return batch.Active and batch.Mode=="Aimed throws" and batch.Targets==generation and State.CanAuraContact()
            and own and root and (root.Position-own.Position).Magnitude<=State.GetKillAuraRange()
    end)
    record.KillAllThrow=accepted and record.Charging or nil
    return accepted,accepted and "Aimed throw charging; damage unconfirmed"
        or State.KnifeFeedback and State.KnifeFeedback.Message or "Waiting for a clear throw"
end
installKillAura({State=State,Player=player,Players=Players,RunService=RunService,UIS=UIS,Connect=connect,
    RoundEnd=RS.Remotes.Gameplay.RoundEndFade.OnClientEvent,
    RoleFor=roleFor,IsAlive=alive,EquippedWeapon=equippedWeapon,ClearPath=clearPath,Prepare=syncWeapons,BodyPartNames=hitPartNames.Knife,
    CanUseWeapon=State.CanUseCombatWeapon,IsTarget=State.IsCombatTarget,
    InputBlocked=function() return mobileBlocked() or GuiService.MenuIsOpen or UIS:GetFocusedTextBox()~=nil end,
    CanStab=auraKnifeReady,
    IsEliminated=function(p)
        local data=dataFor(p)
        return data and (data.Dead==true or data.Killed==true) or false
    end,
    EquipKnife=function()
        local char=player.Character
        local hum=char and char:FindFirstChildOfClass("Humanoid")
        local knife=toolFor(player,"Knife")
        if hum and knife then hum:EquipTool(knife); syncWeapons() end
    end,
    CancelStab=function()
        for _,record in pairs(State.WeaponHandlers) do
            if record.KillAllThrow then
                record.KillAllThrow=nil
                if record.Charging then
                    record.ThrowToken+=1; record.Charging=false; record.LastThrow=-math.huge
                    pcall(stopTracks,record)
                end
            end
            if record.AuraStab then record.StabbingUntil,record.StabTarget,record.AuraStab=0,nil,false end
        end
        if State.FlushAuraTouches then return State.FlushAuraTouches() end
    end,
    Stab=auraStab,Burst=auraBurst,Throw=auraThrow})
end


do
-- Perspective bounds of an oriented box clipped against the near plane.
-- Coordinates use camera-right, camera-up and positive forward depth.
local function finite(n) return type(n)=="number" and n==n and math.abs(n)<math.huge end
local signsX={-1,1,-1,1,-1,1,-1,1}
local signsY={-1,-1,1,1,-1,-1,1,1}
local signsZ={-1,-1,-1,-1,1,1,1,1}
local edgeA={1,3,5,7,1,2,5,6,1,2,3,4}
local edgeB={2,4,6,8,3,4,7,8,5,6,7,8}
-- No yields: scratch arrays can be reused without per-corner table allocation.
local xs,ys,ds={},{},{}
local projectESPPart=function(center,size,axes,view)
    if not finite(center.X) or not finite(center.Y) or not finite(center.Z)
        or not finite(size.X) or not finite(size.Y) or not finite(size.Z) or size.X<=0 or size.Y<=0 or size.Z<=0
        or not finite(view.FX) or not finite(view.FY) or view.FX<=0 or view.FY<=0
        or not finite(view.CX) or not finite(view.CY) or not finite(view.Near) or view.Near<=0
        or not finite(view.Left) or not finite(view.Top) or not finite(view.Right) or not finite(view.Bottom)
        or view.Right<=view.Left or view.Bottom<=view.Top then return nil end
    if not finite(axes.RX) or not finite(axes.RY) or not finite(axes.RD)
        or not finite(axes.UX) or not finite(axes.UY) or not finite(axes.UD)
        or not finite(axes.ZX) or not finite(axes.ZY) or not finite(axes.ZD) then return nil end
    local hx,hy,hz=size.X*.5,size.Y*.5,size.Z*.5
    local rx,ry,rd=axes.RX*hx,axes.RY*hx,axes.RD*hx
    local ux,uy,ud=axes.UX*hy,axes.UY*hy,axes.UD*hy
    local zx,zy,zd=axes.ZX*hz,axes.ZY*hz,axes.ZD*hz
    local near=view.Near
    if center.Z+math.abs(rd)+math.abs(ud)+math.abs(zd)<near then return nil end
    local left,top,right,bottom=math.huge,math.huge,-math.huge,-math.huge
    local clipped=false
    for i=1,8 do
        local a,b,c=signsX[i],signsY[i],signsZ[i]
        local x,y,d=center.X+a*rx+b*ux+c*zx,center.Y+a*ry+b*uy+c*zy,center.Z+a*rd+b*ud+c*zd
        xs[i],ys[i],ds[i]=x,y,d
        if d>=near then
            local px,py=view.CX+view.FX*x/d,view.CY-view.FY*y/d
            left,top,right,bottom=math.min(left,px),math.min(top,py),math.max(right,px),math.max(bottom,py)
        else clipped=true end
    end
    if clipped then
        for i=1,12 do
            local a,b=edgeA[i],edgeB[i]
            local da,db=ds[a],ds[b]
            if (da<near)~=(db<near) then
                local t=(near-da)/(db-da)
                local x,y=xs[a]+t*(xs[b]-xs[a]),ys[a]+t*(ys[b]-ys[a])
                local px,py=view.CX+view.FX*x/near,view.CY-view.FY*y/near
                left,top,right,bottom=math.min(left,px),math.min(top,py),math.max(right,px),math.max(bottom,py)
            end
        end
    end
    left,top=math.max(view.Left,left),math.max(view.Top,top)
    right,bottom=math.min(view.Right,right),math.min(view.Bottom,bottom)
    if right<=left or bottom<=top then return nil end
    return left,top,right-left,bottom-top
end

-- Calibrate in engine viewport UI units instead of assuming FOV/optical centre.
local function finite(n) return type(n)=="number" and n==n and math.abs(n)<math.huge end
local function insetAreas(service)
    return service:GetInsetArea(Enum.ScreenInsets.None),service:GetInsetArea(Enum.ScreenInsets.DeviceSafeInsets)
end
local calibrateESPCamera=function(camera,view,guiService)
    local frame=camera:GetRenderCFrame()
    local viewport=camera.ViewportSize
    if viewport.X<=0 or viewport.Y<=0 then return nil,"Empty viewport" end
    local point=frame.Position+frame.LookVector*8
    local origin=camera:WorldToViewportPoint(point)
    local across=camera:WorldToViewportPoint(point+frame.RightVector)
    local above=camera:WorldToViewportPoint(point+frame.UpVector)
    local fx,fy=(across.X-origin.X)*8,(origin.Y-above.Y)*8
    if not finite(fx) or not finite(fy) or fx<=0 or fy<=0 or not finite(origin.X) or not finite(origin.Y)
        or math.abs(across.Y-origin.Y)>.5 or math.abs(above.X-origin.X)>.5 then
        return nil,"Projection calibration unavailable"
    end
    view.CX,view.CY,view.FX,view.FY=origin.X,origin.Y,fx,fy
    local near=camera.NearPlaneZ
    view.Near=finite(near) and near<0 and -near or .1
    view.Left,view.Top,view.Right,view.Bottom=0,0,viewport.X,viewport.Y
    view.BoundsSource="Device viewport"
    if guiService then
        local ok,full,device=pcall(insetAreas,guiService)
        if ok and full and device and full.Min and full.Max and device.Min then
            view.Left,view.Top=full.Min.X-device.Min.X,full.Min.Y-device.Min.Y
            view.Right,view.Bottom=full.Max.X-device.Min.X,full.Max.Y-device.Min.Y
            view.BoundsSource="Fullscreen in device-safe coordinates"
        end
    end
    return frame
end

-- Lightweight, camera-refreshed fallback fill. No 3D adornments for normal avatars.
local installScreenESP=function(C)
    local State=C.State
    local function makeLayer()
        local gui=Instance.new("ScreenGui")
        gui.Name="MM2StableBodyFill"; gui.IgnoreGuiInset=true; gui.ResetOnSpawn=false
        pcall(function() gui.ScreenInsets=Enum.ScreenInsets.DeviceSafeInsets; gui.ClipToDeviceSafeArea=false end)
        gui.DisplayOrder=80; gui.ZIndexBehavior=Enum.ZIndexBehavior.Sibling; gui.Parent=C.Parent
        return gui
    end
    local layer=makeLayer()
    local status={Backend="Screen-space body rectangles",DrawnParts=0,AllocatedParts=0,Frames=0,GeometryWrites=0}
    State.ScreenESP=status
    local cache,view,axes,center={},{},{},{}
    local profileBegin,profileEnd=debug and debug.profilebegin,debug and debug.profileend
    local bindName="MM2ScreenFill_"..tostring(State)
    status.BindName=bindName
    status.RenderPriority=Enum.RenderPriority.Last.Value+1
    local function clear(p)
        local entry=cache[p]
        if entry then
            for _,record in pairs(entry.Parts) do record.Frame:Destroy(); status.AllocatedParts-=1 end
            cache[p]=nil
        end
    end
    local function hide(entry)
        for _,record in pairs(entry.Parts) do if record.Frame.Visible then record.Frame.Visible=false end end
    end
    function status.Stop()
        if status.Stopped then return end
        C.RunService:UnbindFromRenderStep(bindName)
        for p in pairs(cache) do clear(p) end
        layer:Destroy(); status.Stopped=true; status.DrawnParts=0
    end
    State.StopScreenESP=status.Stop
    local function makeFill(name)
        local f=Instance.new("Frame"); f.Name="BodyFill_"..name; f.BorderSizePixel=0
        f.BackgroundTransparency=.6; f.Active=false; f.Visible=false; f.ZIndex=1; f.Parent=layer
        return f
    end
    local function refresh(p,v,now)
        local entry=cache[p]
        if entry and entry.Character~=v.Character then clear(p); entry=nil end
        if not entry then entry={Character=v.Character,Parts={},NextScan=0}; cache[p]=entry end
        if now>=entry.NextScan then
            entry.NextScan=now+.4
            for part,record in pairs(entry.Parts) do
                if part.Parent~=v.Character or not record.Frame.Parent then record.Frame:Destroy(); entry.Parts[part]=nil; status.AllocatedParts-=1 end
            end
            for _,name in ipairs(C.PartNames) do
                local part=v.Character:FindFirstChild(name)
                if part and part:IsA("BasePart") and not entry.Parts[part] then
                    entry.Parts[part]={Frame=makeFill(name),Name=name}; status.AllocatedParts+=1
                end
            end
        end
        return entry
    end
    local function step(dt)
        if status.Stopped or not State.Running then return end
        status.Frames+=1; status.DrawnParts=0
        if not layer.Parent then for p in pairs(cache) do clear(p) end; layer=makeLayer() end
        local camera=C.Camera()
        if not camera or State.StreamerActive or not State.Config.ESP or State.Config.StableBodyESP==false or (C.IsVR and C.IsVR()) then
            for p,entry in pairs(cache) do
                if not State.Visuals[p] then clear(p) else hide(entry) end
            end
            return
        end
        local valid,frame,reason=pcall(C.Calibrate,camera,view,C.GuiService)
        if not valid or not frame then
            for _,entry in pairs(cache) do hide(entry) end
            status.LastError=valid and reason or tostring(frame); return
        end
        local right,up,forward=frame.RightVector,frame.UpVector,frame.LookVector
        status.BoundsSource=view.BoundsSource
        local now=C.Clock and C.Clock() or os.clock()
        local began=os.clock()
        if profileBegin and profileEnd then profileBegin("MM2/BodyProjectionAndGUI") end
        for p,entry in pairs(cache) do if not State.Visuals[p] then clear(p) end end
        for p,v in pairs(State.Visuals) do
            -- One bad/streamed-out body cannot prevent other players from drawing.
            local ok,err=pcall(function()
                local entry=refresh(p,v,now)
                local color=v.Highlight.FillColor
                for part,record in pairs(entry.Parts) do
                    local f=record.Frame
                    if not f.Parent then
                        f:Destroy(); f=makeFill(record.Name); record.Frame=f
                        record.X,record.Y,record.Width,record.Height=nil,nil,nil,nil
                    end
                    if part.Parent~=v.Character then if f.Visible then f.Visible=false end; entry.NextScan=0
                    else
                        local delta=part.Position-frame.Position
                        center.X,center.Y,center.Z=delta:Dot(right),delta:Dot(up),delta:Dot(forward)
                        local cf=part.CFrame
                        axes.RX,axes.RY,axes.RD=cf.RightVector:Dot(right),cf.RightVector:Dot(up),cf.RightVector:Dot(forward)
                        axes.UX,axes.UY,axes.UD=cf.UpVector:Dot(right),cf.UpVector:Dot(up),cf.UpVector:Dot(forward)
                        axes.ZX,axes.ZY,axes.ZD=cf.LookVector:Dot(right),cf.LookVector:Dot(up),cf.LookVector:Dot(forward)
                        local left,top,width,height=C.Project(center,part.Size,axes,view)
                        if left then
                            if not record.X or math.abs(record.X-left)>.25 or math.abs(record.Y-top)>.25
                                or math.abs(record.Width-width)>.25 or math.abs(record.Height-height)>.25 then
                                f.Position=UDim2.fromOffset(left,top); f.Size=UDim2.fromOffset(width,height)
                                record.X,record.Y,record.Width,record.Height=left,top,width,height
                                status.GeometryWrites+=2
                            end
                            if f.BackgroundColor3~=color then f.BackgroundColor3=color end
                            if not f.Visible then f.Visible=true end; status.DrawnParts+=1
                        elseif f.Visible then f.Visible=false end
                    end
                end
            end)
            if not ok then
                if cache[p] then hide(cache[p]) end
                status.LastError=tostring(err)
            end
        end
        if profileBegin and profileEnd then profileEnd() end
        status.LastGeometryMilliseconds=(os.clock()-began)*1000
    end
    status.Step=step -- Read-only render step, also used by the offline fixture.
    C.RunService:BindToRenderStep(bindName,status.RenderPriority,step)
    return status
end

installScreenESP({State=State,Parent=player:WaitForChild("PlayerGui"),PartNames=hitPartNames.Gun,
    Project=projectESPPart,Calibrate=calibrateESPCamera,GuiService=GuiService,
    IsVR=function() return game:GetService("VRService").VREnabled end,
    Camera=function() return workspace.CurrentCamera end,RunService=RunService})
end


do
-- Explicit user action only. Each stop is attempted even if another one fails.
local installEmergencyStop = function(C)
    local State = C.State
    function State.EmergencyStop()
        local errors = {}
        local hadFling = State.Fling and State.Fling.Active
        local function run(name, callback)
            if callback then local ok,message=pcall(callback); if not ok then table.insert(errors,name..": "..tostring(message)) end end
        end
        State.Config.AutoPickup = false
        run("pickup",function() if State.StopGunPickup then local ok,message=State.StopGunPickup(); if ok==false then error(message) end end end)
        run("map vote",function() if State.StopMapVoteRepeat then local ok,message=State.StopMapVoteRepeat("Emergency stop"); if ok==false then error(message) end end end)
        run("queued attacks",C.CancelWeaponActions)
        run("kill aura",function() if State.StopKillAura then
            local ok,message=State.StopKillAura("Emergency stop")
            if ok==false then error(message or "Aura cleanup failed") end
        end end)
        run("auto attack",function() if State.StopAutoAttack then State.StopAutoAttack("Emergency stop") end end)
        run("triggerbot",function() if State.StopTriggerbot then State.StopTriggerbot("Emergency stop") end end)
        -- End dodge before fling return so a dodge restore cannot replace that return.
        State.Config.AutoKnifeDodge = false
        run("dodge",function() if State.SetAutoKnifeDodge then State.SetAutoKnifeDodge(false) end end)
        run("target memory",State.ClearTargetContinuity)
        run("movement",State.StopMovement)
        run("fling queue",function() if State.StopFlingAll then local ok,message=State.StopFlingAll("Emergency stop"); if ok==false then error(message) end end end)
        run("fling",function() if State.StopFling then State.StopFling() end end)
        if hadFling and State.Fling.ReturnStatus and State.Fling.ReturnStatus:find("Return failed:",1,true) then
            table.insert(errors,State.Fling.ReturnStatus)
        end
        run("invisibility",function()
            if State.SetInvisibility then
                local ok,message=State.SetInvisibility(false)
                if ok==false then error(message or "Character restoration failed") end
            end
        end)
        local message = #errors==0 and "Everything stopped"
            or "Stopped with issues: "..table.concat(errors,"; ")
        State.EmergencyStopReport={OK=#errors==0,Errors=errors,Message=message}
        State.AimStatus=message
        return #errors==0,message
    end
end

installEmergencyStop({State=State,CancelWeaponActions=function()
    local failures={}
    for _, record in pairs(State.WeaponHandlers) do
        record.ThrowToken += 1
        record.Charging,record.AutoSelectedThrow,record.StabbingUntil,record.StabTarget=false,nil,0,nil
        record.LastThrow=-math.huge
        local ok,message=pcall(stopTracks,record)
        if not ok then table.insert(failures,tostring(message)) end
    end
    if #failures>0 then error(table.concat(failures,"; ")) end
end})
end


do
-- Bounded yielding path jobs. A timeout does not imply native cancellation.
-- Successful Path ownership transfers to the callback; other paths are destroyed.
local createAsyncPathPool = function(C)
    local clock=C.Clock or os.clock
    local limit,timeout=C.Limit or 2,C.Timeout or 4
    local budget=C.Budget or {Outstanding=0}
    local status={Outstanding=0,Timeouts=0,Live=false,LastStatus="Idle",Limit=limit,TimeoutSeconds=timeout}
    status.TotalOutstanding=budget.Outstanding
    local pool={Status=status}
    local live,stopped,nextRequest,failures=nil,false,0,0
    local function destroy(path) pcall(function() path:Destroy() end) end
    local function reserve()
        budget.Outstanding+=1; status.Outstanding+=1; status.TotalOutstanding=budget.Outstanding
    end
    local function release()
        budget.Outstanding-=1; status.Outstanding-=1; status.TotalOutstanding=budget.Outstanding
    end
    local function deliver(entry,ok,points,path,reason)
        local accepted,result=pcall(entry.Callback,ok,points,path,reason)
        if not accepted then status.LastError=tostring(result) end
        if path and (not accepted or result==false) then destroy(path) end
    end
    function pool.IsBusy() return live~=nil end
    function pool.Invalidate()
        if live then live.Valid=false end
    end
    function pool.Stop()
        stopped=true; pool.Invalidate(); live=nil; status.Live=false; status.LastStatus="Stopped"
    end
    function pool.Poll()
        status.TotalOutstanding=budget.Outstanding
        if stopped then return end
        if live and clock()-live.Started>=timeout then
            local entry=live; live=nil; status.Live=false
            local report=entry.Valid; entry.Valid=false
            status.Timeouts+=1; status.LastStatus="Timeout"
            failures=math.min(failures+1,5); nextRequest=clock()+math.min(16,2^(failures-1))
            -- Outstanding is decremented only when the worker actually returns.
            if report then deliver(entry,false,nil,nil,"timeout") end
        end
    end
    function pool.Request(params,start,goal,callback)
        pool.Poll()
        if stopped then return false,"stopped" end
        if live then return false,"busy" end
        if budget.Outstanding>=limit then status.LastStatus="Saturated"; return false,"saturated" end
        if clock()<nextRequest then return false,"backoff" end
        local created,path=pcall(C.CreatePath,params)
        if not created or not path then status.LastError=tostring(path); return false,"create-error" end
        local entry={Path=path,Valid=true,Callback=callback,Started=clock()}
        live=entry; status.Live=true; reserve(); status.LastStatus="Computing"
        local scheduled,scheduleError=pcall(C.Spawn,function()
            if stopped or not entry.Valid then
                release()
                if live==entry then live=nil; status.Live=false end
                destroy(path); return
            end
            local ok,points=pcall(C.ComputePath,path,start,goal)
            release()
            local current=live==entry
            if current then live=nil; status.Live=false end
            if stopped or not current or not entry.Valid then destroy(path); return end
            if not ok or not points then
                status.LastStatus=ok and "No path" or "Error"
                if not ok then status.LastError=tostring(points) end
                destroy(path); deliver(entry,false,nil,nil,ok and "no-path" or "compute-error"); return
            end
            failures=0; nextRequest=0; status.LastStatus="Ready"
            deliver(entry,true,points,path,nil)
        end)
        if not scheduled then
            if live==entry then live=nil; status.Live=false end
            release(); entry.Valid=false; destroy(path)
            status.LastError=tostring(scheduleError); return false,"schedule-error"
        end
        return true
    end
    return pool
end

-- Recommendations only, using currently observed characters and map destinations.
local createTacticalPolicy = function()
    local policy={}
    local function countNear(list,position,except,radius)
        local count=0
        for _,p in ipairs(list) do if p.Id~=except and (p.Position-position).Magnitude<radius then count+=1 end end
        return count
    end
    function policy.Decide(s)
        if not s.Active or s.Role=="Unknown" then return {Instruction="Waiting for a round",Kind="Idle"} end
        if s.Mode and s.Mode~="Classic" then
            local result={Kind="Idle",Instruction="Observe the event round"}
            if s.Mode~="Infection" and s.Mode~="FreezeTag" then result.Instruction="Guidance unavailable for this mode"; return result end
            if s.Frozen then result.Instruction="Frozen · wait for a teammate"; return result end
            if s.Paused then result.Instruction="Another action is active · End or Stop cancels it"; return result end
            local target,nearest,threat,threatDistance
            for _,p in ipairs(s.Players) do
                local distance=(p.Position-s.Position).Magnitude
                if p.Enemy and not p.Excluded and (not nearest or distance<nearest) then target,nearest=p,distance end
                if p.Threat and (not threatDistance or distance<threatDistance) then threat,threatDistance=p,distance end
            end
            if (s.Role=="Zombie" or s.Role=="Freezer") and target then
                result.Target=target; result.Label=target.Role:upper()
