    mobile.EquipStatus=settings:Paragraph({Title="Weapon equip status",Desc=State.WeaponEquipRecovery.Status})
    settings:Button({Title = "Reset mobile button positions", Callback = function() if mobile.ResetPositions then mobile.ResetPositions() end end})
    option(settings,"Phone shortcut dock","MobileShortcuts","Invis, Speed, Trigger and Aura; More holds Fly, Noclip, Dodge and Kill all.")
    option(settings,"Start phone menu closed","MobileStartClosed","Open the full menu with the MM2 button.")
    option(hud,"Show instructions on phone","MobileShowStatus","Off by default so the status card cannot cover your inventory.")
    option(hud,"Streamer mode (Windows)","StreamerMode","Requires the Windows companion and connect.lua. Mirrors supported 2D HUD into a separate overlay; configure OBS Window Capture with cursor off.")
    mobile.StreamerStatus=hud:Paragraph({Title="Streamer status",Desc="Off · Windows companion required. Use F4 to toggle, even with the menu open."})
    if State.Settings then
        mobile.SettingsStatus=settings:Paragraph({Title="Saved settings",Desc=State.Settings.Status})
        settings:Button({Title="Reset settings",Desc="Defaults for every setting. Protected players stay.",Callback=function()
            suppressInput()
            local ok,message=State.ResetSettings()
            if mobile.Toast then mobile.Toast(message,ok and "info" or "warn",true) end
        end})
    end
    local repairs=settings
    local supportStatus=settings:Paragraph({Title="Support",Desc=State.Build .. " · " .. State.ReleaseChannel})
    settings:Button({Title="Copy support report",Desc="Version, settings and counters. No names or keys.",Callback=function()
        suppressInput()
        local ok,report=pcall(State.GetSupportReport)
        local message
        if not ok then message="Couldn't generate the report. Try unloading and reloading."
        else
            local copy=setclipboard or toclipboard
            -- Phones have no developer console, so without a clipboard the report goes in this card.
            if type(copy)=="function" and pcall(copy,report) then message="Support report copied. Paste it into your issue."
            else print("MM2 support report: " .. report); message="Clipboard unavailable. Report:\n" .. report end
        end
        if supportStatus and supportStatus.ParagraphFrame then supportStatus.ParagraphFrame:SetDesc(message) end
    end})
    repairs:Button({Title = "Repair camera input", Callback = function() State.FixCamera() end})
