    settings:Button({Title = "Unload and restore", Callback = function() State.Destroy() end})
    if State.FlingPlayer then
        -- Register configuration containers after the primary target/actions below.
        local contactOptions,diagnostics
        local function buildFlingSettings()
        contactOptions=flingOptions
        if State.SetFlingSpinContact then
            mobile.SpinContactToggle = contactOptions:Toggle({Title = "Spin contact", Value = State.Fling.Mode == "Spin",
                Desc = "Orbit the target. Changing mode stops fling.",
                Callback = function(enabled) if State.StopFlingAll then State.StopFlingAll("Fling mode changed") end; State.SetFlingSpinContact(enabled) end})
        end
        if State.SetFlingDownward then
            mobile.DownwardContactToggle = contactOptions:Toggle({Title = "Downward contact (experimental)", Value = State.Fling.Mode == "Downward",
                Desc = "Hit from above. Changing mode stops fling.",
                Callback = function(enabled) if State.StopFlingAll then State.StopFlingAll("Fling mode changed") end; State.SetFlingDownward(enabled) end})
        end
        if State.SetFlingAdaptivePursuit then
            mobile.AdaptivePursuitToggle = contactOptions:Toggle({Title = "Track fast / flying targets", Value = State.Fling.AdaptivePursuit,
                Desc = "Follow jumping and flying targets.",
                Callback = function(enabled) if State.StopFlingAll then State.StopFlingAll("Fling tracking changed") end; State.SetFlingAdaptivePursuit(enabled) end})
        end
        if State.GetFlingReport then
            diagnostics=flingReports
            diagnostics:Paragraph({Title = "Build", Desc = tostring(State.Build)})
            diagnostics:Button({Title = "Copy fling report", Desc = "Status and contact data.", Callback = function()
                local copy = setclipboard or toclipboard
                local report = State.GetFlingReport()
                local ok = type(copy) == "function" and pcall(copy, report)
                if not ok and mobile.FlingStatus and mobile.FlingStatus.ParagraphFrame then
                    mobile.FlingStatus.ParagraphFrame:SetDesc(report)
                end
            end})
        end
        end
        local function runFlingAction(name, callback)
            if name~="All players" and State.StopFlingAll then State.StopFlingAll("Manual fling selected") end
            local request = {Name = name, At = os.clock()}
            mobile.LastFlingAction = request
            local ok, accepted, message = pcall(callback)
            request.Accepted = ok and accepted ~= false
            if not ok then
                State.Fling.Status = "Fling error: " .. tostring(accepted)
                request.Error = tostring(accepted)
            elseif accepted == false and message then
                State.Fling.Status = tostring(message)
            end
            State.Fling.DisplayUntil = os.clock() + 4
            if mobile.FlingStatus and mobile.FlingStatus.ParagraphFrame then
                mobile.FlingStatus.ParagraphFrame:SetDesc(State.Fling.Status)
            end
        end
        local selectedId, labelToId, picker, flingPicker
        local selecting=false
        local function roster()
            local labels, selectedLabel = {}, nil
            labelToId = {}
            for _, entry in ipairs(State.GetFlingPlayers()) do
                local label = entry.DisplayName .. " (@" .. entry.Name .. ") | " .. entry.Role
                table.insert(labels, label)
                labelToId[label] = entry.UserId
                if selectedId == entry.UserId then selectedLabel = label end
            end
            if not selectedLabel then selectedId = nil end
            selecting=true
            if picker then picker:Refresh(labels); picker:Select(selectedLabel) end
            if flingPicker then flingPicker:Refresh(labels); flingPicker:Select(selectedLabel) end
            selecting=false
            if State.SetSelectedPlayer then State.SetSelectedPlayer(selectedId) end
            return labels
        end
        local function selectPlayer(label)
            if selecting then return end
            selectedId=labelToId[label]
            if State.SetSelectedPlayer then State.SetSelectedPlayer(selectedId) end
            selecting=true
            if picker then picker:Select(label) end
            if flingPicker then flingPicker:Select(label) end
            selecting=false
        end
        picker = playersTab:Dropdown({Title = "Specific player", Values = roster(), Multi = false, AllowNone = true,
            SearchBarEnabled = true, Callback = selectPlayer})
        flingPicker=flingTab:Dropdown({Title="Fling target",Values=roster(),Multi=false,AllowNone=true,
            SearchBarEnabled=true,Callback=selectPlayer})
        if State.PlayerActions then
            local selectedActions=playersTab
            mobile.PlayerActionStatus = selectedActions:Paragraph({Title = "Status", Desc = State.PlayerActions.Status})
            local function playerAction(callback)
                if State.StopFlingAll then State.StopFlingAll("Player action selected") end
                local ok, accepted, message = pcall(callback)
                if not ok then State.PlayerActions.Status = "Player action error: " .. tostring(accepted)
                elseif accepted == false and message then State.PlayerActions.Status = tostring(message) end
                if mobile.PlayerActionStatus and mobile.PlayerActionStatus.ParagraphFrame then
                    mobile.PlayerActionStatus.ParagraphFrame:SetDesc(State.PlayerActions.Status)
                end
                return ok and accepted ~= false
            end
            selectedActions:Button({Title = "Teleport to selected player", Callback = function()
                playerAction(function() return State.TeleportToPlayer(selectedId) end)
            end})
            local autoToggle
            autoToggle = selectedActions:Toggle({Title = "Auto attack selected player", Value = false,
                Desc = "Uses your weapon once the menu closes.",
                Callback = function(enabled)
                    local accepted = playerAction(function() return State.SetAutoAttack(enabled,selectedId) end)
                    if not accepted and autoToggle then autoToggle:Set(false,false) end
                end})
            mobile.AutoAttackToggle = autoToggle
            selectedActions:Button({Title = "Stop all player actions", Callback = function()
                if State.EmergencyStop then mobile.TriggerEmergencyStop()
                else State.StopAutoAttack("All player actions stopped"); State.StopFling() end
            end})
        end
        flingTab:Button({Title = "Fling selected player", Callback = function() runFlingAction("Selected player", function() return State.FlingPlayer(selectedId) end) end})
        roleFling:Button({Title = "Fling role opponent", Desc = "Murderer flings sheriff, others fling murderer.", Callback = function() runFlingAction("Role opponent", function() return State.FlingRole("Opponent") end) end})
        if State.FlingAll then
            flingTab:Button({Title="Fling all",Desc="One at a time. Skips protected players.",Callback=function()
                runFlingAction("All players",State.FlingAll)
            end})
            mobile.FlingAllStatus=flingReports:Paragraph({Title="Fling all",Desc=State.FlingQueue.Status})
        end
        flingTab:Button({Title = "Stop fling / return", Callback = function() if State.StopFlingAll then State.StopFlingAll() end; State.StopFling() end})
        mobile.FlingSummary=flingTab:Paragraph({Title="Status",Desc=State.Fling.Status})
        mobile.RoleFlingSummary=roleFling:Paragraph({Title="Status",Desc=State.Fling.Status})
        mobile.FlingStatus = flingReports:Paragraph({Title = "Status", Desc = State.Fling.Status})
        local roleActions=roleFling
        roleActions:Button({Title = "Fling murderer", Callback = function() runFlingAction("Murderer", function() return State.FlingRole("Murderer") end) end})
        roleActions:Button({Title = "Fling sheriff", Callback = function() runFlingAction("Sheriff", function() return State.FlingRole("Sheriff") end) end})
        buildFlingSettings()
        playersTab:Button({Title = "Refresh player list", Callback = roster})
        flingTab:Button({Title="Refresh fling targets",Callback=roster})
        local function refreshRoster()
            task.defer(function() if State.Running and not mobile.Destroyed then roster() end end)
        end
        if C.Players then
            connect(C.Players.PlayerAdded, refreshRoster)
            connect(C.Players.PlayerRemoving, refreshRoster)
        end
    end
    if exclusionsTab then
        local addId, removeId, addMap, removeMap = nil, nil, {}, {}
        local addPicker, removePicker
        mobile.ExclusionsStatus = exclusionsTab:Paragraph({Title = "Status", Desc = "Pick a player, then Exclude."})
        local function refreshExclusions()
            local addLabels, removeLabels, addLabel, removeLabel = {}, {}, nil, nil
            addMap, removeMap = {}, {}
            for _, entry in ipairs(State.GetFlingPlayers()) do
                local label = entry.DisplayName .. " (@" .. entry.Name .. ")"
                table.insert(addLabels, label); addMap[label] = entry.UserId
                if entry.UserId == addId then addLabel = label end
            end
            for _, entry in ipairs(State.GetPlayerExclusions()) do
                local label = entry.DisplayName .. " (@" .. entry.Name .. ")" .. (entry.Permanent and " [always protected]" or "")
                table.insert(removeLabels, label); removeMap[label] = entry.UserId
                if entry.UserId == removeId then removeLabel = label end
            end
            if not addLabel then addId = nil end
            if not removeLabel then removeId = nil end
            if addPicker then addPicker:Refresh(addLabels); addPicker:Select(addLabel) end
            if removePicker then removePicker:Refresh(removeLabels); removePicker:Select(removeLabel) end
            mobile.LastExclusionsRevision = State.ExclusionsRevision
            return addLabels, removeLabels
        end
        local addLabels, removeLabels = refreshExclusions()
        addPicker = exclusionsTab:Dropdown({Title = "Player to exclude", Values = addLabels, Multi = false, AllowNone = true,
            SearchBarEnabled = true, Callback = function(label) addId = addMap[label] end})
        removePicker = exclusionsTab:Dropdown({Title = "Excluded players", Values = removeLabels, Multi = false, AllowNone = true,
            SearchBarEnabled = true, Callback = function(label) removeId = removeMap[label] end})
        mobile.AddExclusionPicker, mobile.ExcludedPlayerPicker = addPicker, removePicker
        local function change(callback)
            local _, message = callback()
            refreshExclusions()
            if mobile.ExclusionsStatus.ParagraphFrame then mobile.ExclusionsStatus.ParagraphFrame:SetDesc(message) end
        end
        exclusionsTab:Button({Title = "Exclude selected player", Callback = function()
            change(function() return State.SetPlayerExcluded(addId, true) end)
        end})
        exclusionsTab:Button({Title = "Remove selected exclusion", Callback = function()
            change(function() return State.SetPlayerExcluded(removeId, false) end)
        end})
        exclusionsTab:Button({Title = "Clear exclusions", Callback = function() change(State.ClearPlayerExclusions) end})
        mobile.RefreshExclusions = refreshExclusions
        if C.Players then
            local function rosterChanged() task.defer(function() if State.Running and not mobile.Destroyed then refreshExclusions() end end) end
            connect(C.Players.PlayerAdded, rosterChanged)
            connect(C.Players.PlayerRemoving, rosterChanged)
        end
    end
    home:Select()
    local descriptions={}
    local function updateDescription(card,key,text)
        if card and card.ParagraphFrame and descriptions[key]~=text then
            card.ParagraphFrame:SetDesc(text); descriptions[key]=text
        end
    end
    -- Short wording shared by the menu session line and the status card.
    local roleLook={Murderer={"MURDERER",Color3.fromRGB(255,90,100)},Sheriff={"SHERIFF",Color3.fromRGB(90,160,255)},
        Hero={"HERO",Color3.fromRGB(90,160,255)},Innocent={"INNOCENT",Color3.fromRGB(90,220,130)},
        Zombie={"ZOMBIE",colors.Zombie},Survivor={"SURVIVOR",colors.Survivor},Freezer={"FREEZER",colors.Freezer},Runner={"RUNNER",colors.Runner},
        Lobby={"LOBBY"},Eliminated={"OUT"},["Waiting for character"]={"SPAWNING"}}
    local weaponWords={["No weapon equipped"]="Unarmed",["Gun reloading / disabled"]="Reloading",["Knife charging"]="Charging"}
    local resultWords={["No gun feedback yet"]="No shots yet",["Awaiting server shot reply"]="Shot sent",
        ["Last: server ray hit target"]="Last shot hit",["Last: reported ray hit (heuristic match)"]="Last shot likely hit",
        ["Last: server ray missed target"]="Last shot missed",["Last: reported miss (heuristic match)"]="Last shot likely missed",
        ["Last: server reported round victory"]="Round won",["No unique reply matched this shot; outcome unknown"]="Last shot unconfirmed"}
    local toneColors={confirmed=Color3.fromRGB(110,232,158),warning=Color3.fromRGB(255,140,128),waiting=Color3.fromRGB(255,206,110)}
    local function weaponWord(weapon) return weaponWords[weapon] or weapon or "" end
    local function updateDashboard()
        if not mobile.MenuOpen then return end
        local data
        if State.GetCombatHUDData then local ok,result=pcall(State.GetCombatHUDData); if ok and type(result)=="table" then data=result end end
        local role=data and data.Role
        local session=State.GameContext.Mode().."  ·  "..(role and role~="Unknown" and role or "Waiting for round").."  ·  "..weaponWord(data and data.Weapon or "No weapon equipped")
        local function flag(value) return value and "on" or "off" end
        session..="\nGun aim "..flag(State.Config.MagicBullet).."  ·  ESP "..flag(State.Config.ESP).."  ·  Aura "..flag(State.KillAura and State.KillAura.Enabled)
        updateDescription(mobile.OverviewStatus,"Overview",session)
        if mobile.SettingsStatus and State.Settings then updateDescription(mobile.SettingsStatus,"Settings",State.Settings.Status) end
        if mobile.EquipStatus and State.WeaponEquipRecovery then
            local equip=State.GetWeaponEquipSnapshot()
            updateDescription(mobile.EquipStatus,"Equip",equip.Status..("\n%d slot 1 presses · %d local recoveries · %d skipped · %d failed"):format(equip.Presses,equip.Recoveries,equip.Skipped,equip.Failures))
        end
        if State.Triggerbot then
            local bot=State.Triggerbot
            local detail=bot.Status..("\n%d aim checks · %d gun requests · %d stab requests (not confirmed kills)"):format(bot.AimChecks,bot.Shots,bot.Stabs)
            if bot.LastAimCheck then detail..="\nLast gun check: "..bot.LastAimCheck.Message end
            if bot.BeforePause then detail..="\nBefore pause: "..bot.BeforePause end
            updateDescription(mobile.TriggerbotStatus,"GunTriggerbot",detail)
            updateDescription(mobile.KnifeTriggerbotStatus,"KnifeTriggerbot",detail)
        end
        if State.KillAll then updateDescription(mobile.KillAllStatus,"KillAll",State.KillAll.Status) end
        if mobile.ResultsStatus and State.GetCombatResults then
            updateDescription(mobile.ResultsStatus,"CombatResults",State.GetCombatResults().Text)
            updateDescription(mobile.ResultsHistory,"CombatHistory",select(2,State.GetRecentCombatRuns()))
        end
        local binds=State.Config.Keybinds or {}
        updateDescription(mobile.ControlsCard,"Controls",("PC  %s menu  ·  Click fire or stab  ·  E or right-click throw  ·  %s stop\nMobile  MM2 button  ·  Fire  ·  Throw  ·  Stop  ·  Up and Down while flying")
            :format(keyLabel(binds.Menu or "RightShift"),keyLabel(binds.Stop or "End")))
        if mobile.GuidanceStatus then updateDescription(mobile.GuidanceStatus,"Guidance",State.Guidance and State.Guidance.Instruction or "Waiting for a round") end
        if mobile.RevealStatus and State.GetRoleReveal then
            local message,reason=State.GetRoleReveal()
            updateDescription(mobile.RevealStatus,"Reveal",mobile.RevealResult or message or reason)
        end
    end
    if State.RevealRolesInChat then
        chatSection:Button({Title="Reveal roles",Desc="Posts the murderer and sheriff in chat. Never names you.",Callback=function()
            suppressInput()
            local ok,sent,message=pcall(State.RevealRolesInChat)
            local text=ok and tostring(message) or "Reveal failed: "..tostring(sent)
            mobile.RevealResult=text
            updateDescription(mobile.RevealStatus,"Reveal",text)
            task.delay(4,function() if mobile.RevealResult==text then mobile.RevealResult=nil end end)
        end})
        mobile.RevealStatus=chatSection:Paragraph({Title="Message",Desc="Available during a round"})
    end
    mobile.UpdateDashboard=updateDashboard
    updateDashboard()

    -- One visual system for every overlay: near-black surface, white hairline, menu accent, menu font.
