    local function clamp(frame)
        -- Use assigned offsets before the next render updates AbsoluteSize after rotation.
        local extent=Vector2.new(frame.Size.X.Scale==0 and frame.Size.X.Offset or frame.AbsoluteSize.X,
            frame.Size.Y.Scale==0 and frame.Size.Y.Offset or frame.AbsoluteSize.Y)
        local max = canvas.AbsoluteSize - extent - Vector2.new(6, 6)
        frame.Position = UDim2.fromOffset(
            math.clamp(frame.Position.X.Offset, 6, math.max(6, max.X)),
            math.clamp(frame.Position.Y.Offset, 6, math.max(6, max.Y)))
    end
    local userPositioned={}
    -- Follow only the touch that began this gesture; a second finger keeps movement usable.
    local function draggable(handleObject, frame, onTap)
        local gesture
        connect(handleObject.InputBegan, function(input)
            local touch = input.UserInputType == Enum.UserInputType.Touch
            if gesture or not (touch or input.UserInputType == Enum.UserInputType.MouseButton1) then return end
            gesture = {Input = input, Touch = touch, Start = input.Position,
                Position = frame.Position, Moved = false}
            suppressInput()
        end)
        connect(UIS.InputChanged, function(input)
            local g = gesture
            if not g or (g.Touch and input ~= g.Input)
                or (not g.Touch and input.UserInputType ~= Enum.UserInputType.MouseMovement) then return end
            local delta = input.Position - g.Start
            if delta.Magnitude > 9 then g.Moved = true end
            if g.Moved then
                userPositioned[frame]=true
                frame.Position = g.Position + UDim2.fromOffset(delta.X, delta.Y)
                clamp(frame)
            end
            suppressInput()
        end)
        connect(UIS.InputEnded, function(input)
            local g = gesture
            if not g or (g.Touch and input ~= g.Input)
                or (not g.Touch and input.UserInputType ~= Enum.UserInputType.MouseButton1) then return end
            gesture = nil
            suppressInput()
            -- Compare gesture positions in the same screen coordinate space.
            -- This avoids notch/topbar inset differences between Input and AbsolutePosition.
            local moved = g.Moved or (input.Position - g.Start).Magnitude > 9
            if not moved and onTap then onTap() end
        end)
        connect(UIS.WindowFocusReleased, function() gesture = nil end)
    end
    draggable(icon, icon, function() window:Toggle() end)
    draggable(handle, pad)
    draggable(flyHandle, flyPad)
    -- Holding Up or Down sets the fly direction until that same finger or mouse button lifts.
    local function holdVertical(control, direction)
        local holding
        connect(control.InputBegan, function(input)
            local kind = input.UserInputType
            if kind ~= Enum.UserInputType.Touch and kind ~= Enum.UserInputType.MouseButton1 then return end
            holding = input
            suppressInput()
            if State.Movement then State.Movement.Vertical = direction end
        end)
        connect(UIS.InputEnded, function(input)
            local h = holding
            if not h or (h.UserInputType == Enum.UserInputType.Touch and input ~= h)
                or (h.UserInputType ~= Enum.UserInputType.Touch and input.UserInputType ~= h.UserInputType) then return end
            holding = nil
            if State.Movement and State.Movement.Vertical == direction then State.Movement.Vertical = 0 end
        end)
    end
    holdVertical(flyUp, 1)
    holdVertical(flyDown, -1)
    local emergencyButton
    if State.EmergencyStop then
        emergencyButton=button("STOP / RETURN",UDim2.fromOffset(112,40),canvas)
        emergencyButton.Name="EmergencyStop"
        emergencyButton.Text="Stop"
        emergencyButton.BackgroundColor3=Color3.fromRGB(46,16,20)
        emergencyButton.TextColor3=Color3.fromRGB(255,150,156)
        emergencyButton.UIStroke.Color,emergencyButton.UIStroke.Transparency=Color3.fromRGB(255,90,100),.45
        emergencyButton.Visible=false
        mobile.EmergencyButton=emergencyButton
        draggable(emergencyButton,emergencyButton,mobile.TriggerEmergencyStop)
    end
    -- The menu and stop keys come from Settings -> Keybinds (Right Shift and End by default).
    local function menuKey() return keyCode(State.Config.Keybinds and State.Config.Keybinds.Menu) or Enum.KeyCode.RightShift end
    local function stopKey() return keyCode(State.Config.Keybinds and State.Config.Keybinds.Stop) or Enum.KeyCode.End end
    local function menuPressed(_, state)
        if mobile.Destroyed or getMode() ~= "PC" or UIS:GetFocusedTextBox() then
            return Enum.ContextActionResult.Pass
        end
        if state == Enum.UserInputState.Begin then window:Toggle() end
        return Enum.ContextActionResult.Sink
    end
    local function stopPressed(_, state)
        if mobile.Destroyed or not State.Running or getMode() ~= "PC" or UIS:GetFocusedTextBox() then return Enum.ContextActionResult.Pass end
        if state == Enum.UserInputState.Begin then mobile.TriggerEmergencyStop() end
        return Enum.ContextActionResult.Sink
    end
    local boundMenuKey, boundStopKey
    -- Rebinds only when a key actually changed; called again whenever the keybind cards sync.
    function mobile.BindMenuKeys()
        if not actionService or mobile.Destroyed then return end
        local wantedMenu, wantedStop = menuKey(), stopKey()
        if wantedMenu ~= boundMenuKey then
            if menuBound then actionService:UnbindAction(menuAction) end
            -- High priority so the menu key wins over native mouse-lock bindings.
            actionService:BindActionAtPriority(menuAction, menuPressed, false, Enum.ContextActionPriority.High.Value + 100, wantedMenu)
            menuBound, boundMenuKey = true, wantedMenu
        end
        if State.EmergencyStop and wantedStop ~= boundStopKey then
            if emergencyBound then actionService:UnbindAction(emergencyAction) end
            actionService:BindActionAtPriority(emergencyAction, stopPressed, false, Enum.ContextActionPriority.High.Value + 110, wantedStop)
            emergencyBound, boundStopKey = true, wantedStop
        end
    end
    if actionService then
        mobile.BindMenuKeys()
    else
        connect(UIS.InputBegan, function(input, processed)
            if processed or getMode() ~= "PC" or UIS:GetFocusedTextBox() then return end
            if input.KeyCode == menuKey() then window:Toggle() end
            if input.KeyCode == stopKey() and State.EmergencyStop then mobile.TriggerEmergencyStop() end
        end)
    end
    local function action(callback)
        if mobile.Destroyed or not State.Running or mobile.Mode ~= "Mobile" or mobile.MenuOpen or UIS:GetFocusedTextBox() then return end
        suppressInput()
        State.MobileActionInProgress = true
        local ok, message = pcall(callback)
        State.MobileActionInProgress = false
        if not ok then State.AimStatus = "Mobile input: " .. tostring(message) end
    end
    local quickDock,moreDock,shortcutButtons
