    local function layoutHUD()
        if not combatHUD then return end
        local compact=State.Config.CompactHUD~=false
        local width=math.max(160,math.min(compact and 260 or 290,canvas.AbsoluteSize.X-24))
        combatHUD.Size=UDim2.fromOffset(width,compact and 64 or 86)
        hudDetail.Visible=not compact
        mobile.LastHUDCompact=compact
        if not userPositioned[combatHUD] then
            local size=canvas.AbsoluteSize
            combatHUD.Position=UDim2.fromOffset(size.X/2-width/2,mobile.Mode=="Mobile" and 92 or size.Y-combatHUD.Size.Y.Offset-12)
        end
        clamp(combatHUD)
    end
    mobile.LayoutHUD=layoutHUD
    local hudShown={}
    local function setText(l,text) if l.Text~=text then l.Text=text end end
    local function renderHUD(data)
        local roleName=tostring(data.Role or "Unknown")
        if hudShown.Role~=roleName then
            local role=roleLook[roleName]
            local color=role and role[2] or look.Muted
            hudRole.Text,hudRole.TextColor3,hudChip.BackgroundColor3=role and role[1] or roleName:upper(),color,color
            hudShown.Role=roleName
        end
        setText(hudWeapon,weaponWord(data.Weapon))
        local primary=data.Primary or data.Instruction
        if not primary and data.Target then
            primary="@"..data.Target
            if data.Distance then primary..="  ·  "..math.floor(data.Distance+.5).." studs" end
            if data.Height and data.Height>5 then primary..="  ·  above" elseif data.Height and data.Height< -5 then primary..="  ·  below" end
        end
        if not primary then
            primary=(data.Role=="Lobby" or data.Role=="Waiting for character") and "Waiting for round"
                or data.Role=="Eliminated" and "Spectating"
                or not State.Config.Aim and "Aim off" or "No target"
        end
        setText(hudPrimary,primary)
        setText(hudResult,resultWords[data.Result] or tostring(data.Result or ""))
        if hudShown.Tone~=data.Tone then
            hudDot.BackgroundColor3=toneColors[data.Tone] or look.Muted
            hudShown.Tone=data.Tone
        end
    end
    local function positionControls()
        local size=canvas.AbsoluteSize
        if size.X<240 or size.Y<240 then return end -- wait for the ScreenGui's first real layout
        local layout=mobile.PhoneControls.Layout(size.X,size.Y)
        quickDock.Size=UDim2.fromOffset(layout.Dock.W,layout.Dock.H)
        mobile.ShortcutGrip.Size=UDim2.fromOffset(layout.Dock.W,18)
        local index=0
        for _,entry in ipairs(mobile.PhoneControls.Items) do
            if not entry.More then
                shortcutButtons[entry.Id].Position=UDim2.fromOffset((index%layout.Columns)*68,18+math.floor(index/layout.Columns)*48)
                index+=1
            end
        end
        for _,control in ipairs({mobile.ShortcutMoreButton,mobile.ShortcutStopButton}) do
            control.Position=UDim2.fromOffset((index%layout.Columns)*68,18+math.floor(index/layout.Columns)*48)
            index+=1
        end
        local function place(frame,rect)
            if not userPositioned[frame] then frame.Position=UDim2.fromOffset(rect.X,rect.Y) end
            clamp(frame)
        end
        place(icon,layout.Icon); place(pad,layout.Weapon); place(flyPad,layout.Fly)
        place(quickDock,layout.Dock); place(moreDock,layout.More)
        if emergencyButton then
            if not userPositioned[emergencyButton] then
                emergencyButton.Position=UDim2.fromOffset(size.X-emergencyButton.Size.X.Offset-8,8)
            end
            clamp(emergencyButton)
        end
        layoutHUD()
    end
    function mobile.ResetPositions()
        table.clear(userPositioned)
        mobile.MoreOpen=false
        positionControls()
        mobile.UpdatePhoneControls()
    end
    local function resized()
        local size = canvas.AbsoluteSize
        if size.X<240 or size.Y<240 then return end
        local phone=mobile.Mode=="Mobile"
        local menu=mobile.PhoneControls.Layout(size.X,size.Y).Menu
        local width=phone and menu.W or math.max(280,math.min(680,size.X-24))
        local height=phone and menu.H or math.max(240,math.min(520,size.Y-24))
        window.Size = UDim2.fromOffset(width, height)
        if not window.Closed then window:SetSize(window.Size) end
        window:SetToTheCenter()
        notice.Size = UDim2.fromOffset(math.min(300, size.X - 24), 36)
        notice.Position = UDim2.new(0.5, -notice.Size.X.Offset / 2, 0, 8)
        window.UIElements.SideBarContainer.Visible=not phone
        window.UIElements.MainBar.Size=UDim2.new(1,phone and 0 or -window.SideBarWidth,1,-window.Topbar.Height-(phone and 48 or 0))
        mobile.PhoneNav.Visible=phone
        if not phone then mobile.PhoneNavList.Visible=false end
        positionControls()
    end
    function mobile.ApplyInputMode()
        local mode = getMode()
        if mode == mobile.Mode then return end
        mobile.Mode = mode
        State.InputMode = mode
        icon.Visible = mode == "Mobile"
        for _, frame in ipairs(mobile.KeybindCards or {}) do frame.Visible = mode == "PC" end
        if emergencyButton and mode~="Mobile" then emergencyButton.Visible=false end
        pad.Visible = mode == "Mobile" and not mobile.MenuOpen and C.EquippedWeapon() ~= nil
        suppressInput()
        resized()
        mobile.UpdatePhoneControls()
    end
    -- PreferredInput changes on hybrid devices and when phone peripherals are used.
    if C.GetInputMode then
        local ok, changed = pcall(function() return UIS:GetPropertyChangedSignal("PreferredInput") end)
        if ok and changed then connect(changed, mobile.ApplyInputMode) end
        if UIS.LastInputTypeChanged then connect(UIS.LastInputTypeChanged, mobile.ApplyInputMode) end
    end
    connect(canvas:GetPropertyChangedSignal("AbsoluteSize"), resized)
    task.defer(function()
        if State.Running and not mobile.Destroyed then
            mobile.ResetPositions(); resized()
            mobile.UpdatePhoneControls()
        end
    end)
    local elapsed = 0
    connect(RunService.Heartbeat, function(dt)
        elapsed += dt
        if elapsed < State.GetBackgroundInterval(0.3) then return end
        elapsed = 0
        updateDashboard()
        local item = C.EquippedWeapon()
        mobile.ApplyInputMode()
        mobile.UpdatePhoneControls()
        mobile.SyncPhonePage()
        local flying = mobile.Mode == "Mobile" and not mobile.MenuOpen and not moreDock.Visible and State.Config.Fly == true
        if flyPad.Visible ~= flying then flyPad.Visible = flying end
        if not flying and State.Movement and State.Movement.Vertical ~= 0 then State.Movement.Vertical = 0 end
        local fireText = item and item.Name == "Knife" and "Stab" or "Fire"
        if fire.Text ~= fireText then fire.Text = fireText end
        throw.Visible = item ~= nil and item.Name == "Knife"
        local statusAllowed=mobile.PhoneControls.ShowStatus()
        local showHUD=combatHUD and State.Config.CombatHUD and statusAllowed and not mobile.MenuOpen
        if combatHUD and mobile.LastHUDCompact~=(State.Config.CompactHUD~=false) then layoutHUD() end
        notice.Visible = not mobile.MenuOpen and not showHUD and statusAllowed
        if combatHUD then
            combatHUD.Visible=showHUD==true
            if showHUD then
                local ok,data=pcall(State.GetCombatHUDData)
                if ok and type(data)=="table" and type(data.Text)=="string" then
                    mobile.LastCombatHUDData,mobile.LastCombatHUDError=data,nil
                    renderHUD(data)
                else
                    mobile.LastCombatHUDError=ok and "Invalid HUD snapshot" or tostring(data)
                    renderHUD({Role="Unknown",Weapon="",Primary="Status unavailable",Tone="warning",Result=""})
                end
            end
        end
        local fling = State.Fling
        if fling and mobile.AdaptivePursuitToggle and mobile.AdaptivePursuitToggle.Value ~= fling.AdaptivePursuit then
            mobile.AdaptivePursuitToggle:Set(fling.AdaptivePursuit,false)
        end
        local actions = State.PlayerActions
        if emergencyButton then
            local pendingWeapon=false
            for _,record in pairs(State.WeaponHandlers or {}) do
                if record.Charging or (record.StabbingUntil or 0)>os.clock() then pendingWeapon=true; break end
            end
            emergencyButton.Visible=mobile.Mode=="Mobile" and State.Config.MobileShortcuts==false and not mobile.MenuOpen
                and ((State.FlingQueue and State.FlingQueue.Active) or (State.KillAura and State.KillAura.Enabled) or (State.Invis and (State.Invis.Active or State.Invis.Busy)) or (fling and fling.Active) or (actions and actions.Enabled) or pendingWeapon or State.Config.AutoPickup or State.Config.AutoKnifeDodge
                    or State.Config.Triggerbot or State.Config.KnifeTriggerbot
                    or State.Config.Fly or State.Config.Noclip or State.Config.SpeedBoost or State.Config.JumpBoost or State.Config.InfiniteJump) or false
        end
        if fling and mobile.SpinContactToggle and mobile.SpinContactToggle.Value ~= (fling.Mode == "Spin") then mobile.SpinContactToggle:Set(fling.Mode == "Spin",false) end
        if fling and mobile.DownwardContactToggle and mobile.DownwardContactToggle.Value ~= (fling.Mode == "Downward") then mobile.DownwardContactToggle:Set(fling.Mode == "Downward",false) end
        if mobile.RefreshExclusions and mobile.LastExclusionsRevision ~= State.ExclusionsRevision then mobile.RefreshExclusions() end
        if actions and mobile.AutoAttackToggle and mobile.AutoAttackToggle.Value ~= actions.Enabled then
            mobile.AutoAttackToggle:Set(actions.Enabled,false)
        end
        if actions and mobile.PlayerActionStatus and mobile.PlayerActionStatus.ParagraphFrame and mobile.LastPlayerActionStatus ~= actions.Status then
            mobile.PlayerActionStatus.ParagraphFrame:SetDesc(actions.Status)
            mobile.LastPlayerActionStatus = actions.Status
        end
        if fling and mobile.FlingStatus and mobile.FlingStatus.ParagraphFrame and mobile.LastFlingStatus ~= fling.Status then
            mobile.FlingStatus.ParagraphFrame:SetDesc(fling.Status)
            mobile.LastFlingStatus = fling.Status
        end
        if State.FlingQueue and mobile.FlingAllStatus then
            updateDescription(mobile.FlingAllStatus,"FlingQueue",State.FlingQueue.Status)
        end
        if fling then
            local summary=State.FlingQueue and State.FlingQueue.Active and (State.FlingQueue.Status.."\n"..fling.Status) or fling.Status
            updateDescription(mobile.FlingSummary,"FlingSummary",summary)
            updateDescription(mobile.RoleFlingSummary,"RoleFlingSummary",fling.Status)
        end
        if State.Invis and mobile.InvisibilityStatus and mobile.InvisibilityStatus.ParagraphFrame and mobile.LastInvisibilityStatus~=State.Invis.Status then
            mobile.InvisibilityStatus.ParagraphFrame:SetDesc(State.Invis.Status)
            mobile.LastInvisibilityStatus=State.Invis.Status
            refresh()
        end
        if mobile.MapVoteStatus then
            local r=State.MapVote
            updateDescription(mobile.MapVoteStatus,"MapVote",r.Status..("\nRespawns: %d/3 · touches: %d · observed total increase: %d"):format(r.Respawns,r.Touches,r.ObservedIncrease))
            if toggles.MapVoteRepeat and toggles.MapVoteRepeat.Value~=State.Config.MapVoteRepeat then refresh() end
        end
        if mobile.KnifeDodgeStatus then
            local d=State.KnifeDodge
            updateDescription(mobile.KnifeDodgeStatus,"KnifeDodge",d.Status..("\nTeleports sent: %d · jumps: %d · sidesteps: %d"):format(d.Teleports,d.Jumps,d.Sidesteps))
        end
        if mobile.StreamerStatus and State.Streamer then updateDescription(mobile.StreamerStatus,"Streamer",State.Streamer.Status) end
        if State.Movement and mobile.MovementStatus then updateDescription(mobile.MovementStatus,"Movement",State.Movement.Status) end
        if State.AntiFling and mobile.AntiFlingStatus then updateDescription(mobile.AntiFlingStatus,"AntiFling",State.AntiFling.Status) end
        if mobile.PackPicker then
            -- Keep the picker honest when a pose, F9 or a respawn changes the active pack.
            local label=State.Config.MageAnimations and State.Config.AnimationPack or "Default"
            if mobile.PackLabel~=label then
                mobile.PackSyncing=true; mobile.PackPicker:Select(label); mobile.PackSyncing=false
                mobile.PackLabel=label
            end
            updateDescription(mobile.AnimationStatus,"Animation",State.Config.PoseEnabled and State.Pose and State.Pose.Status
                or (State.Mage and State.Mage.Status) or "Default animations")
        end
        if mobile.KeybindElements then
            -- A key picked in the menu is validated here; reserved keys revert and duplicates move.
            for id,element in pairs(mobile.KeybindElements) do
                if not element.Picking and element.Value~=mobile.KeybindShown[id] then
                    local ok,message=State.SetKeybind(id,element.Value)
                    mobile.Toast(message,ok and "info" or "warn",true)
                    if not ok then mobile.KeybindShown[id]=nil end
                end
            end
            for id,element in pairs(mobile.KeybindElements) do
                local key=State.Config.Keybinds[id]
                if not element.Picking and (element.Value~=key or mobile.KeybindShown[id]~=key) then
                    element:Set(key)
                    mobile.KeybindShown[id]=key
                end
            end
            if mobile.BindMenuKeys then mobile.BindMenuKeys() end
        end
        if State.Config.Toasts~=false and State.GetCombatHUDData then
            local ok,data=pcall(State.GetCombatHUDData)
            local role=ok and type(data)=="table" and data.Role or nil
            if role and role~=mobile.LastRole then
                local previous=mobile.LastRole
                mobile.LastRole=role
                if role=="Murderer" then mobile.Toast("You are the murderer",roleLook.Murderer[2])
                elseif role=="Sheriff" then mobile.Toast(previous=="Innocent" and "You picked up the gun" or "You are the sheriff",roleLook.Sheriff[2])
                elseif role=="Innocent" then mobile.Toast("You are innocent",roleLook.Innocent[2])
                elseif role=="Zombie" or role=="Survivor" or role=="Freezer" or role=="Runner" then mobile.Toast("You are a "..role:lower(),roleLook[role][2])
                elseif role=="Eliminated" and previous and previous~="Lobby" then mobile.Toast("You were eliminated","off") end
            end
        end
        if State.KillAura and mobile.KillAuraStatus and mobile.KillAuraStatus.ParagraphFrame and mobile.LastKillAuraStatus~=State.KillAura.Status then
            mobile.KillAuraStatus.ParagraphFrame:SetDesc(State.KillAura.Status)
            mobile.LastKillAuraStatus=State.KillAura.Status
        end
        if State.GunPickup and mobile.PickupStatus and mobile.PickupStatus.ParagraphFrame and mobile.LastPickupStatus~=State.GunPickup.Status then
            mobile.PickupStatus.ParagraphFrame:SetDesc(State.GunPickup.Status); mobile.LastPickupStatus=State.GunPickup.Status
        end
        if State.WorldTeleport and mobile.TeleportStatus and mobile.TeleportStatus.ParagraphFrame and mobile.LastTeleportStatus~=State.WorldTeleport.Status then
            mobile.TeleportStatus.ParagraphFrame:SetDesc(State.WorldTeleport.Status); mobile.LastTeleportStatus=State.WorldTeleport.Status
        end
        notice.Text = State.Invis and (State.Invis.Active or State.Invis.Busy) and State.Invis.Status
            or fling and (fling.Active or os.clock() < (fling.DisplayUntil or 0)) and fling.Status
            or (State.KnifeFeedback and os.clock() < State.KnifeFeedback.Until and State.KnifeFeedback.Message or State.AimStatus)
        refresh()
    end)
    return mobile
end

do
    local ok, message = pcall(function()
        createMobileUI({
            State = State, UIS = UIS, RunService = RunService, Parent = gui.Parent,
            Connect = connect, CreateLibrary = createLibrary, SyncWeapons = syncWeapons,
            Players = Players, ContextActionService = game:GetService("ContextActionService"),
            EquippedWeapon = equippedWeapon,
            GetInputMode = function() return detectInputMode(UIS) end,
            UpdateVisuals = function() updateESP(); updateThreat(); updateGunESP() end,
            EquipWeapon = function()
                local hum = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
                local item = toolFor(player, "Gun") or toolFor(player, "Knife")
                if hum and item then hum:EquipTool(item) end
            end,
            Fire = function()
                local item = equippedWeapon()
                if not item then State.AimStatus = "Equip a weapon"; return end
                local record = State.WeaponHandlers[item]
                if record then
                    if record.Kind == "Gun" then sendGun(record) else clickKnife(record) end
                else
                    -- Aim OFF: use the normal tool activation rather than sending custom remotes.
                    item:Activate()
                    task.defer(function() if item.Parent then item:Deactivate() end end)
                end
            end,
            Throw = function()
                local item = equippedWeapon()
                local record = item and State.WeaponHandlers[item]
                if record and record.Kind == "Knife" then
                    State.LastThrowInput = "MobileThrowButton"
                    startThrow(record)
                else
                    State.AimStatus = "Equip your knife and turn on Aim assist"
                end
            end,
        })
    end)
    if not ok then
        State.Destroy()
        error("MM2 could not open its UI: " .. tostring(message))
    end
end

do
-- Windows streamer transport. The companion owns its capture-excluded window;
-- Roblox continues processing input under a transparent, click-through mirror.
local installStreamerMode=function(C)
    local State=C.State
    local info={Active=false,Pending=false,Frames=0,Items=0,Failures=0,Status="Off · Windows companion required"}
    State.Streamer=info
    State.StreamerActive=false
    State.Config.StreamerMode=false
    local generation,session,hidden,inFlight,nextAt=0,nil,false,false,0
    local function send(path,frame,id)
        local ran,accepted,reply=pcall(C.Send,path,frame,id)
        return ran and accepted==true,reply
    end
    local function clear(id)
        if id then C.Spawn(function() send("/clear",nil,id) end) end
    end
    local function restore()
        local ran,accepted=pcall(C.Leave)
        if not ran or accepted==false then
            info.Status="UI restoration incomplete · toggle streamer off again"
            State.Config.StreamerMode=true
            return false,info.Status
        end
        hidden=false; State.StreamerActive=false; State.Config.StreamerMode=false
        if C.Changed then pcall(C.Changed,false) end
        return true
    end
    local function frame(id)
        local data=C.Snapshot()
        if type(data)~="table" or type(data.Items)~="table" or #data.Items>1600
            or type(data.Width)~="number" or type(data.Height)~="number"
            or data.Width~=data.Width or data.Height~=data.Height
            or data.Width<200 or data.Height<200 or data.Width>16384 or data.Height>16384 then
            error("Invalid overlay snapshot",0)
        end
        data.Protocol,data.Session=1,id
        return data
    end
    function State.SetStreamerMode(enabled)
        if not enabled then
            generation+=1; info.Pending=false; info.Active=false
            local old=session; session=nil; clear(old)
            local ok,message=restore()
            if ok then info.Status="Off" end
            return ok,message or info.Status
        end
        if not State.Running then return false,"Script is unloaded" end
        if info.Active then return true,info.Status end
        if info.Pending then return false,"Streamer connection is already being checked" end
        if hidden then return false,"Turn streamer off to restore the UI before reconnecting" end
        generation+=1; local epoch=generation
        info.Pending=true; State.Config.StreamerMode=false
        info.Status="Checking local Windows overlay"
        local accepted,reply=send("/status")
        if epoch~=generation or not State.Running then return false,"Streamer activation cancelled" end
        if not accepted or type(reply)~="table" or reply.Protocol~=1 or reply.Ready~=true or reply.CaptureExcluded~=true then
            info.Pending=false
            info.Status="Unavailable · start the Windows companion and run connect.lua"
            return false,info.Status
        end
        session=C.Session()..":"..tostring(epoch)
        local id=session
        State.StreamerActive=true; hidden=true
        local prepared,entered=pcall(C.Enter)
        local built,data=false,nil
        if prepared and entered~=false then built,data=pcall(frame,id) end
        local sent,response=false,nil
        if built then sent,response=send("/frame",data,id) end
        if epoch~=generation or not State.Running then clear(id); return false,"Streamer activation cancelled" end
        if not prepared or entered==false or not built or not sent or type(response)~="table" or response.Accepted~=true then
            generation+=1; session=nil; info.Pending=false; clear(id)
            local restored=restore()
            if restored then info.Status="Unavailable · native UI could not be mirrored completely" end
            return false,info.Status
        end
        info.Pending=false; info.Active=true; State.Config.StreamerMode=true; info.Frames+=1; info.Items=#data.Items
        info.Status="On · Windows exclusion flag active; verify your saved clip"
        nextAt=C.Clock()+.05
        if C.Changed then pcall(C.Changed,true) end
        return true,info.Status
    end
    function State.StopStreamerMode() return State.SetStreamerMode(false) end
    function State.GetStreamerSnapshot()
        return {Enabled=State.Config.StreamerMode==true,Active=info.Active,NativeHidden=hidden,Pending=info.Pending,
            Frames=info.Frames,Items=info.Items,Failures=info.Failures,Status=info.Status,RecordingVerified=false}
    end
    function info.Step()
        if not State.Running or not info.Active or inFlight or C.Clock()<nextAt then return end
        nextAt=C.Clock()+.05
        local epoch,id=generation,session
        local built,data=pcall(frame,id)
        if not built then info.Failures+=1; info.Status="Overlay snapshot failed · native UI remains hidden; use streamer Off"; nextAt=C.Clock()+.5; return end
        inFlight=true
        C.Spawn(function()
            local accepted,reply=send("/frame",data,id)
            inFlight=false
            if epoch~=generation or not State.Running then return end
            if accepted and type(reply)=="table" and reply.Accepted==true then
                info.Frames+=1; info.Items=#data.Items; info.Status="On · Windows exclusion flag active; verify your saved clip"
            else
                info.Failures+=1; nextAt=C.Clock()+.5
                info.Status="Overlay disconnected · native UI stays hidden until streamer Off"
            end
        end)
    end
    C.Tick(info.Step)
    return info
end

local createStreamerSurfaces=function(C)
    local records,connections,lifetimes={},{},{}
    local active=false
    local function read(object,key)
        local entries=records[object]
        if entries and entries[key] then return entries[key].Before end
        return object[key]
    end
    local function force(object,key,value)
        local entries=records[object]
        if entries and entries[key] then return true end
        local ok,before=pcall(function() return object[key] end)
        if not ok then return false end
        if not entries then
            entries={}; records[object]=entries
            lifetimes[object]=object.Destroying:Connect(function()
                for _,entry in pairs(entries) do if entry.Connection then entry.Connection:Disconnect() end end
                records[object]=nil
                if lifetimes[object] then lifetimes[object]:Disconnect(); lifetimes[object]=nil end
            end)
        end
        local entry={Before=before,Hidden=value,Writing=false}; entries[key]=entry
        local function apply()
            entry.Writing=true
            local wrote=pcall(function() object[key]=value end)
            entry.Writing=false
            return wrote
        end
        local listened,connection=pcall(function() return object:GetPropertyChangedSignal(key):Connect(function()
            if not active or entry.Writing then return end
            local current=object[key]
            if current~=value then entry.Before=current; if not apply() then C.Failed() end end
        end) end)
        if not listened then entries[key]=nil; return false end
        entry.Connection=connection
        if not apply() then connection:Disconnect(); entries[key]=nil; return false end
        return true
    end
    local function hide(object)
        local ok=true
        if object:IsA("GuiObject") then
            ok=force(object,"BackgroundTransparency",1) and ok
            ok=force(object,"BorderSizePixel",0) and ok
            if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
                ok=force(object,"TextTransparency",1) and ok
                ok=force(object,"TextStrokeTransparency",1) and ok
            end
            if object:IsA("ImageLabel") or object:IsA("ImageButton") or object:IsA("ViewportFrame") then ok=force(object,"ImageTransparency",1) and ok end
            if object:IsA("ScrollingFrame") then ok=force(object,"ScrollBarImageTransparency",1) and ok end
        elseif object:IsA("UIStroke") then ok=force(object,"Transparency",1) and ok end
        if not ok then error("A native UI surface cannot be hidden",0) end
    end
    local surfaces={Read=read}
    function surfaces.Enter()
        active=true
        for _,root in ipairs(C.Roots()) do
            hide(root)
            for _,object in ipairs(root:GetDescendants()) do hide(object) end
            table.insert(connections,root.DescendantAdded:Connect(function(object)
                if active then
                    local ok=pcall(hide,object)
                    if not ok then C.Failed() end
                end
            end))
        end
        if not force(C.UIS,"MouseIconEnabled",false) then error("Mouse cursor cannot be mirrored",0) end
        C.Visuals(true)
        return true
    end
    function surfaces.Leave()
        active=false
        for _,connection in ipairs(connections) do connection:Disconnect() end
        table.clear(connections)
        local failed=0
        for object,entries in pairs(records) do
            for key,entry in pairs(entries) do
                if entry.Connection then entry.Connection:Disconnect(); entry.Connection=nil end
                local ok=pcall(function()
                    if object[key]==entry.Hidden then object[key]=entry.Before end
                end)
                if ok then entries[key]=nil else failed+=1 end
            end
            if next(entries)==nil then
                records[object]=nil
                if lifetimes[object] then lifetimes[object]:Disconnect(); lifetimes[object]=nil end
            end
        end
        if failed==0 then C.Visuals(false) end
        return failed==0
    end
    return surfaces
end

local coreGui=game:GetService("CoreGui")
local surfaces
local function visualState(hidden)
    updateESP(); updateGunESP()
    if hidden then
        if State.StopXRay then State.StopXRay() end
        if State.StopTacticalGuide then State.StopTacticalGuide() end
    end
end
local function streamerRoots()
    local roots={coreGui}
    local playerGui=player:FindFirstChildOfClass("PlayerGui")
    if playerGui then table.insert(roots,playerGui) end
    if gui.Parent and gui.Parent~=playerGui and gui.Parent~=coreGui and not gui.Parent:IsDescendantOf(coreGui) then table.insert(roots,gui.Parent) end
    return roots
end
surfaces=createStreamerSurfaces({UIS=UIS,Roots=streamerRoots,Visuals=visualState,Failed=function()
    -- A newly inaccessible surface is a privacy failure: stop adding native visuals.
    State.Streamer.SurfaceError=true
end})
local function color(value)
    return string.format("%02X%02X%02X",math.floor(value.R*255+.5),math.floor(value.G*255+.5),math.floor(value.B*255+.5))
end
local function snapshot()
    if State.Streamer.SurfaceError then error("Native UI surface changed permissions",0) end
    local camera=workspace.CurrentCamera
    if not camera then error("No camera",0) end
    local viewport=camera.ViewportSize
    local items,seen={},{}
    local function add(item)
        if #items>=1600 then error("Too many overlay elements",0) end
        table.insert(items,item)
    end
    local function walk(object,clip,layer,opacity)
        if seen[object] then return end; seen[object]=true
        if object:IsA("LayerCollector") then
            if not object.Enabled then return end
            if object:IsA("ScreenGui") then layer=object.DisplayOrder*10000 else return end
        end
        if object:IsA("GuiObject") then
            if not object.Visible then return end
            local p,s=object.AbsolutePosition,object.AbsoluteSize
            if s.X<=0 or s.Y<=0 then return end
            if object:IsA("CanvasGroup") then opacity*=1-object.GroupTransparency end
            local x,y=math.max(clip.X,p.X),math.max(clip.Y,p.Y)
            local right,bottom=math.min(clip.X+clip.W,p.X+s.X),math.min(clip.Y+clip.H,p.Y+s.Y)
            if right<=x or bottom<=y then return end
            local z=layer+object.ZIndex*3
            local function base(kind,alpha)
                return {Kind=kind,X=p.X,Y=p.Y,W=s.X,H=s.Y,Alpha=math.clamp(alpha*opacity,0,1),Z=z,
                    Rotation=object.AbsoluteRotation,ClipX=clip.X,ClipY=clip.Y,ClipW=clip.W,ClipH=clip.H}
            end
            local border=surfaces.Read(object,"BorderSizePixel")
            local alpha=1-surfaces.Read(object,"BackgroundTransparency")
            local stroke=object:FindFirstChildOfClass("UIStroke")
            local strokeAlpha=stroke and stroke.Enabled and 1-surfaces.Read(stroke,"Transparency") or 0
            if alpha>0 or border>0 or strokeAlpha>0 then
                local item=base("rect",alpha); item.Color=color(object.BackgroundColor3)
                item.Border=strokeAlpha>0 and stroke.Thickness or border
                item.Stroke=color(strokeAlpha>0 and stroke.Color or object.BorderColor3)
                item.StrokeAlpha=(strokeAlpha>0 and strokeAlpha or 1)*opacity
                local corner=object:FindFirstChildOfClass("UICorner")
                item.Radius=corner and corner.CornerRadius.Scale*math.min(s.X,s.Y)+corner.CornerRadius.Offset or 0
                add(item)
            end
            if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
                local item=base("text",1-surfaces.Read(object,"TextTransparency"))
                item.Text=object.ContentText
                if object:IsA("TextBox") and item.Text=="" then item.Text=object.PlaceholderText end
                item.Text=item.Text:sub(1,4096); item.Color=color(object.TextColor3)
                item.Font=math.clamp(object.TextScaled and math.min(s.Y,object.TextBounds.Y) or object.TextSize,1,256)
                item.Center=object.TextXAlignment==Enum.TextXAlignment.Center; item.Right=object.TextXAlignment==Enum.TextXAlignment.Right
                item.Bold=object.FontFace.Weight.Value>=Enum.FontWeight.SemiBold.Value
                item.Wrap=object.TextWrapped; item.Z=z+2
                if item.Text~="" and item.Alpha>0 then add(item) end
            elseif object:IsA("ImageLabel") or object:IsA("ImageButton") then
                local item=base("image",1-surfaces.Read(object,"ImageTransparency"))
                item.Image=object.Image; item.Color=color(object.ImageColor3); item.Z=z+1
                item.ImageX,item.ImageY=object.ImageRectOffset.X,object.ImageRectOffset.Y
                item.ImageW,item.ImageH=object.ImageRectSize.X,object.ImageRectSize.Y
                if #item.Image>0 and #item.Image<=1024 and item.Alpha>0 then add(item) end
            end
            if object.ClipsDescendants then clip={X=x,Y=y,W=right-x,H=bottom-y} end
        end
        for _,child in ipairs(object:GetChildren()) do walk(child,clip,layer,opacity) end
    end
    local clip={X=0,Y=0,W=viewport.X,H=viewport.Y}
    for _,root in ipairs(streamerRoots()) do walk(root,clip,0,1) end
    -- World highlights are removed from Roblox. Equivalent projected boxes stay
    -- in the separate overlay; this does not alter any character hitboxes.
    if State.Config.ESP and espViewerAtRound() then
        for _,other in ipairs(Players:GetPlayers()) do
            if other~=player and visualCharacterReady(other) then
                local root=other.Character:FindFirstChild("HumanoidRootPart")
                if root then
                    local top,topVisible=camera:WorldToViewportPoint(root.Position+Vector3.new(0,3.5,0))
                    local low,lowVisible=camera:WorldToViewportPoint(root.Position-Vector3.new(0,3,0))
                    if topVisible and lowVisible then
                        local height=math.abs(low.Y-top.Y); local width=height*.6
                        local tint=color(colors[visualRoleFor(other)])
                        add({Kind="rect",X=top.X-width/2,Y=top.Y,W=width,H=height,Alpha=0,Color=tint,Stroke=tint,Border=1.5,StrokeAlpha=1,Z=800000})
                        add({Kind="text",X=top.X-110,Y=top.Y-25,W=220,H=24,Alpha=1,Color=tint,Text="@"..other.Name..(State.GameContext.Mode()~="Classic" and " · "..visualRoleFor(other) or ""),Font=13,Center=true,Z=800001})
                    end
                end
            end
        end
    end
    if State.Config.GunESP and espViewerAtRound() then
        for object in pairs(drops) do
            local part=object:IsDescendantOf(workspace) and dropPart(object)
            if part then
                local point,visible=camera:WorldToViewportPoint(part.Position)
                if visible then add({Kind="text",X=point.X-70,Y=point.Y-24,W=140,H=24,Alpha=1,Color="FFD72D",Text="Gun",Font=14,Center=true,Z=800001}) end
            end
        end
    end
    if surfaces.Read(UIS,"MouseIconEnabled") then
        local mouse=UIS:GetMouseLocation()
        local icon=player:GetMouse().Icon
        if icon~="" then add({Kind="image",X=mouse.X-16,Y=mouse.Y-16,W=32,H=32,Alpha=1,Image=icon,Z=2000000000})
        else add({Kind="text",X=mouse.X,Y=mouse.Y,W=30,H=30,Alpha=1,Color="FFFFFF",Text="↖",Font=24,Z=2000000000}) end
    end
    table.sort(items,function(a,b) return a.Z<b.Z end)
    return {Width=math.floor(viewport.X),Height=math.floor(viewport.Y),Items=items}
end
local function send(path,data,session)
    local connection=env.MM2StreamerConnection
    local requestFunction=request or (http and http.request) or (syn and syn.request)
    if type(requestFunction)~="function" or type(connection)~="table" or type(connection.Port)~="number"
        or connection.Port%1~=0 or connection.Port<1024 or connection.Port>65535 or type(connection.Token)~="string" or #connection.Token==0 or #connection.Token>128 then return false end
    local headers={["X-MM2-Token"]=connection.Token,["Content-Type"]="application/json"}
    if session then headers["X-MM2-Session"]=session end
    local body=data and game:GetService("HttpService"):JSONEncode(data) or nil
    if body and #body>1048576 then return false end
    local response=requestFunction({Url="http://127.0.0.1:"..connection.Port..path,Method=path=="/status" and "GET" or "POST",Headers=headers,Body=body,Timeout=3})
    if type(response)~="table" or response.StatusCode~=200 then return false end
    local ok,reply=pcall(game:GetService("HttpService").JSONDecode,game:GetService("HttpService"),response.Body)
    return ok and type(reply)=="table",reply
end
installStreamerMode({State=State,Send=send,Enter=function() State.Streamer.SurfaceError=false; return surfaces.Enter() end,Leave=surfaces.Leave,Snapshot=snapshot,
    Clock=os.clock,Session=function() return State.InstanceToken end,Spawn=task.spawn,
    Changed=function() if State.MobileUI and State.MobileUI.Refresh then State.MobileUI.Refresh() end end,
    Tick=function(callback) connect(RunService.Heartbeat,callback) end})
end
